// ============================================================
//          AUTH SESSION BRIDGE — server session cookie only
//          جلسة سيرفر عبر mbk_session فقط
// ============================================================

const AUTH_COOKIE_NAME = process.env.MURABBIK_AUTH_COOKIE || "mbk_session";
const AUTH_SESSION_DAYS = Number(process.env.MURABBIK_SESSION_DAYS || 7);
const AUTH_SESSION_EXPIRES_MS = Math.max(1, AUTH_SESSION_DAYS) * 24 * 60 * 60 * 1000;

function authDigitsBridgeSrv(raw) {
  const map = {
    "٠":"0","١":"1","٢":"2","٣":"3","٤":"4","٥":"5","٦":"6","٧":"7","٨":"8","٩":"9",
    "۰":"0","۱":"1","۲":"2","۳":"3","۴":"4","۵":"5","۶":"6","۷":"7","۸":"8","۹":"9"
  };

  return String(raw || "")
    .trim()
    .replace(/[٠-٩۰-۹]/g, d => map[d] || d)
    .replace(/\D/g, "");
}

function authCookieValueBridgeSrv(req, name) {
  const raw = String(req.headers.cookie || "");
  if (!raw) return "";

  for (const part of raw.split(";")) {
    const i = part.indexOf("=");
    if (i < 0) continue;

    const k = part.slice(0, i).trim();
    if (k !== name) continue;

    try {
      return decodeURIComponent(part.slice(i + 1).trim());
    } catch (_) {
      return part.slice(i + 1).trim();
    }
  }

  return "";
}

function authIsHttpsReqBridgeSrv(req) {
  return Boolean(
    req.secure ||
    String(req.headers["x-forwarded-proto"] || "").split(",")[0].trim() === "https"
  );
}

function authSetSessionCookieBridgeSrv(req, res, sessionCookie) {
  res.cookie(AUTH_COOKIE_NAME, sessionCookie, {
    httpOnly: true,
    secure: authIsHttpsReqBridgeSrv(req),
    sameSite: "lax",
    path: "/",
    maxAge: AUTH_SESSION_EXPIRES_MS
  });
}

function authClearSessionCookieBridgeSrv(req, res) {
  res.clearCookie(AUTH_COOKIE_NAME, {
    httpOnly: true,
    secure: authIsHttpsReqBridgeSrv(req),
    sameSite: "lax",
    path: "/"
  });
}

function authAccountStatusBridgeSrv(profile = {}) {
  const status = String(profile.accountStatus || "").trim().toLowerCase();

  if (status === "suspended") return "suspended";
  if (status === "closed") return "closed";

  // Backward compatibility: الحسابات الحالية بلا accountStatus تظل فعّالة.
  return "active";
}

function authAccountDeniedBridgeSrv(accountStatus) {
  if (accountStatus === "suspended") {
    return {
      error: "account_suspended",
      message: "🚫 تم إيقاف هذا الحساب مؤقتًا. تواصل مع إدارة مُرَبِّيك."
    };
  }

  if (accountStatus === "closed") {
    return {
      error: "account_closed",
      message: "🚫 تم إغلاق هذا الحساب. تواصل مع إدارة مُرَبِّيك."
    };
  }

  return null;
}

function authPublicUserBridgeSrv(profile = {}, uid = "", userId = "") {
  return {
    uid,
    userId,
    name: profile.name || profile.displayName || profile.fullName || "",
    phone: profile.phone || profile.phoneNumber || "",
    role: profile.role || profile.accountRole || "",
    farmName: profile.farmName || profile.farm || "",
    accountStatus: authAccountStatusBridgeSrv(profile)
  };
}

function authProfileUnavailableErrorBridgeSrv(
  code = "auth_profile_unavailable"
) {
  const err = new Error(code);

  err.code = code;
  err.publicStatus = 503;
  err.publicError = code;
  err.publicMessage =
    "❌ تعذّر التحقق من حالة الحساب الآن. حاول مرة أخرى لاحقًا.";

  return err;
}

async function authReadUserProfileBridgeSrv(
  uid,
  { required = false } = {}
) {
  const userUid =
    String(uid || "").trim();

  if (!db || !userUid) {
    if (required) {
      throw authProfileUnavailableErrorBridgeSrv(
        !db
          ? "auth_profile_store_unavailable"
          : "auth_profile_uid_missing"
      );
    }

    return {};
  }

  try {
    const snap =
      await db
        .collection("users")
        .doc(userUid)
        .get();

    if (!snap.exists) {
      if (required) {
        throw authProfileUnavailableErrorBridgeSrv(
          "auth_profile_missing"
        );
      }

      return {};
    }

    return snap.data() || {};

  } catch (e) {
    if (
      String(e?.code || "")
        .startsWith("auth_profile_")
    ) {
      throw e;
    }

    console.warn(
      "auth bridge user profile read failed:",
      e.message || e
    );

    if (required) {
      throw authProfileUnavailableErrorBridgeSrv(
        "auth_profile_read_failed"
      );
    }

    return {};
  }
}

async function authSessionFromRequestBridgeSrv(req) {
  try {
    const sessionCookie =
      authCookieValueBridgeSrv(
        req,
        AUTH_COOKIE_NAME
      );

    if (
      !sessionCookie ||
      !admin.apps.length
    ) {
      return null;
    }

    const decoded =
      await admin.auth()
        .verifySessionCookie(
          sessionCookie,
          true
        );

    const uid =
      String(
        decoded.uid || ""
      ).trim();

    if (!uid) {
      return null;
    }

    const profile =
      await authReadUserProfileBridgeSrv(
        uid,
        { required: true }
      );

    const accountStatus =
      authAccountStatusBridgeSrv(profile);

    // نفس userId القديم، حتى لا تنفصل بيانات الحساب
    const userId =
      tenantKey(
        profile.userId ||
        profile.tenantId ||
        profile.ownerUid ||
        uid
      );

    return {
      uid,
      userId,
      decoded,
      accountStatus,
      user:
        authPublicUserBridgeSrv(
          profile,
          uid,
          userId
        )
    };

  } catch (e) {
    if (
      String(e?.code || "")
        .startsWith("auth_profile_")
    ) {
      throw e;
    }

    return null;
  }
}
async function authPasswordLoginBridgeSrv(email, password) {
  const apiKey =
    process.env.FIREBASE_WEB_API_KEY ||
    process.env.FIREBASE_API_KEY ||
    process.env.MURABBIK_FIREBASE_API_KEY ||
    "";

  if (!apiKey) {
    const err = new Error("firebase_web_api_key_missing");
    err.publicMessage = "❌ خدمة تسجيل الدخول غير متاحة الآن. حاول مرة أخرى لاحقًا.";
    throw err;
  }

  const r = await fetch(
    `https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${encodeURIComponent(apiKey)}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        email,
        password,
        returnSecureToken: true
      })
    }
  );

  const data = await r.json().catch(() => ({}));

  if (!r.ok || !data.idToken) {
    const firebaseError = String(data?.error?.message || "login_failed").trim();
    const err = new Error(firebaseError);

    if (firebaseError === "USER_DISABLED") {
      err.publicStatus = 403;
      err.publicError = "account_disabled";
      err.publicMessage = "🚫 تم إيقاف هذا الحساب. تواصل مع إدارة مُرَبِّيك.";

      try {
        const userRecord = await admin.auth().getUserByEmail(email);
        const uid = String(userRecord?.uid || "").trim();

        if (uid) {
          const profile = await authReadUserProfileBridgeSrv(uid);
          const accountStatus = authAccountStatusBridgeSrv(profile);
          const accountDenied = authAccountDeniedBridgeSrv(accountStatus);

          if (accountDenied) {
            err.publicError = accountDenied.error;
            err.publicMessage = accountDenied.message;
          }
        }
      } catch (_) {}

      throw err;
    }

    err.publicMessage = "❌ رقم الهاتف أو كلمة المرور غير صحيحة.";
    throw err;
  }

  return data;
}
function authRegisterTextBridgeSrv(v) {
  return String(v || "").trim().replace(/\s+/g, " ");
}
const AUTH_OTP_TTL_MS = Number(process.env.MURABBIK_OTP_TTL_MS || 10 * 60 * 1000);
const AUTH_OTP_MAX_ATTEMPTS = Number(process.env.MURABBIK_OTP_MAX_ATTEMPTS || 5);
const AUTH_OTP_DEV_RETURN = process.env.MURABBIK_OTP_DEV_RETURN === "1";

function authSha256BridgeSrv(v) {
  return crypto.createHash("sha256").update(String(v || "")).digest("hex");
}

function authOtpCodeBridgeSrv() {
  return String(crypto.randomInt(100000, 1000000));
}

function authOtpHashBridgeSrv(code, salt) {
  return authSha256BridgeSrv(`${salt}:${code}`);
}

function authRegisterPasswordIssueBridgeSrv(password, ctx = {}) {
  const p = String(password || "");
  const phoneKey = String(ctx.phoneKey || "").trim();
  const fullName = String(ctx.fullName || "").trim().toLowerCase();

  if (p.length < 8) return "كلمة المرور يجب أن تكون ٨ أحرف أو أكثر.";
  if (!/[A-Za-z\u0600-\u06FF]/.test(p)) return "كلمة المرور يجب أن تحتوي على حرف واحد على الأقل.";
  if (!/[0-9٠-٩۰-۹]/.test(p)) return "كلمة المرور يجب أن تحتوي على رقم واحد على الأقل.";

  const passDigits = authDigitsBridgeSrv(p);
  if (phoneKey && (passDigits === phoneKey || p.includes(phoneKey))) {
    return "لا تستخدم رقم الهاتف داخل كلمة المرور.";
  }

  const weakList = ["12345678", "11111111", "00000000", "password", "qwerty", "murabbik", "مربيك"];
  if (weakList.includes(p.toLowerCase())) return "كلمة المرور ضعيفة جدًا، اختر كلمة أقوى.";

  const nameParts = fullName.split(/\s+/).map(s => s.trim()).filter(s => s.length >= 3);
  for (const part of nameParts) {
    if (part && p.toLowerCase().includes(part)) return "لا تستخدم اسمك داخل كلمة المرور.";
  }

  if (/^(.)\1{7,}$/.test(p)) {
    return "كلمة المرور ضعيفة جدًا، لا تستخدم نفس الحرف أو الرقم مكررًا.";
  }

  return "";
}

async function authSendOtpBridgeSrv(phoneRaw, code) {
  const webhook = String(process.env.MURABBIK_SMS_WEBHOOK_URL || "").trim();

  if (!webhook) {
    if (AUTH_OTP_DEV_RETURN) return { ok: true, dev: true };
    return {
      ok: false,
      error: "sms_provider_missing",
      message: "❌ تعذّر إرسال كود التحقق الآن. حاول مرة أخرى لاحقًا."
    };
  }

  const text = `كود التحقق من مُرَبِّيك: ${code}. صالح لمدة 10 دقائق.`;

  try {
    const r = await fetch(webhook, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        to: phoneRaw,
        message: text,
        code,
        purpose: "register"
      })
    });

    if (!r.ok) {
      return {
        ok: false,
        error: "sms_send_failed",
        message: "❌ تعذّر إرسال كود التحقق الآن. حاول مرة أخرى."
      };
    }

    return { ok: true };

  } catch (e) {
    console.warn("otp sms send failed:", e.message || e);
    return {
      ok: false,
      error: "sms_send_failed",
      message: "❌ تعذّر إرسال كود التحقق الآن. حاول مرة أخرى."
    };
  }
}
function authRegisterValidateBridgeSrv(body = {}) {
  const fullName = authRegisterTextBridgeSrv(
    body.fullName || body.name || body.displayName
  );

  const farmName = authRegisterTextBridgeSrv(
    body.farmName || body.farm || ""
  );

  const phoneRaw = authRegisterTextBridgeSrv(
    body.phone || body.phoneNumber
  );

  const phoneKey = authDigitsBridgeSrv(phoneRaw);
  const country = authRegisterTextBridgeSrv(body.country);
  const region = authRegisterTextBridgeSrv(
    body.region || body.governorate || body.area
  );
  const role = authRegisterTextBridgeSrv(body.role);
  const password = String(body.password || "");
  const confirmPassword = String(
    body.confirmPassword || body.passwordConfirm || ""
  );

  if (
    !fullName ||
    !phoneRaw ||
    !country ||
    !region ||
    !role ||
    !password ||
    !confirmPassword
  ) {
    return {
      ok: false,
      status: 400,
      error: "register_fields_required",
      message: "❌ أكمل جميع بيانات إنشاء الحساب."
    };
  }

  if (farmName.length > 80) {
    return {
      ok: false,
      status: 400,
      error: "register_farm_name_too_long",
      message: "❌ اسم المزرعة يجب ألا يزيد عن ٨٠ حرفًا."
    };
  }

  if (!phoneKey) {
    return {
      ok: false,
      status: 400,
      error: "register_phone_invalid",
      message: "❌ أدخل رقم هاتف صحيحًا."
    };
  }

  if (country === "مصر" && !/^01\d{9}$/.test(phoneKey)) {
    return {
      ok: false,
      status: 400,
      error: "register_phone_country_invalid",
      message: "❌ رقم الهاتف لا يطابق الدولة المختارة."
    };
  }

  if (country !== "مصر" && !/^\d{7,15}$/.test(phoneKey)) {
    return {
      ok: false,
      status: 400,
      error: "register_phone_country_invalid",
      message: "❌ رقم الهاتف لا يطابق الدولة المختارة."
    };
  }

  const passwordIssue = authRegisterPasswordIssueBridgeSrv(password, {
    fullName,
    phoneKey
  });

  if (passwordIssue) {
    return {
      ok: false,
      status: 400,
      error: "register_password_weak",
      message: passwordIssue
    };
  }

  if (password !== confirmPassword) {
    return {
      ok: false,
      status: 400,
      error: "register_password_mismatch",
      message: "❌ تأكيد كلمة المرور لا يطابق كلمة المرور."
    };
  }

  return {
    ok: true,
    fullName,
    farmName,
    phoneRaw,
    phoneKey,
    country,
    region,
    role,
    password
  };
}

async function authRegisterStartHandlerBridgeSrv(req, res) {
  try {
    if (!admin.apps.length || !db) {
      return res.status(503).json({
        ok: false,
        error: "firebase_admin_disabled",
        message: "❌ خدمة إنشاء الحساب غير متاحة الآن. حاول مرة أخرى لاحقًا."
      });
    }

    const v = authRegisterValidateBridgeSrv(req.body || {});

    if (!v.ok) {
      return res.status(v.status || 400).json({
        ok: false,
        error: v.error || "register_invalid",
        message: v.message || "راجع بيانات إنشاء الحساب."
      });
    }

    const pseudoEmail = `${v.phoneKey}@murabbik.local`;

    try {
      await admin.auth().getUserByEmail(pseudoEmail);
      return res.status(409).json({
        ok: false,
        error: "phone_already_registered",
        message: "ℹ️ رقم الهاتف مسجّل بالفعل. سجّل الدخول أو استعد كلمة المرور."
      });
    } catch (e) {
      if (e?.code && e.code !== "auth/user-not-found") throw e;
    }

    const code = authOtpCodeBridgeSrv();
    const otpSalt = crypto.randomBytes(16).toString("hex");
    const passwordSalt = crypto.randomBytes(16).toString("hex");
    const requestId = crypto.randomBytes(18).toString("hex");

    const sent = await authSendOtpBridgeSrv(v.phoneRaw, code);

    if (!sent.ok) {
      return res.status(503).json({
        ok: false,
        error: sent.error || "otp_send_failed",
        message: sent.message || "❌ تعذّر إرسال كود التحقق الآن. حاول مرة أخرى."
      });
    }

 await db.collection("auth_register_otps").doc(requestId).set({
  type: "register",

  phoneRaw: v.phoneRaw,
  phoneKey: v.phoneKey,

  fullName: v.fullName,
  farmName: v.farmName || "",

  country: v.country,
  region: v.region,
  role: v.role,

  otpHash: authOtpHashBridgeSrv(code, otpSalt),
  otpSalt,

  passwordHash: authOtpHashBridgeSrv(
    v.password,
    passwordSalt
  ),
  passwordSalt,

  attempts: 0,
  maxAttempts: AUTH_OTP_MAX_ATTEMPTS,

  resendCount: 0,
  lastSentAtMs: Date.now(),

  usedAt: null,

  expiresAt:
    admin.firestore.Timestamp.fromDate(
      new Date(
        Date.now() +
        AUTH_OTP_TTL_MS
      )
    ),

  createdAt:
    admin.firestore.FieldValue.serverTimestamp(),

  source:
    "server:/api/auth/register/start"
}, { merge: false });
    const out = {
      ok: true,
      otpRequired: true,
      requestId,
      expiresInSeconds: Math.floor(AUTH_OTP_TTL_MS / 1000),
      message: "✅ أرسلنا كود التحقق إلى رقم الهاتف. الكود صالح لمدة 10 دقائق."
    };

    if (AUTH_OTP_DEV_RETURN) out.devOtp = code;

    return res.json(out);

  } catch (e) {
    console.warn("auth register start failed:", e.message || e);
    return res.status(500).json({
      ok: false,
      error: "register_start_failed",
      message: "❌ تعذّر بدء إنشاء الحساب الآن. حاول مرة أخرى."
    });
  }
}

app.post("/api/auth/register/start", authRegisterStartHandlerBridgeSrv);
app.post("/api/auth/register/resend", async (req, res) => {
  try {
    if (!admin.apps.length || !db) {
      return res.status(503).json({
        ok: false,
        error: "firebase_admin_disabled",
        message:
          "❌ خدمة إرسال كود التحقق غير متاحة الآن. حاول مرة أخرى لاحقًا."
      });
    }

    const requestId =
      String(
        req.body?.requestId || ""
      ).trim();

    if (!requestId) {
      return res.status(400).json({
        ok: false,
        error: "otp_request_id_required",
        message:
          "❌ تعذّر تحديد طلب التحقق. ابدأ التسجيل من جديد."
      });
    }

    const ref =
      db
        .collection("auth_register_otps")
        .doc(requestId);

    const snap =
      await ref.get();

    if (!snap.exists) {
      return res.status(404).json({
        ok: false,
        error: "otp_not_found",
        message:
          "❌ طلب التحقق غير موجود. ابدأ التسجيل من جديد."
      });
    }

    const p =
      snap.data() || {};

    if (
      p.type !== "register" ||
      p.usedAt
    ) {
      return res.status(409).json({
        ok: false,
        error: "otp_request_not_active",
        message:
          "ℹ️ طلب التحقق لم يعد نشطًا. ابدأ التسجيل من جديد."
      });
    }

    const resendCount =
      Number(
        p.resendCount || 0
      );

    if (resendCount >= 5) {
      return res.status(429).json({
        ok: false,
        error: "otp_resend_limit_reached",
        message:
          "🚫 وصلت للحد الأقصى لإعادة إرسال الكود. ابدأ التسجيل من جديد."
      });
    }

    const lastSentAtMs =
      Number(
        p.lastSentAtMs || 0
      );

    const retryAfterMs =
      60_000 -
      (
        Date.now() -
        lastSentAtMs
      );

    if (
      lastSentAtMs &&
      retryAfterMs > 0
    ) {
      const retryAfterSeconds =
        Math.max(
          1,
          Math.ceil(
            retryAfterMs / 1000
          )
        );

      return res.status(429).json({
        ok: false,
        error: "otp_resend_too_soon",
        retryAfterSeconds,
        message:
          `ℹ️ يمكنك إعادة إرسال الكود بعد ${retryAfterSeconds} ثانية.`
      });
    }

    const phoneKey =
      String(
        p.phoneKey || ""
      ).trim();

    if (!phoneKey) {
      return res.status(400).json({
        ok: false,
        error: "otp_phone_missing",
        message:
          "❌ تعذّر قراءة رقم الهاتف. ابدأ التسجيل من جديد."
      });
    }

    const pseudoEmail =
      `${phoneKey}@murabbik.local`;

    try {
      await admin.auth()
        .getUserByEmail(
          pseudoEmail
        );

      return res.status(409).json({
        ok: false,
        error: "phone_already_registered",
        message:
          "ℹ️ رقم الهاتف مسجّل بالفعل. سجّل الدخول أو استعد كلمة المرور."
      });

    } catch (e) {
      if (
        e?.code &&
        e.code !== "auth/user-not-found"
      ) {
        throw e;
      }
    }

    const code =
      authOtpCodeBridgeSrv();

    const otpSalt =
      crypto
        .randomBytes(16)
        .toString("hex");

    const sent =
      await authSendOtpBridgeSrv(
        p.phoneRaw || phoneKey,
        code
      );

    if (!sent.ok) {
      return res.status(503).json({
        ok: false,
        error:
          sent.error ||
          "otp_send_failed",
        message:
          sent.message ||
          "❌ تعذّر إعادة إرسال كود التحقق الآن. حاول مرة أخرى."
      });
    }

    await ref.set({
      otpHash:
        authOtpHashBridgeSrv(
          code,
          otpSalt
        ),

      otpSalt,

      attempts: 0,

      maxAttempts:
        AUTH_OTP_MAX_ATTEMPTS,

      resendCount:
        resendCount + 1,

      lastSentAtMs:
        Date.now(),

      lastResentAt:
        admin.firestore.FieldValue
          .serverTimestamp(),

      expiresAt:
        admin.firestore.Timestamp
          .fromDate(
            new Date(
              Date.now() +
              AUTH_OTP_TTL_MS
            )
          ),

      source:
        "server:/api/auth/register/resend"

    }, { merge: true });

    const out = {
      ok: true,
      requestId,

      expiresInSeconds:
        Math.floor(
          AUTH_OTP_TTL_MS / 1000
        ),

      message:
        "✅ تم إرسال كود تحقق جديد إلى رقم الهاتف."
    };

    if (AUTH_OTP_DEV_RETURN) {
      out.devOtp = code;
    }

    return res.json(out);

  } catch (e) {
    console.warn(
      "auth register resend failed:",
      e.message || e
    );

    return res.status(500).json({
      ok: false,
      error: "register_resend_failed",
      message:
        "❌ تعذّر إعادة إرسال كود التحقق الآن. حاول مرة أخرى."
    });
  }
});

