function belongs(rec, tenant){
  const t = rec && rec.userId ? rec.userId : '';
  return tenantKey(t) === tenantKey(tenant);
}

async function requireUserId(req, res, next){
  try {
    if (
      req.authSession?.userId &&
      req.userId
    ) {
      return next();
    }

    const session = await authSessionFromRequestBridgeSrv(req);

    if (!session?.userId) {
      authClearSessionCookieBridgeSrv(req, res);

      return res.status(401).json({
        ok: false,
        error: 'auth_required',
        message: '❌ يلزم تسجيل الدخول أولًا.'
      });
    }

    const accountDenied =
      authAccountDeniedBridgeSrv(session.accountStatus);

    if (accountDenied) {
      authClearSessionCookieBridgeSrv(req, res);

      return res.status(403).json({
        ok: false,
        ...accountDenied
      });
    }

    req.authSession = session;
    req.userId = session.userId;
    return next();

   } catch (e) {
    console.error(
      'requireUserId failed:',
      e.message || e
    );

    if (
      Number(
        e?.publicStatus || 0
      ) === 503
    ) {
      return res
        .status(503)
        .json({
          ok: false,

          error:
            e?.publicError ||
            'auth_profile_unavailable',

          message:
            e?.publicMessage ||
            '❌ تعذّر التحقق من حالة الحساب الآن. حاول مرة أخرى لاحقًا.'
        });
    }

    authClearSessionCookieBridgeSrv(
      req,
      res
    );

    return res.status(401).json({
      ok: false,
      error: 'auth_required',
      message:
        '❌ يلزم تسجيل الدخول أولًا.'
    });
  }
}
