// ============================================================
//                  DIM: Daily updater (server-side)
// ============================================================
function cairoTodayISO(){
  // "YYYY-MM-DD" بتوقيت القاهرة (لتحديد اليوم الصحيح فقط)
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "Africa/Cairo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).format(new Date());
}

function isoToUtcMidnightMs(iso){
  const [y,m,d] = String(iso).split("-").map(Number);
  return Date.UTC(y, m-1, d);
}

function diffDaysISO(fromISO, toISO){
  // فرق أيام “تاريخ فقط” (بدون ساعات/دقائق)
  const ms = isoToUtcMidnightMs(toISO) - isoToUtcMidnightMs(fromISO);
  return Math.floor(ms / 86400000);
}
function reproAutoNormArSrv(s) {
  return String(s || "")
    .trim()
    .replace(/\s+/g, " ")
    .replace(/[أإآ]/g, "ا")
    .replace(/ة/g, "ه")
    .replace(/ى/g, "ي");
}

function isFreshReproStatusForAutoOpenSrv(v) {
  const n = reproAutoNormArSrv(v);

  return (
    n === "حديثه الولاده" ||
    (n.includes("حديث") && n.includes("ولاد"))
  );
}

function reproAutoOpenThresholdDaysSrv(a = {}) {
  const t = String(
    a.animaltype ||
    a.animalTypeAr ||
    a.animalType ||
    a.species ||
    a.type ||
    ""
  ).trim().toLowerCase();

  const isBuffalo =
    t.includes("buffalo") ||
    t.includes("جاموس");

  // نفس السلوك الفعلي في repro-auto القديم:
  // جاموس: من 41 يوم، أبقار: من 50 يوم
  return isBuffalo ? 41 : 50;
}

function buildReproAutoOpenPatchSrv(a = {}, todayISO = "") {
  const reproNorm = reproAutoNormArSrv(a.reproductiveStatus);

  const isFresh = isFreshReproStatusForAutoOpenSrv(a.reproductiveStatus);
  const isAbortion = reproNorm.includes("اجهاض");

  if (!isFresh && !isAbortion) return null;
  if (a.breedingBlocked === true) return null;

  if (isAbortion) {
    const lad = String(
      a.lastAbortionDate ||
      a.abortionDate ||
      ""
    ).trim().slice(0, 10);

    if (!/^\d{4}-\d{2}-\d{2}$/.test(lad)) return null;

    const daysAfterAbortion = diffDaysISO(lad, todayISO);
    if (!Number.isFinite(daysAfterAbortion) || daysAfterAbortion < 40) return null;

    return {
      reproductiveStatus: "مفتوحة",
      reproAutoUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
      reproAutoReason: "AutoOpenAfter40DaysFromAbortion",
      reproAutoDaysAfterAbortion: daysAfterAbortion,
      reproAutoSource: "server:daily_maintenance"
    };
  }

  const lcd = String(
    a.lastCalvingDate ||
    a.calvingDate ||
    a.lastCalving ||
    ""
  ).trim().slice(0, 10);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(lcd)) return null;

  const dim = diffDaysISO(lcd, todayISO);
  if (!Number.isFinite(dim) || dim < 0) return null;

  const threshold = reproAutoOpenThresholdDaysSrv(a);
  if (dim < threshold) return null;

  return {
    reproductiveStatus: "مفتوحة",
    reproAutoUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
    reproAutoReason: `AutoOpenAfter${threshold}Days`,
    reproAutoDim: dim,
    reproAutoSource: "server:daily_maintenance"
  };
}
async function updateAllDIM(){
  try{
    if (!db) {
      console.log("⚠️ DIM skipped: Firestore disabled");
      return;
    }

    const todayISO = cairoTodayISO();

    const snap = await db.collection("animals").get();

    let updated = 0;
    let scanned = 0;
    const touchedTenants = new Set();

    let batch = db.batch();
    let ops = 0;

    for (const doc of snap.docs){
      scanned++;
      const a = doc.data() || {};

      const st = String(a.status || "active").toLowerCase();
      if (st === "inactive") continue;
      const reproPatch = buildReproAutoOpenPatchSrv(a, todayISO);

if (reproPatch) {
  batch.set(doc.ref, reproPatch, { merge: true });

  if (a.userId) touchedTenants.add(String(a.userId).trim());
  updated++;
  ops++;

  if (ops >= 400) {
    await batch.commit();
    batch = db.batch();
    ops = 0;
  }
}
      const productionStatusText = String(a.productionStatus || "").trim().toLowerCase();

const isDryAnimal =
  a.inMilk === false ||
  productionStatusText === "جاف" ||
  productionStatusText === "dry" ||
  productionStatusText.includes("جاف") ||
  productionStatusText.includes("dry");

if (isDryAnimal) {
  const needsDryDimReset =
    a.daysInMilk !== null ||
    a.dailyMilk !== null ||
    a.milkTodayKg !== null;

  if (needsDryDimReset) {
    batch.set(doc.ref, {
      daysInMilk: null,
      dailyMilk: null,
      milkTodayKg: null,
      _dimUpdatedAt: todayISO
    }, { merge: true });

    if (a.userId) touchedTenants.add(String(a.userId).trim());
    updated++;
    ops++;
  }

  if (ops >= 400) {
    await batch.commit();
    batch = db.batch();
    ops = 0;
  }

  continue;
}

      const lcd = String(a.lastCalvingDate || "").trim();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(lcd)) continue;

      let dim = diffDaysISO(lcd, todayISO);
      if (!Number.isFinite(dim) || dim < 0) dim = 0;

      if (Number(a.daysInMilk) === dim) continue;

      batch.set(doc.ref, { daysInMilk: dim, _dimUpdatedAt: todayISO }, { merge:true });
      if (a.userId) touchedTenants.add(String(a.userId).trim());
      updated++;
      ops++;

      if (ops >= 400){
        await batch.commit();
        batch = db.batch();
        ops = 0;
      }
    }

    if (ops > 0) await batch.commit();

// ✅ التوابع التي أجهضت:
// تظل reproductiveStatus = "إجهاض" لمدة 40 يومًا.
// بعد اكتمال 40 يومًا تعود «مفتوحة / تحت التلقيح».
const abortionFollowersSnap =
  await db
    .collection("calves")
    .where(
      "reproductiveStatus",
      "==",
      "إجهاض"
    )
    .get();

let followerBatch =
  db.batch();

let followerOps = 0;

for (const doc of abortionFollowersSnap.docs) {
  scanned++;

  const a =
    doc.data() || {};

  const st =
    String(a.status || "")
      .trim()
      .toLowerCase();

  if (
    st === "inactive" ||
    st === "archived"
  ) {
    continue;
  }

  const reproPatch =
    buildReproAutoOpenPatchSrv(
      a,
      todayISO
    );

  // قبل 40 يومًا ترجع null
  if (!reproPatch) {
    continue;
  }

  followerBatch.set(
    doc.ref,
    {
      ...reproPatch,

      followerStatus:
        "تحت التلقيح",

      status:
        "تحت التلقيح",

      pregnancyDays:
        null
    },
    { merge: true }
  );

  if (a.userId) {
    touchedTenants.add(
      String(a.userId).trim()
    );
  }

  updated++;
  followerOps++;

  if (followerOps >= 400) {
    await followerBatch.commit();

    followerBatch =
      db.batch();

    followerOps = 0;
  }
}

if (followerOps > 0) {
  await followerBatch.commit();
}

for (const uid of touchedTenants) {
      if (typeof scheduleGroupsRebuildSrv === 'function') {
        scheduleGroupsRebuildSrv(uid, 'daily_dim_update');
      }
    }

    console.log("✅ DIM updated:", { todayISO, scanned, updated, groupsRebuildQueued: touchedTenants.size });
  } catch (e){
    console.error("❌ DIM update failed:", e.message || e);
  }
}

function msUntilNextCairo0010(){
  // تشغيل يومي 00:10 بتوقيت القاهرة
  const now = new Date();
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "Africa/Cairo",
    hour12: false,
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit"
  }).formatToParts(now).reduce((acc,p)=>{ acc[p.type]=p.value; return acc; }, {});

  const y = Number(parts.year), m = Number(parts.month), d = Number(parts.day);
  const hh = Number(parts.hour), mm = Number(parts.minute), ss = Number(parts.second);

  const nowCairoUtcMs = Date.UTC(y, m-1, d, hh, mm, ss);

  const targetTodayUtcMs = Date.UTC(y, m-1, d, 0, 10, 0);
  const targetUtcMs = (nowCairoUtcMs < targetTodayUtcMs)
    ? targetTodayUtcMs
    : Date.UTC(y, m-1, d+1, 0, 10, 0);

  return Math.max(1000, targetUtcMs - nowCairoUtcMs);
}

function startDailyDimJob(){
  const first = msUntilNextCairo0010();
  console.log("⏳ DIM job scheduled (ms):", first);

  setTimeout(async () => {
    await updateAllDIM();
    setInterval(updateAllDIM, 24 * 60 * 60 * 1000);
  }, first);
}


// ===== Admin gate (optional) =====
const ADMIN_EMAILS   = (process.env.ADMIN_EMAILS || '').split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);
const ADMIN_DEV_OPEN = process.env.ADMIN_DEV_OPEN === '1';
async function ensureAdmin(req, res, next) {
  try {
    const header = req.headers.authorization || '';
    const m = header.match(/^Bearer (.+)$/);
    const idToken = m ? m[1] : (req.query.token || '');
    if (idToken && admin.apps.length) {
      const decoded = await admin.auth().verifyIdToken(idToken);
      const okClaim = decoded.admin === true;
      const okEmail = decoded.email && ADMIN_EMAILS.includes(decoded.email.toLowerCase());
      if (okClaim || okEmail) return next();
    }
    if (ADMIN_DEV_OPEN && req.query.dev === '1') return next();
    return res.status(404).send('Not Found');
  } catch {
    return res.status(404).send('Not Found');
  }
}
// ============================================================
//          ACCOUNT ADMIN GATE — session-first, production-safe
// ============================================================
const ACCOUNT_ADMIN_UIDS = (process.env.ADMIN_UIDS || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

function accountAdminAllowedSrv(decoded = {}) {
  const uid = String(decoded.uid || decoded.sub || '').trim();
  const email = String(decoded.email || '').trim().toLowerCase();

  return (
    decoded.admin === true ||
    (uid && ACCOUNT_ADMIN_UIDS.includes(uid)) ||
    (email && ADMIN_EMAILS.includes(email))
  );
}

async function ensureAccountAdminSrv(req, res, next) {
  try {
    if (!admin.apps.length) {
      return res.status(404).send('Not Found');
    }

    let decoded = null;

    const sessionCookie = authCookieValueBridgeSrv(req, AUTH_COOKIE_NAME);

    if (sessionCookie) {
      decoded = await admin.auth().verifySessionCookie(
        sessionCookie,
        true
      );
    }

    if (!decoded) {
      const header =
        String(req.headers.authorization || '');

      const m =
        header.match(/^Bearer\s+(.+)$/i);

      const idToken =
        m ? String(m[1] || '').trim() : '';

      if (idToken) {
        decoded = await admin.auth().verifyIdToken(
          idToken,
          true
        );
      }
    }

    if (!decoded || !accountAdminAllowedSrv(decoded)) {
      return res.status(404).send('Not Found');
    }

    req.accountAdminAuth = decoded;
    return next();

  } catch (_) {
    return res.status(404).send('Not Found');
  }
}
// ============================================================
//          ADMIN BOOTSTRAP — env allowlist -> custom admin claim
// ============================================================
async function ensureAccountAdminBootstrapSrv(req, res, next) {
  try {
    if (!admin.apps.length) {
      return res.status(404).send('Not Found');
    }

    const sessionCookie =
      authCookieValueBridgeSrv(req, AUTH_COOKIE_NAME);

    if (!sessionCookie) {
      return res.status(404).send('Not Found');
    }

    const decoded =
      await admin.auth().verifySessionCookie(
        sessionCookie,
        true
      );

    const uid =
      String(decoded?.uid || decoded?.sub || '').trim();

    if (!uid || !ACCOUNT_ADMIN_UIDS.includes(uid)) {
      return res.status(404).send('Not Found');
    }

    req.accountAdminAuth = decoded;
    return next();

  } catch (_) {
    return res.status(404).send('Not Found');
  }
}

async function ensureAccountAdminClaimSrv(req, res, next) {
  try {
    if (!admin.apps.length) {
      return res.status(404).send('Not Found');
    }

    const sessionCookie =
      authCookieValueBridgeSrv(req, AUTH_COOKIE_NAME);

    if (!sessionCookie) {
      return res.status(404).send('Not Found');
    }

    const decoded =
      await admin.auth().verifySessionCookie(
        sessionCookie,
        true
      );

    if (decoded?.admin !== true) {
      return res.status(404).send('Not Found');
    }

    req.accountAdminAuth = decoded;
    return next();

  } catch (_) {
    return res.status(404).send('Not Found');
  }
}
// ============================================================
//       ADMIN API HARDENING — no-store + same-origin writes
// ============================================================

function adminSensitiveHeadersSrv(req, res, next) {
  res.setHeader(
    'Cache-Control',
    'no-store, max-age=0'
  );

  res.setHeader(
    'Pragma',
    'no-cache'
  );

  res.setHeader(
    'Expires',
    '0'
  );

  res.setHeader(
    'X-Content-Type-Options',
    'nosniff'
  );

  return next();
}

function adminRequestSourceOriginSrv(req) {
  const rawOrigin =
    String(
      req.get('origin') || ''
    ).trim();

  if (
    rawOrigin &&
    rawOrigin !== 'null'
  ) {
    try {
      return new URL(
        rawOrigin
      ).origin;
    } catch (_) {
      return '';
    }
  }

  const rawReferer =
    String(
      req.get('referer') || ''
    ).trim();

  if (!rawReferer) {
    return '';
  }

  try {
    return new URL(
      rawReferer
    ).origin;
  } catch (_) {
    return '';
  }
}

function adminRequestTargetOriginSrv(req) {
  const protocol =
    String(
      req.protocol || ''
    )
      .trim()
      .toLowerCase();

  const host =
    String(
      req.get('host') || ''
    ).trim();

  if (!protocol || !host) {
    return '';
  }

  try {
    return new URL(
      `${protocol}://${host}`
    ).origin;
  } catch (_) {
    return '';
  }
}

function adminMutationRequestGuardSrv(req, res, next) {
  const method =
    String(
      req.method || 'GET'
    )
      .trim()
      .toUpperCase();

  if (
    method === 'GET' ||
    method === 'HEAD' ||
    method === 'OPTIONS'
  ) {
    return next();
  }

  const fetchSite =
    String(
      req.get('sec-fetch-site') || ''
    )
      .trim()
      .toLowerCase();

  if (
    fetchSite === 'cross-site' ||
    fetchSite === 'same-site'
  ) {
    return res.status(403).json({
      ok: false,
      error:
        'admin_cross_origin_blocked',
      message:
        '🚫 تم رفض طلب إداري من مصدر غير موثوق.'
    });
  }

  const sourceOrigin =
    adminRequestSourceOriginSrv(
      req
    );

  const targetOrigin =
    adminRequestTargetOriginSrv(
      req
    );

  if (
    !sourceOrigin ||
    !targetOrigin ||
    sourceOrigin !== targetOrigin
  ) {
    return res.status(403).json({
      ok: false,
      error:
        'admin_origin_verification_failed',
      message:
        '🚫 تعذّر التحقق من مصدر الطلب الإداري.'
    });
  }

  const requestMarker =
    String(
      req.get(
        'x-murabbik-admin-request'
      ) || ''
    ).trim();

  if (requestMarker !== '1') {
    return res.status(403).json({
      ok: false,
      error:
        'admin_request_marker_missing',
      message:
        '🚫 الطلب الإداري غير موثّق.'
    });
  }

  return next();
}

