function normalizeEventType(raw) {
  const t = String(raw || '').toLowerCase();
  for (const [norm, arr] of Object.entries(EVENT_SYNONYMS)) {
    for (const w of arr) {
      if (t.includes(w.toLowerCase())) return norm;
    }
  }
  return t;
}
// ============================================================
//                 API: ADD ANIMAL — SERVER SIDE SAVE
//                 تسجيل حيوان جديد من السيرفر فقط
// ============================================================

function addAnimalDigitsSrv(v) {
  const map = {
    "٠":"0","١":"1","٢":"2","٣":"3","٤":"4","٥":"5","٦":"6","٧":"7","٨":"8","٩":"9",
    "۰":"0","۱":"1","۲":"2","۳":"3","۴":"4","۵":"5","۶":"6","۷":"7","۸":"8","۹":"9"
  };

  return String(v || "")
    .trim()
    .replace(/[^\d٠-٩۰-۹]/g, "")
    .replace(/[٠-٩۰-۹]/g, d => map[d] || d);
}

function addAnimalStrSrv(v) {
  return String(v ?? "").trim();
}
function addAnimalSireNumberSrv(fd = {}) {
  return addAnimalStrSrv(fd.sireNumber);
}
function addAnimalNumSrv(v, fallback = 0) {
  if (v === "" || v === null || v === undefined) return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function addAnimalIsDateSrv(v) {
  const s = String(v || "").trim().slice(0, 10);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    return false;
  }

  const [year, month, day] =
    s.split("-").map(Number);

  const d =
    new Date(Date.UTC(year, month - 1, day));

  return (
    d.getUTCFullYear() === year &&
    d.getUTCMonth() === month - 1 &&
    d.getUTCDate() === day
  );
}

function addAnimalDateOrNullSrv(v) {
  const s = String(v || "").trim().slice(0, 10);
  return addAnimalIsDateSrv(s) ? s : null;
}

function addAnimalTodaySrv() {
  return typeof cairoTodayISO === "function"
    ? cairoTodayISO()
    : new Date().toISOString().slice(0, 10);
}

function addAnimalDiffDaysSrv(fromISO, toISO) {
  if (!addAnimalIsDateSrv(fromISO) || !addAnimalIsDateSrv(toISO)) return null;

  const [fy, fm, fd] = String(fromISO).slice(0, 10).split("-").map(Number);
  const [ty, tm, td] = String(toISO).slice(0, 10).split("-").map(Number);

  const a = Date.UTC(fy, fm - 1, fd);
  const b = Date.UTC(ty, tm - 1, td);
  const d = Math.floor((b - a) / 86400000);

  return Number.isFinite(d) && d >= 0 ? d : null;
}

function addAnimalSpeciesFromTypeSrv(animalType) {
  const raw = addAnimalStrSrv(animalType);

  if (raw === "بقرة" || /cow|بقر|ابقار|أبقار/i.test(raw)) {
    return {
      animalTypeAr: "بقرة",
      animaltype: "cow",
      species: "أبقار"
    };
  }

  if (raw === "جاموسة" || /buffalo|جاموس/i.test(raw)) {
    return {
      animalTypeAr: "جاموسة",
      animaltype: "buffalo",
      species: "جاموس"
    };
  }

  return {
    animalTypeAr: raw,
    animaltype: "",
    species: ""
  };
}

function addAnimalBasicFieldsDecisionSrv(fd = {}, options = {}) {
  const errors = {};
  const partial = options.partial === true;

  if (
    !partial &&
    !addAnimalDigitsSrv(fd.animalNumber || fd.number || fd.calfNumber)
  ) {
    errors.animalNumber = "أدخل رقم الحيوان.";
  }

  if (
    !partial &&
    !addAnimalStrSrv(fd.animalType || fd.animalTypeAr)
  ) {
    errors.animalType = "اختر نوع الحيوان.";
  }

  if (!partial && !addAnimalStrSrv(fd.breed)) {
    errors.breed = "اختر السلالة.";
  }

  if (!partial && !addAnimalStrSrv(fd.birthDate)) {
    errors.birthDate = "أدخل تاريخ ميلاد الحيوان.";
  }

  const entryType = addAnimalStrSrv(fd.entryType);

  if (!entryType) {
    if (!partial) {
      errors.entryType = "اختر نوع الإدخال.";
    }
  } else if (!["mothers", "followers"].includes(entryType)) {
    errors.entryType = "نوع الإدخال غير صحيح.";
  }

  const dateFields = [
    ["birthDate", "أدخل تاريخ ميلاد صحيحًا."],
    ["lastCalvingDate", "أدخل تاريخ آخر ولادة صحيحًا."],
    ["lastInseminationDate", "أدخل تاريخ آخر تلقيح صحيحًا."],
    ["weaningDate", "أدخل تاريخ فطام صحيحًا."],
    ["followerLastInseminationDate", "أدخل تاريخ آخر تلقيح صحيحًا."]
  ];

  for (const [field, msg] of dateFields) {
    if (addAnimalStrSrv(fd[field]) && !addAnimalIsDateSrv(fd[field])) {
      errors[field] = msg;
    }
  }

  const numFields = [
    ["dailyMilk", "أدخل إنتاج اللبن بقيمة رقمية صحيحة."],
    ["servicesCount", "أدخل عدد مرات التلقيح بقيمة رقمية صحيحة."],
    ["lactationNumber", "أدخل رقم موسم حليب صحيحًا."],
    ["daysInMilk", "أدخل عدد أيام الحليب بقيمة رقمية صحيحة."],
    ["pregnancyDays", "أدخل عدد أيام الحمل بقيمة رقمية صحيحة."],
    ["followerServicesCount", "أدخل عدد مرات التلقيح بقيمة رقمية صحيحة."],
    ["followerPregnancyDays", "أدخل عدد أيام الحمل بقيمة رقمية صحيحة."]
  ];

  for (const [field, msg] of numFields) {
    const val = addAnimalStrSrv(fd[field]);

    if (val && !Number.isFinite(Number(val))) {
      errors[field] = msg;
    }
  }

  const birthDate = addAnimalDateOrNullSrv(fd.birthDate);
const lastCalvingDate = addAnimalDateOrNullSrv(fd.lastCalvingDate);
const today = addAnimalTodaySrv();
if (
  entryType === "mothers" &&
  birthDate &&
  !errors.birthDate
) {
  const speciesInfo =
    addAnimalSpeciesFromTypeSrv(
      fd.animalType ||
      fd.animalTypeAr
    );

  if (birthDate > today) {
    errors.birthDate =
      "❌ تاريخ الميلاد لا يمكن أن يكون في المستقبل.";
  } else {
    const [by, bm, bd] =
      birthDate.split("-").map(Number);

    const [ty, tm, td] =
      today.split("-").map(Number);

    let ageTodayMonths =
      (ty - by) * 12 + (tm - bm);

    if (td < bd) {
      ageTodayMonths -= 1;
    }

    const minMotherAgeMonths =
      speciesInfo.animaltype === "cow"
        ? 18
        : speciesInfo.animaltype === "buffalo"
          ? 24
          : null;

    if (
      Number.isFinite(ageTodayMonths) &&
      Number.isFinite(minMotherAgeMonths) &&
      ageTodayMonths < minMotherAgeMonths
    ) {
      errors.birthDate =
        speciesInfo.animaltype === "cow"
          ? "❌ لا يمكن تسجيل هذه البقرة ضمن الأمهات: عمرها أقل من 18 شهرًا."
          : "❌ لا يمكن تسجيل هذه الجاموسة ضمن الأمهات: عمرها أقل من 24 شهرًا.";
    }
  }
}   

if (
  entryType === "mothers" &&
  birthDate &&
  lastCalvingDate &&
  !errors.birthDate &&
  !errors.lastCalvingDate
) {
  // استحالة زمنية مطلقة:
  // لا يمكن أن تسبق آخر ولادة تاريخ ميلاد الحيوان.
  if (lastCalvingDate < birthDate) {
    errors.lastCalvingDate =
      "❌ تاريخ آخر ولادة لا يمكن أن يسبق تاريخ ميلاد الحيوان. راجع التاريخين.";
  } else {
    const speciesInfo =
      addAnimalSpeciesFromTypeSrv(
        fd.animalType ||
        fd.animalTypeAr
      );

    const [by, bm, bd] =
      birthDate.split("-").map(Number);

    const [cy, cm, cd] =
      lastCalvingDate.split("-").map(Number);

    let ageAtCalvingMonths =
      (cy - by) * 12 + (cm - bm);

    if (cd < bd) {
      ageAtCalvingMonths -= 1;
    }

    // أرضية لمنع بيانات ولادة مستحيلة بيولوجيًا.
    // تطبق على أي موسم، وليست مرتبطة بالموسم الأول.
    const minimumPossibleCalvingAgeMonths =
      speciesInfo.animaltype === "cow"
        ? 18
        : speciesInfo.animaltype === "buffalo"
          ? 24
          : null;

       if (
      Number.isFinite(ageAtCalvingMonths) &&
      Number.isFinite(
        minimumPossibleCalvingAgeMonths
      ) &&
      ageAtCalvingMonths <
        minimumPossibleCalvingAgeMonths
    ) {
      errors.lastCalvingDate =
        speciesInfo.animaltype === "cow"
          ? "❌ البيانات غير منطقية: عمر البقرة عند آخر ولادة أقل من 18 شهرًا. راجع تاريخ الميلاد أو تاريخ آخر ولادة."
          : "❌ البيانات غير منطقية: عمر الجاموسة عند آخر ولادة أقل من 24 شهرًا. راجع تاريخ الميلاد أو تاريخ آخر ولادة.";
    }
  }
}

const lastInseminationDate =
  addAnimalDateOrNullSrv(
    fd.lastInseminationDate
  );

if (
  entryType === "mothers" &&
  lastCalvingDate &&
  lastInseminationDate &&
  !errors.lastCalvingDate &&
  !errors.lastInseminationDate &&
  lastInseminationDate <= lastCalvingDate
) {
  errors.lastInseminationDate =
    "❌ تاريخ آخر تلقيح يجب أن يكون بعد تاريخ آخر ولادة. راجع التاريخين.";
}

  return errors;
}

function addAnimalDecisionSrv(fd = {}) {
  const mode = addAnimalStrSrv(fd.entryType);

  if (mode === "mothers") {
    if (!addAnimalStrSrv(fd.productionStatus)) {
      return "❌ اختر الحالة الإنتاجية للحيوان.";
    }

    if (!addAnimalStrSrv(fd.reproductiveStatus)) {
      return "❌ اختر الحالة التناسلية للحيوان.";
    }

    if (
      addAnimalStrSrv(fd.productionStatus) === "حلاب" &&
      !addAnimalStrSrv(fd.dailyMilk)
    ) {
      return "❌ أدخل إنتاج اللبن اليومي للحيوان الحلاب.";
    }

    const repro = addAnimalStrSrv(fd.reproductiveStatus);
    const services = addAnimalNumSrv(fd.servicesCount, 0);

    const needsSireNumber =
      repro === "ملقحة" ||
      repro === "ملقح" ||
      repro === "عشار";

    if (needsSireNumber && !addAnimalSireNumberSrv(fd)) {
      return "❌ أدخل رقم الطلوقة للحيوان العشار أو الملقح.";
    }

    if (
      (
        repro === "ملقحة" ||
        repro === "ملقح" ||
        repro === "عشار" ||
        services > 0
      ) &&
      !addAnimalStrSrv(fd.lastInseminationDate)
    ) {
      return "❌ أدخل تاريخ آخر تلقيح للحيوان العشار أو الملقح أو الذي سبق تلقيحه في الموسم.";
    }

    return null;
  }

  if (mode === "followers") {
    const sex = addAnimalStrSrv(fd.followerSex);
    const st = addAnimalStrSrv(fd.followerStatus);

    if (!sex) {
      return "❌ اختر جنس التابع.";
    }

    if (!st) {
      return "❌ اختر الحالة الحالية للتابع.";
    }

    const femaleStatuses = [
      "رضيع",
      "فطام",
      "نامي",
      "تحت التلقيح",
      "ملقح",
      "عشار"
    ];

    const maleStatuses = [
      "رضيع",
      "فطام",
      "نامي"
    ];

    if (sex === "أنثى" && !femaleStatuses.includes(st)) {
      return "❌ الحالة الحالية لا تتوافق مع تابع أنثى.";
    }

    if (sex === "ذكر" && !maleStatuses.includes(st)) {
      return "❌ الحالة الحالية لا تتوافق مع تابع ذكر.";
    }

    if (sex !== "أنثى" && sex !== "ذكر") {
      return "❌ جنس التابع غير صحيح.";
    }

      const damNumber =
      addAnimalStrSrv(fd.damNumber);

    const damReferenceStatus =
      addAnimalStrSrv(
        fd.damReferenceStatus ||
        (damNumber ? "known" : "unknown")
      );

    if (
      ![
        "known",
        "unknown",
        "deceased"
      ].includes(damReferenceStatus)
    ) {
      return "❌ اختر حالة بيانات الأم بصورة صحيحة.";
    }

    if (
      damReferenceStatus === "known" &&
      !damNumber
    ) {
      return "❌ أدخل رقم أم التابع أو اختر أن بيانات الأم غير معروفة.";
    }

    if (
      st === "فطام" &&
      !addAnimalStrSrv(fd.weaningDate)
    ) {
      return "❌ أدخل تاريخ فطام التابع.";
    }

    const isInseminatedFollower =
      st === "ملقح" ||
      st === "عشار";

    if (
      isInseminatedFollower &&
      !addAnimalStrSrv(fd.followerLastInseminationDate)
    ) {
      return "❌ أدخل تاريخ آخر تلقيح للتابع.";
    }

    if (
      isInseminatedFollower &&
      !addAnimalStrSrv(fd.followerSireNumber)
    ) {
      return "❌ أدخل رقم طلوقة آخر تلقيح للتابع.";
    }

    return null;
  }

  return "❌ اختر نوع الإدخال: حيوان رئيسي أو تابع.";
}

async function addAnimalDuplicateCheckSrv(uid, numberStr) {
  if (!db || !uid || !numberStr) {
    return {
      ok: false,
     message: "❌ تعذّر فحص رقم الحيوان الآن. حاول مرة أخرى."
    };
  }

  const key = `${uid}#${numberStr}`;
  const nNum = Number(numberStr);
  const collectionsToCheck = ["animals", "calves"];

  for (const colName of collectionsToCheck) {
    const q1 = await db.collection(colName)
      .where("userId_number", "==", key)
      .limit(1)
      .get();

    if (!q1.empty) {
      return {
        ok: false,
        duplicate: true,
        collection: colName,
        message: `❌ الرقم ${numberStr} مسجل بالفعل لحيوان في حسابك.`
      };
    }

    const q2 = await db.collection(colName)
      .where("userId", "==", uid)
      .where("number", "==", numberStr)
      .limit(1)
      .get();

    if (!q2.empty) {
      return {
        ok: false,
        duplicate: true,
        collection: colName,
        message: `❌ الرقم ${numberStr} مسجل بالفعل لحيوان في حسابك.`
      };
    }

    if (Number.isFinite(nNum)) {
      const q3 = await db.collection(colName)
        .where("userId", "==", uid)
        .where("animalNumber", "==", nNum)
        .limit(1)
        .get();

      if (!q3.empty) {
        return {
          ok: false,
          duplicate: true,
          collection: colName,
          message: `❌ الرقم ${numberStr} مسجل بالفعل لحيوان في حسابك.`
        };
      }
    }
  }

  return { ok: true };
}
