function addAnimalBuildSinglePayloadSrv(uid, fd = {}) {
  const entryType = addAnimalStrSrv(fd.entryType || "mothers");
  const numberStr = addAnimalDigitsSrv(fd.animalNumber || fd.number || fd.calfNumber);
  const speciesInfo = addAnimalSpeciesFromTypeSrv(fd.animalType || fd.animalTypeAr);
  const key = `${uid}#${numberStr}`;
  const today = addAnimalTodaySrv();

   if (entryType === "followers") {
    const followerStatus = addAnimalStrSrv(fd.followerStatus);
    const followerSex = addAnimalStrSrv(fd.followerSex);
    const followerLastAI = addAnimalDateOrNullSrv(
      fd.followerLastInseminationDate
    );

    const followerFatherNumber = addAnimalStrSrv(fd.fatherNumber);

     const followerInseminationSireNumber = addAnimalStrSrv(
      fd.followerSireNumber
    );

    const followerDamNumber =
      addAnimalStrSrv(fd.damNumber);

    const rawDamReferenceStatus =
      addAnimalStrSrv(fd.damReferenceStatus);

    const followerDamReferenceStatus =
      followerDamNumber
        ? "known"
        : ["unknown", "deceased"].includes(
            rawDamReferenceStatus
          )
          ? rawDamReferenceStatus
          : "unknown";

    const isInseminatedFollower =
      followerStatus === "ملقح" ||
      followerStatus === "عشار";

    const followerReproductiveStatus =
      followerStatus === "عشار"
        ? "عشار"
        : followerStatus === "ملقح"
          ? "ملقحة"
          : followerStatus === "تحت التلقيح"
            ? "مفتوحة"
            : "";

    const followerPregDays =
      followerStatus === "عشار" && followerLastAI
        ? addAnimalDiffDaysSrv(followerLastAI, today)
        : addAnimalNumSrv(fd.followerPregnancyDays, 0);

    return {
      collectionName: "calves",

      payload: {
        ownerUid: uid,
        userId: uid,
        userId_number: key,
        entryType: "followers",

        calfNumber: numberStr,
        number: numberStr,
        animalNumber: Number(numberStr),

        species: speciesInfo.species,
        animaltype: speciesInfo.animaltype,
        animalTypeAr: speciesInfo.animalTypeAr,
        breed: addAnimalStrSrv(fd.breed),

        sex: followerSex,
        status: followerStatus,
        followerStatus,

        reproductiveStatus:
          followerReproductiveStatus || null,

        birthDate:
          addAnimalDateOrNullSrv(fd.birthDate),

          damNumber:
          followerDamNumber || null,

        damReferenceStatus:
          followerDamReferenceStatus,

        ...(followerFatherNumber
          ? {
              sireNumber: followerFatherNumber,
              fatherNumber: followerFatherNumber,
              sireSource:
                addAnimalStrSrv(fd.sireSource) ||
                "manual_add_animal"
            }
          : {}),

        weaningDate:
          followerStatus === "فطام"
            ? addAnimalDateOrNullSrv(fd.weaningDate)
            : null,

        lastInseminationDate:
          isInseminatedFollower
            ? followerLastAI
            : null,

        servicesCount:
          isInseminatedFollower
            ? addAnimalNumSrv(fd.followerServicesCount, 0)
            : 0,

        inseminationSireNumber:
          isInseminatedFollower
            ? followerInseminationSireNumber || null
            : null,

        pregnancyDays:
          followerStatus === "عشار"
            ? (
                Number.isFinite(Number(followerPregDays))
                  ? Number(followerPregDays)
                  : null
              )
            : null,

        createdAt:
          admin.firestore.FieldValue.serverTimestamp(),

        updatedAt:
          admin.firestore.FieldValue.serverTimestamp(),

        source:
          "server:/api/add-animal/save"
      }
    };
  }
  const productionStatus = addAnimalStrSrv(fd.productionStatus);
  const reproductiveStatus = addAnimalStrSrv(fd.reproductiveStatus);
  const lastCalvingDate = addAnimalDateOrNullSrv(fd.lastCalvingDate);
  const lastAI = addAnimalDateOrNullSrv(fd.lastInseminationDate);
  const servicesCount = addAnimalNumSrv(fd.servicesCount, 0);
  const sireNumber = addAnimalSireNumberSrv(fd) || null;
  

 const hasMotherInseminationHistory =
  reproductiveStatus === "ملقحة" ||
  reproductiveStatus === "ملقح" ||
  reproductiveStatus === "عشار" ||
  servicesCount > 0;

const daysInMilk =
  productionStatus === "جاف"
    ? null
    : lastCalvingDate
      ? addAnimalDiffDaysSrv(lastCalvingDate, today)
      : null;

const pregnancyDays =
  reproductiveStatus === "عشار" && lastAI
    ? addAnimalDiffDaysSrv(lastAI, today)
    : addAnimalNumSrv(fd.pregnancyDays, 0);
  return {
    collectionName: "animals",
    payload: {
      ownerUid: uid,
      userId: uid,
      userId_number: key,
      entryType: "mothers",

      number: numberStr,
      animalNumber: Number(numberStr),

      animaltype: speciesInfo.animaltype,
      animalTypeAr: speciesInfo.animalTypeAr,
      species: speciesInfo.species,
      breed: addAnimalStrSrv(fd.breed),

      productionStatus,
      dailyMilk: productionStatus === "حلاب"
        ? Number(addAnimalNumSrv(fd.dailyMilk, 0))
        : null,

      reproductiveStatus,
      servicesCount,
      lactationNumber: addAnimalNumSrv(fd.lactationNumber, 0),

      birthDate: addAnimalDateOrNullSrv(fd.birthDate),
      lastCalvingDate,
      lastInseminationDate: hasMotherInseminationHistory ? lastAI : null,
      sireNumber: hasMotherInseminationHistory ? sireNumber : null,

      daysInMilk: Number.isFinite(Number(daysInMilk)) ? Number(daysInMilk) : null,
      pregnancyDays: reproductiveStatus === "عشار"
        ? (Number.isFinite(Number(pregnancyDays)) ? Number(pregnancyDays) : null)
        : null,

      status: "active",

      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      source: "server:/api/add-animal/save"
    }
  };
}
async function addAnimalWriteSingleSrv(uid, fd = {}, options = {}) {
  const canonical =
    addAnimalBuildSinglePayloadSrv(uid, fd);

  const payloadPatch =
    options.payloadPatch &&
    typeof options.payloadPatch === "object"
      ? options.payloadPatch
      : {};

  const payload = {
    ...canonical.payload,
    ...payloadPatch
  };

  const source =
    addAnimalStrSrv(options.source);

  if (source) {
    payload.source = source;
  }

  const ref =
    options.ref ||
    db.collection(canonical.collectionName).doc();

  if (options.batch) {
    options.batch.set(ref, payload);
  } else {
    await ref.set(payload);
  }

  return {
    collectionName:
      canonical.collectionName,

    payload,
    ref,
    animalId: ref.id
  };
}
