// ============================================================
//                 API: ADD ANIMAL — SERVER SIDE IMPORT
//                 استيراد الحيوانات من السيرفر فقط
// ============================================================

function addAnimalImportRowsSrv(body = {}) {
  if (Array.isArray(body.rows)) return body.rows;
  if (Array.isArray(body.preview)) return body.preview;
  if (Array.isArray(body.records)) return body.records;
  if (Array.isArray(body.formData?.rows)) return body.formData.rows;
  return [];
}
function addAnimalImportDecodeBase64Srv(fileBase64 = "") {
  const raw = String(fileBase64 || "").trim();
  if (!raw) return Buffer.alloc(0);

  const clean = raw.includes(",")
    ? raw.split(",").pop()
    : raw;

  return Buffer.from(clean, "base64");
}

function addAnimalImportSplitCsvLineSrv(line) {
  const out = [];
  let cur = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    const next = line[i + 1];

    if (ch === '"') {
      if (inQuotes && next === '"') {
        cur += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === "," && !inQuotes) {
      out.push(cur.trim());
      cur = "";
    } else {
      cur += ch;
    }
  }

  out.push(cur.trim());
  return out;
}

function addAnimalImportParseCsvTextSrv(text = "") {
  const lines = String(text || "")
    .replace(/^\uFEFF/, "")
    .split(/\r?\n/)
    .map(s => s.trim())
    .filter(Boolean);

  if (!lines.length) return [];

  const headers = addAnimalImportSplitCsvLineSrv(lines[0])
    .map(h => String(h || "").trim())
    .filter(Boolean);

  if (!headers.length) return [];

  return lines.slice(1).map(line => {
    const vals = addAnimalImportSplitCsvLineSrv(line);
    const row = {};

    headers.forEach((h, i) => {
      row[h] = vals[i] ?? "";
    });

    return row;
  }).filter(r => Object.keys(r).length > 0);
}

function addAnimalImportNormalizeSheetRowsSrv(rows = []) {
  return rows
    .map(r => {
      const clean = {};
      Object.keys(r || {}).forEach(k => {
        const key = String(k || "").trim();
        if (!key) return;
        clean[key] = r[k] == null ? "" : String(r[k]).trim();
      });
      return clean;
    })
    .filter(r => Object.keys(r).length > 0);
}

function addAnimalImportParseUploadedFileSrv(body = {}) {
  const fileName = String(body.fileName || body.filename || "").toLowerCase().trim();
  const fileBase64 = String(body.fileBase64 || body.base64 || "").trim();

  if (!fileBase64) return [];

  const buf = addAnimalImportDecodeBase64Srv(fileBase64);
  if (!buf.length) return [];

  if (fileName.endsWith(".csv") || fileName.endsWith(".txt")) {
    return addAnimalImportParseCsvTextSrv(buf.toString("utf8"));
  }

  if (fileName.endsWith(".xlsx") || fileName.endsWith(".xls")) {
    const XLSX = require("xlsx");

    const wb = XLSX.read(buf, { type: "buffer" });
    const firstSheetName = wb.SheetNames?.[0];

    if (!firstSheetName) return [];

    const sheet = wb.Sheets[firstSheetName];
    if (!sheet) return [];

    const jsonRows = XLSX.utils.sheet_to_json(sheet, {
      defval: "",
      raw: false
    });

    return addAnimalImportNormalizeSheetRowsSrv(jsonRows);
  }

  return [];
}

function addAnimalImportRowsFromBodySrv(body = {}) {
  const existing = addAnimalImportRowsSrv(body);
  if (existing.length) return existing;

  return addAnimalImportParseUploadedFileSrv(body);
}
function herdImportV2TemplateErrorSrv(message) {
  const err = new Error("herd_import_v2_template_invalid");

  err.status = 400;
  err.code = "herd_import_v2_template_invalid";
  err.publicMessage = message;

  return err;
}

function herdImportV2ParseApprovedTemplateSrv(body = {}) {
  const fileName = String(
    body.fileName ||
    body.filename ||
    ""
  ).toLowerCase().trim();

  const fileBase64 = String(
    body.fileBase64 ||
    body.base64 ||
    ""
  ).trim();

  if (!fileName.endsWith(".xlsx") || !fileBase64) {
    throw herdImportV2TemplateErrorSrv(
      "❌ استخدم ملف Excel بصيغة XLSX من قالب مُرَبِّيك المعتمد."
    );
  }

  const buf =
    addAnimalImportDecodeBase64Srv(
      fileBase64
    );

  if (!buf.length) {
    throw herdImportV2TemplateErrorSrv(
      "❌ تعذّرت قراءة ملف القالب. حمّل قالب مُرَبِّيك من الصفحة ثم أعد تعبئته."
    );
  }

  const XLSX = require("xlsx");

  const wb = XLSX.read(
    buf,
    {
      type: "buffer"
    }
  );

  const sheetNames = [
    ...(wb.SheetNames || [])
  ];

  const hasMothersSheet =
    sheetNames.includes(
      "الأمهات"
    );

  const hasFollowersSheet =
    sheetNames.includes(
      "التوابع"
    );

  if (
    !hasMothersSheet ||
    !hasFollowersSheet
  ) {
    throw herdImportV2TemplateErrorSrv(
      "❌ الملف لا يطابق قالب مُرَبِّيك المعتمد. يجب أن يحتوي على شيت «الأمهات» وشيت «التوابع»."
    );
  }

  const readSheetRows = (
    sheetName,
    entryType = ""
  ) => {
    const sheet =
      wb.Sheets[sheetName];

    if (!sheet) return [];

    const jsonRows =
      XLSX.utils.sheet_to_json(
        sheet,
        {
          defval: "",
          raw: false
        }
      );

    return jsonRows
      .map((sourceRow, index) => {
        const normalizedRows =
          addAnimalImportNormalizeSheetRowsSrv(
            [sourceRow]
          );

        const row =
          normalizedRows[0] || null;

        if (!row) return null;

        const sourceRowNumber =
          Number(sourceRow?.__rowNum__);

        const excelRowNumber =
          Number.isInteger(sourceRowNumber)
            ? sourceRowNumber + 1
            : index + 2;

        Object.defineProperties(
          row,
          {
            __murabbikEntryType: {
              value: entryType,
              enumerable: false,
              configurable: false
            },

            __murabbikSheetName: {
              value: sheetName,
              enumerable: false,
              configurable: false
            },

            __murabbikRowNumber: {
              value: excelRowNumber,
              enumerable: false,
              configurable: false
            }
          }
        );

        return row;
      })
      .filter(Boolean);
  };

  const mothersRows =
    readSheetRows(
      "الأمهات",
      "mothers"
    );

  const followersRows =
    readSheetRows(
      "التوابع",
      "followers"
    );

  const eventRows =
    readSheetRows(
      "الأحداث"
    );

  return {
    animalRows: [
      ...mothersRows,
      ...followersRows
    ],

    eventRows,
    sheetNames,

    sheets: {
      mothers: {
        exists: hasMothersSheet,
        rowsCount: mothersRows.length
      },

      followers: {
        exists: hasFollowersSheet,
        rowsCount: followersRows.length
      },

      events: {
        exists:
          sheetNames.includes(
            "الأحداث"
          ),

        rowsCount:
          eventRows.length
      }
    }
  };
}
