      heatStatus: String(ev.heatStatus ?? "").trim(),
      heatTime: String(ev.heatTime ?? ev.observationTime ?? "").trim(),

      pregnancyMethod: String(ev.method ?? ev.pregnancyMethod ?? "").trim(),
      pregnancyResult: String(ev.result ?? ev.pregnancyResult ?? "").trim(),
