//                 CALVING CALF UNIQUE CHECK — moved from form-rules.js
//                 نقل كما هو من uniqueCalfNumbers
// ============================================================

async function uniqueCalfNumbersSrv(ctx) {
  const userId = String(ctx.userId || "").trim();
  const nums = Array.isArray(ctx.calfNumbers) ? ctx.calfNumbers : [];

  const cleaned = nums
    .map(calvingNormDigitsOnlySrv)
    .filter(Boolean);

  if (!userId || cleaned.length === 0) return { ok: true };

  // منع تكرار داخل نفس الطلب
  const s = new Set();
  for (const n of cleaned){
    if (s.has(n)) return { ok:false, msg:`❌ رقم العجل ${n} مكرر داخل نفس الولادة.` };
    s.add(n);
  }

  // شيك قاعدة البيانات
  for (const n of cleaned){
    const snap = await db.collection("calves")
      .where("userId", "==", userId)
      .where("calfNumber", "==", n)
      .limit(1)
      .get();

    if (!snap.empty){
     return { ok:false, msg:`❌ رقم العجل ${n} مسجل من قبل. اختر رقمًا آخر.` };
    }
  }

  return { ok:true };
}
function calvingFirstNonEmptySrv(row = {}, keys = [], fallback = "") {
  for (const k of keys) {
    const v = row?.[k];
    if (v !== null && v !== undefined && String(v).trim() !== "") {
      return String(v).trim();
    }
  }
  return fallback;
}

function calvingSireLineageFromInseminationEventSrv(e = {}, aiDate = "") {
  const source = {
  ...(
    e?.details &&
    typeof e.details === "object"
      ? e.details
      : {}
  ),
  ...e
};
  const sireNumber = calvingFirstNonEmptySrv(source, [
    "sireNumber",
    "fatherNumber",
    "sireId",
    "bullNumber",
    "bullCode",
    "semenCode",
    "semenNumber",
    "strawCode",
    "sire",
    "bull",
    "semen"
  ]);

  const semenCode = calvingFirstNonEmptySrv(source, [
    "semenCode",
    "semenNumber",
    "strawCode",
    "straw",
    "bullCode",
    "sireNumber",
    "fatherNumber",
    "bullNumber",
    "sire",
    "bull",
    "semen"
  ]);

  const sireName = calvingFirstNonEmptySrv(source, [
    "sireName",
    "fatherName",
    "bullName"
  ]);

  const finalSire = sireNumber || semenCode || "";

  if (!finalSire && !sireName) return null;

  return {
    sireNumber: finalSire,
    fatherNumber: finalSire,
    bullNumber: finalSire,
    semenCode: semenCode || finalSire,
    sireName,
    fatherName: sireName,
    sireSource: "last_fertile_insemination",
    sireEventId: String(e.id || "").trim(),
    sireInseminationDate: String(e.eventDate || e.date || aiDate || "").trim().slice(0, 10)
  };
}

async function calvingFindSireLineageForCalvesSrv({ userId, animalNumber, lastInseminationDate } = {}) {
  const uid = String(userId || "").trim();
  const damNumber = calvingNormDigitsOnlySrv(animalNumber || "");
  const aiDate = String(lastInseminationDate || "").trim().slice(0, 10);

  if (!db || !uid || !damNumber || !calvingIsDateSrv(aiDate)) return null;

  const values = [damNumber, Number(damNumber)]
    .filter(v => !(typeof v === "number" && Number.isNaN(v)));

  for (const v of values) {
    try {
      const snap = await db.collection("events")
        .where("userId", "==", uid)
        .where("animalNumber", "==", v)
        .limit(60)
        .get();

      for (const d of snap.docs) {
        const e = { id: d.id, ...(d.data() || {}) };

        const t = String(
          e.eventType ||
          e.type ||
          e.eventTypeNorm ||
          ""
        )
          .trim()
          .toLowerCase();

        if (!(t.includes("تلقيح") || t.includes("insemination"))) continue;

        const eventDate = String(
          e.eventDate ||
          e.date ||
          e.inseminationDate ||
          ""
        ).trim().slice(0, 10);

        if (eventDate !== aiDate) continue;

        const lineage =
          calvingSireLineageFromInseminationEventSrv(
            e,
            eventDate
          );

        if (lineage) return lineage;
      }

    } catch (e) {
      console.warn(
        "calving sire lineage lookup failed:",
        e.message || e
      );
    }
  }

  return null;
}
// ============================================================
//                 API: CALVING GATE — moved from forms-init.js
//                 نقل Gate الولادة كما هو: تحقق فقط بدون حفظ
// ============================================================

async function fetchAnimalByNumberForCalvingGateSrv(uid, number) {
  const num = calvingNormDigitsOnlySrv(number);
  if (!uid || !num) return null;

  async function findInCollection(colName) {
    try {
      const key = `${uid}#${num}`;
      const s1 = await db.collection(colName)
        .where("userId_number", "==", key)
        .limit(1)
        .get();

      if (!s1.empty) {
        const d = s1.docs[0];
        return { id: d.id, data: d.data() || {}, _collection: colName };
      }
    } catch (_) {}

    const tries = [
      ["number", num],
      ["animalNumber", num],
      ["animalNumber", Number(num)],
      ["calfNumber", num],
      ["calfNumber", Number(num)]
    ].filter((t) => !(typeof t[1] === "number" && Number.isNaN(t[1])));

    for (const [field, val] of tries) {
      for (const ownerField of ["userId", "ownerUid"]) {
        try {
          const s2 = await db.collection(colName)
            .where(ownerField, "==", uid)
            .where(field, "==", val)
            .limit(1)
            .get();

          if (!s2.empty) {
            const d = s2.docs[0];
            return { id: d.id, data: d.data() || {}, _collection: colName };
          }
        } catch (_) {}
      }
    }

    return null;
  }

  const animalDoc = await findInCollection("animals");
  if (animalDoc) return animalDoc;

  const calfDoc = await findInCollection("calves");
  if (calfDoc) return calfDoc;

  return null;
}

app.post("/api/calving/gate", requireUserId, async (req, res) => {
  try {
   if (!db) {
  return res.status(503).json({
    ok: false,
    allowed: false,
    error: "firestore_disabled",
    message: "❌ تعذّر فحص بيانات الولادة الآن. حاول مرة أخرى."
  });
}

    const uid = req.userId;
    const body = req.body || {};

    const n = calvingNormDigitsOnlySrv(body.animalNumber || body.number || "");
    const d = String(body.eventDate || body.date || "").trim().slice(0,10);

    if (!n || !d) {
      return res.json({
        ok: true,
        allowed: false,
        silent: true
      });
    }

    const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, n);

    if (!animal) {
      return res.status(404).json({
        ok: false,
        allowed: false,
      message: `❌ الحيوان رقم ${n} خارج القطيع، لذلك لا يمكن تسجيل ولادة له.`
      });
    }

    const doc = animal.data || {};

    const st = String(doc.status ?? "").trim().toLowerCase();
if (st === "inactive" || st === "archived") {
  return res.status(400).json({
    ok: false,
    allowed: false,
    message: `❌ لم أجد الحيوان رقم ${n}. راجع الرقم ثم حاول مرة أخرى.`
  });
}

    const sig = await fetchCalvingSignalsFromEventsSrv(uid, n);

   const docSpecies = String(
  doc.species ||
  doc.animalTypeAr ||
  doc.animalType ||
  doc.animaltype ||
  doc.type ||
  ""
).trim();

    let sp = String(body.species || "").trim() || docSpecies;
    if (/cow|بقر/i.test(sp)) sp = "أبقار";
    if (/buffalo|جاموس/i.test(sp)) sp = "جاموس";

    const reproFromEvents = String(sig.reproStatusFromEvents || "").trim();
    const reproFromDoc = String(doc.reproductiveStatus || "").trim();
    const repro = reproFromEvents || reproFromDoc || "";

   const lastAI = String(
  sig.lastInseminationDateFromEvents ||
  doc.lastInseminationDate ||
  ""
).trim();

    const gateData = {
      animalNumber: n,
      eventDate: d,
      animalId: animal.id || "",
      animalCollection: animal._collection || "animals",
      species: sp,
      documentData: doc,
      reproductiveStatus: repro,
      reproStatusFromEvents: reproFromEvents,
      lastInseminationDate: lastAI,
      lastBoundary: String(sig.lastBoundary || "").trim(),
      lastBoundaryType: String(sig.lastBoundaryType || "").trim()
    };

    const g = calvingDecisionSrv(gateData);

if (g) {
  const raw = String(g || "");
  const hasAbortHint = raw.startsWith("OFFER_ABORT|");

  let cleaned = raw.replace(/^OFFER_ABORT\|/, "");

  if (hasAbortHint) {
    const ageMatch = cleaned.match(/عمر الحمل\s+(\d+)\s+يوم/);
    const ageText = ageMatch ? ` — عمر الحمل ${ageMatch[1]} يوم فقط` : "";

  cleaned = `❌ التاريخ مبكر للولادة${ageText}.\nعدّل التاريخ أو سجّل الحالة كإجهاض.`;
  }

  return res.status(400).json({
    ok: false,
    allowed: false,
    message: cleaned,
    guardError: raw,
    offerAbort: hasAbortHint,
    actions: hasAbortHint ? [
      {
        key: "focus_date",
        label: "تعديل التاريخ",
        focus: "eventDate"
      },
      {
        key: "open_abortion",
        label: "تسجيل إجهاض",
        primary: true,
        url: `/abortion.html?number=${encodeURIComponent(n)}&date=${encodeURIComponent(d)}`
      }
    ] : []
  });
}
   const isFollower = animal._collection === "calves";

return res.json({
  ok: true,
  allowed: true,

  message: isFollower
    ? `✅ راجعت بيانات العجلة رقم ${n}، ويمكن تسجيل الولادة الآن. أدخل رقم الأم الجديد حسب سيريال المزرعة ثم أكمل البيانات واحفظ.`
    : `✅ راجعت بيانات الحيوان رقم ${n}، ويمكنك تسجيل الولادة الآن. أكمل البيانات ثم احفظ.`,

  animalId: animal.id || "",
  animalCollection: animal._collection || "animals",

  isFollower,
  requiresNewMotherNumber: isFollower,

  previousFollowerNumber: isFollower
    ? n
    : null,

  species: sp,
  lastInseminationDate: lastAI,
  signals: sig
});

  } catch (e) {
    console.error("calving-gate", e);
    return res.status(500).json({
      ok: false,
      allowed: false,
      error: "calving_gate_failed",
      message: "❌ تعذّر التحقق من بيانات الولادة الآن. حاول مرة أخرى."
    });
  }
});
