app.post("/api/insemination/save", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        error: "firestore_disabled",
        message: "❌ تعذّر حفظ التلقيح الآن. حاول مرة أخرى."
      });
    }

    const uid = req.userId;
    const formData = req.body || {};

    const animalNumber = calvingNormDigitsOnlySrv(
      formData.animalNumber ||
      formData.number ||
      ""
    );

    const eventDate = String(
      formData.eventDate ||
      formData.date ||
      ""
    ).trim().slice(0, 10);

    if (!animalNumber || !eventDate) {
      return res.status(400).json({
          ok: false,
          message: "❌ أدخل رقم الحيوان وتاريخ التلقيح.",
          fieldErrors: {
          animalNumber: !animalNumber ? "أدخل رقم الحيوان." : undefined,
          eventDate: !eventDate ? "أدخل تاريخ تلقيح صحيحًا." : undefined
        }
      });
    }

    const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, animalNumber);

    if (!animal) {
      return res.status(404).json({
        ok: false,
        message: `❌ لم أجد الحيوان رقم ${animalNumber} في حسابك. راجع الرقم وحاول مرة أخرى.`,
        fieldErrors: {
         animalNumber: "لم أجد الحيوان في حسابك."
        }
      });
    }

    const doc = animal.data || {};

    const signals = await fetchCalvingSignalsFromEventsSrv(uid, animalNumber);

    let species = String(
      formData.species ||
      doc.species ||
      doc.animalTypeAr ||
      doc.animalType ||
      doc.animaltype ||
      doc.type ||
      ""
    ).trim();

    if (/cow|بقر/i.test(species)) species = "أبقار";
    if (/buffalo|جاموس/i.test(species)) species = "جاموس";

    const reproFromEvents = String(signals.reproStatusFromEvents || "").trim();
    const reproFromDoc = String(doc.reproductiveStatus || "").trim();
    const reproStatus = reproFromEvents || reproFromDoc || "";

    const lastInseminationDate = String(
      signals.lastInseminationDateFromEvents ||
      doc.lastInseminationDate ||
      ""
    ).trim();

    const sameDayInseminationCount = await countInseminationsSameDaySrv(
      uid,
      animalNumber,
      eventDate
    );

    const gateData = {
      ...formData,
      animalNumber,
      eventDate,
      animalId: animal.id || "",
      animalCollection:
      animal._collection || "animals",
      species,
      documentData: doc,
      reproductiveStatus: reproStatus,
      reproStatusFromEvents: reproFromEvents,
      lastInseminationDate,
      sameDayInseminationCount,
      confirmEmbryonicLoss: formData.confirmEmbryonicLoss,
      embryonicLossConfirmed: formData.embryonicLossConfirmed,
      confirmPregnancyLoss: formData.confirmPregnancyLoss,
      pregnancyLossConfirmed: formData.pregnancyLossConfirmed,
      lastBoundary: String(signals.lastBoundary || "").trim(),
      lastBoundaryType: String(signals.lastBoundaryType || "").trim()
    };

    const fieldErrors = validateInseminationFieldsSrv(gateData);

    const cleanFieldErrors = {};
    for (const [k, v] of Object.entries(fieldErrors || {})) {
      if (v !== undefined && v !== null && String(v).trim() !== "") {
        cleanFieldErrors[k] = v;
      }
    }

if (Object.keys(cleanFieldErrors).length) {
  return res.status(400).json({
    ok: false,
    message: inseminationJoinMessageSrv(
     `❌ لم أتمكن من تسجيل التلقيح للحيوان رقم ${animalNumber}.`,
      inseminationRejectedReasonsTextSrv(
        [{
          animalNumber,
          fieldErrors: cleanFieldErrors
        }],
       "سبب عدم تسجيل التلقيح"
      )
    ),
    fieldErrors: cleanFieldErrors
  });
}

    const decision = inseminationDecisionSrv(gateData);
    let warningMessage = "";

    if (decision) {
      const raw = String(decision || "");
      const isWarn = raw.startsWith("WARN|");
      const needsEmbryonicConfirm = raw.startsWith("CONFIRM_EMBRYONIC_LOSS|");

      const message = needsEmbryonicConfirm
        ? raw.replace(/^CONFIRM_EMBRYONIC_LOSS\|/, "")
        : isWarn
          ? raw.replace(/^WARN\|/, "")
          : raw;

if (needsEmbryonicConfirm) {
  return res.status(409).json({
    ok: false,
    requiresEmbryonicLossConfirmation: true,
    message: inseminationJoinMessageSrv(
      `❌ لم يتم تسجيل التلقيح للحيوان رقم ${animalNumber}.`,
      inseminationRejectedReasonsTextSrv(
        [{
          animalNumber,
          reason: message
        }],
        "الأرقام المرفوضة وسبب الرفض"
      )
    )
  });
}

if (!isWarn) {
  return res.status(400).json({
    ok: false,
    message: inseminationJoinMessageSrv(
      `❌ لم يتم تسجيل التلقيح للحيوان رقم ${animalNumber}.`,
      inseminationRejectedReasonsTextSrv(
        [{
          animalNumber,
          reason: message
        }],
        "الأرقام المرفوضة وسبب الرفض"
      )
    )
  });
}

      warningMessage = message;
    }

      // التحذير لا يمنع الحفظ — مطابق للمنطق القديم
  
        const needsEmbryonicLoss =
      inseminationIsPregnantStatusSrv(reproStatus) &&
      inseminationConfirmEmbryonicLossSrv(formData);
        let thiAtInsemination = null;

    try {
      thiAtInsemination = await weatherBuildFarmThiSrv(req.authSession?.uid || uid);
    } catch (e) {
      console.warn("insemination thi snapshot failed:", e.message || e);
      thiAtInsemination = null;
    }
    const payload = {
      userId: uid,
      animalId: animal.id || "",
      animalNumber,
      eventDate,

      eventType: "insemination",
      type: "insemination",
      eventTypeNorm: "insemination",

      inseminationMethod: String(formData.inseminationMethod || "").trim(),
      semenCode: String(formData.semenCode || "").trim(),
      inseminator: String(formData.inseminator || "").trim(),
      inseminationTime:
        inseminationDayPartSrv(formData.inseminationTime),

      heatStatus:
        inseminationDayPartSrv(formData.heatStatus),
      inseminationSource:
       inseminationSourceNormSrv(formData) || null,
            thiAtInsemination: thiAtInsemination ? {
        thi: thiAtInsemination.thi ?? null,
        tempC: thiAtInsemination.tempC ?? null,
        humidity: thiAtInsemination.humidity ?? null,
        status: thiAtInsemination.status || null,
        level: thiAtInsemination.status?.level || "",
        label: thiAtInsemination.status?.label || "",
        severity: thiAtInsemination.status?.severity ?? null,
        source: thiAtInsemination.source || "",
        locationSource: thiAtInsemination.locationSource || "",
        locationLabel: thiAtInsemination.locationLabel || "",
        capturedAt: new Date().toISOString()
      } : null,
      thiValue: thiAtInsemination?.thi ?? null,
      thiLevel: thiAtInsemination?.status?.level || "",
      thiLabel: thiAtInsemination?.status?.label || "",
      notes: String(formData.notes || "").trim() || null,

      species,
      source: "server:/api/insemination/save",
      createdAt: admin.firestore.FieldValue.serverTimestamp()
    };

const prevServices = Number(doc.servicesCount || 0);
const nextServices = Number.isFinite(prevServices) ? prevServices + 1 : 1;

const animalCol = animal._collection || "animals";
const eventRef = db.collection("events").doc();
const embryonicLossRef = needsEmbryonicLoss ? db.collection("events").doc() : null;
const animalRef = db.collection(animalCol).doc(animal.id);

const batch = db.batch();

if (needsEmbryonicLoss && embryonicLossRef) {
  batch.set(embryonicLossRef, {
    userId: uid,
    animalId: animal.id || "",
    animalNumber,
    eventDate,

    eventType: "embryonic_loss",
    type: "embryonic_loss",
    eventTypeNorm: "embryonic_loss",
    eventName: "فقد جنيني",

    previousReproductiveStatus: reproStatus || "عشار",
    reproductiveStatusAfter: "مفتوحة",
    linkedInseminationEventId: eventRef.id,
    sequenceInOperation: 1,

    notes: String(formData.embryonicLossNotes || formData.notes || "").trim() || null,
    source: "server:/api/insemination/save:auto-embryonic-loss",
    createdAt: admin.firestore.FieldValue.serverTimestamp()
  });
}

if (needsEmbryonicLoss && embryonicLossRef) {
  payload.linkedEmbryonicLossEventId = embryonicLossRef.id;
  payload.sequenceInOperation = 2;
  payload.smartWarning = warningMessage || null;
}

batch.set(eventRef, payload);

const animalUpdate = {
  reproductiveStatus: "ملقحة",
  lastInseminationDate: eventDate,
  servicesCount: nextServices,
  updatedAt: admin.firestore.FieldValue.serverTimestamp()
};

if (animalCol === "calves") {
  animalUpdate.followerStatus = "ملقح";
  animalUpdate.status = "ملقح";
  animalUpdate.inseminationSireNumber =
    String(formData.semenCode || "").trim() || null;
}

if (needsEmbryonicLoss && embryonicLossRef) {
  animalUpdate.lastEmbryonicLossDate = eventDate;
  animalUpdate.lastPregnancyLossType = "embryonic_loss";
  animalUpdate.lastPregnancyLossEventId = embryonicLossRef.id;
  animalUpdate.reproductiveTransitionBeforeInsemination = "عشار -> مفتوحة -> ملقحة";
}

batch.set(animalRef, animalUpdate, { merge: true });

// ✅ حفظ اختيارات التلقيح المستخدمة داخل حساب المستخدم
// تُستخدم لاحقًا في صفحة التلقيح للاختيار بدل الكتابة كل مرة
const semenOption = String(formData.semenCode || "").trim();
const inseminatorOption = String(formData.inseminator || "").trim();

if (semenOption || inseminatorOption) {
  const optionsRef = db.collection("user_event_options").doc(uid);

  const optionsPatch = {
    userId: uid,
    updatedAt: admin.firestore.FieldValue.serverTimestamp()
  };

  if (semenOption) {
    optionsPatch.inseminationSemenCodes =
      admin.firestore.FieldValue.arrayUnion(semenOption);
  }

  if (inseminatorOption) {
    optionsPatch.inseminators =
      admin.firestore.FieldValue.arrayUnion(inseminatorOption);
  }

  batch.set(optionsRef, optionsPatch, { merge: true });
}

await batch.commit();
    if (typeof scheduleGroupsRebuildSrv === "function") {
      scheduleGroupsRebuildSrv(uid, "insemination_save");
    }
 
  return res.json({
  ok: true,
  message: inseminationSavedNumbersMessageSrv(
    [{ animalNumber }],
    []
  ),
      id: eventRef.id,
      eventId: eventRef.id,
      optionsSaved: !!(semenOption || inseminatorOption),
      optionsPath: `user_event_options/${uid}`,
      savedSemenOption: semenOption || null,
      savedInseminatorOption: inseminatorOption || null,
      animalId: animal.id || "",
      animalNumber,
      eventDate,
      reproductiveStatus: "ملقحة",
      lastInseminationDate: eventDate,
      servicesCount: nextServices,
      actions: [
        {
          key: "event_list",
          label: "فتح قائمة الأحداث",
          primary: true,
          url: `/event-list.html?number=${encodeURIComponent(animalNumber)}`
        },
        {
          key: "cow_card",
          label: "فتح بطاقة الحيوان",
          url: `/cow-card.html?number=${encodeURIComponent(animalNumber)}`
        }
      ]
    });

  } catch (e) {
    console.error("insemination-save", e);

    return res.status(500).json({
      ok: false,
      error: "insemination_save_failed",
      message: "❌ تعذّر حفظ التلقيح الآن."
    });
  }
});
// ============================================================
//                 API: INSEMINATION BULK SAVE
//                 حفظ التلقيح الجماعي من السيرفر فقط
// ============================================================

app.post("/api/insemination/bulk-save", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        error: "firestore_disabled",
        message: "❌ تعذّر حفظ التلقيح الآن. حاول مرة أخرى."
      });
    }

    const uid = req.userId;
    const formData = req.body || {};

    const rawNumbers =
      formData.animalNumbers ||
      formData.numbers ||
      formData.selectedNumbers ||
      formData.groupNumbers ||
      formData.animals ||
      formData.animalNumber ||
      formData.number ||
      "";

    const animalNumbers = typeof parsePregnancyBulkNumbersSrv === "function"
      ? parsePregnancyBulkNumbersSrv(rawNumbers)
      : [calvingNormDigitsOnlySrv(rawNumbers)].filter(Boolean);

    const eventDate = String(
      formData.eventDate ||
      formData.date ||
      ""
    ).trim().slice(0, 10);

    if (!animalNumbers.length || !eventDate) {
      return res.status(400).json({
        ok: false,
        message: "❌ أدخل أرقام الحيوانات وتاريخ التلقيح.",
        savedCount: 0,
        rejectedCount: animalNumbers.length,
        saved: [],
        rejected: []
      });
    }

    if (!calvingIsDateSrv(eventDate)) {
      return res.status(400).json({
        ok: false,
        message: "❌ أدخل تاريخ تلقيح صحيحًا.",
        savedCount: 0,
        rejectedCount: animalNumbers.length,
        saved: [],
        rejected: animalNumbers.map(n => ({
          animalNumber: String(n || ""),
          reason: "أدخل تاريخ تلقيح صحيحًا."
        }))
      });
    }

    const saved = [];
    const rejected = [];

    let batch = db.batch();
    let ops = 0;

    async function commitIfNeeded(force = false) {
      if (ops > 0 && (force || ops >= 400)) {
        await batch.commit();
        batch = db.batch();
        ops = 0;
      }
    }

    for (const rawNum of animalNumbers) {
      const animalNumber = calvingNormDigitsOnlySrv(rawNum);

      if (!animalNumber) {
        rejected.push({
          animalNumber: String(rawNum || ""),
         reason: "رقم الحيوان غير صحيح."
        });
        continue;
      }

      try {
        const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, animalNumber);

        if (!animal) {
          rejected.push({
            animalNumber,
            reason: "لم أجد الحيوان في حسابك. راجع الرقم."
          });
          continue;
        }

        const doc = animal.data || {};
        const signals = await fetchCalvingSignalsFromEventsSrv(uid, animalNumber);

        let species = String(
          formData.species ||
          doc.species ||
          doc.animalTypeAr ||
          doc.animalType ||
          doc.animaltype ||
          doc.type ||
          ""
        ).trim();

        if (/cow|بقر/i.test(species)) species = "أبقار";
        if (/buffalo|جاموس/i.test(species)) species = "جاموس";

        const reproFromEvents = String(signals.reproStatusFromEvents || "").trim();
        const reproFromDoc = String(doc.reproductiveStatus || "").trim();
        const reproStatus = reproFromEvents || reproFromDoc || "";

         const lastInseminationDate = String(
          signals.lastInseminationDateFromEvents ||
          doc.lastInseminationDate ||
          ""
        ).trim();

        const sameDayInseminationCount = await countInseminationsSameDaySrv(
          uid,
          animalNumber,
          eventDate
        );

        const gateData = {
          ...formData,
          animalNumber,
          eventDate,
          animalId: animal.id || "",
          animalCollection:
          animal._collection || "animals",
          species,
          documentData: doc,
          reproductiveStatus: reproStatus,
          reproStatusFromEvents: reproFromEvents,
          lastInseminationDate,
          sameDayInseminationCount,
          confirmEmbryonicLoss: formData.confirmEmbryonicLoss,
          embryonicLossConfirmed: formData.embryonicLossConfirmed,
          confirmPregnancyLoss: formData.confirmPregnancyLoss,
          pregnancyLossConfirmed: formData.pregnancyLossConfirmed,
          lastBoundary: String(signals.lastBoundary || "").trim(),
          lastBoundaryType: String(signals.lastBoundaryType || "").trim()
        };

        const fieldErrors = validateInseminationFieldsSrv(gateData);

        const cleanFieldErrors = {};
        for (const [k, v] of Object.entries(fieldErrors || {})) {
          if (v !== undefined && v !== null && String(v).trim() !== "") {
            cleanFieldErrors[k] = v;
          }
        }

if (Object.keys(cleanFieldErrors).length) {
rejected.push({
  animalNumber,
  reason: inseminationFieldErrorsTextSrv(cleanFieldErrors) || "أكمل بيانات التلقيح المطلوبة.",
  fieldErrors: cleanFieldErrors
});
  continue;
}
        const decision = inseminationDecisionSrv(gateData);
        let warningMessage = "";

                if (decision) {
          const raw = String(decision || "");
          const isWarn = raw.startsWith("WARN|");
          const needsEmbryonicConfirm = raw.startsWith("CONFIRM_EMBRYONIC_LOSS|");

          const message = needsEmbryonicConfirm
            ? raw.replace(/^CONFIRM_EMBRYONIC_LOSS\|/, "")
            : isWarn
              ? raw.replace(/^WARN\|/, "")
              : raw;

          if (needsEmbryonicConfirm) {
            rejected.push({
              animalNumber,
              reason: message,
              requiresEmbryonicLossConfirmation: true
            });
            continue;
          }

          if (!isWarn) {
            rejected.push({
              animalNumber,
              reason: message
            });
            continue;
          }

          warningMessage = message;
        }

        const eventRef = db.collection("events").doc();
                const needsEmbryonicLoss =
          inseminationIsPregnantStatusSrv(reproStatus) &&
          inseminationConfirmEmbryonicLossSrv(formData);

        const embryonicLossRef = needsEmbryonicLoss
          ? db.collection("events").doc()
          : null;

        const payload = {
          userId: uid,
          animalId: animal.id || "",
          animalNumber,
          eventDate,

          eventType: "insemination",
          type: "insemination",
          eventTypeNorm: "insemination",

          inseminationMethod: String(formData.inseminationMethod || "").trim(),
          semenCode: String(formData.semenCode || "").trim(),
          inseminator: String(formData.inseminator || "").trim(),
          inseminationTime:
           inseminationDayPartSrv(formData.inseminationTime),

          heatStatus:
           inseminationDayPartSrv(formData.heatStatus),
          inseminationSource:
           inseminationSourceNormSrv(formData) || null,
          notes: String(formData.notes || "").trim() || null,

          species,
          source: "server:/api/insemination/bulk-save",
          createdAt: admin.firestore.FieldValue.serverTimestamp()
        };

        const prevServices = Number(doc.servicesCount || 0);
        const nextServices = Number.isFinite(prevServices) ? prevServices + 1 : 1;

        const animalCol = animal._collection || "animals";
        const animalRef = db.collection(animalCol).doc(animal.id);

        batch.set(eventRef, payload);
        ops++;
                if (needsEmbryonicLoss && embryonicLossRef) {
          batch.set(embryonicLossRef, {
            userId: uid,
            animalId: animal.id || "",
            animalNumber,
            eventDate,

            eventType: "embryonic_loss",
            type: "embryonic_loss",
            eventTypeNorm: "embryonic_loss",
            eventName: "فقد جنيني",

            previousReproductiveStatus: reproStatus || "عشار",
            reproductiveStatusAfter: "مفتوحة",
            linkedInseminationEventId: eventRef.id,
            sequenceInOperation: 1,

            notes: String(formData.embryonicLossNotes || formData.notes || "").trim() || null,
            source: "server:/api/insemination/bulk-save:auto-embryonic-loss",
            createdAt: admin.firestore.FieldValue.serverTimestamp()
          });
          ops++;

          payload.linkedEmbryonicLossEventId = embryonicLossRef.id;
          payload.sequenceInOperation = 2;
          payload.smartWarning = warningMessage || null;
        }
        const animalUpdate = {
          reproductiveStatus: "ملقحة",
          lastInseminationDate: eventDate,
          servicesCount: nextServices,
          updatedAt: admin.firestore.FieldValue.serverTimestamp()
        };

        if (animalCol === "calves") {
          animalUpdate.followerStatus = "ملقح";
          animalUpdate.status = "ملقح";
          animalUpdate.inseminationSireNumber =
            String(formData.semenCode || "").trim() || null;
        }

        if (needsEmbryonicLoss && embryonicLossRef) {
          animalUpdate.lastEmbryonicLossDate = eventDate;
          animalUpdate.lastPregnancyLossType = "embryonic_loss";
          animalUpdate.lastPregnancyLossEventId = embryonicLossRef.id;
          animalUpdate.reproductiveTransitionBeforeInsemination = "عشار -> مفتوحة -> ملقحة";
        }

        batch.set(animalRef, animalUpdate, { merge: true });
        ops++;

        saved.push({
          animalNumber,
          eventId: eventRef.id,
          reproductiveStatus: "ملقحة",
          lastInseminationDate: eventDate,
          servicesCount: nextServices,
          embryonicLossCreated: !!needsEmbryonicLoss,
          embryonicLossEventId: embryonicLossRef ? embryonicLossRef.id : null,
          warning: warningMessage || ""
        });

        await commitIfNeeded(false);

      } catch (oneErr) {
        console.error("insemination-bulk-save-one", animalNumber, oneErr);

        rejected.push({
          animalNumber,
          reason: "تعذّر حفظ التلقيح لهذا الحيوان. حاول مرة أخرى."
        });
      }
    }

    const semenOption = String(formData.semenCode || "").trim();
    const inseminatorOption = String(formData.inseminator || "").trim();

    if (semenOption || inseminatorOption) {
      const optionsRef = db.collection("user_event_options").doc(uid);

      const optionsPatch = {
        userId: uid,
        updatedAt: admin.firestore.FieldValue.serverTimestamp()
      };

      if (semenOption) {
        optionsPatch.inseminationSemenCodes =
          admin.firestore.FieldValue.arrayUnion(semenOption);
      }

      if (inseminatorOption) {
        optionsPatch.inseminators =
          admin.firestore.FieldValue.arrayUnion(inseminatorOption);
      }

      batch.set(optionsRef, optionsPatch, { merge: true });
      ops++;
    }

    await commitIfNeeded(true);

    if (saved.length && typeof scheduleGroupsRebuildSrv === "function") {
      scheduleGroupsRebuildSrv(uid, "insemination_bulk_save");
    }

if (!saved.length) {
  return res.status(400).json({
    ok: false,
message: inseminationJoinMessageSrv(
  "❌ لم أتمكن من تسجيل التلقيح لأي حيوان.",
  inseminationRejectedReasonsTextSrv(
        rejected,
       "الأرقام التي لم يُسجل لها التلقيح وسبب ذلك"
      )
    ),
    redirectUrl: "",
    savedCount: 0,
    rejectedCount: rejected.length,
    saved,
    rejected
  });
}

return res.json({
  ok: true,
  message: inseminationJoinMessageSrv(
    inseminationSavedNumbersMessageSrv(saved, rejected),
    inseminationRejectedReasonsTextSrv(
      rejected,
      "الأرقام التي لم يتم تسجيل التلقيح لها"
    )
  ),
  redirectUrl: "/event-list.html",
  savedCount: saved.length,
  rejectedCount: rejected.length,
  saved,
  rejected
});

  } catch (e) {
    console.error("insemination-bulk-save", e);

    return res.status(500).json({
      ok: false,
      error: "insemination_bulk_save_failed",
      message: "❌ تعذّر حفظ التلقيح الآن. حاول مرة أخرى."
    });
  }
});
// ============================================================
//                 PREGNANCY DIAGNOSIS — server-side only
//                 نقل قرار/حفظ تشخيص الحمل للسيرفر فقط
// ============================================================

function validatePregnancyDiagnosisFieldsSrv(fd = {}) {
  const fieldErrors = {};

  if (!String(fd.animalNumber || "").trim()) {
    fieldErrors.animalNumber = "أدخل رقم الحيوان.";
  }

  if (!String(fd.eventDate || "").trim() || !calvingIsDateSrv(fd.eventDate)) {
    fieldErrors.eventDate = "أدخل تاريخ تشخيص صحيحًا.";
  }

  if (!fd.documentData) {
    fieldErrors.documentData = "لم أجد الحيوان المسجل بهذا الرقم.";
  }

  if (!String(fd.method || "").trim()) {
    fieldErrors.method = "اختر طريقة التشخيص.";
  }

  if (!String(fd.result || "").trim()) {
    fieldErrors.result = "اختر نتيجة التشخيص.";
  }

  return fieldErrors;
}
function normalizePregnancyMethodSrv(v) {
  const s = String(v || "").trim();

  if (s === "ultrasound" || s === "سونار") return "سونار";
  if (s === "manual" || s === "جس يدوي" || s === "يدوي") return "جس يدوي";

  return s;
}

function normalizePregnancyResultSrv(v) {
  const raw = String(v || "").trim();
  const s = raw.toLowerCase();
  const ar = raw
    .replace(/[أإآ]/g, "ا")
    .replace(/ة/g, "ه")
    .trim();

  // مهم: السالب قبل الموجب حتى لا تُفهم "غير عشار" كأنها "عشار"
  if (
    ar.includes("غير عشار") ||
    ar.includes("ليست عشار") ||
    ar.includes("ليس عشار") ||
    ar.includes("فارغ") ||
    s === "negative" ||
    s === "open" ||
    s === "not pregnant" ||
    s === "not_pregnant"
  ) {
    return "فارغة";
  }

  if (
    raw.includes("عشار") ||
    s === "positive" ||
    s === "pregnant"
  ) {
    return "عشار";
  }

  return raw;
}
function pregnancyDiagnosisCheckTypeSrv(fd = {}) {
  const raw = String(
    fd.checkType ||
    fd.diagnosisType ||
    fd.examType ||
    fd.mode ||
    fd.pregnancyCheckType ||
    fd.confirmationType ||
    ""
  ).trim();

  const low = raw.toLowerCase();

  if (
    raw.includes("120") ||
    raw.includes("تأكيد") ||
    raw.includes("تاكيد") ||
    low.includes("confirm") ||
    low.includes("confirmation")
  ) {
    return "pregnancy_confirmation_120";
  }

  return "initial_pregnancy_diagnosis";
}

function pregnancyDiagnosisIsConfirmation120Srv(fd = {}) {
  return pregnancyDiagnosisCheckTypeSrv(fd) === "pregnancy_confirmation_120";
}

function pregnancyDiagnosisIsPregnantStatusSrv(v) {
  const s = String(v || "")
    .trim()
    .replace(/[أإآ]/g, "ا")
    .replace(/ة/g, "ه");

  const n = calvingStripArSrv(s);

  return n.includes("عشار") || n.includes("حامل");
}

function pregnancyDiagnosisIsInseminatedStatusSrv(v) {
  const s = String(v || "")
    .trim()
    .replace(/[أإآ]/g, "ا")
    .replace(/ة/g, "ه");

  const n = calvingStripArSrv(s);

  return n.includes("ملقح");
}
function pregnancyDiagnosisDecisionSrv(fd) {
  const doc = fd.documentData;
 if (!doc) return "❌ تعذّر قراءة بيانات الحيوان الآن.";

  const st = String(doc.status ?? "").trim().toLowerCase();
  if (st === "inactive" || st === "archived") {
    return "❌ الحيوان خارج القطيع، لذلك لا يمكن تسجيل تشخيص حمل له.";
  }

  const rsRaw = String(
  doc.reproductiveStatus ||
  fd.reproductiveStatus ||
  fd.reproStatusFromEvents ||
  ""
).trim();

  const speciesRaw = String(
    fd.species ||
    doc.species ||
    doc.animalTypeAr ||
    doc.animalType ||
    doc.animaltype ||
    doc.type ||
    ""
  ).trim();

  let species = speciesRaw;
  if (/cow|بقر/i.test(species)) species = "أبقار";
  if (/buffalo|جاموس/i.test(species)) species = "جاموس";

  const animalLabel = species === "جاموس" ? "الجاموسة" : "البقرة";

  const method = normalizePregnancyMethodSrv(fd.method);
  const isSono = method === "سونار";
  const isManual = method === "جس يدوي";

  if (!isSono && !isManual) {
   return "❌ اختر طريقة تشخيص صحيحة.";
  }

  const lastAI = String(
    fd.lastInseminationDate ||
    doc.lastInseminationDate ||
    doc.lastAI ||
    doc.lastInsemination ||
    ""
  ).trim();

  if (!calvingIsDateSrv(lastAI)) {
   return "❌ لا يوجد تاريخ صحيح لآخر تلقيح، لذلك لا يمكن تسجيل تشخيص الحمل.";
  }

  if (!calvingIsDateSrv(fd.eventDate)) {
   return "❌ أدخل تاريخ تشخيص صحيحًا.";
  }

  const diff = calvingDaysBetweenSrv(lastAI, fd.eventDate);

  if (!Number.isFinite(diff)) {
    return "❌ تعذّر حساب الأيام منذ آخر تلقيح.";
  }

  const isConfirmation120 = pregnancyDiagnosisIsConfirmation120Srv(fd);

  if (isConfirmation120) {
    if (!pregnancyDiagnosisIsPregnantStatusSrv(rsRaw)) {
      const shown = rsRaw ? `«${rsRaw}»` : "غير معروفة";
     return `❌ لا يمكن تأكيد الحمل بعد 120 يومًا لأن ${animalLabel} ليست مسجلة عِشار. الحالة الحالية: ${shown}.`;
    }

    if (diff < 120) {
     return `❌ مرّ ${diff} يومًا فقط منذ آخر تلقيح. يمكن تأكيد الحمل بعد مرور 120 يومًا.`;
    }

    return null;
  }

  if (!pregnancyDiagnosisIsInseminatedStatusSrv(rsRaw)) {
    const shown = rsRaw ? `«${rsRaw}»` : "غير معروفة";
   return `❌ لا يمكن تشخيص الحمل لأن ${animalLabel} ليست مسجلة ملقحة. الحالة الحالية: ${shown}.`;
  }

  const minDays = isSono ? 26 : 40;

  if (diff < minDays) {
   return `❌ مرّ ${diff} يومًا فقط منذ آخر تلقيح. الحد الأدنى لهذه الطريقة ${minDays} يومًا.`;
  }

  return null;
}
async function updateAnimalByPregnancyDiagnosisSrv(ev = {}) {
  const uid = String(ev.userId || "").trim();
  const animalNumber = calvingNormDigitsOnlySrv(
    ev.animalNumber ||
    ev.number ||
    ev.animalId ||
    ""
  );

  if (!uid || !animalNumber) {
    console.warn("⛔ updateAnimalByPregnancyDiagnosisSrv: missing uid/animalNumber", { uid, animalNumber, ev });
    return;
  }

  const animal = await findAnimalDocByNumberSrv(uid, animalNumber);

  if (!animal || !animal.id) {
    console.warn("⛔ animal not found for pregnancy diagnosis update:", { uid, animalNumber });
    return;
  }

  const result = normalizePregnancyResultSrv(ev.result);
  const eventDate = String(ev.eventDate || "").trim().slice(0, 10);

  const animalPatch = {
  lastDiagnosis: "تشخيص حمل",
  lastDiagnosisDate: eventDate,

  lastPregnancyDiagnosisDate: eventDate,
  lastPregnancyDiagnosisResult: result,
  lastPregnancyDiagnosisEventId: eventRef.id,
  lastPregnancyDiagnosisCheckType:
    isConfirmation120
      ? "pregnancy_confirmation_120"
      : "initial_pregnancy_diagnosis",

  updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  status: "active"
};

  if (result === "عشار") {
    patch.reproductiveStatus = "عشار";
  }

  if (result === "فارغة") {
    patch.reproductiveStatus = "مفتوحة";
  }

  await db.collection("animals").doc(animal.id).set(patch, { merge: true });

  console.log("🔥 animal updated by pregnancy diagnosis:", animal.id, patch);
}

