//      PREGNANCY DIAGNOSIS FOLLOW-UP DECISION — LATER
//      تسجيل «لاحقًا» لآخر تشخيص حمل فارغ فقط
// ============================================================

app.post(
  "/api/pregnancy-diagnosis/followup-decision",
  requireUserId,
  async (req, res) => {
    try {
      if (!db) {
        return res.status(503).json({
          ok: false,
          error: "firestore_disabled",
          message:
            "❌ تعذّر حفظ قرار المتابعة الآن. حاول مرة أخرى."
        });
      }

      const uid = req.userId;

      const decision =
        String(
          req.body?.decision || ""
        )
          .trim()
          .toLowerCase();

      if (decision !== "later") {
        return res.status(400).json({
          ok: false,
          error: "followup_decision_invalid",
          message:
            "❌ قرار متابعة تشخيص الحمل غير صحيح."
        });
      }

      const rawItems =
        Array.isArray(req.body?.items)
          ? req.body.items
          : [
              {
                animalNumber:
                  req.body?.animalNumber ||
                  req.body?.number ||
                  "",

                eventId:
                  req.body?.eventId ||
                  req.body?.diagnosisEventId ||
                  ""
              }
            ];

      const items = [];
      const seen = new Set();

      for (const raw of rawItems) {
        const animalNumber =
          calvingNormDigitsOnlySrv(
            raw?.animalNumber ||
            raw?.number ||
            ""
          );

        const eventId =
          String(
            raw?.eventId ||
            raw?.diagnosisEventId ||
            ""
          ).trim();

        if (!animalNumber || !eventId) {
          continue;
        }

        const key =
          `${animalNumber}#${eventId}`;

        if (seen.has(key)) continue;

        seen.add(key);

        items.push({
          animalNumber,
          eventId
        });
      }

      if (!items.length) {
        return res.status(400).json({
          ok: false,
          error: "followup_items_required",
          message:
            "❌ لا توجد حيوانات صالحة لحفظ قرار المتابعة."
        });
      }

      const accepted = [];
      const rejected = [];

      let batch = db.batch();
      let operations = 0;

      async function commitIfNeeded(
        force = false
      ) {
        if (!operations) return;

        if (
          !force &&
          operations < 400
        ) {
          return;
        }

        await batch.commit();

        batch = db.batch();
        operations = 0;
      }

      for (const item of items) {
        const animal =
          await fetchAnimalByNumberForCalvingGateSrv(
            uid,
            item.animalNumber
          );

        if (
          !animal ||
          animal._collection !== "animals"
        ) {
          rejected.push({
            animalNumber:
              item.animalNumber,

            reason:
              "الحيوان غير موجود في القطيع."
          });

          continue;
        }

        const doc =
          animal.data || {};

        const currentResult =
          String(
            doc.lastPregnancyDiagnosisResult ||
            ""
          ).trim();

        const currentCheckType =
          String(
            doc.lastPregnancyDiagnosisCheckType ||
            ""
          ).trim();

        const currentEventId =
          String(
            doc.lastPregnancyDiagnosisEventId ||
            ""
          ).trim();

   if (
  currentResult !== "فارغة" ||
  !currentEventId ||
  currentEventId !== item.eventId
) {
          rejected.push({
            animalNumber:
              item.animalNumber,

            reason:
              "تشخيص الحمل الحالي لا يطابق طلب المتابعة."
          });

          continue;
        }

        batch.set(
          db
            .collection("animals")
            .doc(animal.id),

          {
            pregnancyDiagnosisFollowupDecision:
              "later",

            pregnancyDiagnosisFollowupDecisionEventId:
              currentEventId,

            pregnancyDiagnosisFollowupDecisionAt:
              admin.firestore
                .FieldValue
                .serverTimestamp(),

            pregnancyDiagnosisFollowupDecisionSource:
              "pregnancy_diagnosis_after_save",

            updatedAt:
              admin.firestore
                .FieldValue
                .serverTimestamp()
          },

          {
            merge: true
          }
        );

        operations++;

        accepted.push({
          animalNumber:
            item.animalNumber,

          eventId:
            currentEventId
        });

        await commitIfNeeded(false);
      }

      await commitIfNeeded(true);

      const ok =
        accepted.length > 0;

      return res
        .status(ok ? 200 : 409)
        .json({
          ok,

          message: ok
            ? (
                accepted.length === 1
                  ? "✅ أُضيف الحيوان إلى متابعة تلقيح الحيوانات المفتوحة."
                  : `✅ أُضيفت ${accepted.length} حيوانات إلى متابعة تلقيح الحيوانات المفتوحة.`
              )
            : "❌ لم يتم حفظ قرار المتابعة؛ تغيّرت حالة الحيوانات أو تشخيصها.",

          acceptedCount:
            accepted.length,

          rejectedCount:
            rejected.length,

          accepted,
          rejected
        });

    } catch (e) {
      console.error(
        "pregnancy-diagnosis-followup-decision",
        e
      );

      return res.status(500).json({
        ok: false,
        error:
          "pregnancy_diagnosis_followup_decision_failed",

        message:
          "❌ تعذّر حفظ قرار المتابعة الآن."
      });
    }
  }
);
// ============================================================
//                 OVSYNCH PROTOCOL DURATION HELPERS
//                 إنهاء/تجاهل البروتوكول النشط حسب مدة البرنامج
// ============================================================

function ovsynchProgramDurationDaysSrv(program) {
  const p = String(program || "").trim().toLowerCase();

  if (p === "ovsynch") return 10;
  if (p === "cosynch72") return 10;
  if (p === "presynch_ovsynch") return 38;

  // لو البرنامج القديم غير محفوظ في وثيقة الحيوان، نستخدم أطول مدة آمنة.
  return 38;
}

function addDaysToIsoDateSrv(iso, days) {
  if (!calvingIsDateSrv(iso)) return "";
  const [y, m, d] = String(iso).slice(0, 10).split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + Number(days || 0));
  return dt.toISOString().slice(0, 10);
}

function resolveOvsynchProgramFromAnimalSrv(doc = {}) {
  return String(
    doc.currentProtocolProgram ||
    doc.protocolProgram ||
    doc.program ||
    ""
  ).trim();
}

function ovsynchActiveProtocolBlockMessageSrv(doc = {}, eventDate = "") {
  const curProto = String(doc.currentProtocol || "").trim().toLowerCase();
  const protoStatus = String(doc.protocolStatus || "").trim().toLowerCase();
  const protoStart = String(doc.protocolStartDate || "").trim().slice(0, 10);

  if (curProto !== "ovsynch" || protoStatus !== "active") {
    return null;
  }

  if (!calvingIsDateSrv(protoStart) || !calvingIsDateSrv(eventDate)) {
    return "❌ لا يمكن بدء برنامج تزامن جديد؛ الحيوان مسجل حاليًا في برنامج تزامن نشط."
  }

  const program = resolveOvsynchProgramFromAnimalSrv(doc);
  const durationDays = ovsynchProgramDurationDaysSrv(program);
  const activeDays = calvingDaysBetweenSrv(protoStart, eventDate);

  if (!Number.isFinite(activeDays)) {
   return "❌ لا يمكن بدء برنامج تزامن جديد؛ الحيوان مسجل حاليًا في برنامج تزامن نشط.";
  }

  // لو لم تنته مدة البرنامج بعد، يمنع.
  if (activeDays >= 0 && activeDays <= durationDays) {
    return "❌ لا يمكن بدء برنامج تزامن جديد؛ الحيوان مسجل حاليًا في برنامج تزامن نشط.";
  }

  // لو تعدى مدة البرنامج، لا يمنع؛ يعتبر منتهيًا منطقيًا.
  return null;
}
// ============================================================
//                 API: OVSYNCH GATE
//                 أهلية أرقام التزامن فقط — بدون حفظ وبدون Tasks
// ============================================================

app.post("/api/ovsynch/gate", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        allowed: false,
        error: "firestore_disabled",
        message: "❌ تعذّر فحص أهلية الحيوانات لبرنامج التزامن الآن. حاول مرة أخرى.",
        acceptedCount: 0,
        rejectedCount: 0,
        accepted: [],
        rejected: []
      });
    }

    const uid = req.userId;
    const body = req.body || {};

   const rawNumbers =
  body.animalNumbers ||
  body.numbers ||
  body.animalNumber ||
  body.number ||
  "";

function parseOvsynchNumbers(raw) {
  let arr = [];

  if (Array.isArray(raw)) {
    arr = raw;
  } else {
    const txt = String(raw || "").trim();
    if (!txt) return [];

    try {
      const parsed = JSON.parse(txt);
      arr = Array.isArray(parsed) ? parsed : txt.split(/\n|,|;|،|\s+/g);
    } catch (_) {
      arr = txt.split(/\n|,|;|،|\s+/g);
    }
  }

  return [...new Set(
    arr
      .map(x => calvingNormDigitsOnlySrv(x))
      .filter(Boolean)
  )];
}

const numbers = parseOvsynchNumbers(rawNumbers);

    const eventDate = String(
      body.eventDate ||
      body.date ||
      body.startDate ||
      ""
    ).trim().slice(0, 10);

    if (!numbers.length || !eventDate) {
      return res.json({
        ok: true,
        allowed: false,
        silent: true,
        stage: "missing_context",
        message: "بيانات برنامج التزامن لم تكتمل بعد.",
        acceptedCount: 0,
        rejectedCount: 0,
        accepted: [],
        rejected: []
      });
    }

    if (!calvingIsDateSrv(eventDate)) {
      return res.status(400).json({
        ok: false,
        allowed: false,
        stage: "invalid_date",
        message: "❌ أدخل تاريخ بدء صحيحًا لبرنامج التزامن.",
        acceptedCount: 0,
        rejectedCount: numbers.length,
        accepted: [],
        rejected: numbers.map(n => ({
          animalNumber: String(n || ""),
          reason: "أدخل تاريخ بدء صحيحًا لبرنامج التزامن."
        }))
      });
    }

    function normalizeOvsynchSpecies(doc = {}, fallback = "") {
      let sp = String(
        fallback ||
        doc.species ||
        doc.animalTypeAr ||
        doc.animalType ||
        doc.animaltype ||
        doc.type ||
        ""
      ).trim();

      if (/cow|بقر/i.test(sp)) sp = "أبقار";
      if (/buffalo|جاموس/i.test(sp)) sp = "جاموس";

      return sp || "أبقار";
    }

    function ovsynchAnimalWord(sp) {
      return sp === "جاموس" ? "جاموسة" : "بقرة";
    }

    function ovsynchAnimalLabel(doc = {}) {
      return normalizeOvsynchSpecies(doc) === "جاموس" ? "الجاموسة" : "البقرة";
    }

    function ovsynchReproCategory(raw) {
      const n = calvingStripArSrv(raw);

      if (
        n.includes("لاتلقح") ||
        n.includes("لاتلقحمرةاخرى") ||
        n.includes("لاتلقحمرهاخرى") ||
        n.includes("لاتلقحمرةاخري")
      ) return "blocked";

      if (n.includes("عشار")) return "pregnant";

      if (
        n.includes("ملقح") ||
        n.includes("ملقحة") ||
        n.includes("ملقّحة")
      ) return "inseminated";

      if (
        n.includes("مفتوح") ||
        n.includes("فارغ") ||
        n.includes("فارغة")
      ) return "open";

      return "unknown";
    }

    function compactOvsynchReason(reason) {
      let s = String(reason || "").trim();

      s = s.replace(/^\s*❌\s*/, "");
      s = s.replace(/\s+/g, " ").trim();

      s = s.replace(/الحالة الحالية:\s*«?\s*حديث(?:ة)? الولادة\s*»?/g, "حديثة الولادة");
      s = s.replace(/الحالة الحالية:\s*«?\s*تحضير(?: لل)?ولادة\s*»?/g, "تحضير للولادة");
      s = s.replace(/الحالة الحالية:\s*«?\s*ملقح(?:ة)?\s*»?/g, "ملقحة");
      s = s.replace(/الحالة الحالية:\s*«?\s*عشار\s*»?/g, "عشار");
      s = s.replace(/الحالة الحالية:\s*«?\s*مفتوح(?:ة)?\s*»?/g, "مفتوحة");

      s = s.replace(/\s*—\s*المسموح.*$/, "").trim();

      return "❌ " + s;
    }

    function ovsynchEligibilityDecision(fd = {}) {
      const doc = fd.documentData;
      if (!doc) return "❌ تعذّر قراءة بيانات الحيوان الآن.";

      const st = String(doc.status ?? "").trim().toLowerCase();
     if (st === "inactive") {
  return "❌ الحيوان خارج القطيع، لذلك لا يمكن بدء برنامج التزامن له.";
}

      const reproDocRaw = String(doc.reproductiveStatus || "").trim();
      const reproDocCat = ovsynchReproCategory(reproDocRaw);

      if (doc.breedingBlocked === true || reproDocCat === "blocked") {
        return "❌ الحيوان مستبعد من التلقيح، لذلك لا يمكن بدء برنامج التزامن له.";
      }

     const activeProtocolMsg = ovsynchActiveProtocolBlockMessageSrv(doc, fd.eventDate);
if (activeProtocolMsg) return activeProtocolMsg;

      const sp = normalizeOvsynchSpecies(doc, fd.species);
      const w = ovsynchAnimalWord(sp);

      const rsRaw = String(doc.reproductiveStatus || fd.reproStatusFromEvents || "").trim();
      const cat = ovsynchReproCategory(rsRaw);
      const shownStatus = rsRaw ? `«${rsRaw}»` : "غير معروفة";

      if (cat === "pregnant" || cat === "inseminated" || cat === "blocked") {
        return `❌ لا يمكن بدء برنامج التزامن؛ حالة ${w} التناسلية الحالية هي ${shownStatus}.`;
      }

      if (cat !== "open") {
       return `❌ لا يمكن بدء برنامج التزامن؛ حالة ${w} التناسلية الحالية هي ${shownStatus}، والبرنامج متاح للحيوانات المفتوحة فقط.`;
      }

      if (!calvingIsDateSrv(fd.eventDate)) {
        return "❌ أدخل تاريخ بدء صحيحًا لبرنامج التزامن.";
      }

      const lastCalving = String(doc.lastCalvingDate || "").trim();

      if (lastCalving && calvingIsDateSrv(lastCalving)) {
       const minAfterCalving = sp === "جاموس" ? 35 : 45;
        const sinceCalving = calvingDaysBetweenSrv(lastCalving, fd.eventDate);

        if (
          Number.isFinite(sinceCalving) &&
          sinceCalving >= 0 &&
          sinceCalving < minAfterCalving
        ) {
         return `❌ لا يمكن بدء برنامج التزامن الآن؛ مرّ على ولادة ${w} ${sinceCalving} يومًا فقط، والحد الأدنى ${minAfterCalving} يومًا.`;
        }
      }

      return null;
    }

    async function getLastOvsynchEvent(animalNumber) {
      const num = calvingNormDigitsOnlySrv(animalNumber);
      if (!uid || !num) return null;

      try {
        const snap = await db.collection("events")
          .where("userId", "==", uid)
          .where("animalNumber", "==", num)
          .where("eventType", "==", "بروتوكول تزامن")
          .orderBy("eventDate", "desc")
          .limit(1)
          .get();

        if (snap.empty) return null;

        const d = snap.docs[0].data() || {};

        return {
          eventDate: String(d.eventDate || "").slice(0, 10),
          program: String(d.program || "").trim()
        };
      } catch (_) {
        return null;
      }
    }

    const accepted = [];
    const rejected = [];

    for (const rawNum of numbers) {
      const animalNumber = calvingNormDigitsOnlySrv(rawNum);

      if (!animalNumber) {
        rejected.push({
          animalNumber: String(rawNum || ""),
          reason: "رقم الحيوان غير صحيح."
        });
        continue;
      }

      const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, animalNumber);

      if (!animal) {
        rejected.push({
          animalNumber,
          reason: "لم أجد الحيوان في القطيع المسجل بحسابك."
        });
        continue;
      }

      const doc = animal.data || {};
      const signals = await fetchCalvingSignalsFromEventsSrv(uid, animalNumber);

      const species = normalizeOvsynchSpecies(doc, body.species);
      const reproFromEvents = String(signals.reproStatusFromEvents || "").trim();

      const decision = ovsynchEligibilityDecision({
        animalNumber,
        eventDate,
        animalId: animal.id || "",
        species,
        documentData: doc,
        reproStatusFromEvents: reproFromEvents,
        lastBoundary: String(signals.lastBoundary || "").trim(),
        lastBoundaryType: String(signals.lastBoundaryType || "").trim()
      });

      if (decision) {
        rejected.push({
          animalNumber,
          reason: String(decision)
        });
        continue;
      }

      const last = await getLastOvsynchEvent(animalNumber);

      if (last?.eventDate && String(last.program || "").trim() === "ovsynch") {
        const g14 = calvingDaysBetweenSrv(last.eventDate, eventDate);

        if (Number.isFinite(g14) && g14 >= 0 && g14 < 14) {
          rejected.push({
            animalNumber,
            reason: `سبق تسجيل برنامج تزامن بدأ بتاريخ ${last.eventDate}.`
          });
          continue;
        }
      }

      accepted.push({
        animalNumber,
        animalId: animal.id || "",
        species,
       reproductiveStatus: String(doc.reproductiveStatus || "").trim() || reproFromEvents || ""
      });
    }

    const allowed = accepted.length > 0;

   const acceptedCount = accepted.length;
const rejectedCount = rejected.length;
const isBulk = numbers.length > 1;

if (!isBulk) {
  if (!acceptedCount) {
    const r0 = rejected[0] || {};
    return res.status(400).json({
      ok: false,
      allowed: false,
      stage: "no_eligible_animals",
      message: (() => {
  const n = String(r0.animalNumber || "").trim();
  const reason = compactOvsynchReason(r0.reason || "❌ لا يمكن بدء برنامج التزامن لهذا الحيوان.").replace(/^❌\s*/, "");
  return n ? `❌ الحيوان رقم ${n}: ${reason}` : `❌ ${reason}`;
})(),
      acceptedCount,
      rejectedCount,
      accepted,
      rejected
    });
  }

  return res.json({
    ok: true,
    allowed: true,
    stage: "eligible",
    message: `✅ راجعت بيانات الحيوان رقم ${accepted[0].animalNumber}، ويمكنك بدء برنامج التزامن الآن.`,
    acceptedCount,
    rejectedCount,
    accepted,
    rejected
  });
}

if (!acceptedCount) {
  return res.status(400).json({
    ok: false,
    allowed: false,
    stage: "no_eligible_animals",
message:
  "❌ لا يمكن بدء برنامج التزامن لأي من الحيوانات المدخلة.\n\nالأسباب:\n" +
  rejected.map(r => {
    const n = String(r.animalNumber || "").trim();
    const reason = compactOvsynchReason(r.reason).replace(/^❌\s*/, "");
    return n ? `❌ الحيوان رقم ${n}: ${reason}` : `❌ ${reason}`;
  }).join("\n"),
    acceptedCount,
    rejectedCount,
    accepted,
    rejected
  });
}

return res.json({
  ok: true,
  allowed: true,
  stage: "eligible",
message:
  `راجعت ${numbers.length} حيوانًا: يمكن بدء برنامج التزامن لعدد ${acceptedCount}، ولا يمكن بدءه لعدد ${rejectedCount}.` +
  (
    rejectedCount
      ? "\n\n" + rejected.map(r => {
          const n = String(r.animalNumber || "").trim();
          const reason = compactOvsynchReason(r.reason).replace(/^❌\s*/, "");
          return n ? `❌ الحيوان رقم ${n}: ${reason}` : `❌ ${reason}`;
        }).join("\n")
      : ""
  ),
  acceptedCount,
  rejectedCount,
  accepted,
  rejected
});
  } catch (e) {
    console.error("ovsynch-gate", e);

    return res.status(500).json({
      ok: false,
      allowed: false,
      error: "ovsynch_gate_failed",
      message: "❌ تعذّر فحص أهلية الحيوانات لبرنامج التزامن الآن. حاول مرة أخرى.",
      acceptedCount: 0,
      rejectedCount: 0,
      accepted: [],
      rejected: []
    });
  }
});
// ============================================================
//                 API: OVSYNCH SAVE
//                 حفظ بروتوكول التزامن + Tasks + تحديث الحيوان
// ============================================================

app.post("/api/ovsynch/save", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        error: "firestore_disabled",
        message: "❌ تعذّر حفظ برنامج التزامن الآن. حاول مرة أخرى."
      });
    }

    const uid = req.userId;
    const body = req.body || {};

    const rawNumbers =
      body.animalNumbers ||
      body.numbers ||
      body.animalNumber ||
      body.number ||
      "";

    function parseOvsynchNumbersForSave(raw) {
      let arr = [];

      if (Array.isArray(raw)) {
        arr = raw;
      } else {
        const txt = String(raw || "").trim();
        if (!txt) return [];

        try {
          const parsed = JSON.parse(txt);
          arr = Array.isArray(parsed) ? parsed : txt.split(/\n|,|;|،|\s+/g);
        } catch (_) {
          arr = txt.split(/\n|,|;|،|\s+/g);
        }
      }

      return [...new Set(
        arr
          .map(x => calvingNormDigitsOnlySrv(x))
          .filter(Boolean)
      )];
    }

    function parseOvsynchStepsForSave(raw) {
      if (Array.isArray(raw)) return raw;

      const txt = String(raw || "").trim();
      if (!txt) return [];

      try {
        const parsed = JSON.parse(txt);
        return Array.isArray(parsed) ? parsed : [];
      } catch (_) {
        return [];
      }
    }

    const numbers = parseOvsynchNumbersForSave(rawNumbers);

    const eventDate = String(
      body.eventDate ||
      body.date ||
      body.startDate ||
      ""
    ).trim().slice(0, 10);

    const program = String(body.program || "").trim();
    const steps = parseOvsynchStepsForSave(body.steps);

    // حماية طلب الحفظ فقط — لا كتابة قبل اكتمال هذه البيانات
    const missing = {};
    if (!numbers.length) {
  missing.animalNumbers = "اختر حيوانًا واحدًا على الأقل.";
}

if (!eventDate || !calvingIsDateSrv(eventDate)) {
  missing.eventDate = "أدخل تاريخ بدء صحيحًا لبرنامج التزامن.";
}

if (!program) {
  missing.program = "اختر برنامج التزامن.";
}

if (!steps.length) {
  missing.steps = "اختر البرنامج أولًا حتى تظهر خطواته.";
}

    if (Object.keys(missing).length) {
      return res.status(400).json({
        ok: false,
        savedCount: 0,
        alreadyCount: 0,
        rejectedCount: 0,
        rejected: [],
        fieldErrors: missing,
        message: "❌ أكمل بيانات برنامج التزامن قبل الحفظ."
      });
    }

    function normalizeOvsynchSpeciesForSave(doc = {}, fallback = "") {
      let sp = String(
        fallback ||
        doc.species ||
        doc.animalTypeAr ||
        doc.animalType ||
        doc.animaltype ||
        doc.type ||
        ""
      ).trim();

      if (/cow|بقر/i.test(sp)) sp = "أبقار";
      if (/buffalo|جاموس/i.test(sp)) sp = "جاموس";

      return sp || "أبقار";
    }

    function ovsynchAnimalWordForSave(sp) {
      return sp === "جاموس" ? "جاموسة" : "بقرة";
    }

    function ovsynchReproCategoryForSave(raw) {
      const n = calvingStripArSrv(raw);

      if (
        n.includes("لاتلقح") ||
        n.includes("لاتلقحمرةاخرى") ||
        n.includes("لاتلقحمرهاخرى") ||
        n.includes("لاتلقحمرةاخري")
      ) return "blocked";

      if (n.includes("عشار")) return "pregnant";

      if (
        n.includes("ملقح") ||
        n.includes("ملقحة") ||
        n.includes("ملقّحة")
      ) return "inseminated";

      if (
        n.includes("مفتوح") ||
        n.includes("فارغ") ||
        n.includes("فارغة")
      ) return "open";

      return "unknown";
    }

    function compactOvsynchReasonForSave(reason) {
      let s = String(reason || "").trim();

      s = s.replace(/^\s*❌\s*/, "");
      s = s.replace(/\s+/g, " ").trim();

      s = s.replace(/الحالة الحالية:\s*«?\s*حديث(?:ة)? الولادة\s*»?/g, "حديثة الولادة");
      s = s.replace(/الحالة الحالية:\s*«?\s*تحضير(?: لل)?ولادة\s*»?/g, "تحضير للولادة");
      s = s.replace(/الحالة الحالية:\s*«?\s*ملقح(?:ة)?\s*»?/g, "ملقحة");
      s = s.replace(/الحالة الحالية:\s*«?\s*عشار\s*»?/g, "عشار");
      s = s.replace(/الحالة الحالية:\s*«?\s*مفتوح(?:ة)?\s*»?/g, "مفتوحة");

      s = s.replace(/\s*—\s*المسموح.*$/, "").trim();

      return "❌ " + s;
    }

function ovsynchEligibilityDecisionForSave(fd = {}) {
  const doc = fd.documentData;

  if (!doc) {
    return "❌ تعذّر قراءة بيانات الحيوان الآن.";
  }

  const st = String(doc.status ?? "").trim().toLowerCase();

  if (st === "inactive") {
    return "❌ الحيوان خارج القطيع، لذلك لا يمكن بدء برنامج التزامن له.";
  }

  const reproDocRaw = String(doc.reproductiveStatus || "").trim();
  const reproDocCat = ovsynchReproCategoryForSave(reproDocRaw);

  if (doc.breedingBlocked === true || reproDocCat === "blocked") {
    return "❌ الحيوان مستبعد من التلقيح، لذلك لا يمكن بدء برنامج التزامن له.";
  }

  const activeProtocolMsg = ovsynchActiveProtocolBlockMessageSrv(
    doc,
    fd.eventDate
  );

  if (activeProtocolMsg) return activeProtocolMsg;

  const sp = normalizeOvsynchSpeciesForSave(doc, fd.species);
  const w = ovsynchAnimalWordForSave(sp);

  const rsRaw = String(
    fd.reproStatusFromEvents ||
    doc.reproductiveStatus ||
    ""
  ).trim();

  const cat = ovsynchReproCategoryForSave(rsRaw);
  const shownStatus = rsRaw ? `«${rsRaw}»` : "غير معروفة";

  if (
    cat === "pregnant" ||
    cat === "inseminated" ||
    cat === "blocked"
  ) {
    return `❌ لا يمكن بدء برنامج التزامن؛ حالة ${w} التناسلية الحالية هي ${shownStatus}.`;
  }

  if (cat !== "open") {
    return `❌ لا يمكن بدء برنامج التزامن؛ حالة ${w} التناسلية الحالية هي ${shownStatus}، والبرنامج متاح للحيوانات المفتوحة فقط.`;
  }

  if (!calvingIsDateSrv(fd.eventDate)) {
    return "❌ أدخل تاريخ بدء صحيحًا لبرنامج التزامن.";
  }

  const lastCalving = String(doc.lastCalvingDate || "").trim();

  if (lastCalving && calvingIsDateSrv(lastCalving)) {
    const minAfterCalving = sp === "جاموس" ? 35 : 45;
    const sinceCalving = calvingDaysBetweenSrv(
      lastCalving,
      fd.eventDate
    );

    if (
      Number.isFinite(sinceCalving) &&
      sinceCalving >= 0 &&
      sinceCalving < minAfterCalving
    ) {
      return `❌ لا يمكن بدء برنامج التزامن الآن؛ مرّ على ولادة ${w} ${sinceCalving} يومًا فقط، والحد الأدنى ${minAfterCalving} يومًا.`;
    }
  }

  return null;
}

    async function getLastOvsynchEventForSave(animalNumber) {
      const num = calvingNormDigitsOnlySrv(animalNumber);
      if (!uid || !num) return null;

      try {
        const snap = await db.collection("events")
          .where("userId", "==", uid)
          .where("animalNumber", "==", num)
          .where("eventType", "==", "بروتوكول تزامن")
          .orderBy("eventDate", "desc")
          .limit(1)
          .get();

        if (snap.empty) return null;

        const d = snap.docs[0].data() || {};

        return {
          eventDate: String(d.eventDate || "").slice(0, 10),
          program: String(d.program || "").trim()
        };
      } catch (_) {
        return null;
      }
    }

    async function upsertOvsynchTasksForSave(batch, animalNumber, protocolStartISO, programKey, stepsArr) {
      if (!animalNumber || !protocolStartISO || !Array.isArray(stepsArr) || !stepsArr.length) return 0;

      const startDay = String(protocolStartISO).slice(0, 10);
      let ops = 0;

      for (let i = 0; i < stepsArr.length; i++) {
        const st = stepsArr[i] || {};
        const stepDay = (typeof st.day === "number") ? st.day : i;
        const stepName = st.name || `Step ${i}`;
        const stepDT = String(st.date || "");
        const dueDate = stepDT.slice(0, 10) || startDay;
        const taskId = `task__${animalNumber}__ovsynch__${startDay}__d${stepDay}`;
        const ref = db.collection("tasks").doc(taskId);

        const snap = await ref.get();

        if (snap.exists) {
          const cur = snap.data() || {};
          const stt = String(cur.status || "").toLowerCase();

          if (stt === "done" || stt === "cancelled") {
            continue;
          }
        }

        const isDone = !!st.done;
        const payload = {
          userId: uid,
          animalNumber: String(animalNumber),
          type: "protocol_step",
          taskType: "ovsynch_step",
          protocol: "ovsynch",
          program: programKey || "ovsynch",
          protocolStartDate: startDay,
          stepIndex: i,
          stepDay,
          stepKey: `ovsynch_d${stepDay}`,
          stepName,
          dueDate,
          plannedDate: dueDate,
          plannedTime: (stepDT && stepDT.length >= 16) ? stepDT.slice(11, 16) : "08:00",
          plannedDateTime: stepDT || (dueDate + "T08:00"),
          status: isDone ? "done" : "pending",
          done: isDone ? true : false,
          doneAt: isDone ? admin.firestore.FieldValue.serverTimestamp() : null,
          updatedAt: admin.firestore.FieldValue.serverTimestamp()
        };

        if (!snap.exists) {
          payload.createdAt = admin.firestore.FieldValue.serverTimestamp();
        }

        batch.set(ref, payload, { merge: true });
        ops++;
      }

      return ops;
    }

    const valid = [];
    const rejected = [];

    // إعادة فحص الأهلية داخل الحفظ قبل أي كتابة
    for (const animalNumber of numbers) {
      const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, animalNumber);

      if (!animal) {
        rejected.push({
          animalNumber,
          reason: "❌ لم أجد الحيوان في القطيع المسجل بحسابك."
        });
        continue;
      }

      // تم فحص الأهلية مسبقًا في /api/ovsynch/gate.
// الحفظ لا يعيد قرار الأهلية؛ يراجع فقط وجود الحيوان والتكرار القريب قبل الكتابة.
      const last = await getLastOvsynchEventForSave(animalNumber);

      if (last?.eventDate && String(last.program || "").trim() === "ovsynch") {
        const g14 = calvingDaysBetweenSrv(last.eventDate, eventDate);

        if (Number.isFinite(g14) && g14 >= 0 && g14 < 14) {
          rejected.push({
            animalNumber,
            reason: `❌ سبق تسجيل برنامج تزامن بدأ بتاريخ ${last.eventDate}.`
          });
          continue;
        }
      }

      valid.push({
        animalNumber,
        animal
      });
    }

    if (!valid.length) {
      return res.status(400).json({
        ok: false,
        savedCount: 0,
        alreadyCount: 0,
        rejectedCount: rejected.length,
        saved: [],
        rejected,
        message: rejected.length
  ? (
     numbers.length === 1
  ? (() => {
      const x = rejected[0] || {};
      const n = String(x.animalNumber || "").trim();
      const reason = compactOvsynchReasonForSave(
        x.reason || "❌ لا يمكن تسجيل برنامج التزامن لهذا الحيوان."
      ).replace(/^❌\s*/, "");

      return n ? `❌ الحيوان رقم ${n}: ${reason}` : `❌ ${reason}`;
    })()
  : rejected.slice(0, 8).map(x => {
      const n = String(x.animalNumber || "").trim();
      const reason = compactOvsynchReasonForSave(x.reason).replace(/^❌\s*/, "");

      return n ? `❌ الحيوان رقم ${n}: ${reason}` : `❌ ${reason}`;
    }).join("\n")
    )
  : (
      numbers.length === 1
        ? "❌ لا يمكن تسجيل برنامج التزامن لهذا الحيوان."
        : "❌ لا يمكن تسجيل برنامج التزامن لأي من الحيوانات المدخلة."
    )
      });
    }

    const batch = db.batch();
    let ops = 0;
    let savedCount = 0;
    let alreadyCount = 0;
    const saved = [];

    for (const item of valid) {
      const animalNumber = item.animalNumber;
      const animal = item.animal;

      const id = ["ovsynch", animalNumber, program, eventDate].join("__");
      const eventRef = db.collection("events").doc(id);

      const ex = await eventRef.get();

      if (ex.exists) {
        alreadyCount++;
        continue;
      }

      const eventPayload = {
        type: "ovsynch",
        eventType: "بروتوكول تزامن",
        eventTypeNorm: "ovsynch",
        eventDate,
        program,
        steps,
        userId: uid,
        ownerUid: uid,
        animalId: animal.id || "",
        animalNumber: String(animalNumber),
        source: "server:/api/ovsynch/save",
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedAt: admin.firestore.FieldValue.serverTimestamp()
      };

      batch.set(eventRef, eventPayload);
      ops++;

      ops += await upsertOvsynchTasksForSave(batch, animalNumber, eventDate, program, steps);

     const protocolDurationDays = ovsynchProgramDurationDaysSrv(program);

batch.set(db.collection(animal._collection || "animals").doc(animal.id), {
  currentProtocol: "ovsynch",
  currentProtocolProgram: program,
  protocolProgram: program,
  protocolStatus: "active",
  protocolStartDate: eventDate,
  protocolExpectedEndDate: addDaysToIsoDateSrv(eventDate, protocolDurationDays),
  status: "active",
  updatedAt: admin.firestore.FieldValue.serverTimestamp()
}, { merge: true });
      ops++;

      savedCount++;
      saved.push({
        animalNumber,
        eventId: id
      });
    }

    if (ops > 0) {
      await batch.commit();
    }
  if (savedCount && typeof scheduleGroupsRebuildSrv === "function") {
      scheduleGroupsRebuildSrv(uid, "ovsynch_save");
    }

const savedNumbers = saved
  .map(x => String(x.animalNumber || "").trim())
  .filter(Boolean);

let message = "";

if (savedNumbers.length === 1) {
  message = `✅ سجلت برنامج التزامن للحيوان رقم ${savedNumbers[0]} بنجاح.`;

} else if (savedNumbers.length > 1) {
  message = `✅ سجلت برنامج التزامن لعدد ${savedNumbers.length} من الحيوانات بنجاح.`;

} else if (alreadyCount > 0) {
  message = alreadyCount === 1
    ? "سبق تسجيل برنامج التزامن لهذا الحيوان."
    : `سبق تسجيل برنامج التزامن لعدد ${alreadyCount} من الحيوانات.`;

} else {
  message = "❌ لم أتمكن من تسجيل برنامج التزامن لأي حيوان.";
}
    return res.json({
      ok: true,
      message,
      savedCount,
      alreadyCount,
      rejectedCount: rejected.length,
      saved,
      rejected
    });

  } catch (e) {
    console.error("ovsynch-save", e);

    return res.status(500).json({
      ok: false,
      error: "ovsynch_save_failed",
      message: "❌ تعذّر حفظ برنامج التزامن الآن. حاول مرة أخرى."
    });
  }
});
// ============================================================
//                 API: OVSYNCH DASHBOARD ALERTS
//                 تنبيهات الداشبورد الذكية من tasks — عرض فقط
// ============================================================

app.get("/api/ovsynch/dashboard-alerts", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        alerts: [],
       message: "❌ تعذّر تحميل تنبيهات برنامج التزامن الآن. حاول مرة أخرى."
      });
    }

    const uid = req.userId;

    function addDaysISOForOvsynchAlerts(iso, days) {
      const s = String(iso || "").trim().slice(0, 10);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return "";
      const [y, m, d] = s.split("-").map(Number);
      const dt = new Date(Date.UTC(y, m - 1, d));
      dt.setUTCDate(dt.getUTCDate() + Number(days || 0));
      return dt.toISOString().slice(0, 10);
    }

    function normTaskNumberForOvsynchAlerts(v) {
      if (typeof calvingNormDigitsOnlySrv === "function") {
        return calvingNormDigitsOnlySrv(v);
      }
      return String(v || "").replace(/[^\d]/g, "").trim();
    }

   const today =
  await farmTodayISOSrv(
    req.authSession?.uid ||
    req.userId
  );
        const yesterday = addDaysISOForOvsynchAlerts(today, -1);
    const tomorrow = addDaysISOForOvsynchAlerts(today, 1);

    const farmClock = await farmTimeContextSrv(
      req.authSession?.uid ||
      req.userId
    );

    const farmTimeZone =
      String(farmClock?.timeZone || "UTC").trim() ||
      "UTC";

    const nowMs = Date.now();

    const snap = await db.collection("tasks")
      .where("userId", "==", uid)
      .where("status", "==", "pending")
      .limit(500)
      .get();

    const groups = new Map();

    snap.forEach(docSnap => {
      const t = docSnap.data() || {};

      const isOvsynchTask =
        String(t.taskType || "").trim() === "ovsynch_step" ||
        String(t.type || "").trim() === "ovsynch_step" ||
        (
          String(t.type || "").trim() === "protocol_step" &&
          String(t.protocol || "").trim() === "ovsynch"
        );

      if (!isOvsynchTask) return;

          const dueDate = String(t.dueDate || t.plannedDate || "").trim().slice(0, 10);

      if (
        dueDate !== yesterday &&
        dueDate !== today &&
        dueDate !== tomorrow
      ) {
        return;
      }

      const plannedTime =
        murabbikOvsynchAlertTimeSrv(
          t.plannedTime ||
          String(t.plannedDateTime || "").slice(11, 16)
        );

      const dueAtMs =
        murabbikOvsynchAlertDateTimeMsSrv(
          dueDate,
          plannedTime,
          farmTimeZone
        );

      if (!Number.isFinite(dueAtMs)) return;

      const visibleFromMs =
        dueAtMs -
        (
          MURABBIK_OVSYNCH_ALERT_LEAD_MINUTES *
          60 *
          1000
        );

      const visibleUntilMs =
        dueAtMs +
        (
          MURABBIK_OVSYNCH_ALERT_GRACE_MINUTES *
          60 *
          1000
        );

      const isDayBefore =
        dueDate === tomorrow &&
        nowMs < visibleFromMs;

      const isDueWindow =
        nowMs >= visibleFromMs &&
        nowMs <= visibleUntilMs;

      if (!isDayBefore && !isDueWindow) return;

      const alertPhase =
        isDueWindow
          ? "due_window"
          : "day_before";

      const animalNumber = normTaskNumberForOvsynchAlerts(t.animalNumber || t.number || "");
      if (!animalNumber) return;

      const stepIndex = Number(t.stepIndex ?? 0) || 0;
      const stepDay = Number(t.stepDay ?? 0) || 0;
      const stepName = String(t.stepName || t.title || "خطوة التزامن").trim();
      const program = String(t.program || t.protocolProgram || "ovsynch").trim();
      const protocolStartDate = String(t.protocolStartDate || "").trim().slice(0, 10);

       const key = [
        alertPhase,
        dueDate,
        plannedTime,
        program,
        protocolStartDate,
        stepIndex,
        stepDay,
        stepName
      ].join("__");
      
      if (!groups.has(key)) {
          groups.set(key, {
          alertPhase,
          dueDate,
          dueDate,
          plannedTime,
          program,
          protocolStartDate,
          stepIndex,
          stepDay,
          stepName,
          animalNumbers: []
        });
      }

      groups.get(key).animalNumbers.push(animalNumber);
    });

    const alerts = [];

    for (const g of groups.values()) {
      const nums = [...new Set(g.animalNumbers)].filter(Boolean).sort((a, b) => Number(a) - Number(b));
      if (!nums.length) continue;

        const isDueWindow =
        g.alertPhase === "due_window";

      const title = isDueWindow
        ? "خطوة برنامج التزامن اليوم"
        : "خطوة برنامج التزامن غدًا";

      const prefix = isDueWindow ? "⏰ اليوم" : "📌 غدًا";

      const message =
        `${prefix} خطوة برنامج التزامن: ${g.stepName}\n` +
        `للحيوانات أرقام: ${nums.join("، ")}\n` +
        `الموعد: ${g.plannedTime}`;

      const actionUrl =
        `ovysynch.html?mode=step` +
        `&date=${encodeURIComponent(g.dueDate)}` +
        `&dueDate=${encodeURIComponent(g.dueDate)}` +
        `&stepIndex=${encodeURIComponent(g.stepIndex)}` +
        `&program=${encodeURIComponent(g.program)}` +
        `&protocolStartDate=${encodeURIComponent(g.protocolStartDate || "")}`;

      alerts.push({
        id: `ovsynch_${g.dueDate}_${g.stepIndex}_${g.protocolStartDate || "no_start"}`,
        source: "server:/api/ovsynch/dashboard-alerts",
        type: "ovsynch_step",
        level: isDueWindow ? "warn" : "info",
        title,
        message,
        actionText: "فتح صفحة التزامن",
        actionUrl,
        dueDate: g.dueDate,
        plannedTime: g.plannedTime,
        program: g.program,
        protocolStartDate: g.protocolStartDate,
        stepIndex: g.stepIndex,
        stepDay: g.stepDay,
        stepName: g.stepName,
        animalNumbers: nums,
        count: nums.length
      });
    }

    alerts.sort((a, b) => {
      const da = String(a.dueDate || "");
      const dbb = String(b.dueDate || "");
      if (da !== dbb) return da.localeCompare(dbb);
      return String(a.plannedTime || "").localeCompare(String(b.plannedTime || ""));
    });

    return res.json({
      ok: true,
      today,
      tomorrow,
      count: alerts.length,
      alerts
    });

  } catch (e) {
    console.error("ovsynch-dashboard-alerts", e);

    return res.status(500).json({
      ok: false,
      alerts: [],
     message: "❌ تعذّر تحميل تنبيهات برنامج التزامن الآن. حاول مرة أخرى."
    });
  }
});
