app.get("/api/ovsynch/step-targets", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        message: "❌ تعذّر تحميل الحيوانات المستحقة لخطوة التزامن الآن. حاول مرة أخرى.",
        animalNumbers: [],
        count: 0,
        meta: null
      });
    }

    const uid = req.userId;

    const stepIndex = Math.max(
      0,
      parseInt(
        req.query.stepIndex ??
        req.query.step ??
        "0",
        10
      ) || 0
    );

   const farmToday =
  await farmTodayISOSrv(
    req.authSession?.uid ||
    req.userId
  );

const dueDate = String(
  req.query.dueDate ||
  req.query.date ||
  farmToday
).trim().slice(0, 10);

const requestedProgram = String(
  req.query.program ||
  req.query.protocolProgram ||
  ""
).trim();

const requestedProtocolStartDate =
  String(
    req.query.protocolStartDate ||
    req.query.startDate ||
    ""
  ).trim().slice(0, 10);

    const snap = await db.collection("tasks")
      .where("userId", "==", uid)
      .where("dueDate", "==", dueDate)
      .where("status", "==", "pending")
      .limit(500)
      .get();

    const nums = [];
    let meta = null;

    snap.forEach(docSnap => {
      const t = docSnap.data() || {};

      const isOvsynchTask =
        String(t.type || "").trim() === "ovsynch_step" ||
        (
          String(t.type || "").trim() === "protocol_step" &&
          String(t.protocol || "").trim() === "ovsynch"
        );

     if (!isOvsynchTask) return;
if (Number(t.stepIndex) !== stepIndex) return;

const taskProgram = String(
  t.program ||
  t.protocolProgram ||
  ""
).trim();

const taskProtocolStartDate =
  String(
    t.protocolStartDate || ""
  ).trim().slice(0, 10);

if (
  requestedProgram &&
  taskProgram !== requestedProgram
) {
  return;
}

if (
  requestedProtocolStartDate &&
  taskProtocolStartDate !==
    requestedProtocolStartDate
) {
  return;
}

const n =
  calvingNormDigitsOnlySrv(
    t.animalNumber || ""
  );
      if (!n) return;

      nums.push(n);

      if (!meta) {
        meta = {
          type: t.type || "",
          protocol: t.protocol || "ovsynch",
          program: t.program || t.protocolProgram || "",
          protocolProgram: t.protocolProgram || t.program || "",
          protocolStartDate: String(t.protocolStartDate || "").slice(0, 10),
          stepIndex: Number(t.stepIndex || 0),
          stepDay: Number(t.stepDay || 0),
          stepKey: String(t.stepKey || ""),
          stepName: String(t.stepName || ""),
          dueDate: String(t.dueDate || dueDate).slice(0, 10),
          plannedDate: String(t.plannedDate || t.dueDate || dueDate).slice(0, 10),
          plannedTime: String(t.plannedTime || "")
        };
      }
    });

    const animalNumbers = [...new Set(nums)].filter(Boolean);

    if (!animalNumbers.length) {
      return res.json({
        ok: true,
       message: "لا توجد حيوانات مستحقة لتنفيذ هذه الخطوة اليوم.",
        dueDate,
        stepIndex,
        animalNumbers: [],
        count: 0,
        meta: null
      });
    }

    const stepName = String(meta?.stepName || ("الخطوة رقم " + stepIndex));
    const message = animalNumbers.length === 1
    ? `موعد اليوم تنفيذ خطوة «${stepName}» للحيوان رقم ${animalNumbers[0]}.`
    : `موعد اليوم تنفيذ خطوة «${stepName}» لعدد ${animalNumbers.length} من الحيوانات.`;

    return res.json({
      ok: true,
      message,
      dueDate,
      stepIndex,
      animalNumbers,
      count: animalNumbers.length,
      meta
    });

  } catch (e) {
    console.error("ovsynch-step-targets", e);

    return res.status(500).json({
      ok: false,
      message: "❌ تعذّر تحميل الحيوانات المستحقة لخطوة التزامن الآن. حاول مرة أخرى.",
      animalNumbers: [],
      count: 0,
      meta: null
    });
  }
});
