function vaccinationFarmProgramTextSrv(raw) {
  return String(raw || "").trim().replace(/\s+/g, " ");
}

function vaccinationFarmProgramDateSrv(raw) {
  const value = String(raw || "").trim().slice(0, 10);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return "";
  }

  const ms = Date.parse(`${value}T00:00:00Z`);

  if (!Number.isFinite(ms)) {
    return "";
  }

  return new Date(ms).toISOString().slice(0, 10) === value
    ? value
    : "";
}

function vaccinationFarmProgramIntSrv(raw, fallback = 0) {
  if (
    raw === "" ||
    raw === null ||
    raw === undefined
  ) {
    return fallback;
  }

  const n = Number(raw);

  return Number.isInteger(n)
    ? n
    : NaN;
}

function vaccinationFarmProgramRowsSrv(body = {}) {
  const rows =
    body.rows ??
    body.items ??
    body.schedule ??
    body.programRows;

  return Array.isArray(rows)
    ? rows
    : null;
}
function vaccinationProgramDoseLabelSrv({
  doseType = "",
  timingBasis = "",
  scheduleLength = 0,
  fallbackLabel = ""
} = {}) {
  const type =
    String(doseType || "").trim();

  const basis =
    String(timingBasis || "").trim();

  const count =
    Number(scheduleLength || 0);

  if (
    basis ===
      "before_expected_calving"
  ) {
    if (count <= 1) {
      return "جرعة قبل الولادة";
    }

    return type === "booster"
      ? "الجرعة المنشطة قبل الولادة"
      : "الجرعة الأولى قبل الولادة";
  }

  return String(
    fallbackLabel || ""
  ).trim();
}
function vaccinationFarmProgramExpandSimpleRowSrv(raw = {}) {
  if (
    !raw ||
    typeof raw !== "object" ||
    Array.isArray(raw)
  ) {
    return raw;
  }

  if (
    Array.isArray(raw.doseSchedule) &&
    raw.doseSchedule.length
  ) {
    return raw;
  }

  const programType =
    String(raw.programType || "").trim();
  if (!programType) return raw;

  const num = name => vaccinationFarmProgramIntSrv(raw[name], 0);
  const txt = name => String(raw[name] || "").trim();

  const dose = (
    doseType,
    timingBasis,
    timingValue = 0,
    timingUnit = "",
    extra = {}
  ) => ({
    doseType,
    timingBasis,
    timingValue,
    timingUnit,
    ...extra
  });

  const programInput = {
    calfStartValue: num("calfStartValue"),
    calfStartUnit: txt("calfStartUnit"),

    boosterAfterValue: num("boosterAfterValue"),
    boosterAfterUnit: txt("boosterAfterUnit"),

    periodicEveryValue: num("periodicEveryValue"),
    periodicEveryUnit: txt("periodicEveryUnit"),

    motherDose1BeforeValue: num("motherDose1BeforeValue"),
    motherDose1BeforeUnit: txt("motherDose1BeforeUnit"),

    motherDose2BeforeValue: num("motherDose2BeforeValue"),
    motherDose2BeforeUnit: txt("motherDose2BeforeUnit"),

    lifetimeAgeMinValue: num("lifetimeAgeMinValue"),
    lifetimeAgeMinUnit: txt("lifetimeAgeMinUnit"),

    lifetimeAgeMaxValue: num("lifetimeAgeMaxValue"),
    lifetimeAgeMaxUnit: txt("lifetimeAgeMaxUnit")
  };

  let programSection = "";
  let doseSchedule = [];

  if (programType === "herd") {
    programSection = "herd";

    doseSchedule = [
      dose("prime", "any_time"),

      ...(programInput.boosterAfterValue || programInput.boosterAfterUnit
        ? [
            dose(
              "booster",
              "after_previous_dose",
              programInput.boosterAfterValue,
              programInput.boosterAfterUnit
            )
          ]
        : []),

      dose(
        "periodic",
        "repeat",
        programInput.periodicEveryValue,
        programInput.periodicEveryUnit
      )
    ];
  }

  if (programType === "calves_to_herd") {
    programSection = "calves";

    doseSchedule = [
      dose(
        "prime",
        "calf_age",
        programInput.calfStartValue,
        programInput.calfStartUnit
      ),

      ...(programInput.boosterAfterValue || programInput.boosterAfterUnit
        ? [
            dose(
              "booster",
              "after_previous_dose",
              programInput.boosterAfterValue,
              programInput.boosterAfterUnit
            )
          ]
        : []),

      dose(
        "periodic",
        "repeat",
        programInput.periodicEveryValue,
        programInput.periodicEveryUnit,
        {
          joinHerdSchedule: true
        }
      )
    ];
  }

  if (programType === "mothers") {
    programSection = "mothers";

    const hasBooster =
      programInput.motherDose2BeforeValue ||
      programInput.motherDose2BeforeUnit;

    doseSchedule = hasBooster
      ? [
          dose(
            "prime",
            "before_expected_calving",
            programInput.motherDose1BeforeValue,
            programInput.motherDose1BeforeUnit,
            {
              cycle: "each_pregnancy"
            }
          ),

          dose(
            "booster",
            "before_expected_calving",
            programInput.motherDose2BeforeValue,
            programInput.motherDose2BeforeUnit,
            {
              cycle: "each_pregnancy"
            }
          )
        ]
          : [
          dose(
            "prime",
            "before_expected_calving",
            programInput.motherDose1BeforeValue,
            programInput.motherDose1BeforeUnit,
            {
              cycle: "each_pregnancy"
            }
          )
        ];
  }

  if (programType === "once_lifetime") {
    programSection = "calves";

    const hasAgeWindow =
      programInput.lifetimeAgeMaxValue ||
      programInput.lifetimeAgeMaxUnit;

    doseSchedule = [
      hasAgeWindow
        ? dose(
            "prime",
            "calf_age_window",
            0,
            "",
            {
              ageMinValue:
                programInput.lifetimeAgeMinValue,

              ageMinUnit:
                programInput.lifetimeAgeMinUnit,

              ageMaxValue:
                programInput.lifetimeAgeMaxValue,

              ageMaxUnit:
                programInput.lifetimeAgeMaxUnit,

              cycle:
                "once_lifetime"
            }
          )
        : dose(
            "prime",
            "calf_age",
            programInput.lifetimeAgeMinValue,
            programInput.lifetimeAgeMinUnit,
            {
              cycle:
                "once_lifetime"
            }
          )
    ];
  }

  return {
    ...raw,

    programType,
    programSection,
    programInput,
    doseSchedule,

    startDate: ""
  };
}
function vaccinationFarmProgramNormalizeRowsSrv(rawRows = []) {
  const rows = [];
  const errors = [];
  const seenRows = new Set();
  const options = vaccinationFarmProgramOptionsSrv();

  const findOption = (list, raw) => {
    const value = String(raw || "").trim();
    if (!value || !Array.isArray(list)) return null;

    return list.find(item =>
      String(item?.value || "") === value ||
      String(item?.label || "") === value
    ) || null;
  };

  const addError = (
    rowIndex,
    field,
    message,
    doseIndex = null
  ) => {
    errors.push({
      rowIndex,

      ...(Number.isInteger(doseIndex)
        ? { doseIndex }
        : {}),

      field,
      message
    });
  };

  const unitDays = {
    day: 1,
    week: 7,
    month: 30,
    year: 365
  };

  const asDays = (value, unit) =>
    Number(value) *
    Number(unitDays[unit] || 0);

    rawRows.forEach((raw, rowIndex) => {
    raw = vaccinationFarmProgramExpandSimpleRowSrv(
      raw
    );

    const rowNumber = rowIndex + 1;

    if (
      !raw ||
      typeof raw !== "object" ||
      Array.isArray(raw)
    ) {
      addError(
        rowIndex,
        "row",
        `السطر رقم ${rowNumber} غير صالح.`
      );

      return;
    }

    const programSection =
      findOption(
        options.programSections,

        raw.programSection ||
        raw.section ||
        raw.programGroup
      );

    const vaccine =
      findOption(
        options.vaccines,

        raw.vaccineCode ||
        raw.vaccineName ||
        raw.vaccine
      );

    const rawVaccineForm =
      String(
        raw.vaccineForm ||
        raw.vaccineType ||
        raw.formType ||
        ""
      ).trim();

    const vaccineForm =
      vaccine
        ? (
            findOption(
              vaccine.formOptions,
              rawVaccineForm
            ) ||
            (
              !rawVaccineForm &&
              vaccine.formOptions?.length === 1
                ? vaccine.formOptions[0]
                : null
            )
          )
        : null;

    if (!programSection) {
      addError(
        rowIndex,
        "programSection",
        `اختر قسم التحصين في السطر رقم ${rowNumber}.`
      );
    }

    if (!vaccine) {
      addError(
        rowIndex,
        "vaccineCode",
        `اختر اسم التحصين من القائمة في السطر رقم ${rowNumber}.`
      );
    }

    if (vaccine && !vaccineForm) {
      addError(
        rowIndex,
        "vaccineForm",
        `اختر نوع اللقاح في السطر رقم ${rowNumber}.`
      );
    }

    const rowKey =
      programSection && vaccine
        ? `${programSection.value}:${vaccine.value}`
        : "";

    if (
      rowKey &&
      seenRows.has(rowKey)
    ) {
      addError(
        rowIndex,
        "vaccineCode",
        "التحصين مضاف بالفعل داخل نفس القسم. أضف كل تحصين مرة واحدة وضع جميع جرعاته داخله."
      );
    }

    const rawDoseSchedule =
      Array.isArray(raw.doseSchedule)
        ? raw.doseSchedule
        : null;

    if (
      !rawDoseSchedule ||
      !rawDoseSchedule.length
    ) {
      addError(
        rowIndex,
        "doseSchedule",

        !rawDoseSchedule
          ? `أرسل جدول جرعات التحصين في السطر رقم ${rowNumber}.`
          : `أضف جرعة واحدة على الأقل للتحصين في السطر رقم ${rowNumber}.`
      );
    }
    const doseSchedule = [];
    const usedDoseTypes = new Set();

    (rawDoseSchedule || []).forEach(
      (rawStep, doseIndex) => {
        const doseNumber =
          doseIndex + 1;

        if (
          !rawStep ||
          typeof rawStep !== "object" ||
          Array.isArray(rawStep)
        ) {
          addError(
            rowIndex,
            "doseSchedule",
            `الجرعة رقم ${doseNumber} في السطر رقم ${rowNumber} غير صالحة.`,
            doseIndex
          );

          return;
        }

        const doseType =
          findOption(
            options.doseTypes,
            rawStep.doseType
          );

        const timingBasis =
          findOption(
            options.doseTimingBases,
            rawStep.timingBasis
          );

        const cycleRaw =
          String(
            rawStep.cycle || ""
          ).trim();

        const cycle =
          cycleRaw
            ? findOption(
                options.doseCycles,
                cycleRaw
              )
            : null;

        if (!doseType) {
          addError(
            rowIndex,
            "doseType",
            `اختر نوع الجرعة رقم ${doseNumber}.`,
            doseIndex
          );
        } else if (
          usedDoseTypes.has(
            doseType.value
          )
        ) {
          addError(
            rowIndex,
            "doseType",
            `نوع الجرعة «${doseType.label}» مكرر داخل نفس التحصين.`,
            doseIndex
          );
        }

        if (!timingBasis) {
          addError(
            rowIndex,
            "timingBasis",
            `اختر توقيت الجرعة رقم ${doseNumber}.`,
            doseIndex
          );
        }

        if (
          cycleRaw &&
          !cycle
        ) {
          addError(
            rowIndex,
            "cycle",
            `اختر دورة الجرعة رقم ${doseNumber} من القائمة المعتمدة.`,
            doseIndex
          );
        }

        const timingValue =
          vaccinationFarmProgramIntSrv(
            rawStep.timingValue,
            0
          );

        const timingUnit =
          String(
            rawStep.timingUnit || ""
          ).trim()
            ? findOption(
                options.repeatUnits,
                rawStep.timingUnit
              )
            : null;

        const basis =
          timingBasis?.value || "";

        const needsDuration =
          [
            "after_previous_dose",
            "repeat",
            "calf_age",
            "before_expected_calving"
          ].includes(basis);

        if (
          needsDuration &&
          (
            !Number.isInteger(
              timingValue
            ) ||
            timingValue <= 0 ||
            timingValue > 120
          )
        ) {
          addError(
            rowIndex,
            "timingValue",
            `أدخل مدة صحيحة للجرعة رقم ${doseNumber}.`,
            doseIndex
          );
        }

        if (
          needsDuration &&
          !timingUnit
        ) {
          addError(
            rowIndex,
            "timingUnit",
            `اختر وحدة توقيت الجرعة رقم ${doseNumber}.`,
            doseIndex
          );
        }

        if (
          basis ===
            "after_previous_dose" &&
          doseIndex === 0
        ) {
          addError(
            rowIndex,
            "timingBasis",
            "لا يمكن أن تبدأ جرعات التحصين بجرعة محسوبة بعد جرعة سابقة.",
            doseIndex
          );
        }

        if (
          basis === "calf_age" &&
          programSection?.value !==
            "calves"
        ) {
          addError(
            rowIndex,
            "timingBasis",
            "توقيت الجرعة حسب العمر متاح داخل قسم تحصينات العجول فقط.",
            doseIndex
          );
        }

        if (
          basis ===
            "before_expected_calving" &&
          programSection?.value !==
            "mothers"
        ) {
          addError(
            rowIndex,
            "timingBasis",
            "توقيت الجرعة قبل الولادة متاح داخل قسم تحصينات الأمهات فقط.",
            doseIndex
          );
        }

        if (
          basis ===
            "before_expected_calving" &&
          cycle?.value !==
            "each_pregnancy"
        ) {
          addError(
            rowIndex,
            "cycle",
            "جرعات ما قبل الولادة يجب أن تتكرر مع كل حمل.",
            doseIndex
          );
        }

        const ageMinValue =
          vaccinationFarmProgramIntSrv(
            rawStep.ageMinValue,
            NaN
          );

        const ageMinUnit =
          String(
            rawStep.ageMinUnit || ""
          ).trim()
            ? findOption(
                options.calfAgeUnits,
                rawStep.ageMinUnit
              )
            : null;

        const ageMaxValue =
          vaccinationFarmProgramIntSrv(
            rawStep.ageMaxValue,
            NaN
          );

        const ageMaxUnit =
          String(
            rawStep.ageMaxUnit || ""
          ).trim()
            ? findOption(
                options.calfAgeUnits,
                rawStep.ageMaxUnit
              )
            : null;

        if (
          basis ===
            "calf_age_window"
        ) {
          if (
            programSection?.value !==
              "calves"
          ) {
            addError(
              rowIndex,
              "timingBasis",
              "النافذة العمرية متاحة للعجول فقط.",
              doseIndex
            );
          }

          if (
            !Number.isInteger(
              ageMinValue
            ) ||
            ageMinValue <= 0 ||
            ageMinValue > 120
          ) {
            addError(
              rowIndex,
              "ageMinValue",
              `أدخل بداية عمر صحيحة للجرعة رقم ${doseNumber}.`,
              doseIndex
            );
          }

          if (!ageMinUnit) {
            addError(
              rowIndex,
              "ageMinUnit",
              `اختر وحدة بداية العمر للجرعة رقم ${doseNumber}.`,
              doseIndex
            );
          }

          if (
            !Number.isInteger(
              ageMaxValue
            ) ||
            ageMaxValue <= 0 ||
            ageMaxValue > 120
          ) {
            addError(
              rowIndex,
              "ageMaxValue",
              `أدخل نهاية عمر صحيحة للجرعة رقم ${doseNumber}.`,
              doseIndex
            );
          }

          if (!ageMaxUnit) {
            addError(
              rowIndex,
              "ageMaxUnit",
              `اختر وحدة نهاية العمر للجرعة رقم ${doseNumber}.`,
              doseIndex
            );
          }

          if (
            Number.isInteger(
              ageMinValue
            ) &&
            ageMinUnit &&
            Number.isInteger(
              ageMaxValue
            ) &&
            ageMaxUnit &&
            asDays(
              ageMinValue,
              ageMinUnit.value
            ) >=
              asDays(
                ageMaxValue,
                ageMaxUnit.value
              )
          ) {
            addError(
              rowIndex,
              "ageMaxValue",
              "نهاية النافذة العمرية يجب أن تكون بعد بدايتها.",
              doseIndex
            );
          }

          if (
            cycle?.value !==
              "once_lifetime"
          ) {
            addError(
              rowIndex,
              "cycle",
              "جرعة النافذة العمرية يجب أن تكون مرة واحدة في العمر.",
              doseIndex
            );
          }
        }

        if (
          errors.some(item =>
            item.rowIndex === rowIndex &&
            item.doseIndex ===
              doseIndex
          )
        ) {
          return;
        }

        usedDoseTypes.add(
          doseType.value
        );

        doseSchedule.push({
          doseType:
            doseType.value,

                   doseTypeLabel:
            vaccinationProgramDoseLabelSrv({
              doseType:
                doseType.value,

              timingBasis:
                timingBasis.value,

              scheduleLength:
                rawDoseSchedule?.length || 0,

              fallbackLabel:
                doseType.label
            }),

          timingBasis:
            timingBasis.value,

          timingBasisLabel:
            timingBasis.label,

          timingValue:
            needsDuration
              ? timingValue
              : 0,

          timingUnit:
            needsDuration
              ? timingUnit.value
              : "",

          timingUnitLabel:
            needsDuration
              ? timingUnit.label
              : "",

          ...(cycle
            ? {
                cycle:
                  cycle.value,

                cycleLabel:
                  cycle.label
              }
            : {}),

          ...(basis ===
            "calf_age_window"
            ? {
                ageMinValue,

                ageMinUnit:
                  ageMinUnit.value,

                ageMinUnitLabel:
                  ageMinUnit.label,

                ageMaxValue,

                ageMaxUnit:
                  ageMaxUnit.value,

                ageMaxUnitLabel:
                  ageMaxUnit.label
              }
            : {}),

          ...(rawStep
            .joinHerdSchedule === true
            ? {
                joinHerdSchedule: true
              }
            : {})
        });
      }
    );

    const repeatIndexes =
      doseSchedule
        .map(
          (step, doseIndex) =>
            step.timingBasis ===
              "repeat"
              ? doseIndex
              : -1
        )
        .filter(
          doseIndex =>
            doseIndex >= 0
        );

    if (
      repeatIndexes.length > 1
    ) {
      addError(
        rowIndex,
        "doseSchedule",
        "لا يمكن إضافة أكثر من جرعة تكرار دوري داخل التحصين نفسه."
      );
    }

    if (
      repeatIndexes.length === 1 &&
      repeatIndexes[0] !==
        doseSchedule.length - 1
    ) {
      addError(
        rowIndex,
        "doseSchedule",
        "جرعة التكرار الدوري يجب أن تكون آخر جرعة في التسلسل."
      );
    }

    const preCalvingSteps =
      doseSchedule.filter(
        step =>
          step.timingBasis ===
            "before_expected_calving"
      );

    for (
      let i = 1;
      i < preCalvingSteps.length;
      i += 1
    ) {
      const previous =
        preCalvingSteps[i - 1];

      const current =
        preCalvingSteps[i];

      if (
        asDays(
          current.timingValue,
          current.timingUnit
        ) >=
        asDays(
          previous.timingValue,
          previous.timingUnit
        )
      ) {
        addError(
          rowIndex,
          "doseSchedule",
          "رتّب جرعات ما قبل الولادة من الأبعد عن موعد الولادة إلى الأقرب."
        );

        break;
      }
    }

    if (
      doseSchedule.length &&
      !repeatIndexes.length
    ) {
      const finalCycle =
        String(
          doseSchedule[
            doseSchedule.length - 1
          ]?.cycle || ""
        ).trim();

      if (
        ![
          "once_lifetime",
          "each_pregnancy"
        ].includes(finalCycle)
      ) {
        addError(
          rowIndex,
          "cycle",
          "حدّد هل تنتهي آخر جرعة مرة واحدة في العمر أو تتكرر مع كل حمل."
        );
      }
    }

    const startDateRaw =
      String(
        raw.startDate ||
        raw.date ||
        ""
      ).trim();

    const startDate =
      startDateRaw
        ? vaccinationFarmProgramDateSrv(
            startDateRaw
          )
        : "";

    if (
      startDateRaw &&
      !startDate
    ) {
      addError(
        rowIndex,
        "startDate",
        `تاريخ بداية البرنامج غير صحيح في السطر رقم ${rowNumber}.`
      );
    }

    const advanceNoticeDays =
      vaccinationFarmProgramIntSrv(
        raw.advanceNoticeDays,
        0
      );

    if (
      !Number.isInteger(
        advanceNoticeDays
      ) ||
      advanceNoticeDays < 0 ||
      advanceNoticeDays > 90
    ) {
      addError(
        rowIndex,
        "advanceNoticeDays",
        `مدة التنبيه غير صحيحة في السطر رقم ${rowNumber}.`
      );
    }

    const notes =
      vaccinationFarmProgramTextSrv(
        raw.notes
      );

    if (
      notes.length > 500
    ) {
      addError(
        rowIndex,
        "notes",
        `ملاحظات السطر رقم ${rowNumber} أطول من المسموح.`
      );
    }

    if (
      errors.some(
        item =>
          item.rowIndex === rowIndex
      )
    ) {
      return;
    }

    seenRows.add(rowKey);

    const rowId =
      String(
        raw.rowId ||
        raw.programRowId ||
        raw.id ||
        ""
      )
        .trim()
        .replace(
          /[^A-Za-z0-9_-]/g,
          "_"
        )
        .slice(0, 80) ||
      crypto.randomUUID();

    const allowedDoseTypes =
      doseSchedule.map(
        step => step.doseType
      );

    const fixedDoseType =
      allowedDoseTypes.length === 1
        ? allowedDoseTypes[0]
        : "";

      const fixedDoseTypeLabel =
      fixedDoseType
        ? String(
            doseSchedule.find(step =>
              step.doseType ===
                fixedDoseType
            )?.doseTypeLabel || ""
          ).trim()
        : "";

    const repeatStep =
      doseSchedule.find(
        step =>
          step.timingBasis ===
            "repeat"
      ) ||
      null;

    const calfAgeStep =
      doseSchedule.find(
        step =>
          step.timingBasis ===
            "calf_age"
      ) ||
      null;

    const calfAgeWindowStep =
      doseSchedule.find(
        step =>
          step.timingBasis ===
            "calf_age_window"
      ) ||
      null;

    const cycles = [
      ...new Set(
        doseSchedule
          .map(
            step =>
              String(
                step.cycle || ""
              ).trim()
          )
          .filter(Boolean)
      )
    ];

    const rowCycle =
      cycles.length === 1
        ? cycles[0]
        : "";

    const singleOnceLifetime =
      doseSchedule.length === 1 &&
      rowCycle ===
        "once_lifetime";

    const targetGroup =
      programSection.value ===
        "calves"
        ? "calves"
        : programSection.value ===
            "mothers"
          ? (
              doseSchedule.some(
                step =>
                  step.timingBasis ===
                    "before_expected_calving"
              )
                ? "pregnant_mothers"
                : "mothers"
            )
          : "herd_all";

    rows.push({
      rowId,
      programRowId: rowId,

      programSection:
        programSection.value,

        programSectionLabel:
        programSection.label,

      programType:
        String(
          raw.programType ||
          (
            programSection.value === "mothers"
              ? "mothers"
              : programSection.value === "calves"
                ? (
                    doseSchedule.some(step =>
                      String(step.cycle || "") ===
                        "once_lifetime"
                    )
                      ? "once_lifetime"
                      : "calves_to_herd"
                  )
                : "herd"
          )
        ).trim(),

      programInput:
        raw.programInput &&
        typeof raw.programInput === "object" &&
        !Array.isArray(raw.programInput)
          ? raw.programInput
          : {},

      targetGroup,

      vaccineCode:
        vaccine.value,

      vaccineName:
        vaccine.label,

      vaccine:
        vaccine.label,

      vaccineForm:
        vaccineForm.value,

      vaccineFormLabel:
        vaccineForm.label,

      doseType:
        fixedDoseType,

      doseTypeLabel:
        fixedDoseTypeLabel,

      allowedDoseTypes,
      doseSchedule,

      cycle:
        rowCycle,

      startDate,

      repeatEvery:
        repeatStep?.timingValue || 0,

      repeatUnit:
        repeatStep?.timingUnit || "",

      repeatUnitLabel:
        repeatStep
          ?.timingUnitLabel || "",

      oneTime:
        singleOnceLifetime,

      onceLifetime:
        singleOnceLifetime,

      calfSchedule:
        programSection.value ===
          "calves",

      calfAgeValue:
        calfAgeStep
          ?.timingValue || null,

      calfAgeUnit:
        calfAgeStep
          ?.timingUnit || "",

      calfAgeUnitLabel:
        calfAgeStep
          ?.timingUnitLabel || "",

      ageMinValue:
        calfAgeWindowStep
          ?.ageMinValue || 0,

      ageMinUnit:
        calfAgeWindowStep
          ?.ageMinUnit || "",

      ageMaxValue:
        calfAgeWindowStep
          ?.ageMaxValue || 0,

      ageMaxUnit:
        calfAgeWindowStep
          ?.ageMaxUnit || "",

      advanceNoticeDays,
      notes,

      active:
        raw.active !== false
    });
  });

  return {
    rows,
    errors
  };
}
function vaccinationFarmProgramResponseSrv(
  data = {},
  exists = false
) {
  const rows =
    Array.isArray(data.rows)
      ? data.rows
      : [];

  return {
    exists:
      Boolean(exists),

    version:
      Number(data.version || 0),

    previousVersion:
      Number(
        data.previousVersion || 0
      ),

    programName:
      vaccinationFarmProgramTextSrv(
        data.programName ||
        "برنامج المزرعة"
      ),

    programNotes:
      vaccinationFarmProgramTextSrv(
        data.programNotes
      ),

    rowCount:
      rows.length,

    rows,

    contentHash:
      String(
        data.contentHash || ""
      )
  };
}
function vaccinationProgramExecutionRowsSrv(
  rawRows = []
) {
  const rows =
    Array.isArray(rawRows)
      ? rawRows
      : [];

  return rows
    .filter(row =>
      row &&
      typeof row === "object" &&
      row.active !== false &&
            String(
        row.programRowId ||
        row.rowId ||
        ""
      ).trim() &&
      String(row.vaccineCode || "").trim()
    )
    .map(row => {
      const doseSchedule =
        Array.isArray(row.doseSchedule)
          ? row.doseSchedule
              .filter(step =>
                step &&
                typeof step === "object" &&
                !Array.isArray(step) &&
                String(step.doseType || "").trim() &&
                String(step.timingBasis || "").trim()
              )
                           .map(step => {
                const timingBasis =
                  String(
                    step.timingBasis || ""
                  ).trim();

                const rawDoseType =
                  String(
                    step.doseType || ""
                  ).trim();

                const scheduleLength =
                  Array.isArray(
                    row.doseSchedule
                  )
                    ? row.doseSchedule.length
                    : 0;

                const doseType =
                  timingBasis ===
                    "before_expected_calving" &&
                  scheduleLength === 1 &&
                  rawDoseType === "periodic"
                    ? "prime"
                    : rawDoseType;

                return {
                  ...step,

                  doseType,

                  doseTypeLabel:
                    vaccinationProgramDoseLabelSrv({
                      doseType,
                      timingBasis,
                      scheduleLength,

                      fallbackLabel:
                        step.doseTypeLabel || ""
                    }),

                  timingBasis,

                  timingValue:
                    Number(
                      step.timingValue || 0
                    ),

                  timingUnit:
                    String(
                      step.timingUnit || ""
                    ).trim(),

                  cycle:
                    String(
                      step.cycle || ""
                    ).trim()
                };
              })
          : [];

      const allowedDoseTypes =
        [
          ...new Set(
            doseSchedule.map(step =>
              step.doseType
            )
          )
        ];

      const fixedDoseType =
        allowedDoseTypes.length === 1
          ? allowedDoseTypes[0]
          : "";
            const allowedDoseOptions =
        allowedDoseTypes.map(value => {
          const step =
            doseSchedule.find(item =>
              item.doseType === value
            );

          return {
            value,

            label:
              String(
                step?.doseTypeLabel ||
                value
              ).trim()
          };
        });
      const fixedDoseStep =
        fixedDoseType
          ? doseSchedule.find(step =>
              step.doseType === fixedDoseType
            )
          : null;

      return {
        ...row,

         programRowId:
          String(
            row.programRowId ||
            row.rowId ||
            ""
          ).trim(),

        vaccineCode:
          String(row.vaccineCode || "").trim(),

        vaccine:
          String(
            row.vaccineName ||
            row.vaccine ||
            ""
          ).trim(),

        doseType:
          fixedDoseType,

        doseTypeLabel:
          String(
            fixedDoseStep?.doseTypeLabel || ""
          ).trim(),

        allowedDoseTypes,
        allowedDoseOptions,
        doseSchedule,

        repeatEvery:
          Number(row.repeatEvery || 0),

        repeatUnit:
          String(row.repeatUnit || "").trim(),

        oneTime:
          row.oneTime === true,

        onceLifetime:
          row.onceLifetime === true,

        advanceNoticeDays:
          Math.max(
            0,
            Math.min(
              90,
              Number(
                row.advanceNoticeDays || 0
              ) || 0
            )
          )
      };
    })
    .filter(row =>
      row.doseSchedule.length
    );
}

function vaccinationFarmProgramExecutionRowsSrv(
  data = {}
) {
  return vaccinationProgramExecutionRowsSrv(
    Array.isArray(data.rows)
      ? data.rows
      : []
  );
}
async function vaccinationReadFarmProgramExecutionSrv(
  uid
) {
  if (!db || !uid) {
    return {
      exists: false,
      version: 0,
      rows: []
    };
  }

  const snap = await db
    .collection("vaccination_farm_programs")
    .doc(uid)
    .get();

  const data = snap.exists
    ? (snap.data() || {})
    : {};

  return {
    exists: snap.exists,
    version: Number(data.version || 0),

    rows:
      vaccinationFarmProgramExecutionRowsSrv(
        data
      )
  };
}
