async function updateAnimalByAbortionSrv(
  ev = {},
  resolvedAnimal = null,
  writer = null
) {
  const tenant =
    String(
      ev.userId ||
      ""
    ).trim();

  const animalNumber =
    calvingNormDigitsOnlySrv(
      ev.animalNumber ||
      ev.number ||
      ""
    );

  const eventDate =
    String(
      ev.eventDate ||
      ev.date ||
      ""
    )
      .trim()
      .slice(0, 10);

  if (
    !tenant ||
    !animalNumber ||
    !calvingIsDateSrv(eventDate)
  ) {
    const err =
      new Error(
        "abortion_update_missing_subject"
      );

    err.code =
      "abortion_update_missing_subject";

    if (writer) {
      throw err;
    }

    return null;
  }

  const animal =
    resolvedAnimal?.id
      ? resolvedAnimal
      : await fetchAnimalByNumberForCalvingGateSrv(
          tenant,
          animalNumber
        );

  if (!animal?.id) {
    const err =
      new Error(
        "abortion_update_animal_not_found"
      );

    err.code =
      "abortion_update_animal_not_found";

    if (writer) {
      throw err;
    }

    return null;
  }

  const collectionName =
    animal._collection === "calves"
      ? "calves"
      : "animals";

  const eventId =
    String(
      ev.eventId ||
      ""
    ).trim();

  const ageMonths =
    Number(
      ev.abortionAgeMonths
    );

  const patch = {
    reproductiveStatus:
      "إجهاض",

    lastAbortionDate:
      eventDate,

    ...(eventId
      ? {
          lastAbortionEventId:
            eventId
        }
      : {}),

    abortionAgeMonths:
      Number.isFinite(ageMonths)
        ? ageMonths
        : null,

    lastPregnancyLossClass:
      Number.isFinite(ageMonths)
        ? (
            ageMonths >= 5
              ? "late"
              : "early"
          )
        : null,

    pregnancyDays:
      null,

    updatedAt:
      admin.firestore.FieldValue
        .serverTimestamp()
  };

  // التابع الذي أجهض يظل في حالة «إجهاض» أثناء فترة الاستشفاء.
  // الـ maintenance الحالي يعيده «تحت التلقيح» بعد اكتمال 40 يومًا.
  if (collectionName === "calves") {
    patch.followerStatus =
      "إجهاض";

    patch.status =
      "إجهاض";
  }

  const ref =
    db
      .collection(collectionName)
      .doc(animal.id);

  if (
    writer &&
    typeof writer.set === "function"
  ) {
    writer.set(
      ref,
      patch,
      { merge: true }
    );
  } else {
    await ref.set(
      patch,
      { merge: true }
    );
  }

  return {
    ok: true,
    collection: collectionName,
    animalId: animal.id,
    animalNumber,
    eventDate
  };
}
// ============================================================
//                 API: ABORTION GATE
//                 تحقق الإجهاض من السيرفر فقط — بدون حفظ
// ============================================================

app.post("/api/abortion/gate", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        allowed: false,
        error: "firestore_disabled",
       message: "❌ تعذّر فحص بيانات الإجهاض الآن. حاول مرة أخرى."
      });
    }

    const uid = req.userId;
    const body = req.body || {};

    const animalNumber = calvingNormDigitsOnlySrv(body.animalNumber || body.number || "");
    const eventDate = String(body.eventDate || body.date || "").trim().slice(0, 10);

    if (!animalNumber || !eventDate) {
      return res.json({
        ok: true,
        allowed: false,
        silent: true
      });
    }

    const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, animalNumber);

    if (!animal) {
      return res.status(404).json({
        ok: false,
        allowed: false,
       message: `❌ لم أجد الحيوان رقم ${animalNumber} في حسابك. راجع الرقم وحاول مرة أخرى.`
      });
    }

    const doc = animal.data || {};

    const st = String(doc.status ?? "").trim().toLowerCase();
   if (st === "inactive" || st === "archived") {
      return res.status(400).json({
        ok: false,
        allowed: false,
       message: `❌ الحيوان رقم ${animalNumber} خارج القطيع، لذلك لا يمكن تسجيل إجهاض له.`
      });
    }

    const signals = await fetchCalvingSignalsFromEventsSrv(uid, animalNumber);
     const alreadyAbortionSameDay =
  await existsAbortionSameDaySrv(
    uid,
    animalNumber,
    eventDate
  );

if (alreadyAbortionSameDay) {
  return res.status(409).json({
    ok: false,
    allowed: false,
    message:
      `ℹ️ الإجهاض مسجل بالفعل للحيوان رقم ${animalNumber} في هذا التاريخ.`
  });
}

const todayISO =
  await farmTodayISOSrv(
    req.authSession?.uid ||
    uid
  );

    const docSpecies =
  String(
    doc.species ||
    doc.animalTypeAr ||
    doc.animalType ||
    doc.animaltype ||
    doc.type ||
    ""
  ).trim();

let species = docSpecies;

if (/cow|بقر/i.test(species)) {
  species = "أبقار";
}

if (/buffalo|جاموس/i.test(species)) {
  species = "جاموس";
}

    const reproFromEvents = String(signals.reproStatusFromEvents || "").trim();
   const reproFromDoc = String(
  doc.reproductiveStatus ||
  doc.followerStatus ||
  (
    String(doc.entryType || "").trim() === "followers"
      ? doc.status
      : ""
  ) ||
  ""
).trim();
   const reproStatus =
  reproFromEvents ||
  reproFromDoc ||
  "";

    const lastInseminationDate = String(
      signals.lastInseminationDateFromEvents ||
      doc.lastInseminationDate ||
      ""
    ).trim();

    const gateData = {
      animalNumber,
      eventDate,
      todayISO,
      animalId: animal.id || "",
      species,
      documentData: doc,
      reproductiveStatus: reproStatus,
      reproStatusFromEvents: reproFromEvents,
      lastInseminationDate,
      lastBoundary: String(signals.lastBoundary || "").trim(),
      lastBoundaryType: String(signals.lastBoundaryType || "").trim()
    };

    const errMsg = abortionDecisionSrv(gateData);

    if (errMsg) {
      return res.status(400).json({
        ok: false,
        allowed: false,
        message: String(errMsg)
      });
    }

    const derived = calcAbortionAgeAndCauseSrv(lastInseminationDate, eventDate);

    return res.json({
      ok: true,
      allowed: true,
      message: `✅ راجعت بيانات الحيوان رقم ${animalNumber}، ويمكنك تسجيل الإجهاض الآن. أكمل البيانات ثم احفظ.`,
      animalId: animal.id || "",
      animalNumber,
      species,
      lastInseminationDate,
      abortionAgeMonths: derived.abortionAgeMonths,
probableCause: derived.probableCause,
probableCauses: derived.probableCauses || [],
abortionDiagnosticMatrix: derived.abortionDiagnosticMatrix || [],
abortionDiagnosticNote: derived.abortionDiagnosticNote || "",
gestationDays: derived.gestationDays,
      signals
    });

  } catch (e) {
    console.error("abortion-gate", e);

    return res.status(500).json({
      ok: false,
      allowed: false,
      error: "abortion_gate_failed",
      message: "❌ تعذّر فحص بيانات الإجهاض الآن. حاول مرة أخرى."
    });
  }
});
// ============================================================
//                 API: ABORTION SAVE
//                 حفظ الإجهاض وتحديث الحيوان من السيرفر فقط
// ============================================================

app.post("/api/abortion/save", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        error: "firestore_disabled",
      message: "❌ تعذّر حفظ الإجهاض الآن. حاول مرة أخرى."
      });
    }

    const uid = req.userId;
    const formData = req.body || {};

    const animalNumber = calvingNormDigitsOnlySrv(
      formData.animalNumber ||
      formData.number ||
      ""
    );

    const eventDate = String(
      formData.eventDate ||
      formData.date ||
      ""
    ).trim().slice(0, 10);

    if (!animalNumber || !eventDate) {
      return res.status(400).json({
        ok: false,
       message: "❌ أدخل رقم الحيوان وتاريخ الإجهاض."
      });
    }

    const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, animalNumber);

    if (!animal) {
      return res.status(404).json({
        ok: false,
        message: `❌ لم أجد الحيوان رقم ${animalNumber} في حسابك. راجع الرقم وحاول مرة أخرى.`
      });
    }

    const doc = animal.data || {};

    const st = String(doc.status ?? "").trim().toLowerCase();
   if (st === "inactive" || st === "archived") {
      return res.status(400).json({
        ok: false,
        message: `❌ الحيوان رقم ${animalNumber} خارج القطيع، لذلك لا يمكن تسجيل إجهاض له.`
      });
    }

    const signals = await fetchCalvingSignalsFromEventsSrv(uid, animalNumber);
     const alreadyAbortionSameDay =
  await existsAbortionSameDaySrv(
    uid,
    animalNumber,
    eventDate
  );

if (alreadyAbortionSameDay) {
  return res.status(409).json({
    ok: false,
    allowed: false,
    message:
      `ℹ️ الإجهاض مسجل بالفعل للحيوان رقم ${animalNumber} في هذا التاريخ.`
  });
}

const todayISO =
  await farmTodayISOSrv(
    req.authSession?.uid ||
    uid
  );

    const docSpecies =
  String(
    doc.species ||
    doc.animalTypeAr ||
    doc.animalType ||
    doc.animaltype ||
    doc.type ||
    ""
  ).trim();

let species = docSpecies;

if (/cow|بقر/i.test(species)) {
  species = "أبقار";
}

if (/buffalo|جاموس/i.test(species)) {
  species = "جاموس";
}

    const reproFromEvents = String(signals.reproStatusFromEvents || "").trim();
   const reproFromDoc = String(
  doc.reproductiveStatus ||
  doc.followerStatus ||
  (
    String(doc.entryType || "").trim() === "followers"
      ? doc.status
      : ""
  ) ||
  ""
).trim();
    const reproStatus = reproFromEvents || reproFromDoc || "";

   const lastInseminationDate =
  String(
    signals.lastInseminationDateFromEvents ||
    doc.lastInseminationDate ||
    doc.lastAI ||
    doc.lastInsemination ||
    doc.lastServiceDate ||
    ""
  ).trim();

    const gateData = {
      animalNumber,
      eventDate,
       todayISO,
      animalId: animal.id || "",
      species,
      documentData: doc,
      reproductiveStatus: reproStatus,
      reproStatusFromEvents: reproFromEvents,
      lastInseminationDate,
      lastBoundary: String(signals.lastBoundary || "").trim(),
      lastBoundaryType: String(signals.lastBoundaryType || "").trim()
    };

    const errMsg = abortionDecisionSrv(gateData);

    if (errMsg) {
      return res.status(400).json({
        ok: false,
        allowed: false,
        message: String(errMsg)
      });
    }

    const derived = calcAbortionAgeAndCauseSrv(lastInseminationDate, eventDate);

    const payload = {
      userId: uid,

      type: "إجهاض",
      eventType: "إجهاض",
      eventTypeNorm: "abortion",

      eventDate,
      animalNumber,
      animalId: String(animal.id || "").trim(),

      species: species || "",
      reproductiveStatusBefore: reproStatus || "",

      lastInseminationDate,
      lastFertileInseminationDate: lastInseminationDate,

      gestationDays: derived.gestationDays,
      abortionAgeMonths: derived.abortionAgeMonths,
      probableCause: derived.probableCause,
probableCauses: derived.probableCauses || [],
abortionDiagnosticMatrix: derived.abortionDiagnosticMatrix || [],
abortionDiagnosticNote: derived.abortionDiagnosticNote || "",

      notes: String(formData.notes || "").trim(),

      idempotencyKey: `${uid}|${animalNumber}|abortion|${eventDate}`,

      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      source: "server-abortion-save"
    };

const eventDocId =
  eventsPageStableDocIdSrv(
    uid,
    "abortion",
    animalNumber,
    eventDate
  );

const evRef =
  db.collection("events").doc(eventDocId);

const txResult =
  await db.runTransaction(async (tx) => {
    const existing = await tx.get(evRef);

    if (existing.exists) {
      return { created: false };
    }

    tx.set(evRef, payload);

    await updateAnimalByAbortionSrv(
  {
    ...payload,
    eventId: evRef.id
  },
  animal,
  tx
);

    return { created: true };
  });

if (!txResult?.created) {
  return res.status(409).json({
    ok: false,
    allowed: false,
    message:
      `ℹ️ الإجهاض مسجل بالفعل للحيوان رقم ${animalNumber} في هذا التاريخ.`
  });
}

if (typeof scheduleGroupsRebuildSrv === "function") {
  scheduleGroupsRebuildSrv(uid, "abortion_save");
}

return res.json({
  ok: true,
  message: `✅ سجلت الإجهاض للحيوان رقم ${animalNumber} بنجاح، وأصبحت حالته التناسلية الآن «إجهاض».`,
  redirectUrl: `/event-list.html?number=${encodeURIComponent(animalNumber)}`,
  eventId: evRef.id,

  animalNumber,
  animalId: payload.animalId,
  eventDate,

  lastInseminationDate,
  gestationDays: derived.gestationDays,
  abortionAgeMonths: derived.abortionAgeMonths,
  probableCause: derived.probableCause,
  probableCauses: derived.probableCauses || [],
  abortionDiagnosticMatrix: derived.abortionDiagnosticMatrix || [],
  abortionDiagnosticNote: derived.abortionDiagnosticNote || ""
});
  } catch (e) {
    console.error("abortion-save", e);

    return res.status(500).json({
      ok: false,
      error: "abortion_save_failed",
      message: "❌ تعذّر حفظ الإجهاض الآن. حاول مرة أخرى."
    });
  }
});
// ============================================================
//                 CALVING ANIMAL UPDATE — moved from animal-update.js
//                 نقل جزء type === "calving" كما هو
// ============================================================

function calvingPreviousAnimalNumbersSrv(cur = {}, previousNumber = "") {
  const out = [];

  const push = (v) => {
    const n = calvingNormDigitsOnlySrv(v || "");

    if (n && !out.includes(n)) {
      out.push(n);
    }
  };

  if (Array.isArray(cur.previousAnimalNumbers)) {
    cur.previousAnimalNumbers.forEach(push);
  }

  push(cur.previousFollowerNumber);
  push(cur.followerNumberBeforeFirstCalving);
  push(previousNumber);

  return out;
}

async function calvingResolvedSireLineageSrv({
  userId,
  animal,
  animalNumber,
  lastInseminationDate
} = {}) {
  const found =
    await calvingFindSireLineageForCalvesSrv({
      userId,
      animalNumber,
      lastInseminationDate
    });

  if (found) {
    return found;
  }

  const doc =
    animal?.data ||
    {};

  const fallback =
    String(
      animal?._collection === "calves"
        ? doc.inseminationSireNumber || ""
        : doc.sireNumber || ""
    ).trim();

  if (
    !fallback ||
    !calvingIsDateSrv(lastInseminationDate)
  ) {
    return {};
  }

  return {
    sireNumber: fallback,
    fatherNumber: fallback,
    bullNumber: fallback,
    semenCode: fallback,

    sireSource:
      "last_insemination_snapshot",

    sireInseminationDate:
      lastInseminationDate
  };
}

async function calvingNumbersAvailableSrv(
  uid,
  numbers = []
) {
  const cleaned =
    [
      ...new Set(
        numbers
          .map(calvingNormDigitsOnlySrv)
          .filter(Boolean)
      )
    ];

  for (const n of cleaned) {
    const check =
      await addAnimalDuplicateCheckSrv(
        uid,
        n
      );

    if (!check?.ok) {
      return {
        ok: false,
        number: n,

        duplicate:
          !!check?.duplicate,

        message:
          check?.duplicate
            ? `❌ الرقم ${n} مسجل بالفعل لحيوان في حسابك. اختر رقمًا آخر.`
            : (
                check?.message ||
                "❌ تعذّر فحص رقم الحيوان الآن. حاول مرة أخرى."
              )
      };
    }
  }

  return {
    ok: true
  };
}

async function updateAnimalByCalvingSrv(
  ev,
  resolvedAnimal = null,
  writer = null
) {
  const tenant =
    String(
      ev.userId ||
      ""
    ).trim();

  const sourceNumber =
    calvingNormDigitsOnlySrv(
      ev.sourceAnimalNumber ||
      ev.previousFollowerNumber ||
      ev.animalNumber ||
      ev.number ||
      ""
    );

  if (
    !tenant ||
    !sourceNumber
  ) {
    const err =
      new Error(
        "calving_update_missing_subject"
      );

    err.code =
      "calving_update_missing_subject";

    if (writer) {
      throw err;
    }

    return null;
  }

  const date =
    String(
      ev.eventDate ||
      ""
    )
      .trim()
      .slice(0, 10);

  const animal =
    resolvedAnimal?.id
      ? resolvedAnimal
      : await fetchAnimalByNumberForCalvingGateSrv(
          tenant,
          sourceNumber
        );

  if (!animal?.id) {
    const err =
      new Error(
        "calving_update_animal_not_found"
      );

    err.code =
      "calving_update_animal_not_found";

    if (writer) {
      throw err;
    }

    return null;
  }

  const cur =
    animal.data ||
    {};

  const currentLactation =
    Number(
      cur.lactationNumber ||
      0
    );

  const nextLactation =
    ev.lactationNumber != null
      ? (
          Number(
            ev.lactationNumber
          ) ||
          1
        )
      : (
          (
            Number.isFinite(
              currentLactation
            )
              ? currentLactation
              : 0
          ) + 1
        );

 const baseUpdate = {
  lastCalvingDate:
    date,

  reproductiveStatus:
    "حديث الولادة",

  productionStatus:
    "حلاب",

  inMilk:
    true,

  daysInMilk:
    0,

  pregnancyDays:
  null,

lastInseminationDate:
  null,

lastAI:
  null,

lastInsemination:
  null,

lastServiceDate:
  null,

servicesCount:
  0,

  lactationNumber:
    nextLactation,

  status:
    "active",

  updatedAt:
    admin.firestore.FieldValue
      .serverTimestamp()
};

  // ======================================================
  // الحيوان أم موجودة أصلًا داخل animals
  // ======================================================
  if (
    animal._collection !==
    "calves"
  ) {
    const ref =
      db
        .collection("animals")
        .doc(animal.id);

    if (
      writer &&
      typeof writer.set === "function"
    ) {
      writer.set(
        ref,
        baseUpdate,
        { merge: true }
      );
    } else {
      await ref.set(
        baseUpdate,
        { merge: true }
      );
    }

    return {
      convertedFromFollower:
        false,

      animalId:
        animal.id,

      animalNumber:
        sourceNumber,

      previousFollowerNumber:
        null
    };
  }

  // ======================================================
  // أول ولادة للعجلة:
  // calves -> animals
  // ======================================================
  const newMotherNumber =
    calvingNormDigitsOnlySrv(
      ev.newMotherNumber ||
      ev.newAnimalNumber ||
      ""
    );

  if (!newMotherNumber) {
    const err =
      new Error(
        "calving_new_mother_number_required"
      );

    err.code =
      "calving_new_mother_number_required";

    throw err;
  }

  if (
    newMotherNumber ===
    sourceNumber
  ) {
    const err =
      new Error(
        "calving_new_mother_number_same_as_follower"
      );

    err.code =
      "calving_new_mother_number_same_as_follower";

    throw err;
  }

  // أبو العجلة نفسها.
  const pedigreeFatherNumber =
    String(
      cur.fatherNumber ||
      cur.birthSireNumber ||
      cur.sireNumber ||
      ""
    ).trim() ||
    null;

  // مصدر أبو العجلة الوراثي قبل التحويل.
  const pedigreeFatherSource =
    String(
      cur.birthSireSource ||
      cur.sireSource ||
      ""
    ).trim() ||
    null;

  // طلوقة الحمل الذي انتهى بهذه الولادة.
  const lastFertileSireNumber =
    String(
      ev.lastFertileSireNumber ||
      ev.lastFertileSemenCode ||
      cur.inseminationSireNumber ||
      ""
    ).trim() ||
    null;

  // مصدر طلوقة الحمل الحالية.
  const lastFertileSireSource =
    String(
      ev.lastFertileSireSource ||
      ""
    ).trim() ||
    null;

  const motherData = {
    // نحمل تاريخ العجلة وبياناتها بالكامل.
    ...cur,

    // الحالة الحالية بعد الولادة.
    ...baseUpdate,

    ownerUid:
      tenant,

    userId:
      tenant,

    userId_number:
      `${tenant}#${newMotherNumber}`,

    entryType:
      "mothers",

    number:
      newMotherNumber,

    animalNumber:
      Number(
        newMotherNumber
      ),

    // ==========================
    // تاريخ الهوية
    // ==========================
    previousFollowerNumber:
      sourceNumber,

    followerNumberBeforeFirstCalving:
      cur.followerNumberBeforeFirstCalving ||
      sourceNumber,

    previousAnimalNumbers:
      calvingPreviousAnimalNumbersSrv(
        cur,
        sourceNumber
      ),

    followerStatusBeforeFirstCalving:
      String(
        cur.followerStatus ||
        cur.status ||
        ""
      ).trim() ||
      null,

    convertedFromFollower:
      true,

    convertedFromCollection:
      "calves",

    convertedAt:
      admin.firestore.FieldValue
        .serverTimestamp(),

    originalFollowerSource:
      cur.originalFollowerSource ||
      cur.source ||
      null,

    firstCalvingDate:
      cur.firstCalvingDate ||
      date,

    // ==========================
    // النسب والتلقيح
    // ==========================
       fatherNumber:
      pedigreeFatherNumber,

    birthSireNumber:
      pedigreeFatherNumber,

    birthSireSource:
      pedigreeFatherSource,

    sireNumber:
      lastFertileSireNumber,

    sireSource:
      lastFertileSireSource,

    lastFertileSireNumber:
      lastFertileSireNumber,

    lastFertileSireSource:
      lastFertileSireSource,

    source:
      "server:/api/calving/save:follower-to-mother"
  };

  // لم تعد الهوية الحالية «تابع».
  delete motherData.calfNumber;
  delete motherData.followerStatus;

  const followerRef =
    db
      .collection("calves")
      .doc(animal.id);

  const motherRef =
    db
      .collection("animals")
      .doc(animal.id);

  if (
    writer &&
    typeof writer.set === "function" &&
    typeof writer.delete === "function"
  ) {
    writer.set(
      motherRef,
      motherData
    );

    writer.delete(
      followerRef
    );
  } else {
    const batch =
      db.batch();

    batch.set(
      motherRef,
      motherData
    );

    batch.delete(
      followerRef
    );

    await batch.commit();
  }

  return {
    convertedFromFollower:
      true,

    animalId:
      animal.id,

    animalNumber:
      newMotherNumber,

    previousFollowerNumber:
      sourceNumber
  };
}

// ============================================================
//                 API: CALVING SAVE
// ============================================================
app.post(
  "/api/calving/save",
  requireUserId,
  async (req, res) => {
    try {
      if (!db) {
        return res.status(503).json({
          ok: false,
          error: "firestore_disabled",
          message:
            "❌ تعذّر حفظ الولادة الآن. حاول مرة أخرى."
        });
      }

      const uid =
        req.userId;

      const formData =
        req.body ||
        {};

      const sourceAnimalNumber =
        calvingNormDigitsOnlySrv(
          formData.animalNumber ||
          formData.number ||
          ""
        );

      const eventDate =
        String(
          formData.eventDate ||
          formData.date ||
          ""
        )
          .trim()
          .slice(0, 10);

      const animal =
        await fetchAnimalByNumberForCalvingGateSrv(
          uid,
          sourceAnimalNumber
        );

      const doc =
        animal?.data ||
        null;

      const signals =
        animal
          ? await fetchCalvingSignalsFromEventsSrv(
              uid,
              sourceAnimalNumber
            )
          : {
              reproStatusFromEvents: "",
              lastBoundary: "",
              lastBoundaryType: "",
              lastInseminationDateFromEvents: ""
            };

      const docSpecies =
        String(
          doc?.species ||
          doc?.animalTypeAr ||
          doc?.animalType ||
          doc?.animaltype ||
          doc?.type ||
          ""
        ).trim();

      let species =
        String(
          formData.species ||
          ""
        ).trim() ||
        docSpecies;

      if (/cow|بقر/i.test(species)) {
        species =
          "أبقار";
      }

      if (/buffalo|جاموس/i.test(species)) {
        species =
          "جاموس";
      }

      const reproFromEvents =
        String(
          signals.reproStatusFromEvents ||
          ""
        ).trim();

      const reproductiveStatus =
        reproFromEvents ||
        String(
          doc?.reproductiveStatus ||
          doc?.followerStatus ||
          ""
        ).trim();

      const lastInseminationDate =
        String(
          signals.lastInseminationDateFromEvents ||
          doc?.lastInseminationDate ||
          ""
        )
          .trim()
          .slice(0, 10);

      const animalCollection =
        animal?._collection ||
        "animals";

      const isFollower =
        animalCollection ===
        "calves";

      const newMotherNumber =
        isFollower
          ? calvingNormDigitsOnlySrv(
              formData.newMotherNumber ||
              formData.newAnimalNumber ||
              ""
            )
          : "";

      const finalAnimalNumber =
        isFollower &&
        newMotherNumber
          ? newMotherNumber
          : sourceAnimalNumber;

      // ============================
      // SAVE يعيد Gate كاملًا
      // ============================
      const gateErr =
        calvingDecisionSrv({
          animalNumber:
            sourceAnimalNumber,

          eventDate,

          animalId:
            animal?.id ||
            "",

          animalCollection,

          species,

          documentData:
            doc,

          reproductiveStatus,

          reproStatusFromEvents:
            reproFromEvents,

          lastInseminationDate,

          lastBoundary:
            String(
              signals.lastBoundary ||
              ""
            ).trim(),

          lastBoundaryType:
            String(
              signals.lastBoundaryType ||
              ""
            ).trim()
        });

      if (gateErr) {
        const raw =
          String(
            gateErr ||
            ""
          );

        const offerAbort =
          raw.startsWith(
            "OFFER_ABORT|"
          );

        let message =
          raw.replace(
            /^OFFER_ABORT\|/,
            ""
          );

        if (offerAbort) {
          const ageMatch =
            message.match(
              /عمر الحمل\s+(\d+)\s+يوم/
            );

          const ageText =
            ageMatch
              ? ` — عمر الحمل ${ageMatch[1]} يوم فقط`
              : "";

          message =
            `❌ التاريخ مبكر للولادة${ageText}.\nعدّل التاريخ أو سجّل الحالة كإجهاض.`;
        }

        return res
          .status(400)
          .json({
            ok: false,
            allowed: false,
            message,
            guardError: raw,
            offerAbort,

            actions:
              offerAbort
                ? [
                    {
                      key:
                        "focus_date",

                      label:
                        "تعديل التاريخ",

                      focus:
                        "eventDate"
                    },
                    {
                      key:
                        "open_abortion",

                      label:
                        "تسجيل إجهاض",

                      primary:
                        true,

                      url:
                        `/abortion.html?number=${encodeURIComponent(
                          sourceAnimalNumber
                        )}&date=${encodeURIComponent(
                          eventDate
                        )}`
                    }
                  ]
                : []
          });
      }

      // ============================
      // رقم الأم الجديد للعجلة
      // ============================
      if (isFollower) {
        if (!newMotherNumber) {
          return res
            .status(400)
            .json({
              ok: false,

              error:
                "calving_new_mother_number_required",

              message:
                "❌ أدخل رقم الأم الجديد حسب سيريال المزرعة.",

              fieldErrors: {
                newMotherNumber:
                  "❌ أدخل رقم الأم الجديد."
              }
            });
        }

        if (
          newMotherNumber ===
          sourceAnimalNumber
        ) {
          return res
            .status(400)
            .json({
              ok: false,

              error:
                "calving_new_mother_number_same_as_follower",

              message:
                `❌ رقم الأم الجديد يجب أن يختلف عن رقم العجلة الحالي ${sourceAnimalNumber}.`,

              fieldErrors: {
                newMotherNumber:
                  "❌ اختر رقمًا جديدًا مختلفًا."
              }
            });
        }
      }

      // ============================
      // الحقول الأساسية
      // ============================
      const requiredErr =
        calvingRequiredFieldsSrv({
          ...formData,

          animalNumber:
            sourceAnimalNumber,

          eventDate,

          species,

          documentData:
            doc,

          lastInseminationDate
        });

      if (requiredErr) {
        const msg =
          typeof requiredErr ===
          "string"
            ? requiredErr
            : (
                requiredErr.msg ||
                "بيانات الولادة غير مكتملة."
              );

        return res
          .status(400)
          .json({
            ok: false,

            message:
              msg,

            errors: [
              msg
            ],

            fieldErrors:
              typeof requiredErr === "object" &&
              requiredErr.field
                ? {
                    [requiredErr.field]:
                      msg
                  }
                : {}
          });
      }

      const isDead =
        String(
          formData.calvingKind ||
          ""
        ).trim() ===
        "نافقة";

      const calfCount =
        isDead
          ? 0
          : (
              parseInt(
                formData.calfCount ||
                "1",
                10
              ) ||
              1
            );

      const calfNumbers =
        isDead
          ? []
          : [
              formData.calfId ||
                "",

              calfCount >= 2
                ? formData.calf2Id ||
                  ""
                : "",

              calfCount >= 3
                ? formData.calf3Id ||
                  ""
                : ""
            ]
              .map(
                calvingNormDigitsOnlySrv
              )
              .filter(
                Boolean
              );

      if (
        new Set(
          calfNumbers
        ).size !==
        calfNumbers.length
      ) {
        return res
          .status(400)
          .json({
            ok: false,

            error:
              "duplicate_calf_number_in_request",

            message:
              "❌ لا يمكن استخدام نفس الرقم لأكثر من مولود."
          });
      }

      if (
        isFollower &&
        calfNumbers.includes(
          newMotherNumber
        )
      ) {
        return res
          .status(400)
          .json({
            ok: false,

            error:
              "new_mother_number_conflicts_with_calf",

            message:
              `❌ رقم الأم الجديد ${newMotherNumber} لا يمكن استخدامه أيضًا كرقم لأحد المواليد.`,

            fieldErrors: {
              newMotherNumber:
                "❌ اختر رقم أم مختلفًا عن أرقام المواليد."
            }
          });
      }

      // الأم الجديدة + المواليد:
      // جميع الأرقام يجب أن تكون متاحة
      // في animals و calves.
      const availability =
        await calvingNumbersAvailableSrv(
          uid,
          [
            ...(
              isFollower
                ? [
                    newMotherNumber
                  ]
                : []
            ),

            ...calfNumbers
          ]
        );

      if (!availability.ok) {
        return res
          .status(
            availability.duplicate
              ? 409
              : 503
          )
          .json({
            ok: false,

            error:
              availability.duplicate
                ? "duplicate_animal_number"
                : "animal_number_check_failed",

            message:
              availability.message
          });
      }

      // دعم الأحداث القديمة التي كانت تحفظ ID عشوائي.
      const oldSameDay =
        await existsCalvingSameDaySrv(
          uid,
          sourceAnimalNumber,
          eventDate
        );

      const newSameDay =
        isFollower
          ? await existsCalvingSameDaySrv(
              uid,
              finalAnimalNumber,
              eventDate
            )
          : false;

      if (
        oldSameDay ||
        newSameDay
      ) {
        return res
          .status(409)
          .json({
            ok: false,

            error:
              "calving_already_saved",

            message:
              `❌ الولادة مسجلة بالفعل لهذا الحيوان في تاريخ ${eventDate}.`
          });
      }

      // ============================
      // أب المولود
      // ============================
      const sireLineage =
        await calvingResolvedSireLineageSrv({
          userId:
            uid,

          animal,

          animalNumber:
            sourceAnimalNumber,

          lastInseminationDate
        });

      // ID ثابت للولادة.
      const eventRef =
        db
          .collection("events")
          .doc(
            eventsPageStableDocIdSrv(
              uid,
              "calving",
              animal?.id ||
              sourceAnimalNumber,
              eventDate
            )
          );

      const payload = {
        userId:
          uid,

        type:
          "ولادة",

        eventType:
          "ولادة",

        eventTypeNorm:
          "calving",

        eventDate,

        // بعد أول ولادة الرقم الحالي هو رقم الأم الجديد.
        animalNumber:
          finalAnimalNumber,

        animalId:
          String(
            animal?.id ||
            ""
          ).trim(),

        sourceAnimalNumber,

        previousFollowerNumber:
          isFollower
            ? sourceAnimalNumber
            : null,

        convertedFromFollower:
          isFollower,

        newMotherNumber:
          isFollower
            ? finalAnimalNumber
            : null,

        species:
          species ||
          "",

        reproStatus:
          "عشار",

        lastInseminationDate,

        lastFertileInseminationDate:
          lastInseminationDate,

        calvingKind:
          formData.calvingKind ||
          "",

        calfCount:
          isDead
            ? ""
            : String(
                calfCount
              ),

        calf1Sex:
          formData.calf1Sex ||
          "",

        calfId:
          formData.calfId ||
          "",

        calf1Fate:
          formData.calf1Fate ||
          "",

        calf2Sex:
          formData.calf2Sex ||
          "",

        calf2Id:
          formData.calf2Id ||
          "",

        calf2Fate:
          formData.calf2Fate ||
          "",

        calf3Sex:
          formData.calf3Sex ||
          "",

        calf3Id:
          formData.calf3Id ||
          "",

        calf3Fate:
          formData.calf3Fate ||
          "",

        notes:
          formData.notes ||
          "",

        idempotencyKey:
          `${uid}|calving|${animal?.id || sourceAnimalNumber}|${eventDate}`,

        createdAt:
          admin.firestore.FieldValue
            .serverTimestamp()
      };

      // ============================
      // تجهيز المواليد قبل Transaction
      // ============================
      const calvesToSave =
        [];

      const addCalf = (
        numberField,
        sexField,
        fateField
      ) => {
        const calfNumber =
          calvingNormDigitsOnlySrv(
            formData[numberField] ||
            ""
          );

        const sex =
          String(
            formData[sexField] ||
            ""
          ).trim();

        const fate =
          String(
            formData[fateField] ||
            ""
          ).trim();

        if (
          !calfNumber ||
          !sex
        ) {
          return;
        }

        calvesToSave.push({
          ref:
            db
              .collection("calves")
              .doc(),

          data: {
            userId:
              uid,

            ownerUid:
              uid,

            userId_number:
              `${uid}#${calfNumber}`,

            entryType:
              "followers",

            calfNumber,

            number:
              calfNumber,

            animalNumber:
              Number(
                calfNumber
              ),

            damId:
              payload.animalId,

            damNumber:
              finalAnimalNumber,

            damPreviousFollowerNumber:
              isFollower
                ? sourceAnimalNumber
                : null,

            damReferenceStatus:
              "known",

            birthDate:
              eventDate,

            species,
            sex,
            fate,

            status:
              "رضيع",

            followerStatus:
              "رضيع",

            reproductiveStatus:
              null,

            ...sireLineage,

            createdAt:
              admin.firestore.FieldValue
                .serverTimestamp(),

            updatedAt:
              admin.firestore.FieldValue
                .serverTimestamp(),

            source:
              "server:/api/calving/save"
          }
        });
      };

      if (!isDead) {
        addCalf(
          "calfId",
          "calf1Sex",
          "calf1Fate"
        );

        if (
          calfCount >=
          2
        ) {
          addCalf(
            "calf2Id",
            "calf2Sex",
            "calf2Fate"
          );
        }

        if (
          calfCount >=
          3
        ) {
          addCalf(
            "calf3Id",
            "calf3Sex",
            "calf3Fate"
          );
        }
      }

      const sourceRef =
        db
          .collection(
            isFollower
              ? "calves"
              : "animals"
          )
          .doc(
            animal.id
          );

      const motherRef =
        isFollower
          ? db
              .collection(
                "animals"
              )
              .doc(
                animal.id
              )
          : sourceRef;

      // ======================================================
      // Transaction واحدة:
      // event + نقل/تحديث الأم + المواليد
      // ======================================================
      const txResult =
        await db.runTransaction(
          async (
            tx
          ) => {
            // كل القراءات قبل الكتابة.
            const existingEvent =
              await tx.get(
                eventRef
              );

            if (
              existingEvent.exists
            ) {
              return {
                created:
                  false
              };
            }

            const sourceSnap =
              await tx.get(
                sourceRef
              );

            if (
              !sourceSnap.exists
            ) {
              const err =
                new Error(
                  "calving_source_animal_missing"
                );

              err.code =
                "calving_source_animal_missing";

              throw err;
            }

            if (isFollower) {
              const motherSnap =
                await tx.get(
                  motherRef
                );

              if (
                motherSnap.exists
              ) {
                const err =
                  new Error(
                    "calving_mother_target_exists"
                  );

                err.code =
                  "calving_mother_target_exists";

                throw err;
              }
            }

            const sourceData =
              sourceSnap.data() ||
              {};

            const owner =
              String(
                sourceData.userId ||
                sourceData.ownerUid ||
                ""
              ).trim();

            if (
              owner &&
              owner !==
                uid
            ) {
              const err =
                new Error(
                  "calving_source_owner_mismatch"
                );

              err.code =
                "calving_source_owner_mismatch";

              throw err;
            }

            // انتهت القراءات.
            tx.set(
              eventRef,
              payload
            );

            const transition =
              await updateAnimalByCalvingSrv(
                {
                  ...payload,

                  sourceAnimalNumber,

                  newMotherNumber:
                    isFollower
                      ? finalAnimalNumber
                      : "",

                                    lastFertileSireNumber:
                    String(
                      sireLineage.sireNumber ||
                      sireLineage.semenCode ||
                      ""
                    ).trim(),

                  lastFertileSireSource:
                    String(
                      sireLineage.sireSource ||
                      ""
                    ).trim()
                },

                {
                  id:
                    sourceSnap.id,

                  data:
                    sourceData,

                  _collection:
                    isFollower
                      ? "calves"
                      : "animals"
                },

                tx
              );

            for (
              const calf
              of calvesToSave
            ) {
              tx.set(
                calf.ref,
                calf.data
              );
            }

            return {
              created:
                true,

              transition
            };
          }
        );

      if (
        !txResult?.created
      ) {
        return res
          .status(409)
          .json({
            ok: false,

            error:
              "calving_already_saved",

            message:
              `❌ الولادة مسجلة بالفعل لهذا الحيوان في تاريخ ${eventDate}.`
          });
      }

      if (
        typeof scheduleGroupsRebuildSrv ===
        "function"
      ) {
        scheduleGroupsRebuildSrv(
          uid,
          "calving_save"
        );
      }

      const converted =
        txResult
          .transition
          ?.convertedFromFollower ===
        true;

      const savedAnimalNumber =
        txResult
          .transition
          ?.animalNumber ||
        finalAnimalNumber;

      return res.json({
        ok:
          true,

        message:
          converted
            ? (
                isDead
                  ? `✅ سجلت ولادة العجلة رقم ${sourceAnimalNumber} بنجاح، وتم نقلها إلى الأمهات برقم ${savedAnimalNumber}.`
                  : `✅ سجلت ولادة العجلة رقم ${sourceAnimalNumber} بنجاح، وتم نقلها إلى الأمهات برقم ${savedAnimalNumber}، وحفظت بيانات المواليد.`
              )
            : (
                isDead
                  ? `✅ سجلت ولادة الحيوان رقم ${savedAnimalNumber} بنجاح.`
                  : `✅ سجلت ولادة الحيوان رقم ${savedAnimalNumber} بنجاح، وحفظت بيانات المواليد.`
              ),

        redirectUrl:
          `/event-list.html?number=${encodeURIComponent(
            savedAnimalNumber
          )}`,

        id:
          eventRef.id,

        eventId:
          eventRef.id,

        animalNumber:
          savedAnimalNumber,

        previousFollowerNumber:
          converted
            ? sourceAnimalNumber
            : null,

        convertedFromFollower:
          converted,

        animalId:
          payload.animalId,

        eventDate,

        saved: {
          ...payload,

          animalNumber:
            savedAnimalNumber,

          createdAt:
            undefined
        }
      });

    } catch (err) {
      console.error(
        "calving-save",
        err
      );

      const code =
        String(
          err?.code ||
          err?.message ||
          ""
        );

      if (
        code ===
        "calving_source_animal_missing"
      ) {
        return res
          .status(409)
          .json({
            ok: false,
            error: code,

            message:
              "❌ تغيرت بيانات الحيوان أثناء الحفظ. أعد فتح صفحة الولادة وحاول مرة أخرى."
          });
      }

      if (
        code ===
        "calving_mother_target_exists"
      ) {
        return res
          .status(409)
          .json({
            ok: false,
            error: code,

            message:
              "❌ تعذّر نقل العجلة إلى الأمهات لأن هوية الأم المستهدفة موجودة بالفعل."
          });
      }

      if (
        code ===
        "calving_source_owner_mismatch"
      ) {
        return res
          .status(403)
          .json({
            ok: false,
            error: code,

            message:
              "❌ لا يمكنك تسجيل الولادة لهذا الحيوان."
          });
      }

      return res
        .status(500)
        .json({
          ok: false,

          error:
            "calving_save_failed",

          message:
            "❌ تعذّر حفظ الولادة الآن. حاول مرة أخرى."
        });
    }
  }
);
app.post('/api/events', requireUserId, async (req, res) => {
  try {
    const event = req.body || {};
    const tenant = req.userId;
    event.userId = tenant;
   

    if (!event.type || !event.animalId) {
      return res.status(400).json({ ok:false, error:'missing_fields' });
    }

    const events = readJson(eventsPath, []);
    event.id = events.length + 1;
    if (!event.ts) event.ts = Date.now();
    events.push(event);
    fs.writeFileSync(eventsPath, JSON.stringify(events, null, 2));

      if (db) {
      const t = String(event.type || "").toLowerCase();
      const typeNorm =
        t.includes("insemin") || t.includes("تلقيح")
          ? "insemination"
          : t.includes("preg") || t.includes("حمل")
          ? "pregnancy"
          : t.includes("calv") || t.includes("ولادة")
          ? "birth"
          : t.includes("heat") || t.includes("شياع")
          ? "heat"
          : "event";

      const whenMs = Number(event.ts || Date.now());

      // -------- 1) حفظ الحدث في events --------
     const doc = {
  ...event,   // ← يحفظ كل البيانات القادمة من الصفحة

  userId: tenant,
  animalId: String(event.animalId || ""),
  type: typeNorm,
  date: toYYYYMMDD(whenMs),
  createdAt: admin.firestore.Timestamp.fromMillis(whenMs)
};

      doc.eventTypeNorm = normalizeEventType(event.type);

      try {
        await db.collection("events").add(doc);
      } catch (e) {
        console.error("events.save error:", e.message || e);
      }

      // -------- 2) تجهيز تحديث وثيقة الحيوان --------
      const update = {};
      const evDate = toYYYYMMDD(whenMs);
      const raw    = t;
      const result = String(event.result || event.status || "").toLowerCase();

      // ===== الحالة التناسلية =====
      if (/preg|حمل/.test(raw) && /(positive|ايجاب|عشار|حامل)/.test(result)) {
        update.reproductiveStatus = "pregnant";
        update.lastDiagnosisDate  = evDate;
      }
      else if (/preg|حمل/.test(raw) && /(neg|سلب|فارغ)/.test(result)) {
        update.reproductiveStatus = "open";
        update.lastDiagnosisDate  = evDate;
      }
      else if (/insemin|تلقيح/.test(raw)) {
        update.reproductiveStatus   = "inseminated";
        update.lastInseminationDate = evDate;
      }
      else if (/calv|birth|ولادة/.test(raw)) {
        update.reproductiveStatus = "fresh";
        update.lastCalvingDate    = evDate;
      }
      else if (/abortion|اجهاض/.test(raw)) {
        update.reproductiveStatus = "aborted";
        update.lastAbortionDate   = evDate;
      }

      // ===== الحالة الإنتاجية =====
      if (/milk|لبن/.test(raw)) {
        update.productionStatus = "milking";
      }

      if (/dry|تجفيف|جاف/.test(raw)) {
        update.productionStatus = "dry";
        update.lastDryOffDate   = evDate;
      }

      if (/calv|birth|ولادة/.test(raw)) {
        update.productionStatus = "milking";
      }

      if (/close|تحضير/.test(raw)) {
        update.productionStatus = "close_up";
        update.lastCloseUpDate  = evDate;
      }

      // -------- 3) تطبيق التحديث على animals --------
          // -------- 3) تطبيق التحديث على animals --------
      if (Object.keys(update).length > 0 && event.animalId) {
        try {
          const num = isNaN(Number(event.animalId))
            ? String(event.animalId)
            : Number(event.animalId);

          const snapAnimals = await db
            .collection("animals")
            .where("userId", "==", tenant)
            .where("number", "==", num)
            .limit(10)
            .get();

          for (const d of snapAnimals.docs) {
            await d.ref.set(update, { merge: true });
            console.log("🔥 animal updated:", d.id, update);
          }
        } catch (e) {
          console.error("animals.update error:", e.message || e);
        }
      }
    }

    if (typeof scheduleGroupsRebuildSrv === 'function' && isGroupRebuildEventSrv(event)) {
      scheduleGroupsRebuildSrv(tenant, 'group_affecting_event');
    }

    res.json({ ok:true, event });
  } catch (e) {
    console.error('events', e);
    res.status(500).json({ ok:false, error:'failed_to_save_event' });
  }
});


// ============================================================
//          MURABBIK SMART ALERTS — CORE CONTRACT V1
//          عقد نواة تنبيهات مُرَبِّيك الذكية
// ============================================================

const MURABBIK_SMART_ALERT_KIND_RANK = { operational: 0, technical: 1 };
const MURABBIK_SMART_ALERT_PRIORITY_RANK = { urgent: 0, high: 1, normal: 2, low: 3 };
const MURABBIK_SMART_ALERT_URGENCY_RANK = { now: 0, today: 1, soon: 2, review: 3 };
const MURABBIK_SMART_ALERT_CERTAINTY = new Set([
  "confirmed",
  "probable",
  "suspected",
  "data_gap"
]);
const murabbikSmartAlertSourcesSrv = new Map();

function murabbikSmartAlertTextSrv(value) {
  return String(value || "").trim().replace(/\s+/g, " ");
}

function murabbikSmartAlertHashSrv(value) {
  return crypto
    .createHash("sha256")
    .update(JSON.stringify(value))
    .digest("hex")
    .slice(0, 24);
}

function murabbikSmartAlertRegisterSourceSrv(name, builder) {
  const sourceName = murabbikSmartAlertTextSrv(name);

  if (!sourceName || typeof builder !== "function") {
    throw new Error("murabbik_smart_alert_source_invalid");
  }

  if (murabbikSmartAlertSourcesSrv.has(sourceName)) {
    throw new Error(`murabbik_smart_alert_source_duplicate:${sourceName}`);
  }

  murabbikSmartAlertSourcesSrv.set(sourceName, builder);
}

function murabbikSmartAlertNormalizeSrv(sourceName, raw = {}) {
  const source = murabbikSmartAlertTextSrv(sourceName);
  const identityKey = murabbikSmartAlertTextSrv(raw.identityKey);
  const revisionKey = murabbikSmartAlertTextSrv(raw.revisionKey);
  const kind = murabbikSmartAlertTextSrv(raw.kind).toLowerCase();
  const priority = murabbikSmartAlertTextSrv(raw.priority || "normal").toLowerCase();
  const urgency = murabbikSmartAlertTextSrv(raw.urgency || "review").toLowerCase();
  const certainty = murabbikSmartAlertTextSrv(raw.certainty || "confirmed").toLowerCase();
  const title = murabbikSmartAlertTextSrv(raw.title);
  const message = murabbikSmartAlertTextSrv(raw.message);
  const snoozeMinutes = Math.round(Number(raw.snoozeMinutes));

  const valid =
    source &&
    identityKey &&
    revisionKey &&
    title &&
    message &&
    Object.prototype.hasOwnProperty.call(MURABBIK_SMART_ALERT_KIND_RANK, kind) &&
    Object.prototype.hasOwnProperty.call(MURABBIK_SMART_ALERT_PRIORITY_RANK, priority) &&
    Object.prototype.hasOwnProperty.call(MURABBIK_SMART_ALERT_URGENCY_RANK, urgency) &&
    MURABBIK_SMART_ALERT_CERTAINTY.has(certainty) &&
    Number.isFinite(snoozeMinutes) &&
    snoozeMinutes > 0;

  if (!valid) {
    throw new Error(`murabbik_smart_alert_contract_invalid:${source || "unknown"}`);
  }

  const actionType = murabbikSmartAlertTextSrv(raw.action?.type || "none").toLowerCase();
  const actionLabel = murabbikSmartAlertTextSrv(raw.action?.label);
  const actionUrl = murabbikSmartAlertTextSrv(raw.action?.url);

  if (
    !["none", "navigate"].includes(actionType) ||
    (actionType === "navigate" && (!actionLabel || !actionUrl))
  ) {
    throw new Error(`murabbik_smart_alert_action_invalid:${source}`);
  }

   const animalNumbers = [...new Set(
    (Array.isArray(raw.animalNumbers) ? raw.animalNumbers : [])
      .map(murabbikSmartAlertTextSrv)
      .filter(Boolean)
  )];

  const affectedRaw = Number(raw.affectedCount);
  const affectedCount = Number.isFinite(affectedRaw)
    ? Math.max(0, Math.round(affectedRaw))
    : animalNumbers.length;

  return {
    id: `msa_${murabbikSmartAlertHashSrv({ source, identityKey })}`,
    revision: `msr_${murabbikSmartAlertHashSrv({ source, identityKey, revisionKey })}`,
    source,
    kind,
    domain: murabbikSmartAlertTextSrv(raw.domain),
    code: murabbikSmartAlertTextSrv(raw.code),
    priority,
    urgency,
    certainty,
    status: murabbikSmartAlertTextSrv(raw.status),
    title,
    message,

    details: {
      observation: murabbikSmartAlertTextSrv(raw.details?.observation),
      meaning: murabbikSmartAlertTextSrv(raw.details?.meaning),
      recommendation: murabbikSmartAlertTextSrv(raw.details?.recommendation),

      evidence: Array.isArray(raw.details?.evidence)
        ? raw.details.evidence
            .map(murabbikSmartAlertTextSrv)
            .filter(Boolean)
        : []
    },

    dueDate: murabbikSmartAlertTextSrv(raw.dueDate).slice(0, 10),
    affectedCount,
    animalNumbers,

    action: {
      type: actionType,
      label: actionLabel,
      url: actionUrl
    },

       displayStyle: kind,
    _snoozeMinutes: snoozeMinutes
  };
}

function murabbikSmartAlertCompareSrv(a, b) {
  return (
    (MURABBIK_SMART_ALERT_KIND_RANK[a.kind] ?? 99) -
      (MURABBIK_SMART_ALERT_KIND_RANK[b.kind] ?? 99) ||

    (MURABBIK_SMART_ALERT_PRIORITY_RANK[a.priority] ?? 99) -
      (MURABBIK_SMART_ALERT_PRIORITY_RANK[b.priority] ?? 99) ||

    (MURABBIK_SMART_ALERT_URGENCY_RANK[a.urgency] ?? 99) -
      (MURABBIK_SMART_ALERT_URGENCY_RANK[b.urgency] ?? 99) ||

    String(a.dueDate || "9999-12-31").localeCompare(
      String(b.dueDate || "9999-12-31")
    ) ||

    String(a.id).localeCompare(String(b.id))
  );
}

function murabbikSmartAlertPublicSrv(alert) {
  if (!alert) return null;

   const {
    _snoozeMinutes,
    ...publicAlert
  } = alert;
  return publicAlert;
}
const MURABBIK_SMART_ALERT_STATE_COLLECTION = "smart_alert_states";

function murabbikSmartAlertActorUidSrv(req) {
  return murabbikSmartAlertTextSrv(
    req.authSession?.uid ||
    req.userId
  );
}

function murabbikSmartAlertStateDocIdSrv(req, alertId) {
  return `mas_${murabbikSmartAlertHashSrv({
    actorUid: murabbikSmartAlertActorUidSrv(req),
    userId: req.userId,
    alertId
  })}`;
}

function murabbikSmartAlertStateRefSrv(req, alertId) {
  return db
    .collection(MURABBIK_SMART_ALERT_STATE_COLLECTION)
    .doc(
      murabbikSmartAlertStateDocIdSrv(
        req,
        alertId
      )
    );
}

function murabbikSmartAlertDateMsSrv(value) {
  if (!value) return 0;

  if (typeof value.toMillis === "function") {
    return value.toMillis();
  }

  if (Number.isFinite(Number(value?._seconds))) {
    return Number(value._seconds) * 1000;
  }

  const numeric = Number(value);

  if (Number.isFinite(numeric)) {
    return numeric;
  }

  const parsed = new Date(value).getTime();

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}

async function murabbikSmartAlertApplyUserStateSrv(
  req,
  alerts = [],
  nowMs = Date.now()
) {
  if (!alerts.length) {
    return {
      visibleAlerts: [],
      hiddenCount: 0
    };
  }

  const refs = alerts.map(
    alert =>
      murabbikSmartAlertStateRefSrv(
        req,
        alert.id
      )
  );

  const snapshots = [];

  for (let i = 0; i < refs.length; i += 100) {
    snapshots.push(
      ...await db.getAll(
        ...refs.slice(i, i + 100)
      )
    );
  }

  const statesByDocId = new Map(
    snapshots.map(snap => [
      snap.id,
      snap.exists
        ? (snap.data() || {})
        : null
    ])
  );

  const visibleAlerts = [];
  let hiddenCount = 0;

  for (const alert of alerts) {
    const docId =
      murabbikSmartAlertStateDocIdSrv(
        req,
        alert.id
      );

    const state =
      statesByDocId.get(docId);

    if (
      !state ||
      state.revision !== alert.revision
    ) {
      visibleAlerts.push(alert);
      continue;
    }

    const decision =
      murabbikSmartAlertTextSrv(
        state.decision
      ).toLowerCase();

    if (decision === "acknowledged") {
      hiddenCount++;
      continue;
    }

    if (
      decision === "snoozed" &&
      murabbikSmartAlertDateMsSrv(
        state.snoozedUntil
      ) > nowMs
    ) {
      hiddenCount++;
      continue;
    }

    visibleAlerts.push(alert);
  }

  return {
    visibleAlerts,
    hiddenCount
  };
}

// ============================================================
//       SMART ALERT SOURCE: DRY-OFF DUE — 210 DAYS
//       أول مصدر تشغيلي: استحقاق التجفيف
// ============================================================

const MURABBIK_DRY_OFF_COW_DUE_DAYS = 210;
const MURABBIK_DRY_OFF_BUFFALO_DUE_DAYS = 240;

const MURABBIK_DRY_OFF_ALERT_WINDOW_DAYS = 14;

const MURABBIK_DRY_OFF_COW_EXPECTED_DAYS = 270;
const MURABBIK_DRY_OFF_BUFFALO_EXPECTED_DAYS = 300;

const MURABBIK_DRY_OFF_SNOOZE_MINUTES = 24 * 60;
function murabbikDryOffAlertNumberSrv(doc = {}) {
  return murabbikSmartAlertTextSrv(
    doc.number ??
    doc.animalNumber ??
    doc.animalNo ??
    doc.no ??
    ""
  );
}

function murabbikDryOffAlertIsMilkingSrv(doc = {}) {
  if (doc.inMilk === false) return false;

  const production = murabbikSmartAlertTextSrv([
    doc.productionStatus,
    doc.lactationStatus,
    doc.group,
    doc.groupId
  ].filter(Boolean).join(" ")).toLowerCase();

  if (
    production.includes("dry") ||
    production.includes("جاف")
  ) {
    return false;
  }

  const milkKg = Number(
    doc.dailyMilk ??
    doc.milkTodayKg ??
    doc.lastMilkKg
  );

  return (
    doc.inMilk === true ||
    production.includes("milking") ||
    production.includes("حلاب") ||
    production.includes("حلوب") ||
    (Number.isFinite(milkKg) && milkKg > 0)
  );
}

function murabbikDryOffAlertAlreadyDoneSrv(doc = {}) {
  const lastDry = murabbikSmartAlertTextSrv(
    doc.lastDryOffDate
  ).slice(0, 10);

  const lastCalving = murabbikSmartAlertTextSrv(
    doc.lastCalvingDate
  ).slice(0, 10);

  return (
    calvingIsDateSrv(lastDry) &&
    (
      !calvingIsDateSrv(lastCalving) ||
      lastCalving <= lastDry
    )
  );
}
function murabbikDryOffAlertPregnancyEndedSrv(
  doc = {},
  lastInseminationDate = ""
) {
  if (!calvingIsDateSrv(lastInseminationDate)) {
    return true;
  }

  const endingDates = [
    doc.lastCalvingDate,
    doc.calvingDate,
    doc.lastAbortionDate,
    doc.abortionDate
  ]
    .map(value =>
      murabbikSmartAlertTextSrv(value)
        .slice(0, 10)
    )
    .filter(calvingIsDateSrv);

  return endingDates.some(date => {
    const daysAfterService =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        date
      );

    return (
      Number.isFinite(daysAfterService) &&
      daysAfterService >= 0
    );
  });
}
async function murabbikSmartAlertAnimalsSrv(context) {
  return await context.load(
    "smart-alerts:animals",
    async () => {
      const byId = new Map();

const settled = await Promise.allSettled([
  db.collection("animals")
    .where("userId", "==", context.userId)
    .get(),

  db.collection("animals")
    .where("ownerUid", "==", context.profileUid)
    .get()
]);

      let successfulQueries = 0;

      settled.forEach(result => {
        if (result.status !== "fulfilled") return;

        successfulQueries++;

        result.value.docs.forEach(doc => {
          if (!byId.has(doc.id)) {
            byId.set(doc.id, {
              id: doc.id,
              ...(doc.data() || {})
            });
          }
        });
      });

      if (!successfulQueries) {
        throw new Error(
          "murabbik_smart_alert_animals_load_failed"
        );
      }

      return [...byId.values()];
    }
  );
}
// ============================================================
//       SMART ALERT SOURCE: MILK MIRROR — HEALTH / HERD
//       مرآة اللبن: فردي + جماعي + تغذية + طقس
// ============================================================

const MURABBIK_MILK_MIRROR_SNOOZE_MINUTES = 24 * 60;
const MURABBIK_MILK_MIRROR_LOOKBACK_DAYS = 7;
const MURABBIK_MILK_MIRROR_BASELINE_MIN_DAYS = 3;
const MURABBIK_MILK_MIRROR_BASELINE_MAX_DAYS = 5;
const MURABBIK_MILK_MIRROR_GROUP_MIN_ANIMALS = 3;
const MURABBIK_MILK_MIRROR_GROUP_MIN_AFFECTED_PCT = 25;

const MURABBIK_RUMEN_ACIDOSIS_MIN_DAYS = 4;
const MURABBIK_RUMEN_ACIDOSIS_MIN_DAILY_SWING_KG = 2;
const MURABBIK_RUMEN_ACIDOSIS_MAX_DAILY_SWING_KG = 4;
const MURABBIK_RUMEN_ACIDOSIS_BASELINE_MIN_DAYS = 3;
const MURABBIK_RUMEN_ACIDOSIS_BASELINE_MAX_DAYS = 5;
const MURABBIK_RUMEN_ACIDOSIS_LOOKBACK_DAYS = 12;

function murabbikMilkMirrorDateSrv(event = {}) {
  return murabbikSmartAlertTextSrv(
    event.eventDate ||
    event.date ||
    ""
  ).slice(0, 10);
}

function murabbikMilkMirrorMedianSrv(values = []) {
  const rows = values
    .map(Number)
    .filter(n => Number.isFinite(n) && n > 0)
    .sort((a, b) => a - b);

  if (!rows.length) return null;

  const middle = Math.floor(rows.length / 2);

  return rows.length % 2
    ? rows[middle]
    : (rows[middle - 1] + rows[middle]) / 2;
}

function murabbikMilkMirrorDropPctSrv(currentKg, baselineKg) {
  const current = Number(currentKg);
  const baseline = Number(baselineKg);

  if (
    !Number.isFinite(current) ||
    !Number.isFinite(baseline) ||
    current <= 0 ||
    baseline <= 0 ||
    current >= baseline
  ) {
    return 0;
  }

  return Number(
    (((baseline - current) / baseline) * 100)
      .toFixed(1)
  );
}

function murabbikMilkMirrorAnimalActiveSrv(doc = {}) {
  const status = murabbikSmartAlertTextSrv([
    doc.status,
    doc.lifeStatus,
    doc.animalStatus,
    doc.saleStatus,
    doc.exitReason
  ].filter(Boolean).join(" ")).toLowerCase();

  if (
    doc.active === false ||
    doc.isActive === false ||
    doc.inactive === true
  ) {
    return false;
  }

  return ![
    "inactive",
    "archived",
    "dead",
    "sold",
    "نافق",
    "نفوق",
    "مباع",
    "بيع",
    "خارج القطيع"
  ].some(x => status.includes(x));
}

function murabbikMilkMirrorOfficialGroupMetaSrv(groupId = "") {
  const cleanGroupId =
    murabbikSmartAlertTextSrv(groupId);

  if (
    !milkReportOfficialMilkingGroupIdsSrv()
      .includes(cleanGroupId)
  ) {
    return null;
  }

  const groupDef =
    typeof GROUP_DEF_BY_ID_SRV === "object"
      ? GROUP_DEF_BY_ID_SRV[cleanGroupId]
      : null;

  if (!groupDef) return null;

  const speciesKey =
    groupDef.species === "buffalo"
      ? "buffalo"
      : "cow";

  return {
    speciesKey,
    groupId: cleanGroupId,

    groupName:
      murabbikSmartAlertTextSrv(
        groupDef.label || cleanGroupId
      ),

    groupKey: cleanGroupId
  };
}

function murabbikMilkMirrorOfficialGroupIndexSrv(
  groupsMap = {}
) {
  const index = new Map();

  for (
    const groupId of
    milkReportOfficialMilkingGroupIdsSrv()
  ) {
    const group =
      murabbikMilkMirrorOfficialGroupMetaSrv(
        groupId
      );

    if (!group) continue;

    const members =
      Array.isArray(groupsMap?.[groupId])
        ? groupsMap[groupId]
        : [];

    for (const member of members) {
      const animalNumber =
        murabbikDryOffAlertNumberSrv(member);

      if (!animalNumber) continue;

      index.set(animalNumber, group);
    }
  }

  return index;
}
function murabbikRumenAcidosisDailyGroupsSrv({
  historyByAnimal = new Map(),
  animalsByNumber = new Map(),
  officialGroupByAnimalNumber = new Map(),
  today = ""
} = {}) {
  const byGroup = new Map();

  for (
    const [animalNumber, byDate]
    of historyByAnimal.entries()
  ) {
    const doc =
      animalsByNumber.get(animalNumber);

    if (!doc) continue;
    if (!murabbikMilkMirrorAnimalActiveSrv(doc)) continue;
    if (!murabbikDryOffAlertIsMilkingSrv(doc)) continue;

    if (
      String(doc.entryType || "")
        .trim()
        .toLowerCase() === "followers"
    ) {
      continue;
    }

    const group =
      officialGroupByAnimalNumber.get(
        animalNumber
      ) || null;

    if (
      !group?.groupKey ||
      group.speciesKey !== "cow"
    ) {
      continue;
    }

    if (!byGroup.has(group.groupKey)) {
      byGroup.set(group.groupKey, {
        group,
        byDate: new Map()
      });
    }

    const groupState =
      byGroup.get(group.groupKey);

    for (const row of byDate.values()) {
      const eventDate =
        String(row?.eventDate || "")
          .slice(0, 10);

      const milkKg =
        Number(row?.milkKg);

      if (
        !milkReportIsDateSrv(eventDate) ||
        eventDate > today ||
        !Number.isFinite(milkKg) ||
        milkKg <= 0
      ) {
        continue;
      }

      const ageDays =
        milkReportDaysBetweenSrv(
          eventDate,
          today
        );

      if (
        !Number.isFinite(ageDays) ||
        ageDays < 0 ||
        ageDays >
  MURABBIK_RUMEN_ACIDOSIS_LOOKBACK_DAYS
      ) {
        continue;
      }

      if (!groupState.byDate.has(eventDate)) {
        groupState.byDate.set(
          eventDate,
          []
        );
      }

 groupState.byDate
  .get(eventDate)
  .push({
    animalNumber,
    milkKg
  });
    }
  }

  return byGroup;
}

function murabbikRumenAcidosisFluctuationSrv(
  groupState = null,
  today = ""
) {
  if (!groupState?.group?.groupKey) {
    return null;
  }

  const rawByDate = new Map();

  for (
    const [eventDate, rows]
    of groupState.byDate.entries()
  ) {
    const byAnimal = new Map();

    for (
      const row
      of Array.isArray(rows) ? rows : []
    ) {
      const animalNumber =
        calvingNormDigitsOnlySrv(
          row?.animalNumber || ""
        );

      const milkKg =
        Number(row?.milkKg);

      if (
        !animalNumber ||
        !Number.isFinite(milkKg) ||
        milkKg <= 0
      ) {
        continue;
      }

      byAnimal.set(
        animalNumber,
        milkKg
      );
    }

    if (
      byAnimal.size >=
      MURABBIK_MILK_MIRROR_GROUP_MIN_ANIMALS
    ) {
      rawByDate.set(
        eventDate,
        byAnimal
      );
    }
  }

  const availableDates =
    [...rawByDate.keys()]
      .sort((a, b) =>
        String(a).localeCompare(
          String(b)
        )
      );

  if (
    availableDates.length <
    MURABBIK_RUMEN_ACIDOSIS_MIN_DAYS
  ) {
    return null;
  }

  const patternDates =
    availableDates.slice(
      -MURABBIK_RUMEN_ACIDOSIS_MIN_DAYS
    );

  const currentDate =
    patternDates[
      patternDates.length - 1
    ];

  const latestAgeDays =
    milkReportDaysBetweenSrv(
      currentDate,
      today
    );

  if (
    !Number.isFinite(latestAgeDays) ||
    latestAgeDays < 0 ||
    latestAgeDays > 1
  ) {
    return null;
  }

  for (
    let i = 1;
    i < patternDates.length;
    i++
  ) {
    const gap =
      milkReportDaysBetweenSrv(
        patternDates[i - 1],
        patternDates[i]
      );

    if (gap !== 1) {
      return null;
    }
  }

  let commonAnimals = null;

  for (
    const eventDate
    of patternDates
  ) {
    const animalNumbers =
      new Set(
        rawByDate
          .get(eventDate)
          ?.keys() || []
      );

    if (commonAnimals === null) {
      commonAnimals =
        animalNumbers;

      continue;
    }

    commonAnimals =
      new Set(
        [...commonAnimals]
          .filter(animalNumber =>
            animalNumbers.has(
              animalNumber
            )
          )
      );
  }

  if (
    !commonAnimals ||
    commonAnimals.size <
      MURABBIK_MILK_MIRROR_GROUP_MIN_ANIMALS
  ) {
    return null;
  }

  const averageForDate =
    eventDate => {
      const byAnimal =
        rawByDate.get(eventDate);

      if (!byAnimal) {
        return null;
      }

      const values =
        [...commonAnimals]
          .map(animalNumber =>
            Number(
              byAnimal.get(
                animalNumber
              )
            )
          )
          .filter(value =>
            Number.isFinite(value) &&
            value > 0
          );

      if (
        values.length !==
        commonAnimals.size
      ) {
        return null;
      }

      return Number(
        (
          values.reduce(
            (sum, value) =>
              sum + value,
            0
          ) / values.length
        ).toFixed(2)
      );
    };

  const days =
    patternDates.map(
      eventDate => ({
        eventDate,

        averageKg:
          averageForDate(
            eventDate
          ),

        animalCount:
          commonAnimals.size
      })
    );

  if (
    days.some(day =>
      !Number.isFinite(
        day.averageKg
      ) ||
      day.averageKg <= 0
    )
  ) {
    return null;
  }

  const dailyChangesKg = [];

  for (
    let i = 1;
    i < days.length;
    i++
  ) {
    dailyChangesKg.push(
      Number(
        (
          days[i].averageKg -
          days[i - 1].averageKg
        ).toFixed(2)
      )
    );
  }

  const allChangesWithinRange =
    dailyChangesKg.every(
      changeKg => {
        const absoluteChangeKg =
          Math.abs(changeKg);

        return (
          absoluteChangeKg >=
            MURABBIK_RUMEN_ACIDOSIS_MIN_DAILY_SWING_KG &&
          absoluteChangeKg <=
            MURABBIK_RUMEN_ACIDOSIS_MAX_DAILY_SWING_KG
        );
      }
    );

  const directionsAlternate =
    dailyChangesKg.every(
      (changeKg, index) =>
        index === 0 ||
        Math.sign(changeKg) !==
          Math.sign(
            dailyChangesKg[
              index - 1
            ]
          )
    );

  if (
    !allChangesWithinRange ||
    !directionsAlternate
  ) {
    return null;
  }

  const baselineDays = [];

  let expectedDate =
    milkReportAddDaysSrv(
      patternDates[0],
      -1
    );

  for (
    let i = 0;
    i <
      MURABBIK_RUMEN_ACIDOSIS_BASELINE_MAX_DAYS;
    i++
  ) {
    if (
      !rawByDate.has(
        expectedDate
      )
    ) {
      break;
    }

    const averageKg =
      averageForDate(
        expectedDate
      );

    if (
      !Number.isFinite(
        averageKg
      ) ||
      averageKg <= 0
    ) {
      break;
    }

    baselineDays.unshift({
      eventDate:
        expectedDate,

      averageKg,

      animalCount:
        commonAnimals.size
    });

    expectedDate =
      milkReportAddDaysSrv(
        expectedDate,
        -1
      );
  }

  if (
    baselineDays.length <
    MURABBIK_RUMEN_ACIDOSIS_BASELINE_MIN_DAYS
  ) {
    return null;
  }

  const baselineKg =
    murabbikMilkMirrorMedianSrv(
      baselineDays.map(
        day => day.averageKg
      )
    );

  const peakKg =
    Math.max(
      ...days.map(
        day => day.averageKg
      )
    );

  if (
    !Number.isFinite(
      baselineKg
    ) ||
    baselineKg <= 0 ||
    peakKg >= baselineKg
  ) {
    return null;
  }

  const absoluteChangesKg =
    dailyChangesKg.map(
      changeKg =>
        Math.abs(changeKg)
    );

  return {
    group:
      groupState.group,

    days,
    baselineDays,

    startDate:
      patternDates[0],

    currentDate,

    baselineKg:
      Number(
        baselineKg.toFixed(2)
      ),

    peakKg:
      Number(
        peakKg.toFixed(2)
      ),

    minDailySwingKg:
      Number(
        Math.min(
          ...absoluteChangesKg
        ).toFixed(2)
      ),

    maxDailySwingKg:
      Number(
        Math.max(
          ...absoluteChangesKg
        ).toFixed(2)
      ),

    dailyChangesKg,

    animalCount:
      commonAnimals.size
  };
}
function murabbikMilkMirrorReportUrlSrv(speciesKey = "cow") {
  const type = speciesKey === "buffalo" ? "buffalo" : "cows";
  const species = speciesKey === "buffalo" ? "buffalo" : "cow";

  return `nutrition-report.html?type=${encodeURIComponent(type)}&species=${encodeURIComponent(species)}`;
}
function murabbikMilkMirrorGroupRationUrlSrv(
  allEvents = [],
  group = {},
  groupNumbers = [],
  currentDate = ""
) {
  const wantedTokens = [
    group.groupKey,
    group.groupId,
    group.groupName
  ].map(normReportText).filter(Boolean);

  const latestEvent = (Array.isArray(allEvents) ? allEvents : [])
    .filter(isNutritionSavedEvent)
    .filter(event =>
      Array.isArray(event?.nutrition?.rows) &&
      event.nutrition.rows.length
    )
    .filter(event => {
      const eventDate = String(
        event.eventDate ||
        event.date ||
        ""
      ).slice(0, 10);

      return (
        !currentDate ||
        !milkReportIsDateSrv(eventDate) ||
        eventDate <= currentDate
      );
    })
    .filter(event => {
      const eventTokens =
        nutritionReportGroupTokensSrv(event);

      return wantedTokens.some(token =>
        eventTokens.includes(token)
      );
    })
    .sort((a, b) => {
      const aDate = String(
        a.eventDate ||
        a.date ||
        ""
      ).slice(0, 10);

      const bDate = String(
        b.eventDate ||
        b.date ||
        ""
      ).slice(0, 10);

      if (aDate !== bDate) {
        return bDate.localeCompare(aDate);
      }

      return eventCreatedMs(b) - eventCreatedMs(a);
    })[0] || null;

  const eventId =
    String(latestEvent?.id || "").trim();

  if (eventId) {
    return `nutrition.html?eventId=${encodeURIComponent(eventId)}`;
  }

  const params = new URLSearchParams();

  const groupName =
    String(group.groupName || "").trim();

  const groupKey =
    String(
      group.groupKey ||
      group.groupId ||
      ""
    ).trim();

  const numbers = [...new Set(
    (Array.isArray(groupNumbers) ? groupNumbers : [])
      .map(murabbikDryOffAlertNumberSrv)
      .filter(Boolean)
  )];

  if (groupName) {
    params.set("groupName", groupName);
  }

  if (groupKey) {
    params.set("groupKey", groupKey);
  }

  if (numbers.length) {
    params.set("numbers", numbers.join(","));
  }

  const query = params.toString();

  return query
    ? `nutrition.html?${query}`
    : "nutrition.html";
}
function murabbikMilkMirrorGroupRationEventIdSrv(
  allEvents = [],
  group = {},
  currentDate = ""
) {
  const wantedTokens = [
    group.groupId,
    group.groupKey,
    group.groupName
  ]
    .map(normReportText)
    .filter(Boolean);

  if (!wantedTokens.length) return "";

  const latestEvent = (Array.isArray(allEvents) ? allEvents : [])
    .filter(event => {
      const type = String(
        event.type ||
        event.eventTypeNorm ||
        ""
      ).trim().toLowerCase();

      return type === "nutrition_group";
    })
    .filter(event =>
      Array.isArray(event?.nutrition?.rows) &&
      event.nutrition.rows.length > 0
    )
    .filter(event => {
      const eventDate = String(
        event.eventDate ||
        event.date ||
        ""
      ).slice(0, 10);

      return (
        !currentDate ||
        !milkReportIsDateSrv(eventDate) ||
        eventDate <= currentDate
      );
    })
    .filter(event => {
      const eventTokens =
        nutritionReportGroupTokensSrv(event);

      return wantedTokens.some(token =>
        eventTokens.includes(token)
      );
    })
    .sort((a, b) => {
      const aDate = String(
        a.eventDate ||
        a.date ||
        ""
      ).slice(0, 10);

      const bDate = String(
        b.eventDate ||
        b.date ||
        ""
      ).slice(0, 10);

      if (aDate !== bDate) {
        return bDate.localeCompare(aDate);
      }

      return eventCreatedMs(b) - eventCreatedMs(a);
    })[0] || null;

  return String(
    latestEvent?.id ||
    latestEvent?.firestoreId ||
    ""
  ).trim();
}
