async function murabbikDryOffDueAlertSourceSrv(context) {
  const animals = await murabbikSmartAlertAnimalsSrv(
    context
  );

  const due = [];

  for (const doc of animals) {
    const animalNumber =
      murabbikDryOffAlertNumberSrv(doc);

    const status = murabbikSmartAlertTextSrv(
      doc.status || "active"
    ).toLowerCase();

    if (!animalNumber) continue;
    if (["inactive", "archived"].includes(status)) continue;

    if (
      String(doc.entryType || "")
        .trim()
        .toLowerCase() === "followers"
    ) {
      continue;
    }

    if (dryOffIsBlockedSrv(doc)) continue;
    if (!murabbikDryOffAlertIsMilkingSrv(doc)) continue;
    if (murabbikDryOffAlertAlreadyDoneSrv(doc)) continue;

    const reproStatus = calvingStripArSrv(
      doc.reproductiveStatus || ""
    );

    if (!reproStatus.includes("عشار")) continue;

    const lastInseminationDate =
      murabbikSmartAlertTextSrv(
        doc.lastInseminationDate ||
        doc.lastAI ||
        doc.lastInsemination ||
        doc.lastServiceDate ||
        ""
      ).slice(0, 10);

    if (!calvingIsDateSrv(lastInseminationDate)) continue;

    if (
      murabbikDryOffAlertPregnancyEndedSrv(
        doc,
        lastInseminationDate
      )
    ) {
      continue;
    }

    const speciesKey = dryOffSpeciesKeySrv(doc);

    const dueGestationDay =
      speciesKey === "buffalo"
        ? MURABBIK_DRY_OFF_BUFFALO_DUE_DAYS
        : MURABBIK_DRY_OFF_COW_DUE_DAYS;

    const expectedGestationDays =
      speciesKey === "buffalo"
        ? MURABBIK_DRY_OFF_BUFFALO_EXPECTED_DAYS
        : MURABBIK_DRY_OFF_COW_EXPECTED_DAYS;

    const alertEndGestationDay = Math.min(
      dueGestationDay +
        MURABBIK_DRY_OFF_ALERT_WINDOW_DAYS,
      expectedGestationDays
    );

    const gestationDays = calvingDaysBetweenSrv(
      lastInseminationDate,
      context.today
    );

    if (
      !Number.isFinite(gestationDays) ||
      gestationDays < dueGestationDay ||
      gestationDays >= alertEndGestationDay ||
      gestationDays >= expectedGestationDays
    ) {
      continue;
    }

    due.push({
      animalNumber,
      speciesKey,
      lastInseminationDate,
      gestationDays,
      dueGestationDay,
      alertEndGestationDay,

      dueDate: addDaysToIsoDateSrv(
        lastInseminationDate,
        dueGestationDay
      ),

      alertEndDate: addDaysToIsoDateSrv(
        lastInseminationDate,
        alertEndGestationDay
      )
    });
  }

  if (!due.length) return [];

  due.sort((a, b) =>
    b.gestationDays - a.gestationDays ||
    String(a.animalNumber).localeCompare(
      String(b.animalNumber),
      "ar",
      { numeric: true }
    )
  );

  const animalNumbers = [
    ...new Set(
      due
        .map(item => item.animalNumber)
        .filter(Boolean)
    )
  ];

  const count = animalNumbers.length;

  const evidence = due
    .slice(0, 12)
    .map(item =>
      `الحيوان ${item.animalNumber}: ${item.gestationDays} يوم حمل، وتنتهي نافذة التذكير ${item.alertEndDate}`
    );

  if (due.length > evidence.length) {
    evidence.push(
      `و${due.length - evidence.length} حيوان آخر داخل نافذة تذكير التجفيف.`
    );
  }

  const revisionKey = [...due]
    .sort((a, b) =>
      String(a.animalNumber).localeCompare(
        String(b.animalNumber),
        "ar",
        { numeric: true }
      )
    )
    .map(item =>
      [
        item.animalNumber,
        item.speciesKey,
        item.lastInseminationDate,
        item.dueGestationDay,
        item.alertEndGestationDay
      ].join(":")
    )
    .join("|");

  const earliestDueDate = due
    .map(item => item.dueDate)
    .filter(calvingIsDateSrv)
    .sort()[0] || context.today;

  return [{
    identityKey: "dry-off-due-herd",
    revisionKey,

    kind: "operational",
    domain: "reproduction",
    code: "dry_off_due_210",

    priority: "normal",
    urgency: "today",
    certainty: "confirmed",
    status: "due",

    title:
      count === 1
        ? "حيوان مستحق للتجفيف"
        : "حيوانات مستحقة للتجفيف",

    message:
      count === 1
        ? `الحيوان رقم ${animalNumbers[0]} داخل نافذة تذكير التجفيف ولم يُسجّل جافًا بعد.`
        : `يوجد ${count} حيوانات داخل نافذة تذكير التجفيف ولم يُسجّل تجفيفها بعد.`,

    details: {
      observation:
        count === 1
          ? `عمر الحمل الحالي ${due[0].gestationDays} يومًا، وتنتهي نافذة التذكير بتاريخ ${due[0].alertEndDate}.`
          : `أرقام الحيوانات: ${animalNumbers.join("، ")}.`,

      meaning:
        "التجفيف في هذه المرحلة يهيئ الحيوان لفترة الجفاف والاستعداد للولادة التالية.",

      recommendation:
        "راجع الحالات وسجّل التجفيف في الوقت المناسب لكل حيوان.",

      evidence
    },

    dueDate: earliestDueDate,
    affectedCount: count,
    animalNumbers,

    action: {
      type: "navigate",

      label:
        count === 1
          ? "تجفيف الحيوان"
          : "تجفيف الحيوانات",

      url:
        eventsPageBuildRedirectSrv({
          page: "dry-off.html",
          numbers: animalNumbers,
          eventDate: context.today
        })
    },

    snoozeMinutes:
      MURABBIK_DRY_OFF_SNOOZE_MINUTES
  }];
}

murabbikSmartAlertRegisterSourceSrv(
  "dry_off_due",
  murabbikDryOffDueAlertSourceSrv
);
// ============================================================
//     SMART ALERT SOURCE: CLOSE-UP PREPARATION — GROUPED
//     تنبيه تحضير الولادة الذكي — تنبيه واحد مجمّع
// ============================================================

const MURABBIK_CLOSE_UP_SNOOZE_MINUTES = 24 * 60;
const MURABBIK_CLOSE_UP_STOP_DAYS_BEFORE_CALVING = 10;

function murabbikCloseUpAlertAlreadyDoneSrv(
  doc = {},
  lastInseminationDate = ""
) {
  const production = murabbikSmartAlertTextSrv([
    doc.productionStatus,
    doc.lactationStatus,
    doc.group,
    doc.groupId
  ].filter(Boolean).join(" ")).toLowerCase();

  if (
    (
      production.includes("تحضير") &&
      production.includes("ولاد")
    ) ||
    (
      production.includes("انتظار") &&
      production.includes("ولاد")
    ) ||
    production.includes("close_up") ||
    production.includes("closeup")
  ) {
    return true;
  }

  const lastCloseUpDate =
    murabbikSmartAlertTextSrv(
      doc.lastCloseUpDate ||
      doc.closeUpDate ||
      ""
    ).slice(0, 10);

  if (
    !calvingIsDateSrv(lastInseminationDate) ||
    !calvingIsDateSrv(lastCloseUpDate)
  ) {
    return false;
  }

  const closeUpAfterService =
    calvingDaysBetweenSrv(
      lastInseminationDate,
      lastCloseUpDate
    );

  return (
    Number.isFinite(closeUpAfterService) &&
    closeUpAfterService >= 0
  );
}

function murabbikCloseUpAlertPregnancyEndedSrv(
  doc = {},
  lastInseminationDate = ""
) {
  if (!calvingIsDateSrv(lastInseminationDate)) {
    return true;
  }

  const endingDates = [
    doc.lastCalvingDate,
    doc.calvingDate,
    doc.lastAbortionDate,
    doc.abortionDate
  ]
    .map(value =>
      murabbikSmartAlertTextSrv(value)
        .slice(0, 10)
    )
    .filter(calvingIsDateSrv);

  return endingDates.some(date => {
    const daysAfterService =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        date
      );

    return (
      Number.isFinite(daysAfterService) &&
      daysAfterService >= 0
    );
  });
}

async function murabbikCloseUpDueAlertSourceSrv(
  context
) {
  const animals =
    await murabbikSmartAlertAnimalsSrv(
      context
    );

  const due = [];

  for (const doc of animals) {
    const animalNumber =
      murabbikDryOffAlertNumberSrv(doc);

    const status =
      murabbikSmartAlertTextSrv(
        doc.status || "active"
      ).toLowerCase();

    if (!animalNumber) continue;
    if (["inactive", "archived"].includes(status)) continue;

    if (
      String(doc.entryType || "")
        .trim()
        .toLowerCase() === "followers"
    ) {
      continue;
    }

    const reproStatus =
      calvingStripArSrv(
        doc.reproductiveStatus ||
        doc.reproStatus ||
        ""
      );

    if (!reproStatus.includes("عشار")) continue;

    const lastInseminationDate =
      murabbikSmartAlertTextSrv(
        doc.lastInseminationDate ||
        doc.lastAI ||
        doc.lastInsemination ||
        doc.lastServiceDate ||
        ""
      ).slice(0, 10);

    if (!calvingIsDateSrv(lastInseminationDate)) continue;

    if (
      murabbikCloseUpAlertPregnancyEndedSrv(
        doc,
        lastInseminationDate
      )
    ) {
      continue;
    }

    if (
      murabbikCloseUpAlertAlreadyDoneSrv(
        doc,
        lastInseminationDate
      )
    ) {
      continue;
    }

    const policy = closeupPolicySrv(
      doc.species ||
      doc.animalTypeAr ||
      doc.animalType ||
      doc.animaltype ||
      doc.groupSpecies ||
      ""
    );

    if (!policy) continue;

    const gestationDays =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        context.today
      );

if (
  !Number.isFinite(gestationDays) ||
  gestationDays < policy.targetGestationDay ||
  gestationDays >=
    policy.expectedGestationDays -
    MURABBIK_CLOSE_UP_STOP_DAYS_BEFORE_CALVING
) {
  continue;
}
    due.push({
      animalNumber,
      species: policy.species,
      lastInseminationDate,
      gestationDays,

      targetGestationDay:
        policy.targetGestationDay,

      dueDate:
        addDaysToIsoDateSrv(
          lastInseminationDate,
          policy.targetGestationDay
        ),

      expectedCalvingDate:
        addDaysToIsoDateSrv(
          lastInseminationDate,
          policy.expectedGestationDays
        ),

      stage:
        gestationDays >
        policy.targetGestationDay
          ? "overdue"
          : "due"
    });
  }

if (!due.length) return [];

due.sort((a, b) =>
  b.gestationDays - a.gestationDays ||
  String(a.animalNumber).localeCompare(
    String(b.animalNumber),
    "ar",
    { numeric: true }
  )
);

const animalNumbers = [
  ...new Set(
    due
      .map(item => item.animalNumber)
      .filter(Boolean)
  )
];

const count = animalNumbers.length;

const overdueCount = due.filter(
  item => item.stage === "overdue"
).length;

const dueTodayCount =
  count - overdueCount;

const hasOverdue =
  overdueCount > 0;

const evidence = due
  .slice(0, 12)
  .map(item =>
    `الحيوان ${item.animalNumber}: ${item.gestationDays} يوم حمل، والموعد المستهدف ${item.dueDate}`
  );

if (due.length > evidence.length) {
  evidence.push(
    `و${due.length - evidence.length} حيوان آخر مستحق لتحضير الولادة.`
  );
}

const revisionKey = [...due]
  .sort((a, b) =>
    String(a.animalNumber).localeCompare(
      String(b.animalNumber),
      "ar",
      { numeric: true }
    )
  )
  .map(item =>
    [
      item.animalNumber,
      item.lastInseminationDate,
      item.dueDate,
      item.targetGestationDay,
      item.stage
    ].join(":")
  )
  .join("|");

const summaryParts = [];

if (dueTodayCount > 0) {
  summaryParts.push(
    `${dueTodayCount} مستحق${dueTodayCount === 1 ? "" : "ة"}`
  );
}

if (overdueCount > 0) {
  summaryParts.push(
    `${overdueCount} متأخر${overdueCount === 1 ? "" : "ة"}`
  );
}

return [
  {
    identityKey:
      "close-up-due:current",

    revisionKey,

    kind: "operational",
    domain: "reproduction",
    code: "close_up_due",

    priority:
      hasOverdue
        ? "high"
        : "normal",

    urgency: "today",
    certainty: "confirmed",

    status:
      hasOverdue
        ? "overdue"
        : "due",

    title:
      count === 1
        ? "حيوان مستحق لتحضير الولادة"
        : "حيوانات مستحقة لتحضير الولادة",

    message:
      count === 1
        ? (
            hasOverdue
              ? `الحيوان رقم ${animalNumbers[0]} تجاوز موعد تحضير الولادة ولم يُسجّل في انتظار الولادة بعد.`
              : `الحيوان رقم ${animalNumbers[0]} مستحق لتحضير الولادة اليوم.`
          )
        : `يوجد ${count} حيوانات مطلوب تحضيرها للولادة الآن (${summaryParts.join("، ")}).`,

    details: {
      observation:
        count === 1
          ? `آخر تلقيح مسجّل بتاريخ ${due[0].lastInseminationDate}، وعمر الحمل الحالي ${due[0].gestationDays} يومًا.`
          : `أرقام الحيوانات: ${animalNumbers.join("، ")}.`,

      meaning:
        "مرحلة تحضير الولادة تساعد على الانتقال المنظم إلى مجموعة انتظار الولادة وتجهيز التغذية والرعاية قبل الولادة.",

      recommendation:
        "راجع الحالات ميدانيًا، ثم سجّل تحضير الولادة للحيوانات المناسبة.",

      evidence
    },

    dueDate: context.today,
    affectedCount: count,
    animalNumbers,

    action: {
      type: "navigate",

      label:
        count === 1
          ? "تحضير الحيوان"
          : "تحضير الحيوانات",

      url:
        eventsPageBuildRedirectSrv({
          page: "close-up.html",
          numbers: animalNumbers,
          eventDate: context.today
        })
    },

    snoozeMinutes:
      MURABBIK_CLOSE_UP_SNOOZE_MINUTES
  }
];
   
}

murabbikSmartAlertRegisterSourceSrv(
  "close_up_due",
  murabbikCloseUpDueAlertSourceSrv
);
const MURABBIK_CALVING_EXPECTED_COW_DAYS = 270;
const MURABBIK_CALVING_EXPECTED_BUFFALO_DAYS = 300;

const MURABBIK_CALVING_OVERDUE_COW_DAYS = 290;
const MURABBIK_CALVING_OVERDUE_BUFFALO_DAYS = 320;

const MURABBIK_CALVING_OVERDUE_SNOOZE_MINUTES = 24 * 60;

function murabbikCalvingOverdueDateSrv(value) {
  const iso = murabbikSmartAlertTextSrv(
    value
  ).slice(0, 10);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) {
    return "";
  }

  const parsed = new Date(
    `${iso}T00:00:00Z`
  );

  if (
    Number.isNaN(parsed.getTime()) ||
    parsed.toISOString().slice(0, 10) !== iso
  ) {
    return "";
  }

  return iso;
}

function murabbikCalvingOverdueSpeciesSrv(doc = {}) {
  const text = [
    doc.species,
    doc.animalTypeAr,
    doc.animalType,
    doc.animaltype,
    doc.type,
    doc.groupSpecies,
    doc.groupId,
    doc.group
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  if (
    text.includes("buffalo") ||
    text.includes("جاموس") ||
    text.includes("buff_")
  ) {
       return {
      key: "buffalo",
      label: "جاموس",

      expectedDays:
        MURABBIK_CALVING_EXPECTED_BUFFALO_DAYS,

      overdueAfterDays:
        MURABBIK_CALVING_OVERDUE_BUFFALO_DAYS
    };
  }

  if (
    text.includes("cow") ||
    text.includes("cattle") ||
    text.includes("بقر") ||
    text.includes("ابقار") ||
    text.includes("أبقار") ||
    text.includes("cow_")
  ) {
        return {
      key: "cow",
      label: "أبقار",

      expectedDays:
        MURABBIK_CALVING_EXPECTED_COW_DAYS,

      overdueAfterDays:
        MURABBIK_CALVING_OVERDUE_COW_DAYS
    };
  }

  return null;
}

async function murabbikCalvingOverdueAlertSourceSrv(
  context
) {
  const animals =
    await murabbikSmartAlertAnimalsSrv(
      context
    );

  const alerts = [];

  for (const doc of animals) {
    const animalNumber =
      murabbikDryOffAlertNumberSrv(doc);

    const status =
      murabbikSmartAlertTextSrv(
        doc.status || "active"
      ).toLowerCase();

    if (!animalNumber) continue;
    if (status !== "active") continue;

    if (
      murabbikSmartAlertTextSrv(
        doc.entryType
      ).toLowerCase() === "followers"
    ) {
      continue;
    }

    const reproductiveStatus =
      calvingStripArSrv(
        doc.reproductiveStatus || ""
      ).toLowerCase();

    const isPregnant =
      reproductiveStatus.includes("عشار") ||
      reproductiveStatus.includes("حامل") ||
      reproductiveStatus.includes("pregnant");

    if (!isPregnant) continue;

    const species =
      murabbikCalvingOverdueSpeciesSrv(doc);

    if (!species) continue;

    const lastInseminationDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastInseminationDate
      );

    if (!lastInseminationDate) continue;

    const lastCalvingDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastCalvingDate
      );

    if (
      lastCalvingDate &&
      lastCalvingDate >= lastInseminationDate
    ) {
      continue;
    }

    const lastAbortionDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastAbortionDate ||
        doc.abortionDate
      );

    if (
      lastAbortionDate &&
      lastAbortionDate >= lastInseminationDate
    ) {
      continue;
    }

    const gestationDays =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        context.today
      );

if (
  !Number.isFinite(gestationDays) ||
  gestationDays < species.overdueAfterDays
) {
  continue;
}

    const stage =
  gestationDays >= species.overdueAfterDays
    ? "overdue"
    : "due";

    const expectedCalvingDate =
      addDaysToIsoDateSrv(
        lastInseminationDate,
        species.expectedDays
      );

    const overdueStartDate =
      addDaysToIsoDateSrv(
        lastInseminationDate,
        species.overdueAfterDays + 1
      );

    alerts.push({
      identityKey:
        `calving-overdue:${animalNumber}`,

      revisionKey:
        [
          animalNumber,
          species.key,
          lastInseminationDate,
          stage
        ].join(":"),

      kind: "operational",
      domain: "reproduction",
      code: "calving_overdue",

      priority:
        stage === "overdue"
          ? "high"
          : "normal",

      urgency: "today",
      certainty: "confirmed",
      status: stage,

      title:
        stage === "overdue"
          ? "تأخر موعد الولادة"
          : "متابعة موعد الولادة",

      message:
        stage === "overdue"
          ? `الحيوان رقم ${animalNumber} وصل إلى ${gestationDays} يومًا من الحمل وتجاوز نهاية المدى الطبيعي المتوقع للولادة، ولم تُسجّل له ولادة حتى الآن. راجع الحيوان وسجّل الحالة الفعلية.`
          : `الحيوان رقم ${animalNumber} وصل إلى موعد الولادة المتوقع، ولم تُسجّل له ولادة حتى الآن. تابع الحيوان وسجّل الولادة عند حدوثها.`,

      details: {
        observation:
          stage === "overdue"
            ? `آخر تلقيح مسجّل بتاريخ ${lastInseminationDate}، وبدأت متابعة التأخر بتاريخ ${overdueStartDate}.`
            : `آخر تلقيح مسجّل بتاريخ ${lastInseminationDate}، وموعد الولادة المتوقع ${expectedCalvingDate}.`,

        meaning:
          stage === "overdue"
            ? "تجاوز نهاية المدى الطبيعي المتوقع لا يثبت وحده وجود مشكلة صحية، لكنه يستدعي مراجعة الحيوان والبيانات المسجّلة."
            : "الحيوان داخل المدى الطبيعي المتوقع للولادة، وتحتاج حالته إلى المتابعة حتى تسجيل الولادة أو الحالة الفعلية.",

        recommendation:
          "راجع الحيوان ميدانيًا، ثم سجّل الولادة أو الحالة الفعلية من الصفحة المخصصة.",

        evidence: [
          `رقم الحيوان: ${animalNumber}`,
          `النوع: ${species.label}`,
          `عمر الحمل المسجّل: ${gestationDays} يومًا`,
          `موعد الولادة المتوقع: ${expectedCalvingDate}`,
          `نهاية المدى الطبيعي: ${addDaysToIsoDateSrv(
            lastInseminationDate,
            species.overdueAfterDays
          )}`
        ]
      },

      dueDate:
        stage === "overdue"
          ? overdueStartDate
          : expectedCalvingDate,

      affectedCount: 1,

      animalNumbers: [
        animalNumber
      ],

      action: {
        type: "navigate",
        label: "تسجيل الولادة",

        url:
          `calving.html?number=${encodeURIComponent(
            animalNumber
          )}`
      },

      snoozeMinutes:
        MURABBIK_CALVING_OVERDUE_SNOOZE_MINUTES
    });
  }

  return alerts;
}

murabbikSmartAlertRegisterSourceSrv(
  "calving_overdue",
  murabbikCalvingOverdueAlertSourceSrv
);
// ============================================================
//   SMART ALERT SOURCE: PREGNANCY DIAGNOSIS — ULTRASOUND / MANUAL
//   تنبيهان متتابعان: سونار 26–39، وفحص يدوي من 40 يومًا
// ============================================================

const MURABBIK_PREGNANCY_ULTRASOUND_DUE_DAYS = 26;
const MURABBIK_PREGNANCY_MANUAL_DUE_DAYS = 40;
const MURABBIK_PREGNANCY_DIAGNOSIS_SNOOZE_MINUTES = 24 * 60;

function murabbikPregnancyDiagnosisAlertDateSrv(value) {
  const iso =
    murabbikSmartAlertTextSrv(value)
      .slice(0, 10);

  return calvingIsDateSrv(iso)
    ? iso
    : "";
}

function murabbikPregnancyDiagnosisAlertUrlSrv({
  numbers = [],
  eventDate = "",
  method = ""
} = {}) {
  const base =
    eventsPageBuildRedirectSrv({
      page: "pregnancy-diagnosis.html",
      numbers,
      eventDate
    });

  const separator =
    base.includes("?")
      ? "&"
      : "?";

  return (
    `${base}${separator}` +
    `checkType=${encodeURIComponent(
      "initial_pregnancy_diagnosis"
    )}` +
    `&pregnancyCheckType=${encodeURIComponent(
      "initial_pregnancy_diagnosis"
    )}` +
    `&method=${encodeURIComponent(method)}`
  );
}

function murabbikPregnancyDiagnosisAlertClosedSrv(
  doc = {},
  lastInseminationDate = ""
) {
  if (!calvingIsDateSrv(lastInseminationDate)) {
    return true;
  }

  const lastDiagnosisDate =
    murabbikPregnancyDiagnosisAlertDateSrv(
      doc.lastDiagnosisDate ||
      doc.lastPregnancyDiagnosisDate ||
      ""
    );

  if (lastDiagnosisDate) {
    const diagnosisAfterService =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        lastDiagnosisDate
      );

    if (
      Number.isFinite(diagnosisAfterService) &&
      diagnosisAfterService >= 0
    ) {
      return true;
    }
  }

  const lastHeatDate =
    murabbikPregnancyDiagnosisAlertDateSrv(
      doc.lastHeatDate ||
      doc.heatDate ||
      ""
    );

  if (lastHeatDate) {
    const heatAfterService =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        lastHeatDate
      );

    // الشياع والتلقيح قد يُسجلان في اليوم نفسه،
    // لذلك يغلق المسار فقط عند وجود شياع في يوم لاحق.
    if (
      Number.isFinite(heatAfterService) &&
      heatAfterService > 0
    ) {
      return true;
    }
  }

  return false;
}

function murabbikPregnancyDiagnosisGroupedAlertSrv(
  items = [],
  stage = "",
  context = {}
) {
  if (!items.length) return null;

  const isUltrasound =
    stage === "ultrasound";

  const sorted =
    [...items].sort((a, b) =>
      b.daysSinceInsemination -
        a.daysSinceInsemination ||

      String(a.animalNumber).localeCompare(
        String(b.animalNumber),
        "ar",
        { numeric: true }
      )
    );

  const animalNumbers = [
    ...new Set(
      sorted
        .map(item => item.animalNumber)
        .filter(Boolean)
    )
  ];

  const count =
    animalNumbers.length;

  const evidence =
    sorted
      .slice(0, 12)
      .map(item =>
        `الحيوان ${item.animalNumber}: ${item.daysSinceInsemination} يومًا بعد التلقيح، وآخر تلقيح ${item.lastInseminationDate}`
      );

  if (sorted.length > evidence.length) {
    evidence.push(
      `و${sorted.length - evidence.length} حيوان آخر مستحق لتشخيص الحمل.`
    );
  }

  const revisionKey =
    [...sorted]
      .sort((a, b) =>
        String(a.animalNumber).localeCompare(
          String(b.animalNumber),
          "ar",
          { numeric: true }
        )
      )
      .map(item =>
        [
          item.animalNumber,
          item.lastInseminationDate,
          stage
        ].join(":")
      )
      .join("|");

  const dueDays =
    isUltrasound
      ? MURABBIK_PREGNANCY_ULTRASOUND_DUE_DAYS
      : MURABBIK_PREGNANCY_MANUAL_DUE_DAYS;

  const earliestDueDate =
    sorted
      .map(item =>
        addDaysToIsoDateSrv(
          item.lastInseminationDate,
          dueDays
        )
      )
      .filter(calvingIsDateSrv)
      .sort()[0] ||
    context.today;

  return {
    identityKey:
      isUltrasound
        ? "pregnancy-diagnosis-ultrasound:current"
        : "pregnancy-diagnosis-manual:current",

    revisionKey,

    kind: "operational",
    domain: "reproduction",

    code:
      isUltrasound
        ? "pregnancy_diagnosis_ultrasound_due"
        : "pregnancy_diagnosis_manual_due",

    priority:
      isUltrasound
        ? "normal"
        : "high",

    urgency: "today",
    certainty: "confirmed",

    status:
      isUltrasound
        ? "due"
        : "overdue",

    title:
      isUltrasound
        ? (
            count === 1
              ? "موعد تشخيص الحمل بالسونار"
              : "حيوانات مستحقة للسونار"
          )
        : (
            count === 1
              ? "موعد الفحص اليدوي للحمل"
              : "حيوانات مستحقة للفحص اليدوي"
          ),

    message:
      isUltrasound
        ? (
            count === 1
              ? `الحيوان رقم ${animalNumbers[0]} أكمل 26 يومًا بعد التلقيح ويمكن تشخيص الحمل بالسونار الآن.`
              : `يوجد ${count} حيوانات أكملت 26 يومًا بعد التلقيح ويمكن تشخيص الحمل بالسونار الآن.`
          )
        : (
            count === 1
              ? `الحيوان رقم ${animalNumbers[0]} أكمل 40 يومًا بعد التلقيح ولم يُسجّل له تشخيص حمل حتى الآن، ويمكن فحصه يدويًا.`
              : `يوجد ${count} حيوانات أكملت 40 يومًا أو أكثر بعد التلقيح ولم يُسجّل لها تشخيص حمل حتى الآن.`
          ),

    details: {
      observation:
        count === 1
          ? `آخر تلقيح مسجّل بتاريخ ${sorted[0].lastInseminationDate}، ومرّ عليه ${sorted[0].daysSinceInsemination} يومًا.`
          : `أرقام الحيوانات: ${animalNumbers.join("، ")}.`,

      meaning:
        isUltrasound
          ? "التشخيص المبكر بالسونار يساعد على معرفة نتيجة التلقيح وتحديد الخطوة التالية في الوقت المناسب."
          : "مرور 40 يومًا أو أكثر يتيح تشخيص الحمل بالفحص اليدوي عند توافر المختص.",

      recommendation:
        isUltrasound
          ? "راجع الحيوانات وسجّل نتيجة السونار بعد الفحص."
          : "راجع الحيوانات وسجّل نتيجة الفحص اليدوي بعد إجرائه.",

      evidence
    },

    dueDate: earliestDueDate,
    affectedCount: count,
    animalNumbers,

    action: {
      type: "navigate",

      label:
        isUltrasound
          ? "تسجيل السونار"
          : "تسجيل الفحص اليدوي",

      url:
        murabbikPregnancyDiagnosisAlertUrlSrv({
          numbers: animalNumbers,
          eventDate: context.today,

          method:
            isUltrasound
              ? "ultrasound"
              : "manual"
        })
    },

    snoozeMinutes:
      MURABBIK_PREGNANCY_DIAGNOSIS_SNOOZE_MINUTES
  };
}

async function murabbikPregnancyDiagnosisDueAlertSourceSrv(
  context
) {
  const animals =
    await murabbikSmartAlertAnimalsSrv(
      context
    );

  const ultrasoundDue = [];
  const manualDue = [];

  for (const doc of animals) {
    const animalNumber =
      murabbikDryOffAlertNumberSrv(doc);

    const status =
      murabbikSmartAlertTextSrv(
        doc.status || "active"
      ).toLowerCase();

    if (!animalNumber) continue;

    if (
      ["inactive", "archived"]
        .includes(status)
    ) {
      continue;
    }

    if (
      murabbikSmartAlertTextSrv(
        doc.entryType
      ).toLowerCase() === "followers"
    ) {
      continue;
    }

    const reproductiveStatus =
      doc.reproductiveStatus ||
      doc.reproStatus ||
      "";

    if (
      !pregnancyDiagnosisIsInseminatedStatusSrv(
        reproductiveStatus
      )
    ) {
      continue;
    }

    const lastInseminationDate =
      murabbikPregnancyDiagnosisAlertDateSrv(
        doc.lastInseminationDate ||
        doc.lastAI ||
        doc.lastInsemination ||
        doc.lastServiceDate ||
        ""
      );

    if (!lastInseminationDate) continue;

    if (
      murabbikPregnancyDiagnosisAlertClosedSrv(
        doc,
        lastInseminationDate
      )
    ) {
      continue;
    }

    const daysSinceInsemination =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        context.today
      );

    if (
      !Number.isFinite(daysSinceInsemination) ||
      daysSinceInsemination <
        MURABBIK_PREGNANCY_ULTRASOUND_DUE_DAYS
    ) {
      continue;
    }

    const item = {
      animalNumber,
      lastInseminationDate,
      daysSinceInsemination
    };

    if (
      daysSinceInsemination >=
        MURABBIK_PREGNANCY_MANUAL_DUE_DAYS
    ) {
      manualDue.push(item);
    } else {
      ultrasoundDue.push(item);
    }
  }

  const alerts = [];

  const ultrasoundAlert =
    murabbikPregnancyDiagnosisGroupedAlertSrv(
      ultrasoundDue,
      "ultrasound",
      context
    );

  if (ultrasoundAlert) {
    alerts.push(ultrasoundAlert);
  }

  const manualAlert =
    murabbikPregnancyDiagnosisGroupedAlertSrv(
      manualDue,
      "manual",
      context
    );

  if (manualAlert) {
    alerts.push(manualAlert);
  }

  return alerts;
}

murabbikSmartAlertRegisterSourceSrv(
  "pregnancy_diagnosis_due",
  murabbikPregnancyDiagnosisDueAlertSourceSrv
);
// ============================================================
//   SMART ALERT SOURCE: WEEKLY PREGNANCY CONFIRMATION — SATURDAY
//   دفعة أسبوعية لتأكيد الحمل يوم السبت حسب توقيت المزرعة
// ============================================================

const MURABBIK_PREGNANCY_CONFIRMATION_120_DUE_DAYS = 120;
const MURABBIK_PREGNANCY_CONFIRMATION_120_MAX_DAYS = 127;
const MURABBIK_PREGNANCY_CONFIRMATION_120_SNOOZE_MINUTES = 24 * 60;

const MURABBIK_PREGNANCY_CONFIRMATION_120_SOURCE_NAME =
  "pregnancy_confirmation_120_due";

const MURABBIK_PREGNANCY_CONFIRMATION_120_IDENTITY_PREFIX =
  "pregnancy-confirmation-120:weekly-saturday";

function murabbikPregnancyConfirmation120SaturdayOnOrAfterSrv(
  dateISO = ""
) {
  const date =
    String(dateISO || "")
      .trim()
      .slice(0, 10);

  if (!calvingIsDateSrv(date)) {
    return "";
  }

  const dayOfWeek =
    new Date(
      `${date}T00:00:00Z`
    ).getUTCDay();

  const daysUntilSaturday =
    (6 - dayOfWeek + 7) % 7;

  return addDaysToIsoDateSrv(
    date,
    daysUntilSaturday
  );
}

function murabbikPregnancyConfirmation120CurrentSaturdaySrv(
  todayISO = ""
) {
  const today =
    String(todayISO || "")
      .trim()
      .slice(0, 10);

  if (!calvingIsDateSrv(today)) {
    return "";
  }

  const dayOfWeek =
    new Date(
      `${today}T00:00:00Z`
    ).getUTCDay();

  const daysSinceSaturday =
    (dayOfWeek - 6 + 7) % 7;

  return addDaysToIsoDateSrv(
    today,
    -daysSinceSaturday
  );
}

function murabbikPregnancyConfirmation120AlertUrlSrv({
  numbers = [],
  eventDate = ""
} = {}) {
  const base =
    eventsPageBuildRedirectSrv({
      page: "pregnancy-diagnosis.html",
      numbers,
      eventDate
    });

  const separator =
    base.includes("?")
      ? "&"
      : "?";

  return (
    `${base}${separator}` +
    `checkType=${encodeURIComponent(
      "pregnancy_confirmation_120"
    )}` +
    `&pregnancyCheckType=${encodeURIComponent(
      "pregnancy_confirmation_120"
    )}`
  );
}

function murabbikPregnancyConfirmation120IsClosedSrv(
  doc = {},
  lastInseminationDate = ""
) {
  if (!calvingIsDateSrv(lastInseminationDate)) {
    return true;
  }

  const confirmationDate =
    murabbikPregnancyDiagnosisAlertDateSrv(
      doc.lastPregnancyConfirmation120Date ||
      ""
    );

  if (!confirmationDate) {
    return false;
  }

  const confirmationAfterService =
    calvingDaysBetweenSrv(
      lastInseminationDate,
      confirmationDate
    );

  return (
    Number.isFinite(confirmationAfterService) &&
    confirmationAfterService >= 0
  );
}

async function murabbikPregnancyConfirmation120AlertSourceSrv(
  context
) {
  const batchSaturday =
    murabbikPregnancyConfirmation120CurrentSaturdaySrv(
      context.today
    );

  if (!batchSaturday) {
    return [];
  }

  const animals =
    await murabbikSmartAlertAnimalsSrv(
      context
    );

  const due = [];

  for (const doc of animals) {
    const animalNumber =
      murabbikDryOffAlertNumberSrv(doc);

    const status =
      murabbikSmartAlertTextSrv(
        doc.status || "active"
      ).toLowerCase();

    if (!animalNumber) continue;

    if (
      ["inactive", "archived"]
        .includes(status)
    ) {
      continue;
    }

    if (
      murabbikSmartAlertTextSrv(
        doc.entryType
      ).toLowerCase() === "followers"
    ) {
      continue;
    }

    const reproductiveStatus =
      doc.reproductiveStatus ||
      doc.reproStatus ||
      "";

    if (
      !pregnancyDiagnosisIsPregnantStatusSrv(
        reproductiveStatus
      )
    ) {
      continue;
    }

    const lastInseminationDate =
      murabbikPregnancyDiagnosisAlertDateSrv(
        doc.lastInseminationDate ||
        doc.lastAI ||
        doc.lastInsemination ||
        doc.lastServiceDate ||
        ""
      );

    if (!lastInseminationDate) continue;

    if (
      murabbikPregnancyConfirmation120IsClosedSrv(
        doc,
        lastInseminationDate
      )
    ) {
      continue;
    }

    const confirmationDueDate =
      addDaysToIsoDateSrv(
        lastInseminationDate,
        MURABBIK_PREGNANCY_CONFIRMATION_120_DUE_DAYS
      );

    const animalBatchSaturday =
      murabbikPregnancyConfirmation120SaturdayOnOrAfterSrv(
        confirmationDueDate
      );

    if (
      animalBatchSaturday !==
      batchSaturday
    ) {
      continue;
    }

    const daysAtBatch =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        batchSaturday
      );

    if (
      !Number.isFinite(daysAtBatch) ||
      daysAtBatch <
        MURABBIK_PREGNANCY_CONFIRMATION_120_DUE_DAYS ||
      daysAtBatch >
        MURABBIK_PREGNANCY_CONFIRMATION_120_MAX_DAYS
    ) {
      continue;
    }

    const daysSinceInsemination =
      calvingDaysBetweenSrv(
        lastInseminationDate,
        context.today
      );

    due.push({
      animalNumber,
      lastInseminationDate,
      confirmationDueDate,
      batchSaturday,
      daysAtBatch,
      daysSinceInsemination
    });
  }

  if (!due.length) {
    return [];
  }

  const sorted =
    [...due].sort((a, b) =>
      b.daysAtBatch -
        a.daysAtBatch ||

      String(a.animalNumber).localeCompare(
        String(b.animalNumber),
        "ar",
        { numeric: true }
      )
    );

  const animalNumbers = [
    ...new Set(
      sorted
        .map(item => item.animalNumber)
        .filter(Boolean)
    )
  ];

  const count =
    animalNumbers.length;

  const evidence =
    sorted
      .slice(0, 12)
      .map(item =>
        `الحيوان ${item.animalNumber}: استحق التأكيد بتاريخ ${item.confirmationDueDate}، وآخر تلقيح ${item.lastInseminationDate}`
      );

  if (sorted.length > evidence.length) {
    evidence.push(
     `و${sorted.length - evidence.length} حيوان آخر مستحق لتأكيد الحمل.`
    );
  }

  const identityKey =
    `${MURABBIK_PREGNANCY_CONFIRMATION_120_IDENTITY_PREFIX}:${batchSaturday}`;

  return [{
    identityKey,

    revisionKey:
      batchSaturday,

    kind: "operational",
    domain: "reproduction",
    code: "pregnancy_confirmation_120_due",

    priority: "normal",
    urgency: "today",
    certainty: "confirmed",
    status: "due",

    title:
      count === 1
        ? "موعد تأكيد الحمل"
       : "حيوانات مستحقة لتأكيد الحمل",

   message:
  count === 1
    ? `الحيوان رقم ${animalNumbers[0]} مستحق لتأكيد استمرار الحمل.`
    : `يوجد ${count} حيوانات مستحقة لتأكيد استمرار الحمل.`,

    details: {
  observation:
  count === 1
    ? `الحيوان رقم ${animalNumbers[0]} مستحق لتأكيد الحمل.`
    : `أرقام الحيوانات: ${animalNumbers.join("، ")}.`,

      meaning:
        "تجميع تأكيدات الحمل أسبوعيًا يقلل الإزعاج ويساعد على تنفيذ الفحص في جلسة واحدة منظمة.",

      recommendation:
        "راجع الحيوانات المستحقة وسجّل نتيجة تأكيد الحمل، أو اختر التذكير لاحقًا إذا كنت ستنفذ الفحص ولم يتوفر الوقت الآن.",

      evidence
    },

    dueDate:
      batchSaturday,

    affectedCount:
      count,

    animalNumbers,

    action: {
      type: "navigate",
      label: "تسجيل تأكيد الحمل",

      url:
        murabbikPregnancyConfirmation120AlertUrlSrv({
          numbers: animalNumbers,
          eventDate: context.today
        })
    },

    snoozeMinutes:
      MURABBIK_PREGNANCY_CONFIRMATION_120_SNOOZE_MINUTES
  }];
}

murabbikSmartAlertRegisterSourceSrv(
  MURABBIK_PREGNANCY_CONFIRMATION_120_SOURCE_NAME,
  murabbikPregnancyConfirmation120AlertSourceSrv
);
// ============================================================
//       SMART ALERT SOURCE: UTERINE CHECK — DIM 14 / DIM 30
//       تنبيهات فحص الرحم حسب أيام الحليب فقط
// ============================================================

const MURABBIK_UTERINE_CHECK_DAY_14 = 14;
const MURABBIK_UTERINE_CHECK_DAY_30 = 30;
const MURABBIK_UTERINE_CHECK_WINDOW_DAYS = 3;
const MURABBIK_UTERINE_CHECK_SNOOZE_MINUTES = 24 * 60;

function murabbikUterineCheckDimSrv(doc = {}) {
  const raw = doc.daysInMilk;

  if (
    raw === null ||
    raw === undefined ||
    raw === ""
  ) {
    return null;
  }

  const dim = Number(raw);

  return (
    Number.isFinite(dim) &&
    Number.isInteger(dim) &&
    dim >= 0
  )
    ? dim
    : null;
}

function murabbikUterineCheckRecordedSrv(
  doc = {},
  stage = ""
) {
  if (stage === "day14") {
    return Boolean(
      murabbikSmartAlertTextSrv(
        doc.lastUterineCheck14Date
      ) ||
      murabbikSmartAlertTextSrv(
        doc.lastUterineCheck14EventId
      )
    );
  }

  if (stage === "day30") {
    return Boolean(
      murabbikSmartAlertTextSrv(
        doc.lastUterineCheck30Date
      ) ||
      murabbikSmartAlertTextSrv(
        doc.lastUterineCheck30EventId
      )
    );
  }

  return false;
}

function murabbikUterineCheckCycleKeySrv(doc = {}) {
  const raw = doc.lactationNumber;

  if (
    raw === null ||
    raw === undefined ||
    raw === ""
  ) {
    return "";
  }

  const lactationNumber = Number(raw);

  return (
    Number.isInteger(lactationNumber) &&
    lactationNumber > 0
  )
    ? `lactation-${lactationNumber}`
    : "";
}

async function murabbikUterineCheckAlertSourceSrv(
  context
) {
  const animals =
    await murabbikSmartAlertAnimalsSrv(
      context
    );

  const alerts = [];

  for (const doc of animals) {
    const animalNumber =
      murabbikDryOffAlertNumberSrv(doc);

    const status =
      murabbikSmartAlertTextSrv(
        doc.status
      ).toLowerCase();

    const productionStatus =
      murabbikSmartAlertTextSrv(
        doc.productionStatus
      ).toLowerCase();

    if (!animalNumber) continue;

    if (status !== "active") {
      continue;
    }

    if (
      uterineCheckIsFollowerSrv(doc)
    ) {
      continue;
    }

    if (
      doc.inMilk === false ||
      ["dry", "جاف"]
        .includes(productionStatus)
    ) {
      continue;
    }

    const daysInMilk =
      murabbikUterineCheckDimSrv(doc);

    if (daysInMilk === null) continue;

    const day14Window =
      daysInMilk >=
        MURABBIK_UTERINE_CHECK_DAY_14 &&
      daysInMilk <
        MURABBIK_UTERINE_CHECK_DAY_14 +
        MURABBIK_UTERINE_CHECK_WINDOW_DAYS;

    const day30Window =
      daysInMilk >=
        MURABBIK_UTERINE_CHECK_DAY_30 &&
      daysInMilk <
        MURABBIK_UTERINE_CHECK_DAY_30 +
        MURABBIK_UTERINE_CHECK_WINDOW_DAYS;

    if (!day14Window && !day30Window) {
      continue;
    }

    const day14Recorded =
      murabbikUterineCheckRecordedSrv(
        doc,
        "day14"
      );

    const day30Recorded =
      murabbikUterineCheckRecordedSrv(
        doc,
        "day30"
      );

    const day14ResultOption =
      day14Recorded
        ? uterineCheckResultSrv(
            doc.lastUterineCheck14Result
          )
        : null;

    const cycleKey =
      murabbikUterineCheckCycleKeySrv(doc);

    if (!cycleKey) continue;

    if (day14Window) {
      if (day14Recorded) continue;

      alerts.push({
        identityKey:
          `uterine-check-day14:${animalNumber}:${cycleKey}`,

        revisionKey:
          `${animalNumber}:${cycleKey}:day14`,

        kind: "operational",
        domain: "health",
        code: "uterine_check_day_14_due",

        priority: "normal",
        urgency: "today",
        certainty: "confirmed",
        status: "due",

       title:
  "تذكير بفحص الرحم الأولي",

message:
  `الحيوان رقم ${animalNumber} عند ${daysInMilk} يومًا في الحليب، وهذا توقيت مناسب للاطمئنان على تعافي الرحم بعد الولادة.`,

details: {
  observation:
    "لا توجد نتيجة فحص رحم أولي مسجّلة لهذه الدورة.",

  meaning:
    "هذا تذكير استشاري خلال نافذة قصيرة، ولا يفرض إجراء الفحص ولا يمنع أي إجراء آخر.",

  recommendation:
    "يمكن تسجيل نتيجة الفحص إذا تم إجراؤه، أو اختيار «حسنًا» دون أي التزام.",

          evidence: [
            `رقم الحيوان: ${animalNumber}`,
            `أيام الحليب: ${daysInMilk}`,
            "فحص اليوم 14: غير مسجّل"
          ]
        },

        dueDate: context.today,
        affectedCount: 1,
        animalNumbers: [
          animalNumber
        ],

        action: {
          type: "navigate",
          label: "تسجيل فحص الرحم",
          url:
            `uterine-check.html?number=${encodeURIComponent(animalNumber)}&eventDate=${encodeURIComponent(context.today)}`
        },

snoozeMinutes:
  MURABBIK_UTERINE_CHECK_SNOOZE_MINUTES
      });

      continue;
    }

    if (day30Recorded) continue;

    if (
      day14Recorded &&
      !day14ResultOption
    ) {
      continue;
    }

    if (
      day14ResultOption?.value ===
      "normal"
    ) {
      continue;
    }

    const initialMissing =
      !day14Recorded;

    alerts.push({
      identityKey:
        `uterine-check-day30:${animalNumber}:${cycleKey}`,

      revisionKey:
        `${animalNumber}:${cycleKey}:day30`,

      kind: "operational",
      domain: "health",
      code: "uterine_check_day_30_followup",

      priority: "normal",
      urgency: "today",

      certainty:
        initialMissing
          ? "data_gap"
          : "confirmed",

      status: "due",

     title:
  "تذكير بمتابعة فحص الرحم",

message:
  initialMissing
    ? `الحيوان رقم ${animalNumber} عند ${daysInMilk} يومًا في الحليب، وهذه نافذة مناسبة لمتابعة الرحم بعد الولادة، مع عدم وجود نتيجة فحص أولي مسجّلة.`
    : `الحيوان رقم ${animalNumber} عند ${daysInMilk} يومًا في الحليب، وكانت نتيجة الفحص الأولي: ${day14ResultOption.label}، وهذه نافذة مناسبة للمتابعة عند الحاجة.`,

details: {
  observation:
    initialMissing
      ? "لا توجد نتيجة للفحص الأولي أو المتابعة مسجّلة لهذه الدورة."
      : `نتيجة الفحص الأولي: ${day14ResultOption.label}، ولا توجد نتيجة متابعة مسجّلة.`,

  meaning:
    "هذا تذكير استشاري خلال نافذة قصيرة، ولا يفرض إجراء المتابعة ولا يمنع أي إجراء آخر.",

  recommendation:
    "يمكن تسجيل فحص المتابعة إذا تم إجراؤه، أو اختيار «حسنًا» دون أي التزام.",
        evidence: [
          `رقم الحيوان: ${animalNumber}`,
          `أيام الحليب: ${daysInMilk}`,

          initialMissing
            ? "فحص اليوم 14: غير مسجّل"
            : `فحص اليوم 14: ${day14ResultOption.label}`,

          "فحص اليوم 30: غير مسجّل"
        ]
      },

      dueDate: context.today,
      affectedCount: 1,
      animalNumbers: [
        animalNumber
      ],

      action: {
        type: "navigate",
        label: "تسجيل فحص المتابعة",
        url:
          `uterine-check.html?number=${encodeURIComponent(animalNumber)}&eventDate=${encodeURIComponent(context.today)}`
      },

snoozeMinutes:
  MURABBIK_UTERINE_CHECK_SNOOZE_MINUTES
    });
  }

  return alerts;
}

murabbikSmartAlertRegisterSourceSrv(
  "uterine_check_followup",
  murabbikUterineCheckAlertSourceSrv
);
// ============================================================
//   SMART ALERT SOURCE: POSTPARTUM INSEMINATION FOLLOW-UP
//   متابعة التلقيح بعد الولادة
// ============================================================

const MURABBIK_POSTPARTUM_AI_COW_DAYS = 60;
const MURABBIK_POSTPARTUM_AI_BUFFALO_DAYS = 45;
const MURABBIK_POSTPARTUM_AI_HEAT_CYCLE_MIN_DAYS = 18;
const MURABBIK_POSTPARTUM_AI_HEAT_CYCLE_MAX_DAYS = 25;
const MURABBIK_POSTPARTUM_AI_SNOOZE_MINUTES = 24 * 60;

function murabbikPostpartumAiIsCulledSrv(doc = {}) {
  const cullStatus = murabbikSmartAlertTextSrv(
    doc.cullStatus
  ).toLowerCase();

  const repro = calvingStripArSrv(
    String(
      doc.reproductiveStatus ||
      doc.reproStatus ||
      ""
    )
      .replace(/[أإآ]/g, "ا")
      .replace(/ة/g, "ه")
      .replace(/ى/g, "ي")
  );

  return (
    doc.breedingBlocked === true ||
    cullStatus === "excluded" ||
    cullStatus.includes("استبعاد") ||
    repro.includes("لاتلقح") ||
    repro.includes("استبعاد")
  );
}

async function murabbikPostpartumAiAlertSourceSrv(context) {
  const animals =
    await murabbikSmartAlertAnimalsSrv(
      context
    );

  const rows = [];

  for (const doc of animals) {
    const animalNumber =
      murabbikDryOffAlertNumberSrv(
        doc
      );

    const status =
      murabbikSmartAlertTextSrv(
        doc.status || "active"
      ).toLowerCase();

    if (!animalNumber) continue;

    if (
      ["inactive", "archived"]
        .includes(status)
    ) {
      continue;
    }

    if (
      murabbikSmartAlertTextSrv(
        doc.entryType
      ).toLowerCase() === "followers"
    ) {
      continue;
    }

    if (
      murabbikPostpartumAiIsCulledSrv(
        doc
      )
    ) {
      continue;
    }

    const reproductiveStatus =
      doc.reproductiveStatus ||
      doc.reproStatus ||
      "";

    if (
      pregnancyDiagnosisIsInseminatedStatusSrv(
        reproductiveStatus
      ) ||
      pregnancyDiagnosisIsPregnantStatusSrv(
        reproductiveStatus
      )
    ) {
      continue;
    }

    const reproNorm =
      calvingStripArSrv(
        reproductiveStatus
      );

    const isOpen =
      reproNorm.includes("مفتوح") ||
      reproNorm.includes("فارغ");

    // لا نعرض الحيوان إذا دخل فعلًا
    // في برنامج تزامن نشط.
    if (
      ovsynchActiveProtocolBlockMessageSrv(
        doc,
        context.today
      )
    ) {
      continue;
    }

    const species =
      murabbikCalvingOverdueSpeciesSrv(
        doc
      );

    if (!species) continue;

    const dueDays =
      species.key === "buffalo"
        ? MURABBIK_POSTPARTUM_AI_BUFFALO_DAYS
        : MURABBIK_POSTPARTUM_AI_COW_DAYS;

    const lastCalvingDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastCalvingDate ||
        doc.calvingDate ||
        doc.lastCalving
      );

    const daysPostpartum =
      lastCalvingDate
        ? calvingDaysBetweenSrv(
            lastCalvingDate,
            context.today
          )
        : null;

    const lastInseminationDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastInseminationDate ||
        doc.lastAI ||
        doc.lastInsemination ||
        doc.lastServiceDate
      );

    const lastDiagnosisDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastPregnancyDiagnosisDate ||
        doc.lastDiagnosisDate
      );

    const lastDiagnosisResult =
      normalizePregnancyResultSrv(
        doc.lastPregnancyDiagnosisResult ||
        ""
      );

    const lastDiagnosisCheckType =
      murabbikSmartAlertTextSrv(
        doc.lastPregnancyDiagnosisCheckType
      );

    const lastConfirmationDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastPregnancyConfirmation120Date
      );

    const lastConfirmationResult =
      murabbikSmartAlertTextSrv(
        doc.lastPregnancyConfirmation120Result
      ).toLowerCase();

    const lastAbortionDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastAbortionDate ||
        doc.abortionDate
      );

    const diagnosisAfterService =
      lastInseminationDate &&
      lastDiagnosisDate
        ? calvingDaysBetweenSrv(
            lastInseminationDate,
            lastDiagnosisDate
          )
        : null;

    const pregnancyEndedAfterService =
      Boolean(
        lastInseminationDate &&
        (
          (
            lastCalvingDate &&
            lastCalvingDate >
              lastInseminationDate
          ) ||
          (
            lastAbortionDate &&
            lastAbortionDate >
              lastInseminationDate
          )
        )
      );

    const hasExplicitDiagnosisResult =
      Boolean(
        murabbikSmartAlertTextSrv(
          doc.lastPregnancyDiagnosisResult
        )
      );

  const followupDecision =
  murabbikSmartAlertTextSrv(
    doc.pregnancyDiagnosisFollowupDecision
  ).toLowerCase();

const followupDecisionEventId =
  murabbikSmartAlertTextSrv(
    doc.pregnancyDiagnosisFollowupDecisionEventId
  );

const lastDiagnosisEventId =
  murabbikSmartAlertTextSrv(
    doc.lastPregnancyDiagnosisEventId
  );

const isCurrentInitialNegative =
  isOpen &&
  lastDiagnosisResult === "فارغة" &&
  Number.isFinite(
    diagnosisAfterService
  ) &&
  diagnosisAfterService >= 0 &&
  !pregnancyEndedAfterService;

const diagnosedEmpty =
  isCurrentInitialNegative &&
  followupDecision === "later" &&
  Boolean(
    followupDecisionEventId &&
    lastDiagnosisEventId &&
    followupDecisionEventId ===
      lastDiagnosisEventId
  );
    let reasonType = "";
    let reasonDate = "";
    let followupAgeDays = null;

    if (diagnosedEmpty) {
      const daysSinceDiagnosis =
        calvingDaysBetweenSrv(
          lastDiagnosisDate,
          context.today
        );

      if (
        !Number.isFinite(
          daysSinceDiagnosis
        ) ||
        daysSinceDiagnosis < 0
      ) {
        continue;
      }

      reasonType =
        "pregnancy_diagnosis_negative";

      reasonDate =
        lastDiagnosisDate;

      followupAgeDays =
        daysSinceDiagnosis;

    } else {
      if (!lastCalvingDate) continue;

      if (
        !Number.isFinite(
          daysPostpartum
        ) ||
        daysPostpartum < dueDays
      ) {
        continue;
      }

      // وجود تلقيح بعد الولادة يخرج الحيوان
      // من مسار التأخر بعد الولادة.
      if (
        lastInseminationDate &&
        lastInseminationDate >=
          lastCalvingDate
      ) {
        continue;
      }

      reasonType =
        "postpartum_not_inseminated";

      reasonDate =
        lastCalvingDate;

      followupAgeDays =
        daysPostpartum - dueDays;
    }

    const lastHeatDate =
      murabbikCalvingOverdueDateSrv(
        doc.lastHeatDate ||
        doc.heatDate ||
        doc.lastEstrusDate
      );

    let daysSinceHeat = null;
    let validHeatAfterReason = "";

    if (
      lastHeatDate &&
      reasonDate &&
      lastHeatDate >= reasonDate
    ) {
      validHeatAfterReason =
        lastHeatDate;

      daysSinceHeat =
        calvingDaysBetweenSrv(
          lastHeatDate,
          context.today
        );

      // من يوم تسجيل الشياع حتى نهاية اليوم 25:
      // الحيوان داخل دورة شياع قائمة أو نافذة رجوع،
      // فلا يظهر تنبيه المتابعة.
      if (
        Number.isFinite(
          daysSinceHeat
        ) &&
        daysSinceHeat >= 0 &&
        daysSinceHeat <=
          MURABBIK_POSTPARTUM_AI_HEAT_CYCLE_MAX_DAYS
      ) {
        continue;
      }
    }

    rows.push({
      animalNumber,
      reasonType,
      reasonDate,
      followupAgeDays,

      dueDays,
      lastCalvingDate,
      daysPostpartum:
        Number.isFinite(daysPostpartum)
          ? daysPostpartum
          : null,

      lastInseminationDate,
      lastDiagnosisDate,

      lastHeatDate:
        validHeatAfterReason,

      daysSinceHeat:
        Number.isFinite(
          daysSinceHeat
        )
          ? daysSinceHeat
          : null
    });
  }

  if (!rows.length) {
    return [];
  }

  rows.sort(
    (a, b) =>
      b.followupAgeDays -
        a.followupAgeDays ||

      String(
        a.animalNumber
      ).localeCompare(
        String(
          b.animalNumber
        ),
        "ar",
        {
          numeric: true
        }
      )
  );

  const animalNumbers = [
    ...new Set(
      rows.map(
        row =>
          row.animalNumber
      )
    )
  ];

  const count =
    animalNumbers.length;

  const postpartumCount =
    rows.filter(
      row =>
        row.reasonType ===
          "postpartum_not_inseminated"
    ).length;

  const diagnosisNegativeCount =
    rows.filter(
      row =>
        row.reasonType ===
          "pregnancy_diagnosis_negative"
    ).length;

  const single =
    rows[0];

  const revisionKey =
    [...rows]
      .sort(
        (a, b) =>
          String(
            a.animalNumber
          ).localeCompare(
            String(
              b.animalNumber
            ),
            "ar",
            {
              numeric: true
            }
          )
      )
      .map(row =>
        [
          row.animalNumber,
          row.reasonType,
          row.reasonDate,
          row.lastHeatDate ||
            "no_heat"
        ].join(":")
      )
      .join("|");

  const evidence =
    rows
      .slice(0, 12)
      .map(row => {
        if (
          row.reasonType ===
            "pregnancy_diagnosis_negative"
        ) {
          const heatText =
            row.lastHeatDate &&
            Number.isFinite(
              row.daysSinceHeat
            )
              ? `، وآخر شياع مسجّل منذ ${row.daysSinceHeat} يومًا`
              : "";

          return (
            `الحيوان ${row.animalNumber}: ` +
            `ثبت أنه فارغ في تشخيص الحمل بتاريخ ${row.lastDiagnosisDate}` +
            (
              row.lastInseminationDate
                ? ` بعد آخر تلقيح بتاريخ ${row.lastInseminationDate}`
                : ""
            ) +
            `${heatText}.`
          );
        }

        return (
          row.lastHeatDate &&
          Number.isFinite(
            row.daysSinceHeat
          )
            ? (
                `الحيوان ${row.animalNumber}: ` +
                `${row.daysPostpartum} يومًا بعد الولادة، ` +
                `وآخر شياع مسجّل منذ ${row.daysSinceHeat} يومًا.`
              )
            : (
                `الحيوان ${row.animalNumber}: ` +
                `${row.daysPostpartum} يومًا بعد الولادة، ` +
                `ولم يُلقّح ولم تُسجّل له دورة شياع جارية.`
              )
        );
      });

  if (
    rows.length >
      evidence.length
  ) {
    evidence.push(
      `و${rows.length - evidence.length} حيوان آخر.`
    );
  }

const postpartumNumbers =
  rows
    .filter(
      row =>
        row.reasonType ===
        "postpartum_not_inseminated"
    )
    .map(
      row =>
        row.animalNumber
    )
    .sort((a, b) =>
      String(a).localeCompare(
        String(b),
        "ar",
        { numeric: true }
      )
    );

const diagnosisNegativeNumbers =
  rows
    .filter(
      row =>
        row.reasonType ===
        "pregnancy_diagnosis_negative"
    )
    .map(
      row =>
        row.animalNumber
    )
    .sort((a, b) =>
      String(a).localeCompare(
        String(b),
        "ar",
        { numeric: true }
      )
    );
let message = "";

if (count === 1) {
  if (
    single.reasonType ===
      "pregnancy_diagnosis_negative"
  ) {
    message =
      `لديك حيوان مفتوح يحتاج المتابعة لتلقيحه. ` +
      `الحيوان رقم ${single.animalNumber} ثبت أنه فارغ في تشخيص الحمل، ` +
      `ولم يبدأ له تلقيح جديد أو برنامج تزامن.`;

  } else if (
    single.lastHeatDate &&
    Number.isFinite(
      single.daysSinceHeat
    )
  ) {
    message =
      `لديك حيوان مفتوح يحتاج المتابعة لتلقيحه. ` +
      `الحيوان رقم ${single.animalNumber} تخطّى فترة الانتظار بعد الولادة دون تلقيح، ` +
      `ومرّ ${single.daysSinceHeat} يومًا على آخر شياع مسجّل.`;

  } else {
    message =
      `لديك حيوان مفتوح يحتاج المتابعة لتلقيحه. ` +
      `الحيوان رقم ${single.animalNumber} تخطّى فترة الانتظار بعد الولادة ` +
      `دون تسجيل تلقيح أو شياع.`;
  }

} else {
  const messageParts = [
    `لديك ${count} حيوانات مفتوحة تحتاج المتابعة لتلقيحها.`
  ];

  if (
    postpartumNumbers.length > 0
  ) {
    messageParts.push(
      postpartumNumbers.length === 1
        ? "تخطّى حيوان واحد فترة الانتظار بعد الولادة دون تسجيل تلقيح أو شياع."
        : `تخطّت ${postpartumNumbers.length} حيوانات فترة الانتظار بعد الولادة دون تسجيل تلقيح أو شياع.`,

      `${postpartumNumbers.length === 1 ? "الرقم" : "الأرقام"}: ` +
      `${postpartumNumbers.join("، ")}.`
    );
  }

  if (
    diagnosisNegativeNumbers.length > 0
  ) {
    messageParts.push(
      diagnosisNegativeNumbers.length === 1
        ? "ثبت أن حيوانًا واحدًا فارغ في تشخيص الحمل."
        : `ثبت أن ${diagnosisNegativeNumbers.length} حيوانات فارغة في تشخيص الحمل.`,

      `${diagnosisNegativeNumbers.length === 1 ? "الرقم" : "الأرقام"}: ` +
      `${diagnosisNegativeNumbers.join("، ")}.`
    );
  }

  message =
    messageParts.join("\n");
}
  const joinedNumbers =
    animalNumbers.join(",");

  return [{
    identityKey:
      "postpartum-insemination-followup",

    revisionKey,

    kind:
      "operational",

    domain:
      "reproduction",

    code:
      "postpartum_insemination_followup",

    priority:
      "normal",

    urgency:
      "today",

    certainty:
      "confirmed",

    status:
      "due",

    title:
      "متابعة تلقيح الحيوانات المفتوحة",

    message,

    details: {
     observation: "",

      meaning:
        "يجمع هذا التنبيه الحيوانات المفتوحة التي تأخر تلقيحها بعد الولادة، أو ثبتت فارغة بعد تشخيص الحمل.",

      recommendation:
        count === 1
          ? "راجع الحيوان، ويمكن إدخاله في برنامج التزامن إذا كان مناسبًا."
          : "راجع الحيوانات، وأدخل المناسب منها في برنامج التزامن.",

      evidence
    },

    dueDate:
      context.today,

    affectedCount:
      count,

    animalNumbers,

    action: {
      type:
        "navigate",

      label:
        "دخول برنامج تزامن",

      url:
        `ovysynch.html?mbkMode=group` +
        `&numbers=${encodeURIComponent(joinedNumbers)}` +
        `&bulk=${encodeURIComponent(joinedNumbers)}` +
        `&date=${encodeURIComponent(context.today)}`
    },

    snoozeMinutes:
      MURABBIK_POSTPARTUM_AI_SNOOZE_MINUTES
  }];
}
murabbikSmartAlertRegisterSourceSrv(
  "postpartum_insemination_followup",
  murabbikPostpartumAiAlertSourceSrv
);
// ============================================================
//       SMART ALERT SOURCE: VACCINATION PROGRAM TASKS
//       التحصين من نفس حاسب البيانات المستخدم في الراوت القائم
// ============================================================

const MURABBIK_VACCINATION_SMART_ALERT_STATUS = {
  overdue: {
    priority: "high",
    urgency: "today",
    certainty: "confirmed",
    snoozeMinutes: 6 * 60
  },

  due: {
    priority: "normal",
    urgency: "today",
    certainty: "confirmed",
    snoozeMinutes: 12 * 60
  },

  upcoming: {
    priority: "low",
    urgency: "soon",
    certainty: "confirmed",
    snoozeMinutes: 24 * 60
  },
   initial_age_ready: {
    priority: "normal",
    urgency: "soon",
    certainty: "confirmed",
    snoozeMinutes: 12 * 60
  },
  needs_data: {
    priority: "normal",
    urgency: "review",
    certainty: "data_gap",
    snoozeMinutes: 24 * 60
  }
};

async function murabbikVaccinationProgramAlertSourceSrv(
  context
) {
  const payload = await context.load(
    "smart-alerts:vaccination-dashboard-data",

    async () =>
      await vaccinationDashboardAlertsDataSrv({
        userId: context.userId,
        profileUid: context.profileUid
      })
  );

  return (
    Array.isArray(payload.alerts)
      ? payload.alerts
      : []
  ).map(alert => {
       const status =
      murabbikSmartAlertTextSrv(
        alert.status
      ).toLowerCase();

    const alertKind =
      murabbikSmartAlertTextSrv(
        alert.alertKind
      );

    const isInitialAge =
      status === "initial_age_ready" ||
      alertKind ===
        "vaccination_initial_age";

    const isInitialMaternal =
      alertKind ===
        "vaccination_initial_maternal";
    const policy =
      MURABBIK_VACCINATION_SMART_ALERT_STATUS[
        status
      ] ||
      MURABBIK_VACCINATION_SMART_ALERT_STATUS.needs_data;

    const animalNumbers = [
      ...new Set(
        (
          Array.isArray(alert.animalNumbers)
            ? alert.animalNumbers
            : []
        )
          .map(calvingNormDigitsOnlySrv)
          .filter(Boolean)
      )
    ].sort((a, b) => Number(a) - Number(b));

    const cleanText = value =>
      murabbikSmartAlertTextSrv(value)
        .replace(/[🚨⏰📌⚠️]/gu, "")
        .trim();

    const identityKey = [
      "vaccination",
      alert.programMode || "program",

      alert.programRowId ||
        alert.vaccineCode ||
        alert.vaccine ||
        "row",

              isInitialAge
        ? "age_ready"
        : isInitialMaternal
          ? "maternal_group"
          : alert.dueDate ||
            alert.attentionCode ||
            "attention",

      alert.doseType || "dose"
    ].join(":");

    return {
      identityKey,

      revisionKey: [
        identityKey,
        status,
        alert.windowEnd || "",
        alert.requiredField || "",
        animalNumbers.join(",")
      ].join(":"),

      kind: "operational",
      domain: "health",

             code:
        isInitialAge
          ? "vaccination_initial_age_ready"
          : isInitialMaternal
            ? `vaccination_initial_maternal_${status || "review"}`
            : `vaccination_program_${status || "review"}`,

      priority:
        policy.priority,

      urgency:
        policy.urgency,

      certainty:
        policy.certainty,

      status:
        status || "needs_data",

      title:
        cleanText(alert.title),

      message:
        cleanText(alert.message),

            details: {
              observation:
          isInitialAge || isInitialMaternal
            ? ""
            : cleanText(alert.message),

              meaning:
          isInitialAge
            ? "الحيوان داخل النطاق العمري المناسب لبدء الجرعة التأسيسية حسب برنامج التحصينات النشط. هذا تنبيه ذكي وليس مهمة مجدولة."
            : isInitialMaternal
              ? "الأم دخلت توقيت الجرعة المحددة قبل الولادة حسب برنامج التحصينات النشط. هذا أول تنبيه في دورة الحمل الحالية وليس مهمة مبنية على جرعة سابقة."
              : status === "needs_data"
                ? "لا يمكن حساب الموعد التالي بصورة موثوقة قبل استكمال بيانات التحصين المطلوبة."
                : "التنبيه صادر من المهمة الحالية التي أنشأها برنامج التحصينات المعتمد.",

        recommendation:
          isInitialAge
            ? "سجّل الجرعة التأسيسية عند تنفيذها فعليًا، وبعد الحفظ سيحسب مُرَبِّيك الجرعة التالية من البرنامج."
            : isInitialMaternal
              ? "سجّل جرعة ما قبل الولادة عند تنفيذها فعليًا؛ وبعد الحفظ يُغلق التنبيه وتُحسب أي جرعة تالية يحددها البرنامج."
              : status === "upcoming"
                ? "راجع البرنامج واستعد للتنفيذ في موعده، ولا تسجّل الجرعة قبل إعطائها فعليًا."
                : status === "needs_data"
                  ? "راجع بيانات البرنامج والحيوان ثم أكمل الحقل المطلوب."
                  : "سجّل التنفيذ الفعلي عند إعطاء التحصين حتى تُغلق المهمة ويُحسب الموعد التالي.",
        evidence: [
          alert.vaccine
            ? `التحصين: ${alert.vaccine}`
            : "",

          alert.doseTypeLabel
            ? `نوع الجرعة: ${alert.doseTypeLabel}`
            : "",

                   !isInitialAge &&
          alert.dueDate
            ? `الموعد: ${alert.dueDate}`
            : "",
                    isInitialMaternal &&
          alert.expectedCalvingDate
            ? `الولادة المتوقعة: ${alert.expectedCalvingDate}`
            : "",
          animalNumbers.length
            ? `الحيوانات: ${animalNumbers.join("، ")}`
            : ""
        ].filter(Boolean)
      },

 dueDate:
  isInitialAge ||
  (
    isInitialMaternal &&
    animalNumbers.length > 1
  )
    ? ""
    : cleanText(
        alert.dueDate ||
        context.today
      ).slice(0, 10),

      affectedCount:
        Number(alert.count) ||
        animalNumbers.length,

      animalNumbers,

      action: {
        type: "navigate",

        label:
          cleanText(
            alert.actionText ||
            "فتح صفحة التحصين"
          ),

        url:
          cleanText(
            alert.actionUrl ||
            "vaccination.html"
          )
      },

      snoozeMinutes:
        policy.snoozeMinutes
    };
  });
}

murabbikSmartAlertRegisterSourceSrv(
  "vaccination_program_tasks",
  murabbikVaccinationProgramAlertSourceSrv
);
// SMART ALERT SOURCE: OVSYNCH STEPS — موعد باليوم والساعة
// يظهر من ساعتين قبل الموعد حتى ساعتين بعده، و«ذكّرني لاحقًا» = 30 دقيقة
// ============================================================
const MURABBIK_OVSYNCH_ALERT_LEAD_MINUTES = 120;
const MURABBIK_OVSYNCH_ALERT_GRACE_MINUTES = 120;
const MURABBIK_OVSYNCH_ALERT_SNOOZE_MINUTES = 30;

function murabbikOvsynchAlertTimeSrv(value) {
  const m = String(value || "").trim().match(/^(\d{1,2}):(\d{2})/);
  if (!m) return "08:00";

  const hour = Number(m[1]);
  const minute = Number(m[2]);

  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) {
    return "08:00";
  }

  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

function murabbikOvsynchAlertDateTimeMsSrv(dateISO, timeText, timeZone) {
  const date = String(dateISO || "").trim().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return NaN;

  const time = murabbikOvsynchAlertTimeSrv(timeText);
  const [year, month, day] = date.split("-").map(Number);
  const [hour, minute] = time.split(":").map(Number);

  const wallMs = Date.UTC(
    year,
    month - 1,
    day,
    hour,
    minute,
    0,
    0
  );

  const zone =
    String(timeZone || "UTC").trim() ||
    "UTC";

  try {
    const formatter = new Intl.DateTimeFormat(
      "en-CA",
      {
        timeZone: zone,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hourCycle: "h23"
      }
    );

    const offsetAt = instantMs => {
      const parts = Object.fromEntries(
        formatter
          .formatToParts(new Date(instantMs))
          .filter(part => part.type !== "literal")
          .map(part => [part.type, part.value])
      );

      return Date.UTC(
        Number(parts.year),
        Number(parts.month) - 1,
        Number(parts.day),
        Number(parts.hour),
        Number(parts.minute),
        Number(parts.second)
      ) - instantMs;
    };

    let instantMs = wallMs;

    instantMs =
      wallMs -
      offsetAt(instantMs);

    instantMs =
      wallMs -
      offsetAt(instantMs);

    return instantMs;

  } catch (_) {
    return wallMs;
  }
}

async function murabbikOvsynchStepSmartAlertSourceSrv(context) {
  const yesterday =
    addDaysToIsoDateSrv(
      context.today,
      -1
    );

  const tomorrow =
    addDaysToIsoDateSrv(
      context.today,
      1
    );

  const farmClock = await context.load(
    "smart-alerts:farm-time-context",
    () =>
      farmTimeContextSrv(
        context.profileUid
      )
  );

  const farmTimeZone =
    String(
      farmClock?.timeZone ||
      "UTC"
    ).trim() ||
    "UTC";

  const snap = await context.load(
    "smart-alerts:ovsynch-pending-tasks",
    () =>
      db
        .collection("tasks")
        .where("userId", "==", context.userId)
        .where("status", "==", "pending")
        .limit(500)
        .get()
  );

  const groups = new Map();

  snap.forEach(docSnap => {
    const task = docSnap.data() || {};

    const isOvsynchTask =
      String(task.taskType || "").trim() === "ovsynch_step" ||
      String(task.type || "").trim() === "ovsynch_step" ||
      (
        String(task.type || "").trim() === "protocol_step" &&
        String(task.protocol || "").trim() === "ovsynch"
      );

    if (!isOvsynchTask) return;

    const dueDate = String(
      task.dueDate ||
      task.plannedDate ||
      ""
    )
      .trim()
      .slice(0, 10);

      if (
      dueDate !== yesterday &&
      dueDate !== context.today &&
      dueDate !== tomorrow
    ) {
      return;
    }

    const plannedTime =
      murabbikOvsynchAlertTimeSrv(
        task.plannedTime ||
        String(
          task.plannedDateTime ||
          ""
        ).slice(11, 16)
      );

    const dueAtMs =
      murabbikOvsynchAlertDateTimeMsSrv(
        dueDate,
        plannedTime,
        farmTimeZone
      );

    if (!Number.isFinite(dueAtMs)) {
      return;
    }

    const visibleFromMs =
      dueAtMs -
      (
        MURABBIK_OVSYNCH_ALERT_LEAD_MINUTES *
        60 *
        1000
      );

    const visibleUntilMs =
      dueAtMs +
      (
        MURABBIK_OVSYNCH_ALERT_GRACE_MINUTES *
        60 *
        1000
      );

    const isDayBefore =
      dueDate === tomorrow &&
      context.nowMs < visibleFromMs;

    const isDueWindow =
      context.nowMs >= visibleFromMs &&
      context.nowMs <= visibleUntilMs;
    if (!isDayBefore && !isDueWindow) {
      return;
    }

    const alertPhase =
      isDueWindow
        ? "due_window"
        : "day_before";

    const animalNumber =
      calvingNormDigitsOnlySrv(
        task.animalNumber ||
        task.number ||
        ""
      );

    if (!animalNumber) return;

    const stepIndex =
      Number(task.stepIndex ?? 0) ||
      0;

    const stepDay =
      Number(task.stepDay ?? 0) ||
      0;

    const stepName = String(
      task.stepName ||
      task.title ||
      "خطوة التزامن"
    ).trim();

    const program = String(
      task.program ||
      task.protocolProgram ||
      "ovsynch"
    ).trim();

    const protocolStartDate = String(
      task.protocolStartDate ||
      ""
    )
      .trim()
      .slice(0, 10);

    const key = [
      alertPhase,
      dueDate,
      plannedTime,
      program,
      protocolStartDate,
      stepIndex,
      stepDay,
      stepName
    ].join("__");

    if (!groups.has(key)) {
      groups.set(key, {
        alertPhase,
        dueDate,
        plannedTime,
        dueAtMs,
        program,
        protocolStartDate,
        stepIndex,
        stepDay,
        stepName,
        animalNumbers: []
      });
    }

    groups
      .get(key)
      .animalNumbers
      .push(animalNumber);
  });

  const alerts = [];

  for (const group of groups.values()) {
    const animalNumbers = [
      ...new Set(group.animalNumbers)
    ]
      .filter(Boolean)
      .sort(
        (a, b) =>
          (Number(a) - Number(b)) ||
          String(a).localeCompare(
            String(b)
          )
      );

    if (!animalNumbers.length) continue;

       const isDueWindow =
      group.alertPhase === "due_window";

    const title =
      isDueWindow
        ? "خطوة برنامج التزامن اليوم"
        : "خطوة برنامج التزامن غدًا";

    const prefix =
      isDueWindow
        ? "⏰ اليوم"
        : "📌 غدًا";
    const message =
      `${prefix} خطوة برنامج التزامن: ${group.stepName}\n` +
      `للحيوانات أرقام: ${animalNumbers.join("، ")}\n` +
      `الموعد: ${group.plannedTime}`;

    const actionUrl =
      `ovysynch.html?mode=step` +
      `&date=${encodeURIComponent(group.dueDate)}` +
      `&dueDate=${encodeURIComponent(group.dueDate)}` +
      `&stepIndex=${encodeURIComponent(group.stepIndex)}` +
      `&program=${encodeURIComponent(group.program)}` +
      `&protocolStartDate=${encodeURIComponent(group.protocolStartDate || "")}`;

    const identityKey = [
      "ovsynch_step",
      group.alertPhase,
      group.dueDate,
      group.plannedTime,
      group.program,
      group.protocolStartDate || "no_start",
      group.stepIndex,
      group.stepDay
    ].join("|");

    alerts.push({
      identityKey,

      revisionKey:
        `${identityKey}|${group.stepName}|${animalNumbers.join(",")}`,

      kind: "operational",
      domain: "reproduction",
      code: "ovsynch_step_due",

      priority:
        isDueWindow
          ? "high"
          : "normal",

      urgency:
        isDueWindow
          ? "now"
          : "soon",

      certainty: "confirmed",

      status:
        context.nowMs >= group.dueAtMs
          ? "due"
          : "upcoming",

      title,
      message,

      dueDate: group.dueDate,
      affectedCount: animalNumbers.length,
      animalNumbers,

  action: {
  type:
    isDueWindow
      ? "navigate"
      : "none",

  label: "فتح صفحة التزامن",
  url: actionUrl
},
      snoozeMinutes:
        MURABBIK_OVSYNCH_ALERT_SNOOZE_MINUTES
    });
  }

  return alerts;
}
murabbikSmartAlertRegisterSourceSrv(
  "ovsynch_protocol_steps",
  murabbikOvsynchStepSmartAlertSourceSrv
);
async function murabbikSmartAlertCollectSrv(req) {
  const context = {
    req,
    userId: req.userId,
    profileUid: req.authSession?.uid || req.userId,
    today: await farmTodayISOSrv(req.authSession?.uid || req.userId),
    nowMs: Date.now(),
    memo: new Map()
  };

  context.load = async (key, loader) => {
    const memoKey = murabbikSmartAlertTextSrv(key);

    if (!context.memo.has(memoKey)) {
      context.memo.set(
        memoKey,
        Promise.resolve().then(loader)
      );
    }

    return await context.memo.get(memoKey);
  };

  const entries = [...murabbikSmartAlertSourcesSrv.entries()];

  const settled = await Promise.allSettled(
    entries.map(async ([sourceName, builder]) => ({
      sourceName,
      rows: await builder(context)
    }))
  );

  const alerts = [];
  const sourceErrors = [];

  settled.forEach((result, index) => {
    const sourceName = entries[index]?.[0] || "unknown";

    if (result.status !== "fulfilled") {
      console.error(
        `murabbik-smart-alert-source:${sourceName}`,
        result.reason
      );

      sourceErrors.push(sourceName);
      return;
    }

    for (
      const raw of
      Array.isArray(result.value.rows)
        ? result.value.rows
        : []
    ) {
      try {
        alerts.push(
          murabbikSmartAlertNormalizeSrv(
            sourceName,
            raw
          )
        );
      } catch (e) {
        console.error(
          `murabbik-smart-alert-normalize:${sourceName}`,
          e
        );

        sourceErrors.push(sourceName);
      }
    }
  });

  const unique = new Map();

  alerts
    .sort(murabbikSmartAlertCompareSrv)
    .forEach(alert => {
      if (!unique.has(alert.id)) {
        unique.set(alert.id, alert);
      }
    });

  return {
    context,
    alerts: [...unique.values()],
    sourceErrors: [...new Set(sourceErrors)]
  };
}

