app.post(
  "/api/smart-alerts/respond",
  requireUserId,
  async (req, res) => {
    try {
      if (!db) {
        return res
          .status(503)
          .json({
            ok: false,
            message:
              "❌ تعذّر تحديث التنبيه الآن. حاول مرة أخرى."
          });
      }

      const alertId =
        murabbikSmartAlertTextSrv(
          req.body?.alertId
        );

      const revision =
        murabbikSmartAlertTextSrv(
          req.body?.revision
        );

      const decision =
        murabbikSmartAlertTextSrv(
          req.body?.decision
        ).toLowerCase();

      if (
        !alertId ||
        !revision ||
        ![
          "acknowledged",
          "snoozed"
        ].includes(decision)
      ) {
        return res
          .status(400)
          .json({
            ok: false,
            error:
              "smart_alert_response_invalid",

            message:
              "❌ تعذّر تنفيذ اختيارك لهذا التنبيه. حدّث الصفحة ثم حاول مرة أخرى."
          });
      }

      const result =
        await murabbikSmartAlertCollectSrv(
          req
        );

      const alert =
        result.alerts.find(
          item =>
            item.id === alertId &&
            item.revision === revision
        );

      if (!alert) {
        return res
          .status(409)
          .json({
            ok: false,
            error:
              "smart_alert_state_changed",

            message:
              "ℹ️ تغيرت حالة التنبيه. حمّل التنبيهات من جديد."
          });
      }

      const nowMs = Date.now();

      const stateRef =
        murabbikSmartAlertStateRefSrv(
          req,
          alert.id
        );

      const commonState = {
        userId: req.userId,

        actorUid:
          murabbikSmartAlertActorUidSrv(
            req
          ),

        alertId: alert.id,
        revision: alert.revision,
        sourceName: alert.source,
        kind: alert.kind,
        domain: alert.domain,
        code: alert.code,
        decision,

        updatedAt:
          admin.firestore
            .FieldValue
            .serverTimestamp(),

        source:
          "server:/api/smart-alerts/respond"
      };

      if (
        decision === "acknowledged"
      ) {
        await stateRef.set(
          {
            ...commonState,

            acknowledgedAt:
              admin.firestore
                .FieldValue
                .serverTimestamp(),

            snoozedAt: null,
            snoozedUntil: null,
            snoozeMinutes: null
          },
          {
            merge: true
          }
        );

        return res.json({
          ok: true,
          decision,
          alertId: alert.id,
          revision: alert.revision,

          message:
            "✅ تم الاطلاع على التنبيه."
        });
      }

      const snoozeMinutes =
        alert._snoozeMinutes;

      const snoozedUntilMs =
        nowMs +
        (
          snoozeMinutes *
          60 *
          1000
        );

      await stateRef.set(
        {
          ...commonState,

          acknowledgedAt: null,

          snoozedAt:
            admin.firestore
              .FieldValue
              .serverTimestamp(),

          snoozedUntil:
            admin.firestore
              .Timestamp
              .fromMillis(
                snoozedUntilMs
              ),

                  snoozeMinutes
        },
        {
          merge: true
        }
      );

      return res.json({
        ok: true,
        decision,
        alertId: alert.id,
        revision: alert.revision,

        snoozedUntil:
          new Date(
            snoozedUntilMs
          ).toISOString(),

        message:
          "✅ سيذكّرك مُرَبِّيك بهذا التنبيه لاحقًا."
      });

    } catch (e) {
      console.error(
        "murabbik-smart-alert-respond",
        e
      );

      return res
        .status(500)
        .json({
          ok: false,
          error:
            "smart_alert_response_failed",

          message:
            "❌ تعذّر تحديث التنبيه الآن. حاول مرة أخرى."
        });
    }
  }
);

