// ============================================================
//                 API: FERTILITY REPORT
//                 تقرير الخصوبة — Server-first
// ============================================================

function fertilityReportDigitsSrv(v) {
  const map = {
    "٠":"0","١":"1","٢":"2","٣":"3","٤":"4","٥":"5","٦":"6","٧":"7","٨":"8","٩":"9",
    "۰":"0","۱":"1","۲":"2","۳":"3","۴":"4","۵":"5","۶":"6","۷":"7","۸":"8","۹":"9"
  };

  return String(v ?? "")
    .trim()
    .replace(/[٠-٩۰-۹]/g, d => map[d] || d)
    .replace(/\s+/g, "")
    .trim();
}

function fertilityReportDateSrv(v) {
  const s = String(v || "").trim();
  const m = s.match(/\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : "";
}

function fertilityReportMsSrv(v) {
  const iso = fertilityReportDateSrv(v);
  if (!iso) return null;
  const ms = new Date(`${iso}T00:00:00Z`).getTime();
  return Number.isFinite(ms) ? ms : null;
}

function fertilityReportDaysBetweenSrv(a, b) {
  const ams = fertilityReportMsSrv(a);
  const bms = fertilityReportMsSrv(b);
  if (!Number.isFinite(ams) || !Number.isFinite(bms)) return null;
  return Math.round((bms - ams) / 86400000);
}

function fertilityReportPctSrv(num, den) {
  const n = Number(num);
  const d = Number(den);
  if (!Number.isFinite(n) || !Number.isFinite(d) || d <= 0) return null;
  return Math.round((n * 1000) / d) / 10;
}
function fertilityReportHerdCompositionSrv({
  totalActive = 0,
  pregnantCount = 0,
  openCount = 0,
  inseminatedCount = 0,
  freshCount = 0,
  dryCount = 0
} = {}) {
  const total = Number(totalActive || 0);

  function pctText(pct) {
    return pct === null ? "--" : `${pct}%`;
  }

  function card(key, label, count, read) {
    const pct = fertilityReportPctSrv(count, total);

    return {
      key,
      label,
      count: Number(count || 0),
      pct,
      pctText: pctText(pct),
      read
    };
  }

  const cards = [
    card(
      "pregnant",
      "عشار",
      pregnantCount,
      "رصيد الحمل الحالي في القطيع. هذه قراءة وصفية لبنية القطيع، ولا تُستخدم وحدها للحكم على كفاءة الخصوبة إلا مع معدل الحمل 21 يوم، ومعدل رصد الشياع، والأيام المفتوحة."
    ),

    card(
      "open",
      "مفتوحة",
      openCount,
      "حجم الحيوانات غير الحامل حاليًا. أهميته الفنية تظهر عند ربطه بمتوسط الأيام المفتوحة، وكفاءة إدخال الحيوانات للتلقيح، ونتائج تشخيص الحمل."
    ),

    card(
      "inseminated",
      "ملقحة",
      inseminatedCount,
      "حيوانات بين التلقيح والحكم على الحمل. تُقرأ كخط انتظار تناسلي، وليس كنجاح أو فشل، حتى تظهر نتيجة التشخيص أو رجوع الشياع."
    ),

    card(
      "fresh",
      "حديثة الولادة",
      freshCount,
      "مرحلة ما بعد الولادة. لا تُدان تناسليًا قبل تجاوز فترة الانتظار الطوعي وفحص جاهزية الرحم والحالة العامة."
    ),

    card(
      "dry",
      "جافة",
      dryCount,
      "مرحلة مرتبطة بدورة الحمل والولادة القادمة. تُقرأ مع العشار والتحضير للولادة، وليست مؤشر فشل خصوبة منفرد."
    )
  ];

  return {
    title: "بنية القطيع التناسلية الحالية",
    read: "هذا القسم يصف توزيع الحالات التناسلية داخل القطيع الآن. الحكم الفني الحقيقي يأتي من مؤشرات الخصوبة: الحمل 21 يوم، رصد الشياع، الإخصاب، الأيام المفتوحة، فقد الحمل، والتلقيح المتكرر.",
    cards
  };
}
function fertilityReportEventTypeSrv(e = {}) {
  return normalizeEventType(
    e.eventTypeNorm ||
    e.eventType ||
    e.type ||
    e.name ||
    ""
  );
}

function fertilityReportAnimalNumberSrv(x = {}) {
  return fertilityReportDigitsSrv(
    x.animalNumber ??
    x.number ??
    x.calfNumber ??
    x.animalId ??
    ""
  );
}

function fertilityReportSpeciesKeySrv(v) {
  const s = String(v || "").trim().toLowerCase();
  if (s.includes("buffalo") || s.includes("جاموس")) return "buffalo";
  if (s.includes("cow") || s.includes("cattle") || s.includes("بقر") || s.includes("ابقار") || s.includes("أبقار")) return "cows";
  return "";
}

function fertilityReportAnimalSpeciesSrv(a = {}) {
  return fertilityReportSpeciesKeySrv(
    a.species ||
    a.animalTypeAr ||
    a.animalType ||
    a.animaltype ||
    a.type ||
    ""
  );
}

function fertilityReportIsActiveAnimalSrv(a = {}) {
  const st = String(a.status || a.lifeStatus || "").trim().toLowerCase();
  return !["dead", "died", "sold", "archived", "inactive", "nafaq", "نافق", "مباع"].includes(st);
}

function fertilityReportReproKindSrv(v) {
  const s = String(v || "")
    .trim()
    .replace(/\s+/g, " ")
    .replace(/[أإآ]/g, "ا")
    .replace(/ة/g, "ه")
    .replace(/ى/g, "ي");

  // تحضير الولادة = عشار قرب الولادة، وليست متأخرة عن التلقيح
  if (
    /عشار|حامل|preg/i.test(s) ||
    s.includes("تحضير") ||
    s.includes("انتظار الولاده") ||
    s.includes("قرب الولاده") ||
    /close[\s_-]*up|prepartum|pre-partum/i.test(s)
  ) {
    return "pregnant";
  }

  if (/ملقح|ملقحة|ملقحه|inseminated|bred/i.test(s)) return "inseminated";
  if (/حديث|ولاد|fresh/i.test(s)) return "fresh";
  if (/مفتوح|مفتوحه|فارغ|فارغه|open/i.test(s)) return "open";

  return "unknown";
}

function fertilityReportPregResultSrv(v) {
  const s = String(v || "").trim().toLowerCase();

  if (s.includes("عشار") || s.includes("حامل") || s.includes("positive") || s.includes("pregnant")) {
    return "positive";
  }

  if (
    s.includes("فارغة") ||
    s.includes("فارغ") ||
    s.includes("غير حامل") ||
    s.includes("negative") ||
    s.includes("open") ||
    s.includes("empty")
  ) {
    return "negative";
  }

  return "unknown";
}

function fertilityReportTimeBucketSrv(v) {
  const s = String(v || "").trim().toLowerCase();

  if (!s) return "";

  if (
    s.includes("صباح") ||
    s.includes("morning") ||
    s === "am" ||
    s.includes("a.m")
  ) return "am";

  if (
    s.includes("مساء") ||
    s.includes("evening") ||
    s === "pm" ||
    s.includes("p.m")
  ) return "pm";

  const m = s.match(/(\d{1,2})(?::(\d{2}))?/);
  if (m) {
    const h = Number(m[1]);
    if (Number.isFinite(h)) {
      return h < 12 ? "am" : "pm";
    }
  }

  return "";
}

function fertilityReportTimingAssessmentSrv(ai = {}, heatBefore = null) {
  const heatBucket = fertilityReportTimeBucketSrv(
    ai.heatTime ||
    ai.heatStatus ||
    heatBefore?.heatTime ||
    ""
  );

  const aiBucket = fertilityReportTimeBucketSrv(
    ai.inseminationTime ||
    ai.timeOfDay ||
    ai.time ||
    ""
  );

  if (!heatBucket || !aiBucket) {
    return {
      code: "unknown",
      label: "غير مكتمل",
      note: "وقت الشياع أو وقت التلقيح غير مسجل."
    };
  }

  if (heatBucket !== aiBucket) {
    return {
      code: "ideal",
      label: "مناسب",
      note:
        heatBucket === "am"
          ? "شياع صباحًا وتلقيح مساءً — توقيت مناسب."
          : "شياع مساءً وتلقيح صباحًا — توقيت مناسب."
    };
  }

  return {
    code: "wrong",
    label: "غير مناسب",
    note:
      heatBucket === "am"
        ? "الشياع والتلقيح صباحًا؛ كان يجب أن يكون التلقيح مساءً."
        : "الشياع والتلقيح مساءً؛ كان يجب أن يكون التلقيح صباحًا."
  };
}
function inseminationSourceNormSrv(data = {}) {
  const raw = String(
    data.inseminationSource ||
    data.requestSource ||
    data.source ||
    data.protocolSource ||
    data.inseminationMethod ||
    ""
  ).trim();

  return /ovsynch[_\s-]*tai|\btai\b|fixed[\s_-]*time|تزامن|إجباري|اجباري/i.test(raw)
    ? "ovsynch_tai"
    : "";
}

function fertilityReportInseminationSourceSrv(ai = {}) {
  const sourceCode =
    inseminationSourceNormSrv(ai);

  return {
    code:
      sourceCode || "natural",

    isForced:
      sourceCode === "ovsynch_tai",

    label:
      sourceCode === "ovsynch_tai"
        ? "تلقيح إجباري/TAI"
        : "تلقيح مرتبط بشياع طبيعي"
  };
}
function fertilityReportThiInfoSrv(e = {}) {
  const src = e.thiAtInsemination || {};
  const value = Number(e.thiValue ?? src.thi);
  const level = String(e.thiLevel || src.level || src.status?.level || "unknown").trim() || "unknown";
  const label = String(e.thiLabel || src.label || src.status?.label || "").trim();

  return {
    value: Number.isFinite(value) ? Math.round(value) : null,
    level,
    label: label || (
      level === "comfort" ? "راحة" :
      level === "mild" ? "إجهاد خفيف" :
      level === "moderate" ? "إجهاد متوسط" :
      level === "high" ? "إجهاد عالي" :
      "غير متاح"
    )
  };
}

function fertilityReportKpiStatusSrv(value, benchmark, direction = "higher") {
  const v = Number(value);
  const b = Number(benchmark);

  if (!Number.isFinite(v) || !Number.isFinite(b)) {
    return {
      status: "muted",
      label: "غير مكتمل"
    };
  }

  if (direction === "lower") {
    if (v <= b) return { status: "good", label: "جيد" };
    if (v <= b * 1.15) return { status: "warn", label: "متابعة" };
    return { status: "danger", label: "يحتاج تدخل" };
  }

  if (v >= b) return { status: "good", label: "جيد" };
  if (v >= b * 0.8) return { status: "warn", label: "متابعة" };
  return { status: "danger", label: "يحتاج تدخل" };
}
function fertilityReportRound1Srv(v) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n * 10) / 10 : null;
}

function fertilityReportAvgSrv(values = []) {
  const nums = (Array.isArray(values) ? values : [])
    .map(Number)
    .filter(Number.isFinite);

  if (!nums.length) return null;
  return fertilityReportRound1Srv(nums.reduce((s, n) => s + n, 0) / nums.length);
}

function fertilityReportTopValueSrv(values = []) {
  const arr = (Array.isArray(values) ? values : [])
    .map(v => String(v || "").trim())
    .filter(Boolean);

  if (!arr.length) return { value: "", count: 0, pct: null };

  const m = new Map();
  for (const v of arr) m.set(v, (m.get(v) || 0) + 1);

  const [value, count] = [...m.entries()]
    .sort((a, b) => Number(b[1] || 0) - Number(a[1] || 0))[0];

  return {
    value,
    count,
    pct: fertilityReportPctSrv(count, arr.length)
  };
}

function fertilityReportExpertIndicatorSrv({
  key = "",
  title = "",
  value = null,
  unit = "%",
  benchmark = null,
  direction = "higher",
  goodText = "",
  warnText = "",
  dangerText = "",
  advice = ""
} = {}) {
  const n = Number(value);
  const b = Number(benchmark);
  const base = fertilityReportKpiStatusSrv(value, benchmark, direction);

  let read = "البيانات غير كافية لإصدار قراءة فنية على هذا المؤشر.";

  if (base.status === "good") read = goodText || "المؤشر داخل النطاق المقبول فنيًا.";
  if (base.status === "warn") read = warnText || "المؤشر قريب من الحد الفني ويحتاج متابعة مع باقي المؤشرات.";
  if (base.status === "danger") read = dangerText || "المؤشر خارج النطاق المطلوب ويحتاج تفسير سبب الخلل.";

  return {
    key,
    title,
    value: Number.isFinite(n) ? fertilityReportRound1Srv(n) : null,
    valueText: Number.isFinite(n) ? `${fertilityReportRound1Srv(n)}${unit ? " " + unit : ""}` : "غير مكتمل",
    benchmark: Number.isFinite(b) ? b : null,
    benchmarkText: Number.isFinite(b)
      ? `${direction === "lower" ? "المستهدف ≤" : "المستهدف ≥"} ${b}${unit ? " " + unit : ""}`
      : "",
    status: base.status,
    rating: base.label,
    read,
    advice
  };
}

function fertilityReportRepeatBreederAnalysisSrv(repeatBreeders = [], eligibleCount = 0) {
  const rows = Array.isArray(repeatBreeders)
    ? repeatBreeders
    : [];

  const count = rows.length;
  const den = Number(eligibleCount || 0);
  const ratePct = fertilityReportPctSrv(count, den);

  let severity = "good";
  let severityLabel = "لا توجد حالات";

  if (count === 1) {
    severity = "warn";
    severityLabel = "حالة واحدة";
  } else if (count > 1) {
    severity = "warn";
    severityLabel = "حالات متعددة";
  }

  const herdRead =
    count === 0
      ? "لا توجد حيوانات مطابقة لشروط Repeat Breeder حسب البيانات الحالية."
      : `لديك ${count} حيوانات مطابقة لشروط Repeat Breeder.`;

  const recommendation =
    "راجع توقيت التلقيح، وانتظام دورات الشياع، وطريقة حفظ وتداول السائل المنوي. نفّذ التلقيح في الأوقات الأبرد، واهتم بتبريد الحيوانات عند وجود إجهاد حراري.";

  return {
    count,
    eligibleCount: den || null,
    ratePct,
    severity,
    severityLabel,
    herdRead,
    recommendation,
    rows: rows.slice(0, 80)
  };
}
