// ============================================================
//                 HEAT / شياع — SERVER DECISION HELPERS
// ============================================================

function heatStripArSrv(s){
  return String(s || "")
    .trim()
    .replace(/\s+/g, "")
    .replace(/[ًٌٍَُِّْ]/g, "");
}

function heatReproCategorySrv(raw){
  const n = heatStripArSrv(raw);

  if (n.includes("لاتلقح") || n.includes("لاتلقحمرةاخرى")) return "blocked";
  if (n.includes("عشار")) return "pregnant";
  if (n.includes("ملقح") || n.includes("ملقحة") || n.includes("ملقّحة")) return "inseminated";
  if (n.includes("مفتوح") || n.includes("فارغ") || n.includes("فارغة")) return "open";

  return "unknown";
}

function heatAnimalWordSrv(species){
  return normalizeSpeciesSrv(species) === "جاموس" ? "جاموسة" : "بقرة";
}

function heatPickSpeciesSrv(animal = {}, body = {}){
  return normalizeSpeciesSrv(
    body.species ||
    animal.species ||
    animal.animalTypeAr ||
    animal.animalType ||
    animal.animaltype ||
    animal.groupSpecies ||
    ""
  );
}

function heatCurrentReproStatusSrv(animal = {}, fallback = ""){
  return String(
    animal.reproductiveStatus ||
    animal.reproStatus ||
    animal.lastDiagnosis ||
    fallback ||
    ""
  ).trim();
}

function heatDecisionSrv({ animal = {}, species = "", reproductiveStatus = "" } = {}){
  if (!animal || !Object.keys(animal).length) {
   return "❌ لم أجد بيانات الحيوان. راجع الرقم وحاول مرة أخرى.";
  }

  const sp = heatPickSpeciesSrv(animal, { species });
  const aw = heatAnimalWordSrv(sp);

  const rsRaw = heatCurrentReproStatusSrv(animal, reproductiveStatus);
  const cat = heatReproCategorySrv(rsRaw);

  if (animal.breedingBlocked === true || cat === "blocked") {
   return `❌ هذه ${aw} مستبعدة من التناسل، لذلك لا يمكن تسجيل شياع لها.`;
  }

  return null;
}

async function heatDuplicateCheckSrv(uid, animalNumber, eventDate, windowDays = 3){
  const num = normalizeDigitsSrv(animalNumber || "");
  const dt = String(eventDate || "").slice(0,10);

  if (!uid || !num || !/^\d{4}-\d{2}-\d{2}$/.test(dt)) return null;

  const candidates = [];
  const vals = findAnimalNumberMatches(num);

  for (const field of ["animalNumber", "number"]) {
    for (const v of vals) {
      try {
        const snap = await db.collection("events")
          .where("userId", "==", uid)
          .where(field, "==", v)
          .limit(120)
          .get();

        snap.docs.forEach(ds => candidates.push(ds.data() || {}));
      } catch (e) {
        console.error("heat duplicate check failed:", e.message || e);
        return "⚠️ تعذّر فحص سجلات الشياع السابقة الآن. حاول مرة أخرى.";
      }
    }
  }

  const cur = new Date(dt + "T00:00:00");
  if (Number.isNaN(cur.getTime())) return null;

  let bestDate = "";
  let bestDiff = 999999;

  for (const ev of candidates) {
    const txt = eventTextSrv(ev);
    const isHeat =
      txt.includes("شياع") ||
      txt.includes("heat");

    if (!isHeat) continue;

    const d = computeEventDateFromDoc(ev);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(d || ""))) continue;

    const last = new Date(d + "T00:00:00");
    if (Number.isNaN(last.getTime())) continue;

    const diff = Math.floor((cur - last) / 86400000);

    if (diff >= 0 && diff <= Number(windowDays)) {
      if (diff < bestDiff) {
        bestDiff = diff;
        bestDate = d;
      }
    }
  }

  if (!bestDate) return null;

  if (bestDate === dt) {
    return `❌ سبق أن سجلت شياعًا للحيوان رقم ${num} في التاريخ نفسه (${dt})، لذلك لن يتكرر التسجيل.`;
  }

return `❌ سبق أن سجلت شياعًا للحيوان رقم ${num} بتاريخ ${bestDate}. يمكن تسجيل شياع جديد بعد مرور ${windowDays} أيام.`;
}
function heatNormalizeDayPartForInseminationSrv(v) {
  const raw = String(v || "").trim();
  const s = heatStripArSrv(raw).toLowerCase();

  if (s === "ص" || s.includes("صباح")) return "صباحا";
  if (s === "م" || s.includes("مساء")) return "مساءا";

  return raw;
}

function heatBuildInseminationRedirectUrlSrv({ animalNumbers = [], eventDate = "", heatTime = "" } = {}) {
  const nums = animalNumbers
    .map(x => normalizeDigitsSrv(x))
    .filter(Boolean);

  if (!nums.length) return "";

  const heatStatus = heatNormalizeDayPartForInseminationSrv(heatTime);
  const joined = nums.join(",");

  const q = new URLSearchParams();
  q.set("fromHeat", "1");
  q.set("mode", nums.length > 1 ? "bulk" : "single");
  q.set("animalNumbers", joined);
  q.set("numbers", joined);
  q.set("animalNumber", joined);
  q.set("eventDate", eventDate);
  q.set("date", eventDate);
  q.set("heatDate", eventDate);

  if (heatStatus) {
    q.set("heatTime", heatStatus);
    q.set("heatStatus", heatStatus);
  }

  return `insemination.html?${q.toString()}`;
}

async function heatBuildInseminationCandidatesSrv(uid, saved = [], eventDate = "", heatTime = "") {
  const candidates = [];
  const rejected = [];

  for (const item of saved || []) {
    const animalNumber = normalizeDigitsSrv(item?.animalNumber || "");

    if (!animalNumber) continue;

    try {
      const animal = await fetchAnimalByNumberForCalvingGateSrv(uid, animalNumber);

      if (!animal) {
        rejected.push({
          animalNumber,
         reason: "لم أجد الحيوان في حسابك، لذلك لم أتمكن من فحص جاهزيته للتلقيح."
        });
        continue;
      }

      const doc = animal.data || {};
      const signals = await fetchCalvingSignalsFromEventsSrv(uid, animalNumber);

      let species = String(
        doc.species ||
        doc.animalTypeAr ||
        doc.animalType ||
        doc.animaltype ||
        doc.type ||
        ""
      ).trim();

      if (/cow|بقر/i.test(species)) species = "أبقار";
      if (/buffalo|جاموس/i.test(species)) species = "جاموس";
    const dimAtHeat = Number(item?.dimAtEvent);
const recommendedPostCalving = species === "جاموس" ? 45 : 56;
const hardBlockPostCalving = species === "جاموس" ? 35 : 45;

if (
  Number.isFinite(dimAtHeat) &&
  dimAtHeat >= 0 &&
  dimAtHeat < hardBlockPostCalving
) {
  rejected.push({
    animalNumber,
   reason: `مرّ ${Math.round(dimAtHeat)} يومًا فقط منذ الولادة. لا يمكن التلقيح قبل ${hardBlockPostCalving} يومًا، والأفضل الانتظار حتى ${recommendedPostCalving} يومًا.`
  });
  continue;
}
      const reproFromEvents = String(signals.reproStatusFromEvents || "").trim();
      const reproFromDoc = String(doc.reproductiveStatus || "").trim();
      const reproStatus =
  String(item?.reproductiveStatusSnapshot || "").trim() ||
  reproFromEvents ||
  reproFromDoc ||
  "";

      const lastInseminationDate = String(
        signals.lastInseminationDateFromEvents ||
        doc.lastInseminationDate ||
        ""
      ).trim();

      const sameDayInseminationCount = await countInseminationsSameDaySrv(
        uid,
        animalNumber,
        eventDate
      );

      const decision = inseminationDecisionSrv({
        animalNumber,
        eventDate,
        animalId: animal.id || "",
        species,
        documentData: doc,
        reproductiveStatus: reproStatus,
        reproStatusFromEvents: reproFromEvents,
        lastInseminationDate,
        sameDayInseminationCount,
        dimAtEvent: item?.dimAtEvent ?? null,
        lastCalvingDate: item?.lastCalvingDate || "",
        lastBoundary: String(signals.lastBoundary || "").trim(),
        lastBoundaryType: String(signals.lastBoundaryType || "").trim()
      });

      if (decision) {
        const raw = String(decision || "");
        const isWarn = raw.startsWith("WARN|");
        const needsEmbryonicConfirm = raw.startsWith("CONFIRM_EMBRYONIC_LOSS|");

        const message = needsEmbryonicConfirm
          ? raw.replace(/^CONFIRM_EMBRYONIC_LOSS\|/, "")
          : isWarn
            ? raw.replace(/^WARN\|/, "")
            : raw;

        if (!isWarn || needsEmbryonicConfirm) {
          rejected.push({
            animalNumber,
            reason: message
          });
          continue;
        }

        candidates.push({
          animalNumber,
          warning: message
        });
        continue;
      }

      candidates.push({
        animalNumber,
        warning: ""
      });

    } catch (e) {
      console.error("heat-build-insemination-candidate", animalNumber, e);

      rejected.push({
        animalNumber,
       reason: "حُفظ الشياع، لكن تعذّر فحص جاهزية الحيوان للتلقيح الآن."
      });
    }
  }

  const animalNumbers = candidates
    .map(x => String(x.animalNumber || "").trim())
    .filter(Boolean);

  return {
    ok: true,
    animalNumbers,
    candidateCount: animalNumbers.length,
    candidates,
    rejected,
    redirectUrl: heatBuildInseminationRedirectUrlSrv({
      animalNumbers,
      eventDate,
      heatTime
    })
  };
}
async function buildHeatContextSrv(uid, animalNumber, eventDate){
  const num = normalizeDigitsSrv(animalNumber || "");
  const dt = String(eventDate || "").slice(0,10);

  if (!num) {
   return { ok:false, status:400, error:"animalNumber_required", message:"❌ أدخل رقم الحيوان." };
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(dt)) {
    return { ok:false, status:400, error:"eventDate_required", message:"❌ أدخل تاريخ شياع صحيحًا." };
  }

  const animal = await findAnimalDocByNumberSrv(uid, num);
  if (!animal) {
    return {
  ok:false,
  status:404,
  error:"animal_not_found",
  message:`❌ لم أجد الحيوان رقم ${num} في حسابك. راجع الرقم وحاول مرة أخرى.`
};
  }
    const duplicateMsg = await heatDuplicateCheckSrv(uid, num, dt, 0);

  if (duplicateMsg) {
    const reproductiveStatus = heatCurrentReproStatusSrv(animal);

    return {
      ok: true,
      allowed: false,
      status: 409,
      error: "heat_duplicate_same_day",
      message: duplicateMsg,
      animalId: animal.id || "",
      species: heatPickSpeciesSrv(animal),
      reproductiveStatus,
      reproductiveCategory: heatReproCategorySrv(reproductiveStatus),
      actionRequired: "",
      redirectUrl: ""
    };
  }
  const species = heatPickSpeciesSrv(animal);
  const reproductiveStatus = heatCurrentReproStatusSrv(animal);

  let dimAtEvent = null;
  const lastCalvingDate = String(animal.lastCalvingDate || "").slice(0,10);

  if (/^\d{4}-\d{2}-\d{2}$/.test(lastCalvingDate)) {
    dimAtEvent = daysBetweenIsoSrv(lastCalvingDate, dt);
    if (dimAtEvent != null && dimAtEvent < 0) dimAtEvent = 0;
  }

  const lastEvent = await getLatestHeatOrInseminationSrv(uid, num, dt);

  let lastEventType = null;
  let lastEventDate = null;
  let daysSinceLastHeatOrAI = null;

  if (lastEvent?._eventDate) {
    lastEventDate = lastEvent._eventDate;
    lastEventType = lastEvent._typeNorm;
    daysSinceLastHeatOrAI = daysBetweenIsoSrv(lastEventDate, dt);
    if (daysSinceLastHeatOrAI != null && daysSinceLastHeatOrAI < 0) {
      daysSinceLastHeatOrAI = null;
    }
  }

  const decisionMsg = heatDecisionSrv({
    animal,
    species,
    reproductiveStatus
  });

  const reproductiveCategory = heatReproCategorySrv(reproductiveStatus);
  const requiresPregnancyConfirmation = reproductiveCategory === "pregnant";
  const pregnancyConfirmationRedirectUrl =
    `pregnancy-diagnosis.html?number=${encodeURIComponent(num)}` +
    `&date=${encodeURIComponent(dt)}` +
    `&checkType=pregnancy_confirmation_120` +
    `&returnTo=heat`;

  return {
    ok: true,
    allowed: !decisionMsg && !requiresPregnancyConfirmation,
    message: decisionMsg || (
      requiresPregnancyConfirmation
       ? `⚠️ الحيوان رقم ${num} مسجّل عِشار وظهر عليه شياع. يجب تأكيد حالة الحمل أولًا، لذلك لن أسجل الشياع الآن.`
       : `✅ راجعت بيانات الحيوان رقم ${num}، ويمكنك تسجيل الشياع الآن. أكمل البيانات ثم احفظ.`
    ),
    animal,
    animalId: String(animal.id || animal.animalId || num),
    animalNumber: String(animal.animalNumber || animal.number || num),
    species,
    reproductiveStatus,
    reproductiveCategory,
    requiresPregnancyConfirmation,
    actionRequired: requiresPregnancyConfirmation ? "pregnancy_confirmation" : "",
    pregnancyConfirmationRedirectUrl: requiresPregnancyConfirmation ? pregnancyConfirmationRedirectUrl : "",
    redirectUrl: requiresPregnancyConfirmation ? pregnancyConfirmationRedirectUrl : "",
    dimAtEvent,
    lastEventType,
    lastEventDate,
    daysSinceLastHeatOrAI
  };
}
