function animalListStrSrv(v) {
  return String(v ?? '').trim();
}

function animalListIsoDateSrv(v) {
  const s = String(v || '').trim();
  if (!s) return null;

  if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
    return s.slice(0, 10);
  }

  // دعم بيانات مُرَبِّيك القديمة المخزنة بصيغة DD/MM/YYYY.
  const legacyDMY = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (legacyDMY) {
    const day = Number(legacyDMY[1]);
    const month = Number(legacyDMY[2]);
    const year = Number(legacyDMY[3]);

    const d = new Date(
      Date.UTC(year, month - 1, day)
    );

    if (
      d.getUTCFullYear() !== year ||
      d.getUTCMonth() !== month - 1 ||
      d.getUTCDate() !== day
    ) {
      return null;
    }

    return (
      `${String(year).padStart(4, '0')}-` +
      `${String(month).padStart(2, '0')}-` +
      `${String(day).padStart(2, '0')}`
    );
  }

  const d = toDate(v);

  if (!d || Number.isNaN(d.getTime())) {
    return null;
  }

  return d.toISOString().slice(0, 10);
}

function animalListNumDisplaySrv(v, fallback = '---') {
  if (v === null || v === undefined || v === '') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function animalListDaysDisplaySrv(fromISO, todayISO, fallback = '---') {
  const from = animalListIsoDateSrv(fromISO);
  const today = animalListIsoDateSrv(todayISO);
  if (!from || !today) return fallback;

  const d = diffDaysISO(from, today);
  return Number.isFinite(d) && d >= 0 ? d : fallback;
}

function animalListIsActiveSrv(a = {}) {
  const st = animalListStrSrv(a.status || 'active').toLowerCase();
  if (a.archived === true) return false;
  return !['inactive', 'archived', 'deleted'].includes(st);
}

function animalListTypeArSrv(a = {}) {
  const raw = animalListStrSrv(
    a.animalTypeAr || a.animalType || a.species || a.type || a.animaltype || a.kind
  );

  if (/buffalo|جاموس/i.test(raw)) return 'جاموسة';
  if (/cow|cattle|بقر|أبقار|ابقار/i.test(raw)) return 'بقرة';
  return raw;
}

function animalListTypeEnSrv(a = {}) {
  const raw = animalListStrSrv(
    a.animaltype || a.animalType || a.animalTypeAr || a.species || a.type || a.kind
  );

  if (/buffalo|جاموس/i.test(raw)) return 'buffalo';
  if (/cow|cattle|بقر|أبقار|ابقار/i.test(raw)) return 'cow';
  return '';
}

function animalListNumberTextSrv(a = {}) {
  const raw = a.animalNumber ?? a.number ?? a.calfNumber ?? '';
  return normalizeDigitsSrv(raw) || animalListStrSrv(raw);
}
function animalListBreedDisplaySrv(v) {
  const raw = animalListStrSrv(v);
  if (!raw) return '---';

  const k = raw
    .toLowerCase()
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/[._-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const map = {
    'holstein': 'هولشتاين',
    'holstein friesian': 'هولشتاين فريزيان',
    'friesian': 'فريزيان',
    'brown swiss': 'براون سويس',
    'montbeliarde': 'مونتبليارد',
    'montbéliarde': 'مونتبليارد',
    'jersey': 'جيرسي',
    'simmental': 'سيمنتال',
    'fleckvieh': 'فليكفيه',
    'charolais': 'شاروليه',
    'ayrshire': 'أيرشاير',

    'buffalo': 'جاموسي',
    'egyptian buffalo': 'جاموس مصري',
    'murrah': 'مورا',
    'nili ravi': 'نيلي رافي',

    'هولستين': 'هولشتاين',
    'هولشتاين': 'هولشتاين',
    'فريزيان': 'فريزيان',
    'براون سويس': 'براون سويس',
    'مونتبليارد': 'مونتبليارد',
    'جيرسي': 'جيرسي',
    'سيمنتال': 'سيمنتال',
    'جاموس': 'جاموسي',
    'جاموسي': 'جاموسي',
    'جاموس مصري': 'جاموس مصري'
  };

  return map[k] || raw;
}
function animalListDisplayKeySrv(v) {
  return String(v ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_\-.\/]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function animalListProductionDisplaySrv(v) {
  const raw = animalListStrSrv(v);
  if (!raw) return '---';

  const k = animalListDisplayKeySrv(raw);

  const map = {
    'milking': 'حلاب',
    'milk': 'حلاب',
    'lactating': 'حلاب',
    'in milk': 'حلاب',

    'dry': 'جاف',
    'dry off': 'جاف',
    'dryoff': 'جاف',

    'fresh': 'حديث الولادة',
    'fresh cow': 'حديث الولادة',
    'postpartum': 'حديث الولادة',

    'close up': 'تحضير ولادة',
    'closeup': 'تحضير ولادة',
    'close up period': 'تحضير ولادة',
    'close up cow': 'تحضير ولادة'
  };

  return map[k] || raw;
}

function animalListBreedDisplaySrv(v) {
  const raw = animalListStrSrv(v);
  if (!raw) return '---';

  const k = animalListDisplayKeySrv(raw);

  const map = {
    'holstein': 'هولشتاين',
    'holstein friesian': 'هولشتاين فريزيان',
    'friesian': 'فريزيان',

    'brown swiss': 'براون سويس',
    'jersey': 'جيرسي',
    'jersy': 'جيرسي',
    'simmental': 'سيمنتال',
    'montbeliarde': 'مونتبليارد',
    'montbeliard': 'مونتبليارد',
    'fleckvieh': 'فليكفيه',
    'charolais': 'شاروليه',
    'ayrshire': 'أيرشاير',

    'cross': 'خليط',

'italian': 'إيطالي',
'italian cross': 'خليط إيطالي',
'italiancross': 'خليط إيطالي',
'cross italian': 'خليط إيطالي',

'indian': 'هندي',
'indian cross': 'خليط هندي',
'indiancross': 'خليط هندي',
'cross indian': 'خليط هندي',

    'buffalo': 'جاموسي',
    'baladi': 'بلدي',
    'balady': 'بلدي',
    'local': 'بلدي',
    'native': 'بلدي',
    'italian buffalo': 'جاموس إيطالي',
    'murrah': 'مورا',
    'nili ravi': 'نيلي رافي'
  };

  return map[k] || raw;
}
function animalListBuildRowSrv(
  a = {},
  todayISO = '',
  requestedImportId = ''
) {
  const animalNumber = animalListNumberTextSrv(a);
const typeEn = animalListTypeEnSrv(a);
const typeAr =
  typeEn === 'cow'
    ? 'أبقار'
    : typeEn === 'buffalo'
      ? 'جاموس'
      : animalListTypeArSrv(a);
  const productionStatusRaw = animalListStrSrv(a.productionStatus);
  const productionStatus = animalListProductionDisplaySrv(productionStatusRaw);

  const importId =
    animalListStrSrv(
      a.importId ||
      a.importJobId
    );

  const highlightImported =
    animalListStrSrv(requestedImportId) &&
    importId ===
      animalListStrSrv(requestedImportId);

  const reproductiveStatus = animalListStrSrv(a.reproductiveStatus);

const birthDate = animalListIsoDateSrv(
  a.birthDate ||
  a.birth_date ||
  a.dateOfBirth ||
  a.dob
);

const lastCalvingDate =
  animalListIsoDateSrv(a.lastCalvingDate);

const storedLastInseminationDate =
  animalListIsoDateSrv(
    a.lastInseminationDate ||
    a.lastAI ||
    a.lastInsemination ||
    a.lastServiceDate
  );

const lastInseminationDate = (
  storedLastInseminationDate &&
  (
    !lastCalvingDate ||
    storedLastInseminationDate > lastCalvingDate
  )
)
  ? storedLastInseminationDate
  : '';

const lactationNumber =
  animalListNumDisplaySrv(a.lactationNumber);

const servicesCount = (
  lastCalvingDate &&
  !lastInseminationDate
)
  ? 0
  : animalListNumDisplaySrv(a.servicesCount);

  const prodNorm = animalListDisplayKeySrv(
    productionStatusRaw ||
    productionStatus
  );

  const isDry =
    prodNorm.includes('dry') ||
    productionStatus.includes('جاف');

  const daysInMilk = isDry
    ? '---'
    : lastCalvingDate
      ? animalListDaysDisplaySrv(
          lastCalvingDate,
          todayISO
        )
      : animalListNumDisplaySrv(
          a.daysInMilk
        );

  const inseminatedDays = (
    (
      reproductiveStatus === 'ملقحة' ||
      reproductiveStatus === 'ملقح'
    ) &&
    lastInseminationDate
  )
    ? animalListDaysDisplaySrv(
        lastInseminationDate,
        todayISO
      )
    : '---';

  const pregnancyDays = (
    reproductiveStatus === 'عشار' &&
    lastInseminationDate
  )
    ? animalListDaysDisplaySrv(
        lastInseminationDate,
        todayISO
      )
    : (
        reproductiveStatus === 'عشار'
          ? animalListNumDisplaySrv(
              a.pregnancyDays
            )
          : '---'
      );

  const eventUrl = animalNumber
    ? (
        `add-event.html?animalId=${encodeURIComponent(animalNumber)}` +
        `&number=${encodeURIComponent(animalNumber)}` +
        `&animalNumber=${encodeURIComponent(animalNumber)}` +
        `&eventDate=${encodeURIComponent(todayISO)}` +
        `&date=${encodeURIComponent(todayISO)}`
      )
    : '';

  return {
    id: a.id || null,

    importId,

    animalNumber,

    animalTypeAr:
      typeAr,

    animaltype:
      typeEn,

    rowClass: [
      typeEn === 'cow'
        ? 'mbk-row-cow'
        : typeEn === 'buffalo'
          ? 'mbk-row-buffalo'
          : '',

      highlightImported
        ? 'mbk-import-highlight'
        : ''

    ].filter(Boolean).join(' '),

    breed:
      animalListBreedDisplaySrv(
        a.breed
      ),

    productionStatus,

lactationNumber,

daysInMilk,

reproductiveStatus:
  reproductiveStatus || '---',

servicesCount,

lastInseminationDate:
  lastInseminationDate || '---',

inseminatedDays,

    dailyMilk:
      animalListNumDisplaySrv(
        a.dailyMilk
      ),

    pregnancyDays,

   birthDate:
  birthDate || '---',

    lastCalvingDate:
      lastCalvingDate || '---',

    cardUrl:
      animalNumber
        ? `cow-card.html?number=${encodeURIComponent(animalNumber)}`
        : '',

    eventUrl
  };
}

async function animalListFetchFirestoreSrv(uid) {
  const byId = new Map();

  for (const ownerField of ['userId', 'ownerUid']) {
    try {
      const snap = await db.collection('animals')
        .where(ownerField, '==', uid)
        .limit(3000)
        .get();

      snap.docs.forEach(d => {
        if (!byId.has(d.id)) byId.set(d.id, { id: d.id, ...(d.data() || {}) });
      });
    } catch (e) {
      console.warn('animal-list owner query failed:', ownerField, e.code || e.message || e);
    }
  }

  return Array.from(byId.values());
}

function animalListApplyFiltersSrv(rows = [], query = {}) {
  const searchNumber = normalizeDigitsSrv(query.searchNumber || query.number || query.q || '');
  const type = animalListStrSrv(query.type || query.animalTypeAr || '');
  const reproductiveStatus = animalListStrSrv(query.reproductiveStatus || query.repro || '');

  return rows.filter(a => {
    if (searchNumber && !String(a.animalNumber || '').includes(searchNumber)) return false;
    if (type && animalListStrSrv(a.animalTypeAr) !== type) return false;
    if (reproductiveStatus && animalListStrSrv(a.reproductiveStatus) !== reproductiveStatus) return false;
    return true;
  });
}

function animalListSortSrv(a, b) {
  const an = Number(a.animalNumber);
  const bn = Number(b.animalNumber);
  if (Number.isFinite(an) && Number.isFinite(bn)) return an - bn;
  return String(a.animalNumber || '').localeCompare(String(b.animalNumber || ''), 'ar');
}

app.get('/api/animals', requireUserId, async (req, res) => {
  const uid = req.userId;
  const todayISO = cairoTodayISO();
  const requestedImportId =
  animalListStrSrv(
    req.query.importId || ''
  );

  try {
    let rawAnimals = [];

    if (db) {
      rawAnimals = await animalListFetchFirestoreSrv(uid);
    }

    if (!rawAnimals.length) {
      rawAnimals = readJson(animalsPath, []).filter(a => belongs(a, uid));
    }

    const activeRows = rawAnimals
      .filter(animalListIsActiveSrv)
     .map(a =>
  animalListBuildRowSrv(
    a,
    todayISO,
    requestedImportId
  )
)
      .filter(a => a.animalNumber);

    const typeOptions = [...new Set(activeRows.map(a => a.animalTypeAr).filter(Boolean))]
      .sort((a, b) => a.localeCompare(b, 'ar'));

    const animals = animalListApplyFiltersSrv(activeRows, req.query).sort(animalListSortSrv);

    return res.json({
      ok: true,
      today: todayISO,
      count: animals.length,
      totalActive: activeRows.length,
      typeOptions,
      animals
    });

  } catch (e) {
    console.error('animals fatal error:', e);
    return res.status(500).json({
      ok: false,
      error: 'animals_fatal',
      message: 'تعذّر تحميل قائمة الحيوانات الآن.'
    });
  }
});
