// ============================================================
//      BILLING CORE — PROVIDER-READY CHECKOUT ORDERS
// ============================================================
const BILLING_ORDER_VERSION_SRV =
  'billing-order-v1';
const BILLING_ORDER_TTL_MS_SRV =
  72 * 60 * 60 * 1000;
const BILLING_CYCLES_SRV =
  new Set([
    'monthly',
    'annual'
  ]);

function billingPublicErrorSrv(
  status,
  code,
  message
) {
  const err = new Error(code);

  err.publicStatus =
    Number(status) || 500;

  err.publicError =
    String(code || 'billing_failed');

  err.publicMessage =
    String(message || '').trim();

  return err;
}

function billingNormalizeCycleSrv(v) {
  const cycle =
    String(v || '')
      .trim()
      .toLowerCase();

  return BILLING_CYCLES_SRV.has(cycle)
    ? cycle
    : '';
}

function billingNormalizeIdempotencyKeySrv(v) {
  const key =
    String(v || '').trim();

  if (
    key.length < 8 ||
    key.length > 200 ||
    /[\u0000-\u001f\u007f]/.test(key)
  ) {
    return '';
  }

  return key;
}

function billingSha256Srv(v) {
  return crypto
    .createHash('sha256')
    .update(
      String(v || ''),
      'utf8'
    )
    .digest('hex');
}
const BILLING_CURRENCY_EXPONENTS_SRV = Object.freeze({
  EGP: 2,
  USD: 2
});

function billingCurrencyExponentSrv(currencyRaw) {
  const currency =
    String(currencyRaw || '')
      .trim()
      .toUpperCase();

  const exponent =
    BILLING_CURRENCY_EXPONENTS_SRV[currency];

  return Number.isInteger(exponent)
    ? exponent
    : null;
}

function billingAmountMinorSrv(amountRaw, currencyRaw) {
  const amount =
    Number(amountRaw);

  const exponent =
    billingCurrencyExponentSrv(
      currencyRaw
    );

  if (
    !Number.isFinite(amount) ||
    amount <= 0 ||
    exponent === null
  ) {
    return null;
  }

  const minor =
    Math.round(
      (amount + Number.EPSILON) *
      (10 ** exponent)
    );

  return Number.isSafeInteger(minor) &&
    minor > 0
      ? minor
      : null;
}

function billingNormalizeProviderSrv(v) {
  const provider =
    String(v || '')
      .trim()
      .toLowerCase();

  return /^[a-z0-9][a-z0-9_-]{1,39}$/
    .test(provider)
      ? provider
      : '';
}

function billingNormalizeProviderReferenceSrv(v) {
  const ref =
    String(v || '').trim();

  if (
    ref.length < 3 ||
    ref.length > 200 ||
    /[\u0000-\u001f\u007f]/.test(ref)
  ) {
    return '';
  }

  return ref;
}

function billingPaymentIdSrv(
  provider,
  providerReference
) {
  return `pay_${
    billingSha256Srv(
      `${provider}|${providerReference}`
    ).slice(0, 40)
  }`;
}
const BILLING_PAYMENT_METHODS_SRV = Object.freeze({
  manual: Object.freeze({
    provider: 'manual',
    label: 'دفع بتحويل أو اتفاق مباشر',
    mode: 'manual_confirmation'
  })
});

function billingPaymentMethodPublicSrv(method = {}) {
  return {
    provider:
      String(method?.provider || '').trim(),

    label:
      String(method?.label || '').trim(),

    mode:
      String(method?.mode || '').trim()
  };
}

function billingPaymentMethodSrv(providerRaw) {
  const provider =
    billingNormalizeProviderSrv(
      providerRaw
    );

  return provider
    ? BILLING_PAYMENT_METHODS_SRV[provider] || null
    : null;
}

async function billingStartPaymentProviderSrv({
  provider,
  orderId
} = {}) {
  if (provider === 'manual') {
    return {
      provider: 'manual',
      started: true,

      nextAction: {
        type: 'manual_confirmation',
        orderId,

        message:
  'استخدم رقم طلب التجديد عند إتمام الدفع مع إدارة مُرَبِّيك. لن يتم تفعيل الاشتراك إلا بعد تأكيد الدفع. طلب الدفع صالح لمدة 72 ساعة من إنشائه.'
      }
    };
  }

  throw billingPublicErrorSrv(
    409,
    'billing_provider_not_available',
    '❌ وسيلة الدفع المختارة غير متاحة الآن.'
  );
}
function billingOrderIdSrv(
  userId,
  idempotencyKey
) {
  const digest =
    billingSha256Srv(
      `${
        String(userId || '').trim()
      }|${idempotencyKey}`
    );

  return `ord_${digest.slice(0, 40)}`;
}

function billingBillableHashSrv(numbers) {
  const normalized = [
    ...new Set(
      (
        Array.isArray(numbers)
          ? numbers
          : []
      )
        .map(
          v =>
            String(v || '').trim()
        )
        .filter(Boolean)
    )
  ].sort();

  return billingSha256Srv(
    JSON.stringify(normalized)
  );
}

async function billingBuildPricingSnapshotSrv(
  req,
  billingCycle
) {
  const cycle =
    billingNormalizeCycleSrv(
      billingCycle
    );

  if (!cycle) {
    throw billingPublicErrorSrv(
      422,
      'billing_cycle_invalid',
      '❌ اختر دورة اشتراك شهرية أو سنوية.'
    );
  }

  const country =
    await pricingReadAccountCountrySrv(
      req
    );

  if (!country) {
    throw billingPublicErrorSrv(
      422,
      'pricing_country_missing',
      '❌ دولة الحساب غير مسجلة، لذلك تعذّر تحديد سعر مُرَبِّيك.'
    );
  }

  const pricingRegion =
    pricingRegionForCountrySrv(
      country
    );

  if (!pricingRegion) {
    throw billingPublicErrorSrv(
      422,
      'pricing_country_unsupported',
      '❌ التسعير الحالي متاح لمصر والدول العربية فقط.'
    );
  }

  const [
    { catalog, source },
    billable
  ] = await Promise.all([
    pricingLoadCatalogSrv(),

    pricingBillableFemalesForTenantSrv(
      req.userId
    )
  ]);

  /*
   * الـ Preview يستطيع استخدام fallback عند فشل
   * قراءة كتالوج Firestore.
   *
   * الدفع لا يفعل ذلك:
   * لا ننشئ Order مالي بسعر لم نستطع التحقق منه.
   */
  if (
    source ===
    'server_default_after_read_failure'
  ) {
    throw billingPublicErrorSrv(
      503,
      'billing_pricing_unverified',
      '❌ تعذّر التحقق من سعر الاشتراك الآن. حاول مرة أخرى لاحقًا.'
    );
  }

  const price =
    catalog.regions[
      pricingRegion
    ];

  const totals =
    pricingComputeTotalsSrv({
      price,

      billableCount:
        billable.count,

      annualMonthsCharged:
        catalog.annualMonthsCharged
    });

  const amount =
    cycle === 'annual'
      ? totals.annualSubtotal
      : totals.monthlySubtotal;

  if (
    !Number.isFinite(amount) ||
    amount <= 0
  ) {
    throw billingPublicErrorSrv(
      503,
      'billing_amount_invalid',
      '❌ تعذّر تثبيت قيمة الاشتراك الآن. حاول مرة أخرى لاحقًا.'
    );
  }

 const currency =
  String(price.currency || '')
    .trim()
    .toUpperCase();

const currencyExponent =
  billingCurrencyExponentSrv(
    currency
  );

const amountMinor =
  billingAmountMinorSrv(
    amount,
    currency
  );

if (
  currencyExponent === null ||
  amountMinor === null
) {
  throw billingPublicErrorSrv(
    503,
    'billing_currency_unsupported',
    '❌ تعذّر تجهيز عملة الاشتراك للدفع الآن. حاول مرة أخرى لاحقًا.'
  );
}

return {
  billingCycle: cycle,

  amount,
  amountMinor,
  currencyExponent,

  currency,

  pricingSnapshot: {
      country,

      pricingRegion,

      pricingVersion:
        String(
          catalog.version || ''
        ).trim() ||
        null,

      pricingSource:
        source,

      billableFemales:
        Number(
          billable.count || 0
        ),

      breakdown: {
        mothers:
          Number(
            billable.mothersCount || 0
          ),

        reproductiveHeifers:
          Number(
            billable
              .reproductiveHeifersCount ||
            0
          ),

        cows:
          Number(
            billable.cowCount || 0
          ),

        buffalo:
          Number(
            billable.buffaloCount || 0
          )
      },

      baseMonthly:
        Number(
          price.baseMonthly || 0
        ),

      perBillableFemaleMonthly:
        Number(
          price
            .perBillableFemaleMonthly ||
          0
        ),

      monthlySubtotal:
        totals.monthlySubtotal,

      annualMonthsCharged:
        Number(
          catalog
            .annualMonthsCharged ||
          0
        ),

      annualSubtotal:
        totals.annualSubtotal,

      billablePopulationHash:
        billingBillableHashSrv(
          billable.animalNumbers
        )
    }
  };
}
function billingOrderCurrentIdSrv(
  subscription = {}
) {
  return String(
    subscription?.pendingBillingOrderId || ''
  )
    .trim()
    .toLowerCase();
}

function billingOrderExpiresAtMsSrv(
  order = {}
) {
  const explicitMs =
    subscriptionTimestampMsSrv(
      order?.expiresAt
    );

  if (explicitMs !== null) {
    return explicitMs;
  }

  const createdAtMs =
    subscriptionTimestampMsSrv(
      order?.createdAt
    );

  if (createdAtMs === null) {
    return null;
  }

  return createdAtMs +
    BILLING_ORDER_TTL_MS_SRV;
}

function billingOrderEffectiveStatusSrv(
  orderIdRaw,
  order = {},
  subscription = null,
  nowMs = Date.now()
) {
  const storedStatus =
    String(order?.status || '')
      .trim()
      .toLowerCase();

  if (storedStatus !== 'pending_payment') {
    return storedStatus;
  }

  const orderId =
    String(orderIdRaw || '')
      .trim()
      .toLowerCase();

  if (
    !subscription ||
    typeof subscription !== 'object' ||
    billingOrderCurrentIdSrv(subscription) !==
      orderId
  ) {
    return 'superseded';
  }

  const expiresAtMs =
    billingOrderExpiresAtMsSrv(order);

  if (
    expiresAtMs === null ||
    Number(nowMs) > expiresAtMs
  ) {
    return 'expired';
  }

  return 'pending_payment';
}
function billingPublicOrderSrv(
  orderId,
  order = {}
) {
  return {
    orderId:
      String(
        orderId || ''
      ).trim(),

    orderVersion:
      String(
        order?.orderVersion || ''
      ).trim() ||
      null,

   status:
  String(
    order?.effectiveBillingStatus ||
    order?.status ||
    ''
  )
    .trim()
    .toLowerCase() ||
  null,

    billingCycle:
      billingNormalizeCycleSrv(
        order?.billingCycle
      ) ||
      null,

    currency:
      String(
        order?.currency || ''
      )
        .trim()
        .toUpperCase() ||
      null,

   amount:
  Number.isFinite(
    Number(order?.amount)
  )
    ? Number(order.amount)
    : null,

amountMinor:
  Number.isSafeInteger(
    Number(order?.amountMinor)
  )
    ? Number(order.amountMinor)
    : billingAmountMinorSrv(
        order?.amount,
        order?.currency
      ),

currencyExponent:
  Number.isInteger(
    Number(order?.currencyExponent)
  )
    ? Number(order.currencyExponent)
    : billingCurrencyExponentSrv(
        order?.currency
      ),

pricingVersion:
      String(
        order
          ?.pricingSnapshot
          ?.pricingVersion ||
        ''
      ).trim() ||
      null,

    pricingRegion:
      String(
        order
          ?.pricingSnapshot
          ?.pricingRegion ||
        ''
      ).trim() ||
      null,

    country:
      String(
        order
          ?.pricingSnapshot
          ?.country ||
        ''
      ).trim() ||
      null,

    billableFemales:
      Number.isFinite(
        Number(
          order
            ?.pricingSnapshot
            ?.billableFemales
        )
      )
        ? Number(
            order
              .pricingSnapshot
              .billableFemales
          )
        : null,

    paymentProvider:
      String(
        order?.paymentProvider || ''
      ).trim() ||
      null,

    paymentId:
      String(
        order?.paymentId || ''
      ).trim() ||
      null,

    createdAt:
      subscriptionIsoSrv(
        order?.createdAt
      ),
    expiresAt:
  (() => {
    const ms =
      billingOrderExpiresAtMsSrv(
        order
      );

    return ms === null
      ? null
      : new Date(ms).toISOString();
  })(),
    paidAt:
      subscriptionIsoSrv(
        order?.paidAt
      )
  };
}

async function billingCreateCheckoutOrderSrv({
  req,
  billingCycle,
  idempotencyKey,
  source =
    'server:/api/billing/checkout'
} = {}) {
  if (!db) {
    throw billingPublicErrorSrv(
      503,
      'billing_unavailable',
      '❌ تعذّر بدء عملية الاشتراك الآن. حاول مرة أخرى لاحقًا.'
    );
  }

  const userId =
    String(
      req?.userId || ''
    ).trim();

  if (!userId) {
    throw billingPublicErrorSrv(
      401,
      'auth_required',
      '❌ يلزم تسجيل الدخول أولًا.'
    );
  }

  const idemKey =
    billingNormalizeIdempotencyKeySrv(
      idempotencyKey
    );

  if (!idemKey) {
    throw billingPublicErrorSrv(
      400,
      'idempotency_key_required',
      '❌ تعذّر بدء عملية الاشتراك بأمان. أعد المحاولة.'
    );
  }

  const quote =
    await billingBuildPricingSnapshotSrv(
      req,
      billingCycle
    );

  const orderId =
    billingOrderIdSrv(
      userId,
      idemKey
    );

  const requestFingerprint =
    billingSha256Srv(
      JSON.stringify({
        userId,
        billingCycle:
          quote.billingCycle
      })
    );

  const orderRef =
    db
      .collection('billing_orders')
      .doc(orderId);

  const subscriptionRef =
    db
      .collection('subscriptions')
      .doc(userId);

  const nowTs =
    admin.firestore.Timestamp.now();

  const expiresAt =
    admin.firestore.Timestamp.fromMillis(
      nowTs.toMillis() +
      BILLING_ORDER_TTL_MS_SRV
    );

  return db.runTransaction(
    async tx => {
      const existingSnap =
        await tx.get(orderRef);

      const subscriptionSnap =
        await tx.get(
          subscriptionRef
        );

      if (!subscriptionSnap.exists) {
        throw billingPublicErrorSrv(
          409,
          'billing_subscription_missing',
          '❌ تعذّر ربط عملية الاشتراك بحسابك. حاول مرة أخرى.'
        );
      }

      const subscription =
        subscriptionSnap.data() || {};

      const previousOrderId =
        billingOrderCurrentIdSrv(
          subscription
        );

      let previousOrderRef = null;
      let previousOrderSnap = null;

      if (
        previousOrderId &&
        previousOrderId !== orderId &&
        /^ord_[a-f0-9]{40}$/
          .test(previousOrderId)
      ) {
        previousOrderRef =
          db
            .collection('billing_orders')
            .doc(previousOrderId);

        previousOrderSnap =
          await tx.get(
            previousOrderRef
          );
      }

      if (existingSnap.exists) {
        const existing =
          existingSnap.data() || {};

        const sameRequest =
          String(
            existing?.userId || ''
          ).trim() === userId &&

          String(
            existing
              ?.requestFingerprint ||
            ''
          ).trim() ===
            requestFingerprint;

        if (!sameRequest) {
          throw billingPublicErrorSrv(
            409,
            'idempotency_conflict',
            '❌ تعذّر إعادة استخدام طلب الاشتراك السابق. أعد المحاولة من جديد.'
          );
        }

        return {
          created: false,
          replayed: true,
          orderId,

          order: {
            ...existing,

            effectiveBillingStatus:
              billingOrderEffectiveStatusSrv(
                orderId,
                existing,
                subscription
              )
          }
        };
      }

      const ownerUid =
        String(
          subscription?.ownerUid ||
          req?.authSession?.uid ||
          userId
        ).trim() ||
        userId;

      const order = {
        orderId,

        orderVersion:
          BILLING_ORDER_VERSION_SRV,

        userId,
        ownerUid,

        status:
          'pending_payment',

        billingCycle:
          quote.billingCycle,

        currency:
          quote.currency,

        amount:
          quote.amount,

        amountMinor:
          quote.amountMinor,

        currencyExponent:
          quote.currencyExponent,

        pricingSnapshot: {
          ...quote.pricingSnapshot,

          capturedAt:
            nowTs
        },

        subscriptionStatusAtCheckout:
          String(
            subscription?.status || ''
          )
            .trim()
            .toLowerCase() ||
          null,

        effectiveSubscriptionStatusAtCheckout:
          subscriptionEffectiveStatusSrv(
            subscription
          ),

        paymentProvider:
          null,

        paymentId:
          null,

        providerReference:
          null,

        paidAt:
          null,

        expiresAt,

        idempotencyKeyHash:
          billingSha256Srv(
            idemKey
          ),

        requestFingerprint,

        createdAt:
          nowTs,

        updatedAt:
          nowTs,

        source
      };

      if (
        previousOrderRef &&
        previousOrderSnap?.exists
      ) {
        const previousOrder =
          previousOrderSnap.data() || {};

        if (
          String(
            previousOrder?.status || ''
          )
            .trim()
            .toLowerCase() ===
            'pending_payment'
        ) {
          tx.set(
            previousOrderRef,
            {
              status:
                'superseded',

              supersededByOrderId:
                orderId,

              supersededAt:
                nowTs,

              updatedAt:
                nowTs
            },
            { merge: true }
          );
        }
      }

      tx.set(
        orderRef,
        order,
        { merge: false }
      );

      tx.set(
        subscriptionRef,
        {
          pendingBillingOrderId:
            orderId,

          pendingBillingOrderExpiresAt:
            expiresAt,

          pendingBillingOrderUpdatedAt:
            nowTs,

          updatedAt:
            nowTs
        },
        { merge: true }
      );

      return {
        created: true,
        replayed: false,
        orderId,
        order
      };
    }
  );
}

app.post(
  '/api/billing/checkout',
  requireUserId,
  async (req, res) => {
    try {
      res.set(
        'Cache-Control',
        'no-store'
      );

      const result =
        await billingCreateCheckoutOrderSrv({
          req,

          billingCycle:
            req.body?.billingCycle,

          idempotencyKey:
            req.get(
              'Idempotency-Key'
            ) ||
            ''
        });

      return res
        .status(
          result.created
            ? 201
            : 200
        )
        .json({
          ok: true,

          created:
            result.created ===
            true,

          replayed:
            result.replayed ===
            true,

          order:
            billingPublicOrderSrv(
              result.orderId,
              result.order
            )
        });

    } catch (e) {
      console.error(
        'billing.checkout failed:',
        e.message || e
      );

      if (
        Number(
          e?.publicStatus
        )
      ) {
        return res
          .status(
            Number(
              e.publicStatus
            )
          )
          .json({
            ok: false,

            error:
              String(
                e.publicError ||
                'billing_checkout_failed'
              ),

            message:
              String(
                e.publicMessage ||
                '❌ تعذّر بدء عملية الاشتراك الآن. حاول مرة أخرى.'
              )
          });
      }

      return res
        .status(500)
        .json({
          ok: false,

          error:
            'billing_checkout_failed',

          message:
            '❌ تعذّر بدء عملية الاشتراك الآن. حاول مرة أخرى.'
        });
    }
  }
);

