app.post(
  '/api/billing/checkout/:orderId/start-payment',
  requireUserId,
  async (req, res) => {
    try {
      res.set(
        'Cache-Control',
        'no-store'
      );

      if (!db) {
        throw billingPublicErrorSrv(
          503,
          'billing_unavailable',
          '❌ خدمة الدفع غير متاحة الآن.'
        );
      }

      const userId =
        String(
          req.userId || ''
        ).trim();

      const orderId =
        String(
          req.params?.orderId || ''
        )
          .trim()
          .toLowerCase();

      if (
        !/^ord_[a-f0-9]{40}$/
          .test(orderId)
      ) {
        throw billingPublicErrorSrv(
          404,
          'billing_order_not_found',
          '❌ طلب الاشتراك غير موجود.'
        );
      }

      const method =
        billingPaymentMethodSrv(
          req.body?.provider
        );

      if (!method) {
        throw billingPublicErrorSrv(
          409,
          'billing_provider_not_available',
          '❌ وسيلة الدفع المختارة غير متاحة الآن.'
        );
      }

      const orderRef =
        db
          .collection(
            'billing_orders'
          )
          .doc(orderId);

      const subscriptionRef =
        db
          .collection('subscriptions')
          .doc(userId);

      const selected =
        await db.runTransaction(
          async tx => {
            const snap =
              await tx.get(
                orderRef
              );

            const subscriptionSnap =
              await tx.get(
                subscriptionRef
              );

            if (!snap.exists) {
              throw billingPublicErrorSrv(
                404,
                'billing_order_not_found',
                '❌ طلب الاشتراك غير موجود.'
              );
            }

            const order =
              snap.data() || {};

            if (
              String(
                order?.userId || ''
              ).trim() !==
              userId
            ) {
              throw billingPublicErrorSrv(
                404,
                'billing_order_not_found',
                '❌ طلب الاشتراك غير موجود.'
              );
            }

            if (!subscriptionSnap.exists) {
              throw billingPublicErrorSrv(
                409,
                'billing_subscription_missing',
                '❌ اشتراك الحساب غير موجود.'
              );
            }

            const subscription =
              subscriptionSnap.data() || {};

            if (
              billingOrderCurrentIdSrv(
                subscription
              ) !== orderId
            ) {
              throw billingPublicErrorSrv(
                409,
                'billing_order_superseded',
                'ℹ️ طلب الدفع هذا لم يعد هو الطلب الحالي. أنشئ طلبًا جديدًا.'
              );
            }

            if (
              billingOrderEffectiveStatusSrv(
                orderId,
                order,
                subscription
              ) === 'expired'
            ) {
              throw billingPublicErrorSrv(
                409,
                'billing_order_expired',
                'ℹ️ انتهت صلاحية طلب الدفع. أنشئ طلبًا جديدًا بالسعر الحالي.'
              );
            }

            const status =
              String(
                order?.status || ''
              )
                .trim()
                .toLowerCase();

            if (status === 'paid') {
              throw billingPublicErrorSrv(
                409,
                'billing_order_already_paid',
                'ℹ️ طلب الاشتراك مدفوع بالفعل.'
              );
            }

            if (
              status !==
              'pending_payment'
            ) {
              throw billingPublicErrorSrv(
                409,
                'billing_order_not_payable',
                '❌ طلب الاشتراك الحالي غير قابل للدفع.'
              );
            }

            const existingProvider =
              String(
                order?.paymentProvider ||
                ''
              )
                .trim()
                .toLowerCase();

            if (
              existingProvider &&
              existingProvider !==
                method.provider
            ) {
              throw billingPublicErrorSrv(
                409,
                'billing_payment_provider_conflict',
                '❌ تم بدء هذا الطلب بوسيلة دفع أخرى.'
              );
            }

            if (
              existingProvider ===
              method.provider
            ) {
              return {
                replayed: true,
                order
              };
            }

            const nowTs =
              admin.firestore
                .Timestamp.now();

            tx.set(
              orderRef,
              {
                paymentProvider:
                  method.provider,

                paymentInitiatedAt:
                  nowTs,

                updatedAt:
                  nowTs
              },
              { merge: true }
            );

            return {
              replayed: false,

              order: {
                ...order,

                paymentProvider:
                  method.provider,

                paymentInitiatedAt:
                  nowTs,

                updatedAt:
                  nowTs
              }
            };
          }
        );

      const providerResult =
        await billingStartPaymentProviderSrv({
          provider:
            method.provider,

          orderId
        });

      return res.json({
        ok: true,

        replayed:
          selected.replayed ===
          true,

        method:
          billingPaymentMethodPublicSrv(
            method
          ),

        order:
          billingPublicOrderSrv(
            orderId,
            selected.order
          ),

        nextAction:
          providerResult.nextAction
      });

    } catch (e) {
      console.error(
        'billing start payment failed:',
        e.message || e
      );

      const status =
        Number(
          e?.publicStatus || 500
        );

      return res
        .status(status)
        .json({
          ok: false,

          error:
            String(
              e?.publicError ||
              'billing_payment_start_failed'
            ),

          message:
            String(
              e?.publicMessage ||
              '❌ تعذّر بدء وسيلة الدفع الآن.'
            )
        });
    }
  }
);
// ============================================================
//      BILLING PAYMENTS — VERIFIED SETTLEMENT CORE
// ============================================================
function billingAddCalendarMonthsSrv(
  startMsRaw,
  monthsRaw
) {
  const startMs =
    Number(startMsRaw);

  const months =
    Number(monthsRaw);

  if (
    !Number.isFinite(startMs) ||
    !Number.isInteger(months) ||
    months < 1
  ) {
    return null;
  }

  const d =
    new Date(startMs);

  if (
    !Number.isFinite(d.getTime())
  ) {
    return null;
  }

  const day =
    d.getUTCDate();

  const target =
    new Date(
      Date.UTC(
        d.getUTCFullYear(),
        d.getUTCMonth() + months,
        1,
        d.getUTCHours(),
        d.getUTCMinutes(),
        d.getUTCSeconds(),
        d.getUTCMilliseconds()
      )
    );

  const lastDay =
    new Date(
      Date.UTC(
        target.getUTCFullYear(),
        target.getUTCMonth() + 1,
        0
      )
    ).getUTCDate();

  target.setUTCDate(
    Math.min(
      day,
      lastDay
    )
  );

  return target.getTime();
}

function billingPaidPeriodMonthsSrv(cycleRaw) {
  const cycle =
    billingNormalizeCycleSrv(
      cycleRaw
    );

  if (cycle === 'monthly') return 1;
  if (cycle === 'annual') return 12;

  return 0;
}

function billingEntitlementAfterPaymentSrv({
  subscription = {},
  billingCycle,
  paidAtMs = Date.now()
} = {}) {
  const nowMs =
    Number(paidAtMs);

  const months =
    billingPaidPeriodMonthsSrv(
      billingCycle
    );

  if (
    !Number.isFinite(nowMs) ||
    !months
  ) {
    throw billingPublicErrorSrv(
      409,
      'billing_period_invalid',
      '❌ تعذّر حساب مدة الاشتراك الجديدة.'
    );
  }

  const effectiveStatus =
    subscriptionEffectiveStatusSrv(
      subscription,
      nowMs
    );

  if (effectiveStatus === 'invalid') {
    throw billingPublicErrorSrv(
      409,
      'billing_subscription_state_invalid',
      '❌ حالة الاشتراك الحالية غير صالحة للتجديد.'
    );
  }

  const trialEndMs =
    subscriptionTimestampMsSrv(
      subscription?.trialEndsAt
    );

  const periodEndMs =
    subscriptionTimestampMsSrv(
      subscription?.currentPeriodEnd
    );

  let anchorMs =
    nowMs;

  // الدفع المبكر لا يهدر الأيام المتبقية.
  if (
    effectiveStatus === 'trial' &&
    Number.isFinite(trialEndMs) &&
    trialEndMs > nowMs
  ) {
    anchorMs =
      trialEndMs;

  } else if (
    (
      effectiveStatus === 'active' ||
      effectiveStatus === 'cancelled'
    ) &&
    Number.isFinite(periodEndMs) &&
    periodEndMs > nowMs
  ) {
    anchorMs =
      periodEndMs;

  } else if (
    effectiveStatus === 'grace' &&
    Number.isFinite(periodEndMs)
  ) {
    const candidateEnd =
      billingAddCalendarMonthsSrv(
        periodEndMs,
        months
      );

    if (
      Number.isFinite(candidateEnd) &&
      candidateEnd > nowMs
    ) {
      anchorMs =
        periodEndMs;
    }
  }

  let endMs =
    billingAddCalendarMonthsSrv(
      anchorMs,
      months
    );

  if (
    !Number.isFinite(endMs) ||
    endMs <= nowMs
  ) {
    anchorMs =
      nowMs;

    endMs =
      billingAddCalendarMonthsSrv(
        anchorMs,
        months
      );
  }

  if (
    !Number.isFinite(endMs) ||
    endMs <= nowMs
  ) {
    throw billingPublicErrorSrv(
      503,
      'billing_period_compute_failed',
      '❌ تعذّر حساب مدة الاشتراك الجديدة.'
    );
  }

  return {
    previousEffectiveStatus:
      effectiveStatus,

    periodStartMs:
      nowMs,

    entitlementAnchorMs:
      anchorMs,

    periodEndMs:
      endMs,

    monthsAdded:
      months
  };
}

async function billingApplyVerifiedPaymentSrv({
  orderId: orderIdRaw,
  provider: providerRaw,
  providerReference: providerReferenceRaw,
  verifiedAmountMinor: verifiedAmountMinorRaw,
  verifiedCurrency: verifiedCurrencyRaw,
  verificationSource =
    'server:billing_verified_payment',
  actorUid = null
} = {}) {
  if (!db) {
    throw billingPublicErrorSrv(
      503,
      'billing_unavailable',
      '❌ خدمة الدفع غير متاحة الآن.'
    );
  }

  const orderId =
    String(orderIdRaw || '')
      .trim()
      .toLowerCase();

  const provider =
    billingNormalizeProviderSrv(
      providerRaw
    );

  const providerReference =
    billingNormalizeProviderReferenceSrv(
      providerReferenceRaw
    );

  const verifiedAmountMinor =
    Number(
      verifiedAmountMinorRaw
    );

  const verifiedCurrency =
    String(
      verifiedCurrencyRaw || ''
    )
      .trim()
      .toUpperCase();

  if (
    !/^ord_[a-f0-9]{40}$/
      .test(orderId)
  ) {
    throw billingPublicErrorSrv(
      404,
      'billing_order_not_found',
      '❌ طلب الاشتراك غير موجود.'
    );
  }

  if (
    !provider ||
    !providerReference
  ) {
    throw billingPublicErrorSrv(
      400,
      'billing_provider_invalid',
      '❌ بيانات مزود الدفع غير صالحة.'
    );
  }

  if (
    !Number.isSafeInteger(
      verifiedAmountMinor
    ) ||
    verifiedAmountMinor <= 0
  ) {
    throw billingPublicErrorSrv(
      400,
      'billing_verified_amount_invalid',
      '❌ قيمة الدفع المؤكدة غير صالحة.'
    );
  }

  if (
    !/^[A-Z]{3}$/
      .test(verifiedCurrency)
  ) {
    throw billingPublicErrorSrv(
      400,
      'billing_verified_currency_invalid',
      '❌ عملة الدفع المؤكدة غير صالحة.'
    );
  }

  const paymentId =
    billingPaymentIdSrv(
      provider,
      providerReference
    );

  const orderRef =
    db
      .collection('billing_orders')
      .doc(orderId);

  const paymentRef =
    db
      .collection('billing_payments')
      .doc(paymentId);

  const eventRef =
    db
      .collection('billing_payment_events')
      .doc(`${paymentId}__paid`);

  return db.runTransaction(
    async tx => {
      // كل القراءات قبل الكتابة.
      const orderSnap =
        await tx.get(orderRef);

      if (!orderSnap.exists) {
        throw billingPublicErrorSrv(
          404,
          'billing_order_not_found',
          '❌ طلب الاشتراك غير موجود.'
        );
      }

      const order =
        orderSnap.data() || {};

      const userId =
        String(
          order?.userId || ''
        ).trim();

      if (!userId) {
        throw billingPublicErrorSrv(
          409,
          'billing_order_owner_missing',
          '❌ طلب الاشتراك غير مرتبط بحساب صالح.'
        );
      }

      const subscriptionRef =
        db
          .collection('subscriptions')
          .doc(userId);

      const paymentSnap =
        await tx.get(paymentRef);

      const subscriptionSnap =
        await tx.get(
          subscriptionRef
        );

      if (!subscriptionSnap.exists) {
        throw billingPublicErrorSrv(
          409,
          'billing_subscription_missing',
          '❌ اشتراك الحساب غير موجود.'
        );
      }

      const subscription =
        subscriptionSnap.data() || {};

      const orderCurrency =
        String(
          order?.currency || ''
        )
          .trim()
          .toUpperCase();

     const orderAmountMinor =
  Number.isSafeInteger(
    Number(order?.amountMinor)
  )
    ? Number(order.amountMinor)
    : billingAmountMinorSrv(
        order?.amount,
        orderCurrency
      );

const initiatedProvider =
  String(
    order?.paymentProvider || ''
  )
    .trim()
    .toLowerCase();

if (
  initiatedProvider &&
  initiatedProvider !== provider
) {
  throw billingPublicErrorSrv(
    409,
    'billing_payment_provider_mismatch',
    '🚫 مزود الدفع المؤكد لا يطابق وسيلة الدفع التي بدأ بها الطلب.'
  );
}

if (
        !orderCurrency ||
        !Number.isSafeInteger(
          orderAmountMinor
        ) ||
        orderAmountMinor <= 0
      ) {
        throw billingPublicErrorSrv(
          409,
          'billing_order_amount_invalid',
          '❌ قيمة طلب الاشتراك غير صالحة للتسوية.'
        );
      }

      if (
        verifiedCurrency !==
          orderCurrency ||
        verifiedAmountMinor !==
          orderAmountMinor
      ) {
        throw billingPublicErrorSrv(
          409,
          'billing_payment_amount_mismatch',
          '🚫 قيمة أو عملة الدفع لا تطابق طلب الاشتراك.'
        );
      }

      if (paymentSnap.exists) {
        const p =
          paymentSnap.data() || {};

        const samePayment =
          String(
            p?.orderId || ''
          ).trim() === orderId &&

          String(
            p?.provider || ''
          )
            .trim()
            .toLowerCase() ===
            provider &&

          String(
            p?.providerReference || ''
          ).trim() ===
            providerReference &&

          Number(
            p?.amountMinor
          ) ===
            orderAmountMinor &&

          String(
            p?.currency || ''
          )
            .trim()
            .toUpperCase() ===
            orderCurrency &&

          String(
            p?.status || ''
          )
            .trim()
            .toLowerCase() ===
            'paid';

        if (!samePayment) {
          throw billingPublicErrorSrv(
            409,
            'billing_provider_reference_conflict',
            '🚫 مرجع الدفع مستخدم بالفعل لعملية أخرى.'
          );
        }

        if (
          String(
            order?.status || ''
          )
            .trim()
            .toLowerCase() ===
            'paid' &&

          String(
            order?.paymentId || ''
          ).trim() ===
            paymentId
        ) {
          return {
            settled:
              false,

            replayed:
              true,

            orderId,
            paymentId,
            userId,

            subscription:
              subscriptionPublicStateSrv(
                subscription
              )
          };
        }

        throw billingPublicErrorSrv(
          409,
          'billing_payment_state_conflict',
          '🚫 حالة الدفع لا تتطابق مع طلب الاشتراك.'
        );
      }

      const orderStatus =
        String(
          order?.status || ''
        )
          .trim()
          .toLowerCase();

      if (orderStatus === 'paid') {
        throw billingPublicErrorSrv(
          409,
          'billing_order_already_paid',
          'ℹ️ طلب الاشتراك مدفوع بالفعل.'
        );
      }

      if (
        orderStatus !==
        'pending_payment'
      ) {
        throw billingPublicErrorSrv(
          409,
          'billing_order_not_payable',
          '❌ طلب الاشتراك الحالي غير قابل للدفع.'
        );
      }
     if (
  billingOrderCurrentIdSrv(
    subscription
  ) !== orderId
) {
  throw billingPublicErrorSrv(
    409,
    'billing_order_superseded',
    'ℹ️ طلب الدفع هذا لم يعد هو الطلب الحالي للحساب.'
  );
}

if (
  billingOrderEffectiveStatusSrv(
    orderId,
    order,
    subscription
  ) === 'expired'
) {
  throw billingPublicErrorSrv(
    409,
    'billing_order_expired',
    'ℹ️ انتهت صلاحية طلب الدفع. أنشئ طلبًا جديدًا بالسعر الحالي.'
  );
}
      const cycle =
        billingNormalizeCycleSrv(
          order?.billingCycle
        );

      if (!cycle) {
        throw billingPublicErrorSrv(
          409,
          'billing_order_cycle_invalid',
          '❌ دورة الاشتراك داخل الطلب غير صالحة.'
        );
      }

      const nowTs =
        admin.firestore.Timestamp.now();

      const nowMs =
        nowTs.toMillis();

      const entitlement =
        billingEntitlementAfterPaymentSrv({
          subscription,
          billingCycle:
            cycle,
          paidAtMs:
            nowMs
        });

      const periodStart =
        admin.firestore.Timestamp
          .fromMillis(
            entitlement.periodStartMs
          );

      const periodEnd =
        admin.firestore.Timestamp
          .fromMillis(
            entitlement.periodEndMs
          );

      const actor =
        String(actorUid || '')
          .trim() ||
        null;

      const source =
        String(
          verificationSource || ''
        ).trim() ||
        'server:billing_verified_payment';

      tx.set(
        paymentRef,
        {
          paymentId,

          paymentVersion:
            'billing-payment-v1',

          orderId,
          userId,

          ownerUid:
            String(
              order?.ownerUid ||
              subscription?.ownerUid ||
              userId
            ).trim() ||
            userId,

          status:
            'paid',

          provider,
          providerReference,

          currency:
            orderCurrency,

          amount:
            Number(
              order?.amount
            ),

          amountMinor:
            orderAmountMinor,

          currencyExponent:
            Number.isInteger(
              Number(
                order?.currencyExponent
              )
            )
              ? Number(
                  order.currencyExponent
                )
              : billingCurrencyExponentSrv(
                  orderCurrency
                ),

          billingCycle:
            cycle,

          pricingSnapshot:
            order?.pricingSnapshot ||
            null,

          verifiedAt:
            nowTs,

          verificationSource:
            source,

          verifiedByUid:
            actor,

          createdAt:
            nowTs,

          updatedAt:
            nowTs
        },
        { merge: false }
      );

      tx.set(
        orderRef,
        {
          status:
            'paid',

          paymentProvider:
            provider,

          paymentId,

          providerReference,

          paidAt:
            nowTs,

          updatedAt:
            nowTs
        },
        { merge: true }
      );

      const subscriptionPatch = {
        status:
          'active',

        billingCycle:
          cycle,

        currentPeriodStart:
          periodStart,

        currentPeriodEnd:
          periodEnd,

        graceEndsAt:
          null,

        paymentProvider:
          provider,

        lastPaymentId:
          paymentId,

        lastPaymentOrderId:
          orderId,

        lastPaidAt:
          nowTs,
        pendingBillingOrderId:
  null,

pendingBillingOrderExpiresAt:
  null,

pendingBillingOrderUpdatedAt:
  nowTs,
        updatedAt:
          nowTs,

        source:
          'server:billing_verified_payment'
      };

      tx.set(
        subscriptionRef,
        subscriptionPatch,
        { merge: true }
      );

      tx.set(
        eventRef,
        {
          eventVersion:
            'billing-payment-event-v1',

          eventType:
            'payment_settled',

          paymentId,
          orderId,
          userId,

          provider,
          providerReference,

          amountMinor:
            orderAmountMinor,

          currency:
            orderCurrency,

          billingCycle:
            cycle,

          previousEffectiveSubscriptionStatus:
            entitlement
              .previousEffectiveStatus,

          currentPeriodStart:
            periodStart,

          currentPeriodEnd:
            periodEnd,

          verificationSource:
            source,

          actorUid:
            actor,

          occurredAt:
            nowTs
        },
        { merge: false }
      );

      return {
        settled:
          true,

        replayed:
          false,

        orderId,
        paymentId,
        userId,

        subscription:
          subscriptionPublicStateSrv(
            {
              ...subscription,
              ...subscriptionPatch
            },
            nowMs
          )
      };
    }
  );
}

// مزود دائم للدفعات التي تعتمدها إدارة مُرَبِّيك.
// أي Gateway إلكتروني لاحقًا يستدعي نفس Settlement Core
// بعد التحقق من الـWebhook والمبلغ والعملة.
app.post(
  '/api/admin/billing/payments/manual/confirm',
  ensureAccountAdminClaimSrv,
  async (req, res) => {
    try {
      if (!db) {
        return res.status(503).json({
          ok: false,
          error:
            'billing_unavailable',
          message:
            '❌ خدمة الدفع غير متاحة الآن.'
        });
      }

      const orderId =
        String(
          req.body?.orderId || ''
        )
          .trim()
          .toLowerCase();

      const providerReference =
        billingNormalizeProviderReferenceSrv(
          req.body?.providerReference
        );

      if (
        !/^ord_[a-f0-9]{40}$/
          .test(orderId)
      ) {
        return res.status(404).json({
          ok: false,
          error:
            'billing_order_not_found',
          message:
            '❌ طلب الاشتراك غير موجود.'
        });
      }

      if (!providerReference) {
        return res.status(400).json({
          ok: false,
          error:
            'billing_provider_reference_invalid',
          message:
            '❌ أدخل مرجعًا صحيحًا للدفع المؤكد.'
        });
      }

      const orderSnap =
        await db
          .collection('billing_orders')
          .doc(orderId)
          .get();

      if (!orderSnap.exists) {
        return res.status(404).json({
          ok: false,
          error:
            'billing_order_not_found',
          message:
            '❌ طلب الاشتراك غير موجود.'
        });
      }

      const order =
        orderSnap.data() || {};

      const currency =
        String(
          order?.currency || ''
        )
          .trim()
          .toUpperCase();

      const amountMinor =
        Number.isSafeInteger(
          Number(order?.amountMinor)
        )
          ? Number(order.amountMinor)
          : billingAmountMinorSrv(
              order?.amount,
              currency
            );

      if (
        !currency ||
        !Number.isSafeInteger(
          amountMinor
        ) ||
        amountMinor <= 0
      ) {
        return res.status(409).json({
          ok: false,
          error:
            'billing_order_amount_invalid',
          message:
            '❌ قيمة طلب الاشتراك غير صالحة للتأكيد.'
        });
      }

      const actorUid =
        String(
          req.accountAdminAuth?.uid ||
          req.accountAdminAuth?.sub ||
          ''
        ).trim();

      const result =
        await billingApplyVerifiedPaymentSrv({
          orderId,

          provider:
            'manual',

          providerReference,

          verifiedAmountMinor:
            amountMinor,

          verifiedCurrency:
            currency,

          verificationSource:
            'server:/api/admin/billing/payments/manual/confirm',

          actorUid
        });

      return res.json({
        ok: true,
        ...result
      });

    } catch (e) {
      console.error(
        'billing manual confirm failed:',
        e.message || e
      );

      const status =
        Number(
          e?.publicStatus || 500
        );

      return res
        .status(status)
        .json({
          ok: false,

          error:
            String(
              e?.publicError ||
              'billing_manual_confirm_failed'
            ),

          message:
            String(
              e?.publicMessage ||
              '❌ تعذّر تأكيد الدفع الآن.'
            )
        });
    }
  }
);
// ============================================================
//      SUBSCRIPTION ENGINE — CORE + 30-DAY TRIAL (NO GATE)
// ============================================================
const SUBSCRIPTION_TRIAL_DAYS_SRV = 30;
const SUBSCRIPTION_DAY_MS_SRV = 24 * 60 * 60 * 1000;

const SUBSCRIPTION_STATUSES_SRV = new Set([
  'trial',
  'active',
  'grace',
  'expired',
  'cancelled'
]);

function subscriptionTimestampMsSrv(v) {
  if (!v) return null;

  try {
    if (typeof v.toMillis === 'function') {
      const ms = Number(v.toMillis());
      return Number.isFinite(ms) ? ms : null;
    }

    if (typeof v.toDate === 'function') {
      const ms = v.toDate().getTime();
      return Number.isFinite(ms) ? ms : null;
    }

    if (Number.isFinite(Number(v?._seconds))) {
      return Number(v._seconds) * 1000;
    }

    const ms = new Date(v).getTime();
    return Number.isFinite(ms) ? ms : null;
  } catch (_) {
    return null;
  }
}

function subscriptionIsoSrv(v) {
  const ms = subscriptionTimestampMsSrv(v);
  return ms === null ? null : new Date(ms).toISOString();
}

function subscriptionEffectiveStatusSrv(
  subscription = {},
  nowMs = Date.now()
) {
  const storedStatus =
    String(subscription?.status || '')
      .trim()
      .toLowerCase();

  if (!SUBSCRIPTION_STATUSES_SRV.has(storedStatus)) {
    return 'invalid';
  }

  if (storedStatus === 'cancelled') return 'cancelled';
  if (storedStatus === 'expired') return 'expired';

  if (storedStatus === 'trial') {
    const trialEndsAtMs =
      subscriptionTimestampMsSrv(
        subscription?.trialEndsAt
      );

    if (trialEndsAtMs === null) return 'invalid';

    return nowMs <= trialEndsAtMs
      ? 'trial'
      : 'expired';
  }

  if (storedStatus === 'active') {
    const periodEndMs =
      subscriptionTimestampMsSrv(
        subscription?.currentPeriodEnd
      );

    if (
      periodEndMs !== null &&
      nowMs <= periodEndMs
    ) {
      return 'active';
    }

    const graceEndsAtMs =
      subscriptionTimestampMsSrv(
        subscription?.graceEndsAt
      );

    if (
      graceEndsAtMs !== null &&
      nowMs <= graceEndsAtMs
    ) {
      return 'grace';
    }

    return periodEndMs === null
      ? 'invalid'
      : 'expired';
  }

  if (storedStatus === 'grace') {
    const graceEndsAtMs =
      subscriptionTimestampMsSrv(
        subscription?.graceEndsAt
      );

    if (graceEndsAtMs === null) {
      return 'invalid';
    }

    return nowMs <= graceEndsAtMs
      ? 'grace'
      : 'expired';
  }

  return 'invalid';
}

function subscriptionTrialDaysRemainingSrv(
  subscription = {},
  nowMs = Date.now()
) {
  const effectiveStatus =
    subscriptionEffectiveStatusSrv(
      subscription,
      nowMs
    );

  if (effectiveStatus !== 'trial') {
    return 0;
  }

  const trialEndsAtMs =
    subscriptionTimestampMsSrv(
      subscription?.trialEndsAt
    );

  if (trialEndsAtMs === null) return 0;

  return Math.max(
    0,
    Math.ceil(
      (trialEndsAtMs - nowMs) /
      SUBSCRIPTION_DAY_MS_SRV
    )
  );
}

async function subscriptionCreateTrialIfMissingSrv({
  tenant,
  profile = {},
  source = 'server:subscription_trial_init'
} = {}) {
  if (!db) {
    throw new Error(
      'subscription_firestore_unavailable'
    );
  }

  const userId =
    String(tenant || '').trim();

  if (!userId) {
    throw new Error(
      'subscription_user_id_required'
    );
  }

  const country =
    String(profile?.country || '').trim();

  const pricingRegion =
    pricingRegionForCountrySrv(country);

  const { catalog } =
    await pricingLoadCatalogSrv();

  const nowTs =
    admin.firestore.Timestamp.now();

  const trialEndsAt =
    admin.firestore.Timestamp.fromMillis(
      nowTs.toMillis() +
      (
        SUBSCRIPTION_TRIAL_DAYS_SRV *
        SUBSCRIPTION_DAY_MS_SRV
      )
    );

  const subscriptionRef =
    db
      .collection('subscriptions')
      .doc(userId);

  const trialStartedMilestoneRef =
    db
      .collection('subscription_lifecycle_milestones')
      .doc(`${userId}__trial_started`);

  return db.runTransaction(async tx => {
    const existing =
      await tx.get(subscriptionRef);

    // لا نعيد بدء Trial ولا نمدده لو الوثيقة موجودة.
    if (existing.exists) {
      const data =
        existing.data() || {};

      return {
        created: false,
        userId,

        status:
          String(data.status || '')
            .trim()
            .toLowerCase() ||
          null,

        effectiveStatus:
          subscriptionEffectiveStatusSrv(
            data
          )
      };
    }

    const ownerUid =
      String(
        profile?.ownerUid ||
        profile?.uid ||
        userId
      ).trim() || userId;

    const doc = {
      userId,
      ownerUid,

      status: 'trial',

      subscriptionPolicyVersion:
        'trial-30d-v1',

      country,

      pricingRegion:
        pricingRegion || null,

      pricingVersionAtTrialStart:
        String(
          catalog?.version || ''
        ).trim() || null,

      trialDays:
        SUBSCRIPTION_TRIAL_DAYS_SRV,

      trialStartedAt:
        nowTs,

      trialEndsAt,

      billingCycle:
        null,

      currentPeriodStart:
        null,

      currentPeriodEnd:
        null,

      graceEndsAt:
        null,

      paymentProvider:
        null,

      lastPaymentId:
        null,

      createdAt:
        nowTs,

      updatedAt:
        nowTs,

      source
    };

        tx.set(
      subscriptionRef,
      doc,
      { merge: false }
    );

    // Lifecycle milestone is written atomically with Trial creation.
    // Deterministic document id keeps trial_started idempotent.
    tx.set(
      trialStartedMilestoneRef,
      {
        userId,
        ownerUid,
        milestone: 'trial_started',
        milestoneVersion: 'subscription-lifecycle-v1',
        subscriptionStatus: 'trial',
        subscriptionPolicyVersion: 'trial-30d-v1',
        country,
        pricingRegion: pricingRegion || null,
        pricingVersion:
          String(
            catalog?.version || ''
          ).trim() || null,
        trialDays: SUBSCRIPTION_TRIAL_DAYS_SRV,
        trialStartedAt: nowTs,
        trialEndsAt,
        occurredAt: nowTs,
        source
      },
      { merge: false }
    );

    return {
      created: true,
      userId,
      status: 'trial',
      effectiveStatus: 'trial',
      trialEndsAt
    };
  });
}
async function subscriptionLifecycleMarkOnceSrv({
  userId,
  milestone,
  source = 'server:subscription-lifecycle',
  details = {}
} = {}) {
  const uid = String(userId || '').trim();
  const name = String(milestone || '').trim();

  if (!db || !uid || !name) {
    return {
      created: false,
      skipped: true
    };
  }

  const subscriptionRef =
    db.collection('subscriptions').doc(uid);

  const milestoneRef =
    db
      .collection('subscription_lifecycle_milestones')
      .doc(`${uid}__${name}`);

  const safeDetails =
    details &&
    typeof details === 'object' &&
    !Array.isArray(details)
      ? details
      : {};

  try {
    return await db.runTransaction(async tx => {
      const subscriptionSnap =
        await tx.get(subscriptionRef);

      if (!subscriptionSnap.exists) {
        return {
          created: false,
          skipped: true
        };
      }

      const milestoneSnap =
        await tx.get(milestoneRef);

      if (milestoneSnap.exists) {
        return {
          created: false,
          skipped: false
        };
      }

      const subscription =
        subscriptionSnap.data() || {};

      tx.set(
        milestoneRef,
        {
          ...safeDetails,

          userId: uid,

          ownerUid:
            String(
              subscription?.ownerUid || uid
            ).trim() || uid,

          milestone: name,

          milestoneVersion:
            'subscription-lifecycle-v1',

          subscriptionStatus:
            String(subscription?.status || '')
              .trim()
              .toLowerCase() ||
            null,

          effectiveSubscriptionStatus:
            subscriptionEffectiveStatusSrv(
              subscription
            ),

          trialStartedAt:
            subscription?.trialStartedAt || null,

          trialEndsAt:
            subscription?.trialEndsAt || null,

          occurredAt:
            admin.firestore.FieldValue
              .serverTimestamp(),

          source:
            String(source || '').trim() || null
        },
        { merge: false }
      );

      return {
        created: true,
        skipped: false
      };
    });

  } catch (e) {
    console.warn(
      'subscription lifecycle milestone failed:',
      uid,
      name,
      e.message || e
    );

    return {
      created: false,
      skipped: false,
      error:
        String(e?.message || e || '').trim() ||
        'subscription_lifecycle_write_failed'
    };
  }
}
function subscriptionPublicStateSrv(
  subscription = {},
  nowMs = Date.now()
) {
  const storedStatus =
    String(subscription?.status || '')
      .trim()
      .toLowerCase() ||
    null;

  const effectiveStatus =
    subscriptionEffectiveStatusSrv(
      subscription,
      nowMs
    );

  return {
    initialized: true,

    status:
      storedStatus,

    effectiveStatus,

    country:
      String(
        subscription?.country || ''
      ).trim() ||
      null,

    pricingRegion:
      String(
        subscription?.pricingRegion || ''
      ).trim() ||
      null,

    pricingVersionAtTrialStart:
      String(
        subscription?.pricingVersionAtTrialStart ||
        ''
      ).trim() ||
      null,

    trialDays:
      Number(
        subscription?.trialDays || 0
      ) || 0,

    trialStartedAt:
      subscriptionIsoSrv(
        subscription?.trialStartedAt
      ),

    trialEndsAt:
      subscriptionIsoSrv(
        subscription?.trialEndsAt
      ),

    trialDaysRemaining:
      subscriptionTrialDaysRemainingSrv(
        subscription,
        nowMs
      ),

    billingCycle:
      String(
        subscription?.billingCycle || ''
      ).trim() ||
      null,

    currentPeriodStart:
      subscriptionIsoSrv(
        subscription?.currentPeriodStart
      ),

    currentPeriodEnd:
      subscriptionIsoSrv(
        subscription?.currentPeriodEnd
      ),

    graceEndsAt:
      subscriptionIsoSrv(
        subscription?.graceEndsAt
      )
  };
}

