// ============================================================
//      SUBSCRIPTION ACCESS — LEGACY / MANAGED RECONCILIATION
// ============================================================
async function subscriptionAccessDocumentSrv(
  req,
  source = 'server:subscription-access-reconcile'
) {
  const userId =
    String(req.userId || '').trim();

  if (!userId) {
    const err = new Error('subscription_user_id_missing');
    err.code = 'subscription_user_id_missing';
    throw err;
  }

  const subscriptionRef =
    db
      .collection('subscriptions')
      .doc(userId);

  let snap =
    await subscriptionRef.get();

  if (snap.exists) {
    return {
      legacyUnmanaged: false,
      snap
    };
  }

  const uid =
    String(
      req.authSession?.uid ||
      userId
    ).trim();

  let profileSnap =
    await db
      .collection('users')
      .doc(uid)
      .get();

  if (
    !profileSnap.exists &&
    uid !== userId
  ) {
    profileSnap =
      await db
        .collection('users')
        .doc(userId)
        .get();
  }

  const profile =
    profileSnap.exists
      ? (profileSnap.data() || {})
      : {};

  // الحسابات القديمة فقط تظل Legacy إذا لم تُعلَّم كاشتراك مُدار.
  if (profile.subscriptionManaged !== true) {
    return {
      legacyUnmanaged: true,
      snap: null
    };
  }

  // حساب جديد مُدار فقد مستند الاشتراك:
  // نعيد محاولة إنشاء الـ Trial بدل تحويله إلى Legacy مجاني.
  await subscriptionCreateTrialIfMissingSrv({
    tenant: userId,
    profile,
    source
  });

  snap =
    await subscriptionRef.get();

  if (!snap.exists) {
    const err =
      new Error(
        'managed_subscription_missing_after_reconcile'
      );

    err.code =
      'managed_subscription_missing_after_reconcile';

    throw err;
  }

  return {
    legacyUnmanaged: false,
    snap
  };
}
// ============================================================
//       SUBSCRIPTION ACCESS GATE — APP-WIDE API CORE
// ============================================================
async function requireSubscriptionAccessSrv(req, res, next) {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        error: 'subscription_unavailable',
        message:
          '❌ تعذّر التحقق من الاشتراك الآن. حاول مرة أخرى لاحقًا.'
      });
    }

    const userId =
      String(req.userId || '').trim();

    if (!userId) {
      return res.status(401).json({
        ok: false,
        error: 'auth_required',
        message: '❌ يلزم تسجيل الدخول أولًا.'
      });
    }

       const accessDoc =
      await subscriptionAccessDocumentSrv(
        req,
        'server:api-subscription-gate-reconcile'
      );

    // الحسابات القديمة غير المُدارة بالاشتراك تظل كما هي.
    if (accessDoc.legacyUnmanaged) {
      req.subscriptionAccess = {
        initialized: false,
        managed: false,
        effectiveStatus: null,
        gateDecision: 'allow',
        reason: 'legacy_unmanaged'
      };

      return next();
    }

    const subscription =
      accessDoc.snap.data() || {};
    const decision =
      subscriptionAccessDecisionPreviewSrv(
        subscription
      );

    req.subscriptionAccess = {
      initialized: true,
      ...decision,
      gateDecision:
        decision.futureGateDecision
    };

    if (decision.futureGateDecision === 'allow') {
      return next();
    }

    if (decision.effectiveStatus === 'expired') {
      return res.status(402).json({
        ok: false,
        error: 'subscription_expired',
        message:
          'ℹ️ انتهت مدة اشتراك مُرَبِّيك. جدّد الاشتراك لاستمرار الاستخدام.'
      });
    }

    if (decision.effectiveStatus === 'cancelled') {
      return res.status(402).json({
        ok: false,
        error: 'subscription_cancelled',
        message:
          'ℹ️ اشتراك مُرَبِّيك غير نشط حاليًا. فعّل الاشتراك لاستمرار الاستخدام.'
      });
    }

    // أي حالة تالفة أو غير مفهومة تفشل بأمان.
    return res.status(503).json({
      ok: false,
      error: 'subscription_state_invalid',
      message:
        '❌ تعذّر التحقق من حالة الاشتراك الآن. حاول مرة أخرى لاحقًا.'
    });

  } catch (e) {
    console.error(
      'subscription access gate failed:',
      e.message || e
    );

    return res.status(503).json({
      ok: false,
      error: 'subscription_access_check_failed',
      message:
        '❌ تعذّر التحقق من الاشتراك الآن. حاول مرة أخرى لاحقًا.'
    });
  }
}

