app.post('/api/groups/sync', requireUserId, async (req, res) => {
  try {
    if (!db) return res.status(503).json({ ok:false, error:'firestore_disabled' });

const tenant = req.userId;
const groups = Array.isArray(req.body?.groups) ? req.body.groups : [];
const members = Array.isArray(req.body?.members) ? req.body.members : [];

const partial = req.body?.partial === true;
const finalize = req.body?.finalize === true;
const desiredMemberIds = Array.isArray(req.body?.desiredMemberIds)
  ? req.body.desiredMemberIds.map(x => String(x || '').trim()).filter(Boolean)
  : null;

    let batch = db.batch();
    let ops = 0;

    for (const g of groups) {
      const groupId = String(g?.groupId || '').trim();
      if (!groupId) continue;

      const ref = db.collection('groups').doc(`${tenant}_${groupId}`);
      batch.set(ref, {
        ...g,
        userId: tenant,
        updatedAt: admin.firestore.FieldValue.serverTimestamp()
      }, { merge:true });

      ops++;
      if (ops >= 400) {
        await batch.commit();
        batch = db.batch();
        ops = 0;
      }
    }

    const desiredIds = new Set(desiredMemberIds || []);

    for (const m of members) {
      const groupId = String(m?.groupId || '').trim();
      const animalNumber = String(m?.animalNumber || '').trim();
      if (!groupId || !animalNumber) continue;

      const memberId = `${tenant}_${groupId}_${animalNumber}`;
      if (!desiredMemberIds) desiredIds.add(memberId);

      const ref = db.collection('groups_members').doc(memberId);
      batch.set(ref, {
        ...m,
        userId: tenant,
        updatedAt: admin.firestore.FieldValue.serverTimestamp()
      }, { merge:true });

      ops++;
      if (ops >= 400) {
        await batch.commit();
        batch = db.batch();
        ops = 0;
      }
    }

    if (ops > 0) {
      await batch.commit();
    }

if (!partial && (finalize || desiredIds.size > 0)) {
  const oldSnap = await db.collection('groups_members').where('userId', '==', tenant).get();

  if (!oldSnap.empty) {
    let delBatch = db.batch();
    let delOps = 0;

    for (const ds of oldSnap.docs) {
      if (!desiredIds.has(ds.id)) {
        delBatch.delete(ds.ref);
        delOps++;
        if (delOps >= 400) {
          await delBatch.commit();
          delBatch = db.batch();
          delOps = 0;
        }
      }
    }

    if (delOps > 0) {
      await delBatch.commit();
    }
  }
}

 if (groups.length) {
  await syncAnimalGroupFieldsSrv(tenant, groups);
}

return res.json({
  ok: true,
  savedGroups: groups.length,
  savedMembers: members.length,
  animalsSynced: true
});
  } catch (e) {
    console.error('groups.sync', e);
    return res.status(500).json({ ok:false, error:'groups_sync_failed' });
  }
});
function dimFromDatesSrv(calvingISO, eventISO){
  const a = String(calvingISO || '').slice(0,10);
  const b = String(eventISO || '').slice(0,10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(a) || !/^\d{4}-\d{2}-\d{2}$/.test(b)) return null;
  const d = diffDaysISO(a, b);
  return Number.isFinite(d) && d >= 1 ? d : null;
}

function solveLinear3x3Srv(A, b){
  const m = A.map((row,i)=>[...row, b[i]]);
  const n = 3;

  for(let col=0; col<n; col++){
    let pivot = col;
    for(let r=col+1; r<n; r++){
      if (Math.abs(m[r][col]) > Math.abs(m[pivot][col])) pivot = r;
    }
    if (Math.abs(m[pivot][col]) < 1e-12) return null;
    if (pivot !== col) [m[col], m[pivot]] = [m[pivot], m[col]];

    const div = m[col][col];
    for(let c=col; c<=n; c++) m[col][c] /= div;

    for(let r=0; r<n; r++){
      if (r === col) continue;
      const f = m[r][col];
      for(let c=col; c<=n; c++) m[r][c] -= f * m[col][c];
    }
  }
  return [m[0][3], m[1][3], m[2][3]];
}

function aliSchaefferBasisSrv(dim){
  const t = Number(dim);
  if (!Number.isFinite(t) || t < 1) return null;
  const x = t / 305;
  if (x <= 0) return null;
  return [1, x, x*x, Math.log(1/x), Math.log(1/x)*Math.log(1/x)];
}

function breedClassSrv(species, breed = ''){
  const s = String(species || '').toLowerCase();
  const b = String(breed || '').toLowerCase();

  if (/buffalo|جاموس/.test(s)) return 'buffalo';
  if (/holstein|هولشتاين|هولستين/.test(b)) return 'holstein';
  if (/montbeliarde|مونتبليارد/.test(b)) return 'montbeliarde';
  if (/simmental|سيمنتال/.test(b)) return 'simmental';
  return 'cow';
}

function prior305Srv({ species, breed, parity } = {}){
  const cls = breedClassSrv(species, breed);
  const p = Number(parity || 0);

  const table = {
    buffalo:      { p1: 1800, p2: 2200, p3: 2400 },
    holstein:     { p1: 7500, p2: 9200, p3: 9800 },
    montbeliarde: { p1: 6200, p2: 7600, p3: 8200 },
    simmental:    { p1: 5600, p2: 7000, p3: 7600 },
    cow:          { p1: 6000, p2: 7600, p3: 8200 }
  };

  const row = table[cls] || table.cow;
  if (p <= 1) return row.p1;
  if (p === 2) return row.p2;
  return row.p3;
}

function projectLactation305AliSchaefferSrv({
  milkSeries = [],
  lastCalvingDate,
  species,
  breed,
  parity
} = {}){
  const pts = (Array.isArray(milkSeries) ? milkSeries : [])
    .map(p => {
      const dim = p.dim ?? dimFromDatesSrv(lastCalvingDate, p.date);
      const y = Number(p.kg);
      return { dim: Number(dim), y };
    })
    .filter(p => Number.isFinite(p.dim) && p.dim >= 5 && p.dim <= 305 && Number.isFinite(p.y) && p.y > 0)
    .sort((a,b) => a.dim - b.dim);

// شروط صلاحية مرنة لمُرَبِّيك:
// 1) لازم على الأقل 5 نقاط فعلية
// 2) لازم يكون فيها تنوع حقيقي في DIM
const uniqDims = [...new Set(pts.map(p => p.dim))];
if (uniqDims.length < 5) return null;

const dimSpan = Math.max(...uniqDims) - Math.min(...uniqDims);
const fitQuality =
  dimSpan >= 60 ? 'high' :
  dimSpan >= 25 ? 'medium' :
  'low';
  // y = β0 + β1*x + β2*x² + β3*ln(1/x) + β4*ln²(1/x)
  // نثبّت β3, β4 على priors بسيطة حسب النوع/الموسم، ونحل 3x3 للباقي
  const prior305 = prior305Srv({ species, breed, parity });
  const peakScale =
    /buffalo|جاموس/i.test(String(species || '')) ? 0.55 :
    Number(parity || 0) <= 1 ? 0.82 : 1.0;

  const beta3 = 7.5 * peakScale;
  const beta4 = -1.25 * peakScale;

  let s00=0,s01=0,s02=0,s11=0,s12=0,s22=0;
  let t0=0,t1=0,t2=0;

  for (const p of pts){
    const basis = aliSchaefferBasisSrv(p.dim);
    if (!basis) continue;
    const [b0,b1,b2,b3v,b4v] = basis;
    const yy = p.y - (beta3 * b3v + beta4 * b4v);

    s00 += b0*b0; s01 += b0*b1; s02 += b0*b2;
    s11 += b1*b1; s12 += b1*b2; s22 += b2*b2;

    t0 += b0*yy; t1 += b1*yy; t2 += b2*yy;
  }

  // regularization خفيفة باتجاه prior معقول
  const ridge = 0.25;
  const A = [
    [s00 + ridge, s01,         s02],
    [s01,         s11 + ridge, s12],
    [s02,         s12,         s22 + ridge]
  ];

  const avgDailyPrior = prior305 / 305;
  const b = [
    t0 + ridge * avgDailyPrior,
    t1 + ridge * 0,
    t2 + ridge * 0
  ];

  const sol = solveLinear3x3Srv(A, b);
  if (!sol) return null;
  const [beta0, beta1, beta2] = sol;

  let total305 = 0;
  for(let d=1; d<=305; d++){
    const basis = aliSchaefferBasisSrv(d);
    if (!basis) continue;
    const [b0,b1,b2,b3v,b4v] = basis;
    const yhat = beta0*b0 + beta1*b1 + beta2*b2 + beta3*b3v + beta4*b4v;
    total305 += Math.max(0, yhat);
  }

  if (!Number.isFinite(total305) || total305 <= 0) return null;

return {
  m305Kg: Math.round(total305),
  model: 'ali_schaeffer',
  pointsUsed: uniqDims.length,
  dimMin: Math.min(...uniqDims),
  dimMax: Math.max(...uniqDims),
  fitQuality
};
}
// ============================================================
//                 CARD HELPERS — cow/calves server source
// ============================================================
function cardTextSrv(v, fallback = '—') {
  if (v === null || v === undefined || v === '') return fallback;
  if (Array.isArray(v)) return v.map(x => cardTextSrv(x, '')).filter(Boolean).join('، ') || fallback;
  if (typeof v === 'object') {
    const d = cardISODateSrv(v);
    if (d) return d;
    const txt = Object.values(v).map(x => cardTextSrv(x, '')).filter(Boolean).join('، ');
    return txt || fallback;
  }
  return String(v).trim() || fallback;
}

function cardFirstSrv(obj = {}, keys = [], fallback = null) {
  for (const k of keys) {
    const v = obj?.[k];
    if (v !== null && v !== undefined && String(v).trim() !== '') return v;
  }
  return fallback;
}

function cardISODateSrv(v) {
  if (!v) return null;
  if (typeof v === 'string') {
    const m = v.match(/\d{4}-\d{2}-\d{2}/);
    if (m) return m[0];
  }
  try {
    const d = toDate(v);
    if (d && !Number.isNaN(d.getTime())) return toYYYYMMDD(d);
  } catch (_) {}
  return null;
}

function cardAgeTextSrv(birthDate) {
  const bd = cardISODateSrv(birthDate);
  if (!bd) return { ageDays: null, ageText: '—' };

  const ageDays = daysBetweenIsoSrv(bd, cairoTodayISO());
  if (!Number.isFinite(ageDays) || ageDays < 0) return { ageDays: null, ageText: '—' };

  if (ageDays < 30) return { ageDays, ageText: `${ageDays} يوم` };

  if (ageDays < 365) {
    const months = Math.floor(ageDays / 30);
    const days = ageDays % 30;
    return {
      ageDays,
      ageText: days ? `${months} شهر و ${days} يوم` : `${months} شهر`
    };
  }

  const years = Math.floor(ageDays / 365);
  const months = Math.floor((ageDays % 365) / 30);

  return {
    ageDays,
    ageText: months ? `${years} سنة و ${months} شهر` : `${years} سنة`
  };
}

function cardNormalizeSexSrv(v) {
  const s = String(v || '').trim().toLowerCase();
  if (!s) return null;

  if (/female|f\b|انث|أنث|عجلة|عجله/.test(s)) return 'أنثى';
  if (/male|m\b|ذكر|عجل/.test(s)) return 'ذكر';

  return String(v).trim();
}

function cardSubjectNumberSrv(obj = {}) {
  return normalizeDigitsSrv(
    obj.animalNumber ?? obj.number ?? obj.calfNumber ?? obj.no ?? obj.tag ?? ''
  );
}

function cardNumberSetSrv(values = []) {
  const out = new Set();

  for (const v of values) {
    if (v === null || v === undefined || v === '') continue;

    const raw = String(v).trim();
    if (raw) out.add(raw);

    const dig = normalizeDigitsSrv(raw);
    if (dig) out.add(dig);

    const n = Number(dig || raw);
    if (Number.isFinite(n)) out.add(String(n));
  }

  return out;
}

function cardSubjectNumbersSrv(subject = {}) {
  return cardNumberSetSrv([
    subject.animalNumber,
    subject.number,
    subject.calfNumber,
    subject.no,
    subject.tag
  ]);
}

function cardSubjectIdsSrv(subject = {}) {
  return new Set([
    subject.id,
    subject.animalId,
    subject.calfId,
    subject.docId
  ].map(v => String(v || '').trim()).filter(Boolean));
}

async function findCardDocByIdSrv(uid, collectionName, id) {
  const docId = String(id || '').trim();
  if (!db || !uid || !collectionName || !docId) return null;

  try {
    const d = await db.collection(collectionName).doc(docId).get();
    if (!d.exists) return null;

    const row = d.data() || {};
    const owner = String(row.userId || row.ownerUid || '').trim();

    if (owner && owner !== uid) return null;

    return {
      id: d.id,
      _collection: collectionName,
      ...row
    };
  } catch (_) {
    return null;
  }
}

async function findCardDocByNumberSrv(uid, collectionName, number, numberFields = ['animalNumber', 'number']) {
  if (!db || !uid || !collectionName) return null;

  const numberStr = normalizeDigitsSrv(number);
  if (!numberStr) return null;

  const seen = new Set();

  const push = d => {
    if (!d || !d.exists || seen.has(d.id)) return null;

    seen.add(d.id);

    return {
      id: d.id,
      _collection: collectionName,
      ...(d.data() || {})
    };
  };

  const tenantNumberKey = `${uid}#${numberStr}`;

  try {
    const s = await db.collection(collectionName)
      .where('userId_number', '==', tenantNumberKey)
      .limit(1)
      .get();

    if (!s.empty) return push(s.docs[0]);
  } catch (_) {}

  const vals = findAnimalNumberMatches(numberStr);

  for (const ownerField of ['userId', 'ownerUid']) {
    for (const field of numberFields) {
      for (const v of vals) {
        try {
          const s = await db.collection(collectionName)
            .where(ownerField, '==', uid)
            .where(field, '==', v)
            .limit(1)
            .get();

          if (!s.empty) return push(s.docs[0]);
        } catch (_) {}
      }
    }
  }

  return null;
}

async function findCowCardDocSrv(uid, { number, animalId } = {}) {
  const byId = await findCardDocByIdSrv(uid, 'animals', animalId);
  if (byId) return byId;

  return findCardDocByNumberSrv(uid, 'animals', number, ['animalNumber', 'number']);
}

async function findCalfCardDocSrv(uid, { number, calfId } = {}) {
  const byId = await findCardDocByIdSrv(uid, 'calves', calfId);
  if (byId) return byId;

  return findCardDocByNumberSrv(uid, 'calves', number, ['calfNumber', 'animalNumber', 'number']);
}

async function fetchCardEventsSrv(uid, subject = {}) {
  if (!db || !uid || !subject) return [];

  const rows = [];
  const seen = new Set();

  const pushDocs = (docs = []) => {
    for (const d of docs) {
      if (!d || !d.id || seen.has(d.id)) continue;

      seen.add(d.id);
      rows.push({
        id: d.id,
        ...(d.data() || {})
      });
    }
  };

  const ids = cardSubjectIdsSrv(subject);

  for (const id of ids) {
    for (const field of ['animalId', 'calfId', 'subject.animalId', 'subject.calfId']) {
      try {
        const s = await db.collection('events')
          .where('userId', '==', uid)
          .where(field, '==', id)
         .limit(3000)
          .get();

        pushDocs(s.docs);
      } catch (_) {}
    }
  }

  const nums = [...cardSubjectNumbersSrv(subject)];

  for (const field of ['animalNumber', 'number', 'calfNumber']) {
    for (const raw of nums) {
      const vals = findAnimalNumberMatches(raw);

      for (const v of vals) {
        try {
          const s = await db.collection('events')
            .where('userId', '==', uid)
            .where(field, '==', v)
            .limit(3000)
            .get();

          pushDocs(s.docs);
        } catch (_) {}
      }
    }
  }

  return rows.sort((a, b) =>
    String(computeEventDateFromDoc(a) || '').localeCompare(String(computeEventDateFromDoc(b) || ''))
  );
}

function cardEventTitleSrv(e = {}) {
  const direct = cardFirstSrv(e, [
    'displayName',
    'eventNameAr',
    'pageTitleAr',
    'nameAr',
    'titleAr',
    'labelAr',
    'eventName',
    'name',
    'title',
    'label',
    'eventTypeAr',
    'eventType',
    'type',
    'kind',
    'diseaseName',
    'diagnosis',
    'pregnancyResult',
    'heatStatus'
  ], '');

  const raw = String(direct || '').trim();

  if (raw && /[\u0600-\u06FF]/.test(raw)) return raw;

  const type = eventTypeForCardSrv(e);

 const map = {
  milk: 'لبن يومي',
  calving: 'ولادة',
  insemination: 'تلقيح',
  pregnancy: 'تشخيص حمل',
  heat: 'شياع',
  dry: 'تجفيف',
  close_up: 'تحضير للولادة',
  disease: 'حالة صحية',
  other: 'حدث'
};

  return map[type] || raw || 'حدث';
}

function cardEventSummarySrv(e = {}) {
  const existing = cardFirstSrv(e, ['summary', 'shortSummary', 'message', 'detailsText'], '');
  if (existing) return cardTextSrv(existing, '—');

  const type = eventTypeForCardSrv(e);

  if (type === 'milk') {
    const kg = milkKgFromEventSrv(e);
    return kg > 0 ? `${Math.round(kg * 100) / 100} كجم` : '—';
  }

  if (type === 'insemination') {
    const bull = cardFirstSrv(e, ['semenCode', 'bull', 'sire', 'sireNumber', 'straw'], '');
    const method = cardFirstSrv(e, ['method', 'inseminationMethod'], '');

    return [
      method ? `الطريقة: ${method}` : '',
      bull ? `الطلوقة: ${bull}` : ''
    ].filter(Boolean).join(' — ') || 'تلقيح مسجل';
  }

  if (type === 'pregnancy') {
    const result = cardFirstSrv(e, ['result', 'status', 'pregnancyResult', 'diagnosis'], '');
    return result ? `النتيجة: ${cardTextSrv(result, '')}` : 'تشخيص حمل مسجل';
  }

  if (type === 'calving') {
    const calfNo = cardFirstSrv(e, ['calfNumber', 'calf1Number', 'newCalfNumber'], '');
    const sex = cardFirstSrv(e, ['calfSex', 'sex', 'calf1Sex'], '');

    return [
      calfNo ? `رقم المولود: ${calfNo}` : '',
      sex ? `الجنس: ${sex}` : ''
    ].filter(Boolean).join(' — ') || 'ولادة مسجلة';
  }

  const note = cardFirstSrv(e, ['notes', 'note', 'comment', 'reason', 'description'], '');

  return note ? cardTextSrv(note, '—') : '—';
}

function cardEventDetailsSrv(e = {}) {
  const type =
    eventTypeForCardSrv(e);

  const details = [];

  const add = (label, value) => {
    const text =
      cardTextSrv(value, '');

    if (
      !text ||
      text === '—'
    ) {
      return;
    }

    details.push({
      label,
      value: text
    });
  };


  if (type === 'milk') {
    const kg =
      milkKgFromEventSrv(e);

    if (kg > 0) {
      add(
        'الكمية',
        `${Math.round(kg * 100) / 100} كجم`
      );
    }
  }


  if (type === 'insemination') {
    add(
      'الطلوقة',
      cardFirstSrv(
        e,
        [
          'semenCode',
          'bull',
          'sire',
          'sireNumber',
          'straw'
        ],
        ''
      )
    );

    add(
      'الطريقة',
      cardFirstSrv(
        e,
        [
          'method',
          'inseminationMethod'
        ],
        ''
      )
    );

    add(
      'الملقّح',
      cardFirstSrv(
        e,
        [
          'inseminatorName',
          'inseminator',
          'technicianName',
          'technician'
        ],
        ''
      )
    );
  }


  if (type === 'pregnancy') {
    add(
      'النتيجة',
      cardFirstSrv(
        e,
        [
          'result',
          'status',
          'pregnancyResult',
          'diagnosis'
        ],
        ''
      )
    );

    add(
      'طريقة التشخيص',
      cardFirstSrv(
        e,
        [
          'method',
          'diagnosisMethod',
          'pregnancyMethod'
        ],
        ''
      )
    );
  }


  if (type === 'heat') {
    add(
      'وقت الملاحظة',
      cardFirstSrv(
        e,
        [
          'heatTime',
          'observationTime',
          'timeOfObservation',
          'period'
        ],
        ''
      )
    );
  }


  if (type === 'calving') {
    const calfNumbers =
      [
        e.calfNumber,
        e.calf1Number,
        e.calf2Number,
        e.calf3Number,
        e.newCalfNumber
      ]
        .map(
          v =>
            String(v || '').trim()
        )
        .filter(Boolean);

    const calfSexes =
      [
        e.calfSex,
        e.calf1Sex,
        e.calf2Sex,
        e.calf3Sex
      ]
        .map(
          v =>
            String(v || '').trim()
        )
        .filter(Boolean);


    if (calfNumbers.length) {
      add(
        'المواليد',
        [...new Set(calfNumbers)]
          .join('، ')
      );
    }


    if (calfSexes.length) {
      add(
        'الجنس',
        [...new Set(calfSexes)]
          .join('، ')
      );
    }


    add(
      'نوع الولادة',
      cardFirstSrv(
        e,
        [
          'birthType',
          'calvingType',
          'litterType'
        ],
        ''
      )
    );
  }


  if (type === 'disease') {
    add(
      'التشخيص',
      cardFirstSrv(
        e,
        [
          'diseaseName',
          'diagnosis',
          'condition'
        ],
        ''
      )
    );

    add(
      'العلاج',
      cardFirstSrv(
        e,
        [
          'treatment',
          'treatmentName',
          'medicine'
        ],
        ''
      )
    );
  }


  const note =
    cardFirstSrv(
      e,
      [
        'notes',
        'note',
        'comment',
        'reason',
        'description'
      ],
      ''
    );


  if (note) {
    add(
      'ملاحظة',
      note
    );
  }


  return details.slice(0, 8);
}


function cardEventRowSrv(e = {}) {
  const date =
    computeEventDateFromDoc(e) ||
    cardISODateSrv(e.createdAt) ||
    null;

  return {
    id:
      e.id || '',

    date,

    title:
      cardEventTitleSrv(e),

    summary:
      cardEventSummarySrv(e),

    type:
      eventTypeForCardSrv(e),

    details:
      cardEventDetailsSrv(e)
  };
}


function cardEventSeasonsSrv(
  eventRows = [],
  calvingDates = [],
  currentLactationNumber = null
) {
  const rows =
    (
      Array.isArray(eventRows)
        ? eventRows
        : []
    )
      .filter(
        row =>
          row &&
          (
            row.date ||
            row.title
          )
      )
      .sort(
        (a, b) =>
          String(
            a.date || ''
          ).localeCompare(
            String(
              b.date || ''
            )
          )
      );

  const starts =
    [
      ...new Set(
        (
          Array.isArray(calvingDates)
            ? calvingDates
            : []
        )
          .map(cardISODateSrv)
          .filter(Boolean)
      )
    ].sort();

  const currentLactation =
    Number(currentLactationNumber);

  const hasCurrentLactation =
    Number.isFinite(currentLactation) &&
    currentLactation > 0;

  const seasonLabel = (
    seasonNumber,
    fallback
  ) => {
    const n =
      Number(seasonNumber);

    return (
      Number.isFinite(n) &&
      n > 0
    )
      ? `الموسم ${n}`
      : fallback;
  };

  if (!starts.length) {
    const seasonNumber =
      hasCurrentLactation
        ? currentLactation
        : null;

    return [
      {
        key: 'current',

        label:
          seasonLabel(
            seasonNumber,
            'الموسم الحالي'
          ),

        isCurrent: true,

        seasonNumber,

        // رقم الموسم موجود أصلًا داخل animal.lactationNumber.
        // نتركه فارغًا هنا حتى لا تكرر الصفحة العنوان.
        lactationNumber: null,

        startDate: null,
        nextCalvingDate: null,

        eventCount:
          rows.length,

        events:
          [...rows].reverse()
      }
    ];
  }

  const seasons = [];

  for (
    let i = starts.length - 1;
    i >= 0;
    i--
  ) {
    const startDate =
      starts[i];

    const nextCalvingDate =
      starts[i + 1] ||
      null;

    const distanceFromCurrent =
      (starts.length - 1) - i;

    const seasonNumber =
      hasCurrentLactation
        ? currentLactation -
          distanceFromCurrent
        : null;

    const seasonEvents =
      rows.filter(
        row => {
          const d =
            cardISODateSrv(
              row.date
            );

          if (
            !d ||
            d < startDate
          ) {
            return false;
          }

          if (
            nextCalvingDate &&
            d >= nextCalvingDate
          ) {
            return false;
          }

          return true;
        }
      );

    seasons.push({
      key:
        distanceFromCurrent === 0
          ? 'current'
          : `previous_${distanceFromCurrent}`,

      label:
        seasonLabel(
          seasonNumber,
          distanceFromCurrent === 0
            ? 'الموسم الحالي'
            : (
                distanceFromCurrent === 1
                  ? 'الموسم السابق'
                  : `الموسم السابق ${distanceFromCurrent}`
              )
        ),

      isCurrent:
        distanceFromCurrent === 0,

      seasonNumber:
        Number.isFinite(
          seasonNumber
        ) &&
        seasonNumber > 0
          ? seasonNumber
          : null,

      lactationNumber: null,

      startDate,
      nextCalvingDate,

      eventCount:
        seasonEvents.length,

      events:
        [...seasonEvents]
          .reverse()
    });
  }

  const beforeFirst =
    rows.filter(
      row => {
        const d =
          cardISODateSrv(
            row.date
          );

        return (
          !d ||
          d < starts[0]
        );
      }
    );

  if (beforeFirst.length) {
    const previousSeasonNumber =
      hasCurrentLactation
        ? currentLactation -
          starts.length
        : null;

    const validPreviousSeasonNumber =
      Number.isFinite(
        previousSeasonNumber
      ) &&
      previousSeasonNumber > 0
        ? previousSeasonNumber
        : null;

    seasons.push({
      key:
        'before_first_recorded_season',

      label:
        validPreviousSeasonNumber
          ? `الموسم ${validPreviousSeasonNumber}`
          : (
              hasCurrentLactation &&
              currentLactation === starts.length
                ? 'قبل الموسم 1'
                : 'أحداث قبل أول موسم مسجل'
            ),

      isCurrent: false,

      seasonNumber:
        validPreviousSeasonNumber,

      lactationNumber: null,

      startDate: null,
      nextCalvingDate: starts[0],

      eventCount:
        beforeFirst.length,

      events:
        [...beforeFirst]
          .reverse()
    });
  }

  return seasons;
}

function cardMatchSubjectSrv(row = {}, subject = {}) {
  const nums = cardSubjectNumbersSrv(subject);
  const ids = cardSubjectIdsSrv(subject);

  const rowNums = cardNumberSetSrv([
    row.animalNumber,
    row.number,
    row.calfNumber,
    row.subject?.animalNumber,
    row.subject?.number,
    row.subject?.calfNumber,
    row.animal?.animalNumber,
    row.animal?.number,
    row.calf?.calfNumber,
    row.calf?.number
  ]);

  for (const n of rowNums) {
    if (nums.has(n)) return true;
  }

  const rowIds = new Set([
    row.animalId,
    row.calfId,
    row.subject?.animalId,
    row.subject?.calfId,
    row.subject?.id,
    row.animal?.id,
    row.calf?.id
  ].map(v => String(v || '').trim()).filter(Boolean));

  for (const id of rowIds) {
    if (ids.has(id)) return true;
  }

  return false;
}

function cardAlertRowSrv(row = {}, fallbackTitle = 'تنبيه') {
  return {
    id: row.id || row.taskId || '',
    level: String(row.level || row.severity || row.priority || 'info').toLowerCase(),
    title: cardTextSrv(row.title || row.name || fallbackTitle, fallbackTitle),
    message: cardTextSrv(row.message || row.summary || row.note || row.description || row.reason, '—'),
    dueDate: cardISODateSrv(row.dueDate || row.plannedDate || row.date || row.ts || row.createdAt),
    source: row.source || row.taskType || row.type || ''
  };
}

async function fetchCardAlertsSrv(uid, subject = {}) {
  if (!db || !uid || !subject) return [];

  const out = [];
  const seen = new Set();

  const add = row => {
    const key = String(row.id || row.taskId || `${row.title || ''}_${row.message || ''}_${row.dueDate || ''}`);
    if (seen.has(key)) return;

    seen.add(key);
    out.push(row);
  };

  try {
    const snap = await db.collection('alerts')
      .where('userId', '==', uid)
      .limit(400)
      .get();

    snap.docs.forEach(d => {
      const row = {
        id: d.id,
        ...(d.data() || {})
      };

      if (cardMatchSubjectSrv(row, subject)) {
        add(cardAlertRowSrv(row, 'تنبيه'));
      }
    });
  } catch (_) {}

  try {
    const snap = await db.collection('tasks')
      .where('userId', '==', uid)
      .where('status', '==', 'pending')
      .limit(500)
      .get();

    snap.docs.forEach(d => {
      const t = {
        id: d.id,
        ...(d.data() || {})
      };

      if (t.done === true) return;
      if (!cardMatchSubjectSrv(t, subject)) return;

      const title = cardTextSrv(
        t.title || t.taskTitle || t.stepName || t.taskType || 'مهمة مستحقة',
        'مهمة مستحقة'
      );

      const msg = cardTextSrv(
        t.message || t.note || t.description || t.vaccineKey || t.protocol || title,
        title
      );

      add(cardAlertRowSrv({
        ...t,
        title,
        message: msg,
        level: t.level || 'warn'
      }, 'مهمة مستحقة'));
    });
  } catch (_) {}

  out.sort((a, b) => String(a.dueDate || '').localeCompare(String(b.dueDate || '')));

  return out.slice(0, 8);
}
function cardMilkCurveAnimalClassSrv(a = {}) {
  const s = String(
    a.kind ||
    a.animalTypeAr ||
    a.animaltype ||
    a.species ||
    a.type ||
    ''
  ).trim().toLowerCase();

  if (s.includes('جاموس') || s.includes('buffalo')) return 'buffalo';
  if (s.includes('بقر') || s.includes('cow')) return 'cow';

  return '';
}

function cardMilkDimSrv(e = {}, animal = {}) {
  const direct = Number(
    e.dim ??
    e.DIM ??
    e.daysInMilk ??
    e.daysInMilkAtEvent ??
    e.milkDim ??
    NaN
  );

  if (Number.isFinite(direct) && direct >= 0 && direct <= 500) {
    return direct;
  }

  const eventDate = computeEventDateFromDoc(e);
  const calvingDate = cardISODateSrv(
    animal.lastCalvingDate ||
    animal.lastCalving ||
    animal.calvingDate
  );

  if (!eventDate || !calvingDate) return null;

  const dim = daysBetweenIsoSrv(calvingDate, eventDate);
  return Number.isFinite(dim) && dim >= 0 ? dim : null;
}

function cardStandardMilkBreedSrv(a = {}) {
  const breed = String(
    a.breed ||
    a.breedName ||
    a.breedAr ||
    ''
  ).trim().toLowerCase();

  if (/holstein|هولشتاين|هولستين/.test(breed)) {
    return 'holstein';
  }

  if (/simmental|سيمنتال/.test(breed)) {
    return 'simmental';
  }

  if (/brown\s*swiss|براون\s*سويس|براون سويس/.test(breed)) {
    return 'brown_swiss';
  }

  return 'cow';
}


function cardStandardMilkProfileSrv(a = {}) {
  const cls =
    cardStandardMilkBreedSrv(a);

  const parityRaw =
    Number(
      a.lactationNumber ??
      a.parity ??
      a.lactation ??
      1
    );

  const parity =
    Number.isFinite(parityRaw) &&
    parityRaw > 0
      ? (
          parityRaw === 1
            ? 1
            : (
                parityRaw === 2
                  ? 2
                  : 3
              )
        )
      : 1;

  /*
    Scientific reference:
    Wood lactation curve
    Jeretina, Babnik & Skorjanc (2013)

    Published mean parameters for:
    Holstein / Simmental / Brown Swiss
    parity 1 / 2 / >=3.

    Generic cow is a weighted pooled fallback
    derived from the same published dataset.
  */
  const table = {
    holstein: {
      1: {
        a: 15.7,
        b: 0.184,
        c: 0.00290,
        milk305: 6671
      },

      2: {
        a: 19.3,
        b: 0.193,
        c: 0.00385,
        milk305: 7400
      },

      3: {
        a: 19.4,
        b: 0.212,
        c: 0.00417,
        milk305: 7617
      }
    },

    simmental: {
      1: {
        a: 12.9,
        b: 0.162,
        c: 0.00308,
        milk305: 4847
      },

      2: {
        a: 15.4,
        b: 0.166,
        c: 0.00380,
        milk305: 5285
      },

      3: {
        a: 15.6,
        b: 0.180,
        c: 0.00406,
        milk305: 5426
      }
    },

    brown_swiss: {
      1: {
        a: 13.7,
        b: 0.156,
        c: 0.00298,
        milk305: 5094
      },

      2: {
        a: 16.3,
        b: 0.166,
        c: 0.00375,
        milk305: 5622
      },

      3: {
        a: 16.4,
        b: 0.180,
        c: 0.00400,
        milk305: 5797
      }
    },

    cow: {
      1: {
        a: 14.438,
        b: 0.17223,
        c: 0.002974,
        milk305: 5807
      },

      2: {
        a: 17.481,
        b: 0.17944,
        c: 0.003817,
        milk305: 6390
      },

      3: {
        a: 17.258,
        b: 0.19257,
        c: 0.004091,
        milk305: 6363
      }
    }
  };

  const row =
    table[cls]?.[parity] ||
    table.cow[parity];

  return {
    ...row,
    breedClass: cls,
    parity
  };
}


function buildCardCowStandardMilkCurveSrv(
  currentAnimal = {}
) {
  const animalClass =
    cardMilkCurveAnimalClassSrv(
      currentAnimal
    );

  // مرجع الأبقار لا يُستخدم للجاموس.
  if (animalClass !== 'cow') {
    return {
      points: [],
      reference: null
    };
  }

  const profile =
    cardStandardMilkProfileSrv(
      currentAnimal
    );

  /*
    Wood:
    Y(t) = a * t^b * exp(-c*t)

    نثبت شكل المنحنى المنشور،
    ثم نعمل normalization لناتج 305 يوم
    حتى يطابق متوسط 305 المنشور لنفس
    السلالة ورقم الموسم.
  */
  const rawDaily = [];

  for (
    let dim = 1;
    dim <= 305;
    dim++
  ) {
    const kg =
      profile.a *
      Math.pow(
        dim,
        profile.b
      ) *
      Math.exp(
        -profile.c * dim
      );

    if (
      Number.isFinite(kg) &&
      kg > 0
    ) {
      rawDaily.push({
        dim,
        kg
      });
    }
  }

  const raw305 =
    rawDaily.reduce(
      (sum, row) =>
        sum + row.kg,
      0
    );

  const scale =
    raw305 > 0 &&
    Number.isFinite(
      profile.milk305
    )
      ? profile.milk305 /
        raw305
      : 1;

  const points = [];

  /*
    الرسم الحالي يعمل كل 7 DIM.
    نبدأ بصريًا من DIM 0،
    لكن قيمة Wood الأولى محسوبة من day 1
    لأن t يجب أن يكون موجبًا.
  */
  for (
    let dim = 0;
    dim <= 301;
    dim += 7
  ) {
    const modelDay =
      Math.max(
        1,
        dim
      );

    const kg =
      profile.a *
      Math.pow(
        modelDay,
        profile.b
      ) *
      Math.exp(
        -profile.c *
        modelDay
      ) *
      scale;

    points.push({
      dim,

      kg:
        Math.round(
          kg * 100
        ) / 100
    });
  }

  const kg305 =
    profile.a *
    Math.pow(
      305,
      profile.b
    ) *
    Math.exp(
      -profile.c * 305
    ) *
    scale;

  points.push({
    dim: 305,

    kg:
      Math.round(
        kg305 * 100
      ) / 100
  });

  const peakDim =
    Math.max(
      1,
      Math.round(
        profile.b /
        profile.c
      )
    );

  const peakKg =
    profile.a *
    Math.pow(
      peakDim,
      profile.b
    ) *
    Math.exp(
      -profile.c *
      peakDim
    ) *
    scale;

  return {
    points,

    reference: {
      model:
        'Wood',

      species:
        'cow',

      breedClass:
        profile.breedClass,

      parity:
        profile.parity,

      standardDays:
        305,

      target305Kg:
        profile.milk305,

      peakDim,

      peakKg:
        Math.round(
          peakKg * 100
        ) / 100,

      source:
        'Jeretina_Babnik_Skorjanc_2013'
    }
  };
}
// ============================================================
// Cow Card — Scientific buffalo reference lactation curves
// ============================================================

function cardStandardBuffaloBreedSrv(a = {}) {
  const raw = String(
    a.breed ||
    a.breedName ||
    a.breedAr ||
    ''
  )
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[._-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();


  if (
    /nili\s*ravi|نيلي\s*رافي/.test(raw)
  ) {
    return 'nili_ravi';
  }


  if (
    /murrah|مورا/.test(raw)
  ) {
    return 'murrah';
  }


  if (
    /italian\s*buffalo|mediterranean|جاموس\s*ايطالي|جاموس\s*إيطالي|^italian$|^ايطالي$|^إيطالي$/.test(raw)
  ) {
    return 'italian_buffalo';
  }


  if (
    /egyptian\s*buffalo|جاموس\s*مصري|^مصري$|^baladi$|^balady$|^local$|^native$|^بلدي$|جاموس\s*بلدي/.test(raw)
  ) {
    return 'egyptian_buffalo';
  }


  if (
    /italian\s*cross|cross\s*italian|خليط\s*ايطالي|خليط\s*إيطالي/.test(raw)
  ) {
    return 'italian_cross';
  }


  if (
    /indian\s*cross|cross\s*indian|خليط\s*هندي/.test(raw)
  ) {
    return 'indian_cross';
  }


  if (
    /^indian$|^هندي$/.test(raw)
  ) {
    return 'indian_buffalo';
  }


  return 'generic_buffalo';
}


function cardStandardBuffaloProfileSrv(a = {}) {
  const requestedBreedClass =
    cardStandardBuffaloBreedSrv(a);


  const parityRaw =
    Number(
      a.lactationNumber ??
      a.parity ??
      a.lactation ??
      1
    );


  const requestedParity =
    Number.isFinite(parityRaw) &&
    parityRaw > 0
      ? Math.max(
          1,
          Math.round(parityRaw)
        )
      : 1;


  // Egyptian buffalo — Wood — weekly milk yield
  // Aziz et al. 2006 — parity 1..10
  const egyptian = {
    1:  { a: 29.92, b: 0.23, c: 0.03 },
    2:  { a: 41.79, b: 0.12, c: 0.02 },
    3:  { a: 41.89, b: 0.16, c: 0.02 },
    4:  { a: 41.50, b: 0.17, c: 0.02 },
    5:  { a: 43.84, b: 0.18, c: 0.03 },
    6:  { a: 47.57, b: 0.10, c: 0.02 },
    7:  { a: 44.13, b: 0.18, c: 0.03 },
    8:  { a: 46.97, b: 0.15, c: 0.02 },
    9:  { a: 49.23, b: 0.13, c: 0.02 },
    10: { a: 50.16, b: 0.06, c: 0.02 }
  };


  // Nili-Ravi — Wood — weekly milk yield
  // Anwar et al. 2009 — parity 1..8
  const niliRavi = {
    1: { a: 30.40, b: 0.311, c: 0.0357 },
    2: { a: 32.43, b: 0.360, c: 0.0383 },
    3: { a: 37.27, b: 0.297, c: 0.0356 },
    4: { a: 36.07, b: 0.339, c: 0.0380 },
    5: { a: 33.99, b: 0.360, c: 0.0398 },
    6: { a: 33.97, b: 0.331, c: 0.0387 },
    7: { a: 31.59, b: 0.343, c: 0.0372 },
    8: { a: 31.49, b: 0.323, c: 0.0381 }
  };


  // General dairy buffalo reference
  // Ghavi Hossein-Zadeh 2016
  // Daily milk yield — first three parities
  const generic = {
    1: {
      a: 5.42,
      b: 0.0968,
      c: 0.001520
    },

    2: {
      a: 6.36,
      b: 0.0730,
      c: 0.00164
    },

    3: {
      a: 6.66,
      b: 0.0764,
      c: 0.00178
    }
  };


  if (
    requestedBreedClass ===
    'egyptian_buffalo'
  ) {
    const referenceParity =
      Math.min(
        10,
        requestedParity
      );

    return {
      ...egyptian[
        referenceParity
      ],

      requestedBreedClass,

      referenceBreedClass:
        'egyptian_buffalo',

      requestedParity,
      referenceParity,

      timeUnit:
        'week',

      yieldUnit:
        'kg_per_week',

      referenceScope:
        requestedParity <= 10
          ? 'breed_parity_exact'
          : 'breed_parity10_proxy',

      source:
        'Aziz_Shalaby_ElShafie_Mahdy_Nishida_2006'
    };
  }


  if (
    requestedBreedClass ===
    'nili_ravi'
  ) {
    const referenceParity =
      Math.min(
        8,
        requestedParity
      );

    return {
      ...niliRavi[
        referenceParity
      ],

      requestedBreedClass,

      referenceBreedClass:
        'nili_ravi',

      requestedParity,
      referenceParity,

      timeUnit:
        'week',

      yieldUnit:
        'kg_per_week',

      referenceScope:
        requestedParity <= 8
          ? 'breed_parity_exact'
          : 'breed_parity8_proxy',

      source:
        'Anwar_Cain_Rowlinson_Khan_Abdullah_Babar_2009'
    };
  }


  // Murrah:
  // لدينا معادلة Wood مباشرة منشورة للموسم الأول.
  if (
    requestedBreedClass ===
      'murrah' &&
    requestedParity === 1
  ) {
    return {
      a: 3.98,
      b: 0.54,
      c: 0.05,

      requestedBreedClass,

      referenceBreedClass:
        'murrah',

      requestedParity,
      referenceParity: 1,

      timeUnit:
        'week',

      yieldUnit:
        'kg_per_day',

      referenceScope:
        'breed_parity_exact',

      source:
        'Sahoo_Singh_Gupta_Chakravarty_Ambhore_Singh_2016'
    };
  }


  /*
    Italian / Indian / crosses / Murrah parity > 1 /
    unspecified buffalo:

    لا ننسب لها معاملات سلالة غير منشورة.
    نستخدم مرجع الجاموس العام المنشور،
    ونوضح ذلك في metadata.
  */
  const referenceParity =
    Math.min(
      3,
      requestedParity
    );


  return {
    ...generic[
      referenceParity
    ],

    requestedBreedClass,

    referenceBreedClass:
      'generic_buffalo',

    requestedParity,
    referenceParity,

    timeUnit:
      'day',

    yieldUnit:
      'kg_per_day',

    referenceScope:
      requestedParity <= 3
        ? 'generic_parity_fallback'
        : 'generic_parity3_proxy',

    source:
      'Ghavi_HosseinZadeh_2016'
  };
}


function cardStandardBuffaloMilkAtDimSrv(
  dim,
  profile = {}
) {
  const d =
    Math.max(
      0,
      Number(dim) || 0
    );


  const t =
    profile.timeUnit === 'week'
      ? Math.max(
          1,
          d / 7
        )
      : Math.max(
          1,
          d
        );


  let kg =
    Number(profile.a) *
    Math.pow(
      t,
      Number(profile.b)
    ) *
    Math.exp(
      -Number(profile.c) * t
    );


  // الدراسات المصرية وNili-Ravi
  // تسجل Y كإجمالي كجم/أسبوع.
  if (
    profile.yieldUnit ===
    'kg_per_week'
  ) {
    kg /= 7;
  }


  return (
    Number.isFinite(kg) &&
    kg > 0
  )
    ? kg
    : null;
}


function buildCardBuffaloStandardMilkCurveSrv(
  currentAnimal = {}
) {
  const profile =
    cardStandardBuffaloProfileSrv(
      currentAnimal
    );


  if (!profile) {
    return {
      points: [],
      reference: null
    };
  }


  const points = [];


  for (
    let dim = 0;
    dim <= 301;
    dim += 7
  ) {
    const kg =
      cardStandardBuffaloMilkAtDimSrv(
        dim,
        profile
      );


    if (kg === null) {
      continue;
    }


    points.push({
      dim,

      kg:
        Math.round(
          kg * 100
        ) / 100
    });
  }


  const kg305 =
    cardStandardBuffaloMilkAtDimSrv(
      305,
      profile
    );


  if (kg305 !== null) {
    points.push({
      dim: 305,

      kg:
        Math.round(
          kg305 * 100
        ) / 100
    });
  }


  const peakTime =
    Number(profile.c) > 0
      ? (
          Number(profile.b) /
          Number(profile.c)
        )
      : null;


  const peakDim =
    Number.isFinite(
      peakTime
    ) &&
    peakTime > 0
      ? Math.max(
          1,
          Math.round(
            profile.timeUnit ===
              'week'
              ? peakTime * 7
              : peakTime
          )
        )
      : null;


  const peakKg =
    peakDim !== null
      ? cardStandardBuffaloMilkAtDimSrv(
          peakDim,
          profile
        )
      : null;


  let reference305Kg = 0;


  for (
    let dim = 1;
    dim <= 305;
    dim++
  ) {
    const kg =
      cardStandardBuffaloMilkAtDimSrv(
        dim,
        profile
      );


    if (
      Number.isFinite(kg) &&
      kg > 0
    ) {
      reference305Kg += kg;
    }
  }


  return {
    points,

    reference: {
      model:
        'Wood',

      species:
        'buffalo',

      breedClass:
        profile
          .requestedBreedClass,

      referenceBreedClass:
        profile
          .referenceBreedClass,

      parity:
        profile
          .requestedParity,

      referenceParity:
        profile
          .referenceParity,

      referenceScope:
        profile
          .referenceScope,

      timeUnit:
        profile
          .timeUnit,

      yieldUnit:
        profile
          .yieldUnit,

      standardDays:
        305,

      reference305Kg:
        Math.round(
          reference305Kg *
          100
        ) / 100,

      peakDim,

      peakKg:
        Number.isFinite(
          peakKg
        )
          ? Math.round(
              peakKg * 100
            ) / 100
          : null,

      source:
        profile.source
    }
  };
}


// Dispatcher واحد للأبقار والجاموس.
function buildCardStandardMilkCurveSrv(
  currentAnimal = {}
) {
  const animalClass =
    cardMilkCurveAnimalClassSrv(
      currentAnimal
    );


  if (
    animalClass ===
    'buffalo'
  ) {
    return buildCardBuffaloStandardMilkCurveSrv(
      currentAnimal
    );
  }


  return buildCardCowStandardMilkCurveSrv(
    currentAnimal
  );
}
function cardTwinWarningSrv(calf = {}) {
  const sex = cardNormalizeSexSrv(cardFirstSrv(calf, ['sex', 'gender', 'followerSex'], ''));

  const text = [
    calf.litterComposition,
    calf.birthComposition,
    calf.birthType,
    calf.calvingKind
  ].map(v => String(v || '')).join(' ');

  if (sex === 'أنثى' && /ذكر|male|عجل/i.test(text) && /توأم|twin|\+|2/i.test(text)) {
    return 'ملاحظة مهمة: العِجلة مولودة توأم مع عجل ذكر — يوجد احتمال Freemartin.';
  }

  return '';
}
function cardDairyTraitsNumSrv(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function cardDairyTraitsGradeTextSrv(score, fallback = '') {
  const fb = String(fallback || '').trim();
  if (fb) return fb;

  if (typeof dairyTraitsGradeSrv === 'function') {
    return dairyTraitsGradeSrv(score);
  }

  const s = Number(score);
  if (s >= 90) return 'ممتاز';
  if (s >= 85) return 'جيد جدًا';
  if (s >= 80) return 'جيد مرتفع';
  if (s >= 75) return 'جيد';
  if (s >= 65) return 'متوسط';
  if (s >= 50) return 'ضعيف';
  return 'ضعيف جدًا';
}

function cardDairyTraitsPartSrv(breakdown = {}, keys = [], max = 0) {
  for (const k of keys) {
    const n = cardDairyTraitsNumSrv(breakdown?.[k]);
    if (n !== null) {
      return {
        value: Math.max(0, Math.min(Number(max) || 0, Math.round(n))),
        max: Number(max) || 0
      };
    }
  }

  return {
    value: null,
    max: Number(max) || 0
  };
}

function cardDairyTraitsSummarySrv(score, grade, reason = '') {
  const r = String(reason || '').trim();
  if (r) return r;

  const s = Number(score);

  if (s >= 90) return 'تركيب إنتاجي ممتاز وملائم بقوة لإنتاج اللبن.';
  if (s >= 85) return 'تركيب إنتاجي جيد جدًا مع صفات لبنية واضحة.';
  if (s >= 80) return 'تركيب إنتاجي جيد مرتفع مع بعض الملاحظات البسيطة.';
  if (s >= 75) return 'تركيب إنتاجي جيد لكنه يحتاج متابعة في بعض السمات.';
  if (s >= 65) return 'تركيب إنتاجي متوسط مع نقاط تحتاج تحسين.';
  return 'التقييم الإنتاجي منخفض نسبيًا حسب السمات الظاهرة.';
}

function cardDairyTraitsFromAnimalSrv(animal = {}, events = []) {
  const dairyEvents = (Array.isArray(events) ? events : [])
    .filter(e => {
      const txt = eventTextSrv(e);
      return (
        txt.includes('dairy_traits_eval') ||
        txt.includes('dairy traits') ||
        txt.includes('تقييم سمات إنتاج اللبن')
      );
    })
    .sort((a, b) =>
      String(computeEventDateFromDoc(b) || '').localeCompare(String(computeEventDateFromDoc(a) || ''))
    );

  const lastEvent = dairyEvents[0] || null;
  const analysis = lastEvent?.analysis || {};
  const eventBreakdown = analysis.breakdown || {};

  const score = cardDairyTraitsNumSrv(
    animal.lastDairyTraitsScore ??
    animal.dairyTraitsScore ??
    animal.milkTraitsScore ??
    lastEvent?.dairyTraitsScore ??
    lastEvent?.score ??
    analysis.score
  );

  if (score === null) return null;

  const breakdown =
    animal.lastDairyTraitsBreakdown ||
    animal.dairyTraitsBreakdown ||
    eventBreakdown ||
    {};

  const grade = cardDairyTraitsGradeTextSrv(
    score,
    animal.lastDairyTraitsGrade ||
    animal.dairyTraitsGrade ||
    lastEvent?.grade ||
    analysis.grade ||
    ''
  );

  const date = cardISODateSrv(
    animal.lastDairyTraitsDate ||
    animal.dairyTraitsDate ||
    lastEvent?.eventDate ||
    lastEvent?.date ||
    lastEvent?.createdAt
  );

  return {
    score: Math.max(0, Math.min(100, Math.round(score))),
    grade,
    date,
    rangeText: '0–100',
    summary: cardDairyTraitsSummarySrv(score, grade, analysis.reason || lastEvent?.notes || lastEvent?.comment || ''),

    breakdown: {
      udder: cardDairyTraitsPartSrv(breakdown, ['udder'], 40),
      feetAndLegs: cardDairyTraitsPartSrv(breakdown, ['feetAndLegs', 'feetLegs', 'legs'], 20),
      dairyStrength: cardDairyTraitsPartSrv(breakdown, ['dairyStrength', 'strength'], 20),
      frontEndAndCapacity: cardDairyTraitsPartSrv(breakdown, ['frontEndAndCapacity', 'frontEndCapacity', 'capacity', 'bodyCapacity'], 15),
      rump: cardDairyTraitsPartSrv(breakdown, ['rump'], 5)
    }
  };
}
