// ============================================================
app.get('/api/animal-card', requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        error: 'firestore_disabled',
        message: 'قاعدة البيانات غير متاحة الآن.'
      });
    }

    const uid = req.userId;
    const number = normalizeDigitsSrv(req.query.number || req.query.animalNumber || '');
    const animalId = String(req.query.animalId || req.query.id || '').trim();

    if (!number && !animalId) {
      return res.status(400).json({
        ok: false,
        error: 'animalNumber_required',
        message: 'رقم الحيوان مطلوب.'
      });
    }

    const animal = await findCowCardDocSrv(uid, { number, animalId });

    if (!animal) {
      const calf = await findCalfCardDocSrv(uid, { number });

      if (calf) {
        const calfNumber = cardSubjectNumberSrv(calf) || number;

        return res.json({
          ok: false,
          error: 'wrong_card_type',
          cardType: 'calf',
          message: 'هذا الرقم مسجّل كعجل. سيتم فتح بطاقة العجل.',
          redirectUrl: `calf-card.html?number=${encodeURIComponent(calfNumber)}`
        });
      }

     return res.status(404).json({
  ok: false,
  error: 'animal_not_found',
  message: 'هذا الحيوان غير موجود بمزرعتك'
});
    }

    const events = await fetchCardEventsSrv(uid, animal);
    const groupNameFromMembership = await findAnimalGroupNameSrv(uid, animal);

    const state = {
      number: animal.animalNumber ?? animal.number ?? number,

      kind: animal.animalType || animal.kind || animal.type || animal.animalTypeAr || null,

      breed:
        animal.breed ||
        animal.breedName ||
        animal.breedAr ||
        animal.animalBreed ||
        animal.animalBreedAr ||
        animal.strain ||
        animal.line ||
        null,

      group:
        animal.group ||
        animal.groupName ||
        animal.currentGroup ||
        animal.pen ||
        animal.lot ||
        animal.section ||
        groupNameFromMembership ||
        null,

      birthDate: animal.birthDate || animal.birth_date || animal.dob || null,
      lastCalvingDate: animal.lastCalvingDate || animal.lastCalving || animal.calvingDate || null,
      lactationNumber: animal.lactationNumber ?? animal.lactNo ?? null,
      daysInMilk: Number.isFinite(Number(animal.daysInMilk)) ? Number(animal.daysInMilk) : null,

      reproductiveStatus: String(animal.reproductiveStatus || animal.reproStatus || '').trim() || null,
      productionStatus: String(animal.productionStatus || animal.prodStatus || '').trim() || null,
      healthStatus: String(animal.healthStatus || animal.lastDisease || animal.disease || 'سليم').trim(),

            pregnancyDate:
        animal.pregnancyDate ||
        animal.pregnantFrom ||
        null,

      pregnancyDays:
        animal.pregnancyDays !== null &&
        animal.pregnancyDays !== undefined &&
        animal.pregnancyDays !== '' &&
        Number.isFinite(Number(animal.pregnancyDays))
          ? Number(animal.pregnancyDays)
          : null,

      lastInseminationDate:
        animal.lastInseminationDate ||
        null,

      servicesCount:
        Number.isFinite(Number(animal.servicesCount))
          ? Number(animal.servicesCount)
          : null,

      serviceIntervalDays:
        Number.isFinite(Number(animal.serviceIntervalDays))
          ? Number(animal.serviceIntervalDays)
          : null,

      lastHeatDate:
        animal.lastHeatDate ||
        null,

      heatIntervalDays:
        Number.isFinite(Number(animal.heatIntervalDays))
          ? Number(animal.heatIntervalDays)
          : null,

      milkTraitsScore: Number(animal.milkTraitsScore || animal.milk_score || 0) || 0,
      ovsynch: animal.ovsynch || null,

      milkTodayKg: Number.isFinite(Number(animal.milkTodayKg)) ? Number(animal.milkTodayKg) : null,
      seasonTotalKg: Number.isFinite(Number(animal.seasonTotalKg)) ? Number(animal.seasonTotalKg) : null,
      m305Kg: Number.isFinite(Number(animal.m305Kg)) ? Number(animal.m305Kg) : null,

      lastCheckDate: animal.lastCheckDate || animal.healthCheckDate || null,

      inseminations: [],
      estrusDates: Array.isArray(animal.estrusDates) ? [...animal.estrusDates] : [],
      healthHistory: [],
      milkSeries: []
    };

    // ============================================================
    // Current-cycle source of truth
    // بطاقة الحيوان تعرض الحالة الحالية من وثيقة الحيوان،
    // وتستخدم الأحداث فقط لاشتقاق النواقص داخل الدورة الحالية.
    // ============================================================
    const calvingDates = [
  ...new Set([
    cardISODateSrv(
      state.lastCalvingDate
    ),

    ...events
      .filter(
        e =>
          eventTypeForCardSrv(e) ===
          'calving'
      )
      .map(
        e =>
          computeEventDateFromDoc(e)
      )
      .filter(Boolean)

  ].filter(Boolean))
].sort();

    if (calvingDates.length) {
      state.lastCalvingDate =
        calvingDates[
          calvingDates.length - 1
        ];
    }

    const currentCycleStartDate =
      cardISODateSrv(
        state.lastCalvingDate
      );

    const isAfterCurrentCalving =
      d =>
        !currentCycleStartDate ||
        (
          d &&
          String(d).slice(0, 10) >
            currentCycleStartDate
        );

    const isInCurrentLactation =
      d =>
        !currentCycleStartDate ||
        (
          d &&
          String(d).slice(0, 10) >=
            currentCycleStartDate
        );

    let seasonMilk = 0;

    let derivedReproductiveStatus =
      null;

    let derivedProductionStatus =
      null;


    for (const e of events) {

      const t =
        eventTypeForCardSrv(e);

      const d =
        computeEventDateFromDoc(e);


      if (
        t === 'dry' &&
        d &&
        isAfterCurrentCalving(d)
      ) {
        derivedProductionStatus =
          'جاف';
      }


      if (
        t === 'insemination' &&
        d &&
        isAfterCurrentCalving(d)
      ) {
        state.inseminations.push(d);
      }


      if (
        t === 'heat' &&
        d &&
        isAfterCurrentCalving(d)
      ) {
        state.estrusDates.push(d);
      }


      if (
        t === 'pregnancy' &&
        d &&
        isAfterCurrentCalving(d)
      ) {

        if (
          positivePregnancyEventSrv(e)
        ) {

          derivedReproductiveStatus =
            'عِشار';

        } else if (
          negativePregnancyEventSrv(e)
        ) {

          derivedReproductiveStatus =
            'مفتوحة';
        }
      }


      if (t === 'disease') {

        state.healthHistory.push({
          date:
            d || null,

          name:
            e.diseaseName ||
            e.eventType ||
            e.type ||
            'حالة صحية',

          diagnosis:
            e.diseaseName ||
            e.eventType ||
            e.type ||
            'حالة صحية',

          note:
            e.notes ||
            e.note ||
            ''
        });


        if (
          d &&
          !state.lastCheckDate
        ) {
          state.lastCheckDate = d;
        }
      }


      if (
        t === 'milk' &&
        d &&
        isInCurrentLactation(d)
      ) {

        const kg =
          milkKgFromEventSrv(e);


        if (kg > 0) {

          const dim =
            currentCycleStartDate
              ? daysBetweenIsoSrv(
                  currentCycleStartDate,
                  d
                )
              : null;


          state.milkSeries.push({
            date: d,
            kg,

            dim:
              Number.isFinite(dim) &&
              dim >= 0
                ? dim
                : null
          });


          seasonMilk += kg;
        }
      }
    }


    state.inseminations =
      [
        ...new Set(
          state.inseminations
            .filter(Boolean)
        )
      ].sort();


    state.estrusDates =
      [
        ...new Set(
          state.estrusDates
            .filter(Boolean)
        )
      ]
        .filter(
          d =>
            isAfterCurrentCalving(d)
        )
        .sort();


    state.milkSeries =
      state.milkSeries.sort(
        (a, b) =>
          String(a.date)
            .localeCompare(
              String(b.date)
            )
      );


    // الحالة الحالية المحفوظة
    // هي المصدر الأول.
    // الأحداث تستخدم فقط عند غيابها.
    if (
      !state.reproductiveStatus &&
      derivedReproductiveStatus
    ) {

      state.reproductiveStatus =
        derivedReproductiveStatus;
    }


    if (
      !state.productionStatus &&
      derivedProductionStatus
    ) {

      state.productionStatus =
        derivedProductionStatus;
    }


    const storedLastInseminationDate =
      cardISODateSrv(
        state.lastInseminationDate
      );


    if (
      storedLastInseminationDate &&
      currentCycleStartDate &&
      storedLastInseminationDate <=
        currentCycleStartDate
    ) {

      state.lastInseminationDate =
        null;
    }


    state.lastInseminationDate =
      state.lastInseminationDate ||
      lastOfSrv(
        state.inseminations
      );


 state.servicesCount =
  state.lastInseminationDate
    ? (
        Number.isFinite(
          state.servicesCount
        ) &&
        state.servicesCount >= 0
          ? state.servicesCount
          : state.inseminations.length
      )
    : 0;
 


    state.serviceIntervalDays =
      Number.isFinite(
        state.serviceIntervalDays
      ) &&
      state.serviceIntervalDays > 0
        ? state.serviceIntervalDays
        : avgIntervalDaysSrv(
            state.inseminations
          );


    const storedLastHeatDate =
      cardISODateSrv(
        state.lastHeatDate
      );


    if (
      storedLastHeatDate &&
      currentCycleStartDate &&
      storedLastHeatDate <=
        currentCycleStartDate
    ) {

      state.lastHeatDate =
        null;
    }


    const lastHeatDate =
      lastOfSrv(
        state.estrusDates
      );


    state.lastHeatDate =
      state.lastHeatDate ||
      lastHeatDate ||
      null;


    state.heatIntervalDays =
      Number.isFinite(
        state.heatIntervalDays
      ) &&
      state.heatIntervalDays > 0
        ? state.heatIntervalDays
        : avgIntervalDaysSrv(
            state.estrusDates
          );


    let gestationDays = null;


    if (
      state.reproductiveStatus &&
      /عشار|preg/i.test(
        String(
          state.reproductiveStatus
        )
      )
    ) {

      const aiDate =
        cardISODateSrv(
          state.lastInseminationDate
        );


      if (aiDate) {

        const calculated =
          daysBetweenIsoSrv(
            aiDate,
            cairoTodayISO()
          );


        if (
          Number.isFinite(
            calculated
          ) &&
          calculated >= 0
        ) {

          gestationDays =
            calculated;
        }
      }


      if (
        gestationDays === null &&
        Number.isFinite(
          state.pregnancyDays
        ) &&
        state.pregnancyDays >= 0
      ) {

        gestationDays =
          Math.floor(
            state.pregnancyDays
          );
      }
    }


    state.gestationDays =
      gestationDays;

        if (
      state.lastCalvingDate &&
      !/جاف|dry/i.test(
        String(
          state.productionStatus ||
          ''
        )
      )
    ) {

      const dim =
        daysBetweenIsoSrv(
          String(
            state.lastCalvingDate
          ).slice(0, 10),

          cairoTodayISO()
        );


      state.daysInMilk =
        Number.isFinite(dim) &&
        dim >= 0
          ? dim
          : null;
    }

    const todayISO = cairoTodayISO();

    const todayMilk =
      state.milkSeries.find(
        row =>
          String(
            row?.date || ''
          ).slice(0, 10) ===
          todayISO
      );

    state.milkTodayKg =
      todayMilk
        ? Number(
            todayMilk.kg || 0
          )
        : null;

    state.seasonTotalKg =
      state.milkSeries.length
        ? Math.round(
            seasonMilk * 100
          ) / 100
        : null;

    if (
      state.milkSeries.length
    ) {

      const proj =
        projectLactation305AliSchaefferSrv({
          milkSeries:
            state.milkSeries,

          lastCalvingDate:
            state.lastCalvingDate,

          species:
            state.kind,

          breed:
            state.breed,

          parity:
            state.lactationNumber
        });

      state.m305Kg =
        proj?.m305Kg ??
        null;

    } else {

      state.m305Kg =
        null;
    }

   const eventRows = events
  .map(cardEventRowSrv)
  .filter(
    e =>
      e.date ||
      e.title
  );


const eventSeasons =
  cardEventSeasonsSrv(
    eventRows,
    calvingDates,
    state.lactationNumber
  );


const alerts =
  await fetchCardAlertsSrv(
    uid,
    animal
  );
   const dairyTraits = cardDairyTraitsFromAnimalSrv(animal, events);
   const standardMilkCurve =
  buildCardStandardMilkCurveSrv({
    kind:
      state.kind,

    breed:
      state.breed,

    lactationNumber:
      state.lactationNumber
  });

const herdMilkCurve =
  standardMilkCurve.points;

    return res.json({
      ok: true,
      cardType: 'cow',
      page: 'cow-card',
      title: 'بطاقة الحيوان',

      animal: {
        id: animal.id,
        animalNumber: state.number,
        number: state.number,
        kind: state.kind,
        breed: state.breed,
        group: state.group,

        birthDate: cardISODateSrv(state.birthDate),
        lastCalvingDate: cardISODateSrv(state.lastCalvingDate),
        lactationNumber: state.lactationNumber,
        daysInMilk: state.daysInMilk,

        reproductiveStatus: state.reproductiveStatus,
        pregnancyDate: cardISODateSrv(state.pregnancyDate),
        gestationDays: state.gestationDays,
        lastInseminationDate: cardISODateSrv(state.lastInseminationDate),
        servicesCount: state.servicesCount,
        serviceIntervalDays: state.serviceIntervalDays,
        lastHeatDate: cardISODateSrv(state.lastHeatDate),
        heatIntervalDays: state.heatIntervalDays,

        productionStatus: state.productionStatus,
        milkTodayKg: state.milkTodayKg,
        seasonTotalKg: state.seasonTotalKg,
        m305Kg: state.m305Kg,
        milkTraitsScore: state.milkTraitsScore,

        healthStatus: state.healthStatus,
        lastCheckDate: cardISODateSrv(state.lastCheckDate),
        ovsynch: state.ovsynch
      },
      dairyTraits,
      milkSeries: state.milkSeries,
      herdMilkCurve,
      milkCurveReference: standardMilkCurve.reference,
      healthHistory: state.healthHistory.slice(-20).reverse(),
      alerts,

events:
  eventRows,

eventSeasons,

recentEvents:
  [...eventRows]
    .reverse()
    .slice(0, 12)
    });

  } catch (e) {
    console.error('animal-card', e);

    return res.status(500).json({
      ok: false,
      error: 'animal_card_failed',
      message: 'تعذّر تحميل بطاقة الحيوان.'
    });
  }
});
async function findCalfBirthEventForCardSrv(uid, calfNumber) {
  if (!db || !uid || !calfNumber) return null;

  const raw = String(calfNumber).trim();
  const asNum = Number(raw);
  const values = Number.isFinite(asNum) ? [raw, asNum] : [raw];

  const fields = ['calfId', 'calf2Id', 'calf3Id'];
  const found = [];
  const seen = new Set();

  for (const field of fields) {
    for (const value of values) {
      try {
        const snap = await db.collection('events')
          .where('userId', '==', uid)
          .where(field, '==', value)
          .limit(10)
          .get();

        snap.forEach(doc => {
          if (seen.has(doc.id)) return;
          seen.add(doc.id);

          found.push({
            id: doc.id,
            ...(doc.data() || {})
          });
        });
      } catch (_) {}
    }
  }

  return found
    .filter(e => {
      const t = String(e.eventType || e.type || e.eventTypeNorm || '').trim();
      return t.includes('ولادة') || t.includes('calving') || t.includes('birth');
    })
    .sort((a, b) =>
      String(b.eventDate || '').localeCompare(String(a.eventDate || ''))
    )[0] || null;
}
async function findCalfSireFromBirthEventSrv(uid, birthEvent = {}) {
  if (!db || !uid || !birthEvent) return null;

  const directSire = cardFirstSrv(birthEvent, [
    'sireNumber',
    'fatherNumber',
    'sireId',
    'bullNumber',
    'bullCode',
    'semenCode',
    'semenNumber',
    'strawCode',
    'sire',
    'bull',
    'semen'
  ], '');

  const directName = cardFirstSrv(birthEvent, [
    'sireName',
    'fatherName',
    'bullName'
  ], '');

  if (directSire || directName) {
    return {
      sireNumber: directSire || '',
      sireName: directName || ''
    };
  }

  const damNumber = String(
    birthEvent.animalNumber ||
    birthEvent.damNumber ||
    birthEvent.motherNumber ||
    birthEvent.number ||
    ''
  ).trim();

  const aiDate = String(
    birthEvent.lastFertileInseminationDate ||
    birthEvent.lastInseminationDate ||
    birthEvent.inseminationDate ||
    ''
  ).trim().slice(0, 10);

  if (!damNumber || !aiDate) return null;

  const values = Number.isFinite(Number(damNumber))
    ? [damNumber, Number(damNumber)]
    : [damNumber];

  for (const v of values) {
    try {
      const snap = await db.collection('events')
        .where('userId', '==', uid)
        .where('animalNumber', '==', v)
        .where('eventDate', '==', aiDate)
        .limit(10)
        .get();

      for (const doc of snap.docs) {
        const e = { id: doc.id, ...(doc.data() || {}) };
        const t = String(e.eventType || e.type || e.eventTypeNorm || '').trim();

        if (!(t.includes('تلقيح') || t.includes('insemination'))) continue;

        return {
          sireNumber: cardFirstSrv(e, [
            'sireNumber',
            'fatherNumber',
            'sireId',
            'bullNumber',
            'bullCode',
            'semenCode',
            'semenNumber',
            'strawCode',
            'sire',
            'bull',
            'semen'
          ], ''),
          sireName: cardFirstSrv(e, [
            'sireName',
            'fatherName',
            'bullName'
          ], '')
        };
      }
    } catch (_) {}
  }

  return null;
}
