app.post("/api/animals/archive/gate", requireUserId, async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({
        ok: false,
        allowed: false,
        message: String(req.body?.archiveReason || "").trim() === "death" ? "❌ تعذّر فحص بيانات النفوق الآن. حاول مرة أخرى." : "❌ تعذّر فحص بيانات البيع الآن. حاول مرة أخرى.",
      });
    }

    const uid = req.userId;
    const body = req.body || {};

    const animalNumber = archiveNormNumberSrv(body.animalNumber || body.number || "");
    const archiveReason = String(body.archiveReason || "").trim();

    if (!animalNumber) {
      return res.status(400).json({
        ok: false,
        allowed: false,
        message: "أدخل رقم الحيوان.",
      });
    }

    if (!["sale", "death"].includes(archiveReason)) {
      return res.status(400).json({
        ok: false,
        allowed: false,
        message: "تعذّر تحديد نوع العملية من الصفحة. أعد فتحها وحاول مرة أخرى.",
      });
    }

    const animal = await archiveFindAnimalSrv(uid, animalNumber);

    if (!animal) {
      return res.status(404).json({
        ok: false,
        allowed: false,
        message: "❌ لم أجد الحيوان في القطيع المسجل بحسابك.",
      });
    }

    const doc = animal.data || {};
    const st = String(doc.status || "active").trim().toLowerCase();

    if (st !== "active") {
      return res.status(400).json({
        ok: false,
        allowed: false,
       message: "❌ الحيوان خارج القطيع أو سبق تسجيل خروجه.",
      });
    }

    return res.json({
        ok: true,
        allowed: true,
        message: archiveReason === "sale" ? `✅ راجعت بيانات الحيوان رقم ${animalNumber}، ويمكنك تسجيل البيع الآن.` : `✅ راجعت بيانات الحيوان رقم ${animalNumber}، ويمكنك تسجيل النفوق الآن.`,
        animal: {
        id: animal.id,
        animalNumber,
        number: String(doc.number || animalNumber),
        lactationNumber: Number(doc.lactationNumber || 0) || null,
        animalType: doc.animalType || doc.animaltype || null,
        animalTypeAr: doc.animalTypeAr || null,
        species: doc.species || doc.animalTypeAr || doc.animalType || doc.animaltype || null,
        breed: doc.breed || null,
        productionStatus: doc.productionStatus || null,
        reproductiveStatus: doc.reproductiveStatus || null
      }
    });

  } catch (e) {
    console.error("animals.archive.gate", e);
    return res.status(500).json({
      ok: false,
      allowed: false,
      message: String(req.body?.archiveReason || "").trim() === "death" ? "❌ تعذّر فحص بيانات النفوق الآن. حاول مرة أخرى." : "❌ تعذّر فحص بيانات البيع الآن. حاول مرة أخرى.",
    });
  }
});
