function adminPortalPageHeadersSrv(req, res, next) {
  res.setHeader(
    'Content-Security-Policy',
    [
      "default-src 'none'",
      "base-uri 'none'",
      "connect-src 'self'",
      "img-src 'self' data:",
      "style-src 'self'",
      "script-src 'none'",
      "script-src-attr 'none'",
      "style-src-attr 'none'",
      "font-src 'self'",
      "frame-src 'none'",
      "frame-ancestors 'none'",
      "object-src 'none'",
      "worker-src 'none'",
      "form-action 'self'",
      "upgrade-insecure-requests"
    ].join('; ')
  );

 res.setHeader(
  'Referrer-Policy',
  'same-origin'
);

  res.setHeader(
    'X-Frame-Options',
    'DENY'
  );

  res.setHeader(
    'Permissions-Policy',
    'camera=(), microphone=(), geolocation=(), payment=(), usb=()'
  );

  res.setHeader(
    'Cross-Origin-Opener-Policy',
    'same-origin'
  );

  res.setHeader(
    'Cross-Origin-Resource-Policy',
    'same-origin'
  );

  res.setHeader(
    'X-Robots-Tag',
    'noindex, nofollow, noarchive, nosnippet, noimageindex'
  );

  return next();
}

function adminPortalEscapeHtmlSrv(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function adminPortalCsrfTokenSrv(req) {
  const sessionCookie =
    authCookieValueBridgeSrv(
      req,
      AUTH_COOKIE_NAME
    );

  if (!sessionCookie) {
    return '';
  }

  return crypto
    .createHmac(
      'sha256',
      sessionCookie
    )
    .update(
      'murabbik-admin-portal-csrf-v1'
    )
    .digest('base64url');
}

function adminPortalSafeEqualSrv(a, b) {
  const left =
    Buffer.from(
      String(a || ''),
      'utf8'
    );

  const right =
    Buffer.from(
      String(b || ''),
      'utf8'
    );

  if (
    !left.length ||
    left.length !== right.length
  ) {
    return false;
  }

  return crypto.timingSafeEqual(
    left,
    right
  );
}

function adminPortalFormGuardSrv(
  req,
  res,
  next
) {
  const fetchSite =
    String(
      req.get('sec-fetch-site') || ''
    )
      .trim()
      .toLowerCase();

  if (
    fetchSite === 'cross-site' ||
    fetchSite === 'same-site'
  ) {
    return res
      .status(403)
      .send('Forbidden');
  }

  const sourceOrigin =
    adminRequestSourceOriginSrv(req);

  const targetOrigin =
    adminRequestTargetOriginSrv(req);

  if (
    !sourceOrigin ||
    !targetOrigin ||
    sourceOrigin !== targetOrigin
  ) {
    return res
      .status(403)
      .send('Forbidden');
  }

  const supplied =
    String(
      req.body?.adminCsrfToken || ''
    ).trim();

  const expected =
    adminPortalCsrfTokenSrv(req);

  if (
    !adminPortalSafeEqualSrv(
      supplied,
      expected
    )
  ) {
    return res
      .status(403)
      .send('Forbidden');
  }

  return next();
}

function adminPortalJsonCollectorSrv() {
  let statusCode = 200;
  let body = null;

  const response = {
    status(code) {
      statusCode =
        Number(code) || 200;

      return response;
    },

    json(payload) {
      body = payload;
      return payload;
    },

    send(payload) {
      body = payload;
      return payload;
    }
  };

  return {
    response,

    read() {
      return {
        statusCode,
        body
      };
    }
  };
}

function adminPortalStatusLabelSrv(status) {
  if (status === 'active') {
    return 'نشط';
  }

  if (status === 'suspended') {
    return 'موقوف';
  }

  if (status === 'closed') {
    return 'مغلق';
  }

  return 'غير محدد';
}

function adminPortalStatusClassSrv(status) {
  if (status === 'active') {
    return 'status-active';
  }

  if (status === 'suspended') {
    return 'status-suspended';
  }

  if (status === 'closed') {
    return 'status-closed';
  }

  return 'status-unknown';
}

function adminPortalDateSrv(value) {
  if (!value) {
    return '—';
  }

  const d =
    new Date(value);

  if (
    Number.isNaN(
      d.getTime()
    )
  ) {
    return '—';
  }

  try {
    return new Intl
      .DateTimeFormat(
        'ar-EG',
        {
          dateStyle:
            'medium',

          timeStyle:
            'short',

          timeZone:
            'Africa/Cairo'
        }
      )
      .format(d);

  } catch (_) {
    return d.toISOString();
  }
}

function adminPortalReturnStateSrv(
  body = {}
) {
  const q =
    adminAccountsSearchSrv(
      body.returnQ || ''
    );

  const rawStatus =
    String(
      body.returnStatus || 'all'
    )
      .trim()
      .toLowerCase();

  const status =
    rawStatus === 'all'
      ? 'all'
      : (
          adminAccountsStatusFilterSrv(
            rawStatus
          ) || 'all'
        );

  return {
    q,
    status
  };
}

function adminPortalAccountsUrlSrv({
  q = '',
  status = 'all',
  cursor = '',
  notice = ''
} = {}) {
  const params =
    new URLSearchParams();

  if (q) {
    params.set(
      'q',
      q
    );
  }

  if (
    status &&
    status !== 'all'
  ) {
    params.set(
      'status',
      status
    );
  }

  if (cursor) {
    params.set(
      'cursor',
      cursor
    );
  }

  if (notice) {
    params.set(
      'notice',
      notice
    );
  }

  const query =
    params.toString();

  return query
    ? `/admin/accounts?${query}`
    : '/admin/accounts';
}

function adminPortalNoticeSrv(raw) {
  const code =
    String(raw || '')
      .trim()
      .toLowerCase();

  if (
    ![
      'active',
      'suspended',
      'closed'
    ].includes(code)
  ) {
    return null;
  }

  return {
    type: 'ok',

    message:
      adminAccountMessageSrv(
        code
      )
  };
}
function adminPortalBillingCycleLabelSrv(raw) {
  const cycle = billingNormalizeCycleSrv(raw);

  if (cycle === 'monthly') return 'شهري';
  if (cycle === 'annual') return 'سنوي';

  return 'غير محدد';
}

function adminPortalBillingMoneySrv(
  amountRaw,
  currencyRaw
) {
  const amount = Number(amountRaw);
  const currency =
    String(currencyRaw || '')
      .trim()
      .toUpperCase();

  if (
    !Number.isFinite(amount) ||
    !/^[A-Z]{3}$/.test(currency)
  ) {
    return '—';
  }

  try {
    return new Intl.NumberFormat(
      'ar-EG',
      {
        style: 'currency',
        currency
      }
    ).format(amount);

  } catch (_) {
    return `${amount.toFixed(2)} ${currency}`;
  }
}

async function adminPortalPendingBillingOrdersSrv() {
  if (!db) {
    throw new Error(
      'billing_firestore_unavailable'
    );
  }

  const snap =
    await db
      .collection('billing_orders')
      .where(
        'status',
        '==',
        'pending_payment'
      )
      .limit(100)
      .get();

  const orders =
    snap.docs.map(doc => ({
      orderId: doc.id,
      ...(doc.data() || {})
    }));

  const userIds = [
    ...new Set(
      orders
        .map(order =>
          String(
            order?.userId || ''
          ).trim()
        )
        .filter(Boolean)
    )
  ];

  const subscriptions =
    new Map(
      await Promise.all(
        userIds.map(
          async userId => {
            const subscriptionSnap =
              await db
                .collection('subscriptions')
                .doc(userId)
                .get();

            return [
              userId,

              subscriptionSnap.exists
                ? (subscriptionSnap.data() || {})
                : null
            ];
          }
        )
      )
    );

  const nowMs = Date.now();

  const currentOrders =
    orders.filter(order => {
      const userId =
        String(
          order?.userId || ''
        ).trim();

      const subscription =
        subscriptions.get(userId);

      return Boolean(
        subscription &&
        billingOrderEffectiveStatusSrv(
          order.orderId,
          order,
          subscription,
          nowMs
        ) === 'pending_payment'
      );
    });

  const currentUserIds = [
    ...new Set(
      currentOrders
        .map(order =>
          String(
            order?.userId || ''
          ).trim()
        )
        .filter(Boolean)
    )
  ];

  const profiles =
    new Map(
      await Promise.all(
        currentUserIds.map(
          async userId => {
            const profileSnap =
              await db
                .collection('users')
                .doc(userId)
                .get();

            return [
              userId,

              profileSnap.exists
                ? (profileSnap.data() || {})
                : {}
            ];
          }
        )
      )
    );

  return currentOrders
    .map(order => {
      const userId =
        String(
          order?.userId || ''
        ).trim();

      const profile =
        profiles.get(userId) || {};

      return {
        ...order,
        userId,

        customerName:
          profile.name ||
          profile.displayName ||
          profile.fullName ||
          '',

        customerPhone:
          profile.phone ||
          profile.phoneNumber ||
          profile.phoneKey ||
          ''
      };
    })
    .sort(
      (a, b) =>
        (
          subscriptionTimestampMsSrv(
            b?.updatedAt ||
            b?.createdAt
          ) || 0
        ) -
        (
          subscriptionTimestampMsSrv(
            a?.updatedAt ||
            a?.createdAt
          ) || 0
        )
    );
}

async function adminPortalLoadPendingManualOrderSrv(
  orderIdRaw
) {
  const orderId =
    String(orderIdRaw || '')
      .trim()
      .toLowerCase();

  if (
    !/^ord_[a-f0-9]{40}$/
      .test(orderId)
  ) {
    throw billingPublicErrorSrv(
      404,
      'billing_order_not_found',
      '❌ طلب الاشتراك غير موجود.'
    );
  }

  const snap =
    await db
      .collection('billing_orders')
      .doc(orderId)
      .get();

  if (!snap.exists) {
    throw billingPublicErrorSrv(
      404,
      'billing_order_not_found',
      '❌ طلب الاشتراك غير موجود.'
    );
  }

  const order =
    snap.data() || {};

  const userId =
    String(
      order?.userId || ''
    ).trim();

  if (!userId) {
    throw billingPublicErrorSrv(
      409,
      'billing_order_owner_missing',
      '❌ طلب الاشتراك غير مرتبط بحساب صالح.'
    );
  }

  const subscriptionSnap =
    await db
      .collection('subscriptions')
      .doc(userId)
      .get();

  if (!subscriptionSnap.exists) {
    throw billingPublicErrorSrv(
      409,
      'billing_subscription_missing',
      '❌ اشتراك الحساب غير موجود.'
    );
  }

  const subscription =
    subscriptionSnap.data() || {};

  const status =
    String(
      order?.status || ''
    )
      .trim()
      .toLowerCase();

  const provider =
    String(
      order?.paymentProvider || ''
    )
      .trim()
      .toLowerCase();

  if (status === 'paid') {
    throw billingPublicErrorSrv(
      409,
      'billing_order_already_paid',
      'ℹ️ طلب الاشتراك مدفوع بالفعل.'
    );
  }

  if (
    status !== 'pending_payment'
  ) {
    throw billingPublicErrorSrv(
      409,
      'billing_order_not_payable',
      '❌ طلب الاشتراك الحالي غير قابل للدفع.'
    );
  }

  if (
    billingOrderCurrentIdSrv(
      subscription
    ) !== orderId
  ) {
    throw billingPublicErrorSrv(
      409,
      'billing_order_superseded',
      'ℹ️ طلب الدفع هذا لم يعد هو الطلب الحالي للحساب.'
    );
  }

  if (
    billingOrderEffectiveStatusSrv(
      orderId,
      order,
      subscription
    ) === 'expired'
  ) {
    throw billingPublicErrorSrv(
      409,
      'billing_order_expired',
      'ℹ️ انتهت صلاحية طلب الدفع. أنشئ طلبًا جديدًا بالسعر الحالي.'
    );
  }

  if (provider !== 'manual') {
    throw billingPublicErrorSrv(
      409,
      'billing_payment_provider_mismatch',

      provider
        ? '❌ هذا الطلب لا يستخدم الدفع اليدوي.'
        : '❌ لم يبدأ العميل وسيلة الدفع لهذا الطلب بعد.'
    );
  }

  const currency =
    String(
      order?.currency || ''
    )
      .trim()
      .toUpperCase();

  const amountMinor =
    Number.isSafeInteger(
      Number(order?.amountMinor)
    )
      ? Number(order.amountMinor)
      : billingAmountMinorSrv(
          order?.amount,
          currency
        );

  if (
    !/^[A-Z]{3}$/.test(currency) ||
    !Number.isSafeInteger(amountMinor) ||
    amountMinor <= 0
  ) {
    throw billingPublicErrorSrv(
      409,
      'billing_order_amount_invalid',
      '❌ قيمة طلب الاشتراك غير صالحة للتأكيد.'
    );
  }

  return {
    orderId,
    order,
    currency,
    amountMinor
  };
}

